/* ITOps — the script of guide.html (BT90: moved out of the page, so the page policy allows no inline scripts). */
var APP_NAME='ITOps';   // BT20: the client's app name (replaced from /api/branding)
const CONTENT = {"app": "ITOps", "tagline": "IT Master Operations Hub", "intro": "ITOps is your team's single place to log and resolve support requests, store know-how, keep procedures current, track contracts and credentials, and stay on top of deadlines. This guide explains, in plain language, what each part does and how to use it. You don't need to be technical \u2014 follow the steps for the task you want to do.", "categories": [{"cat": "Getting started", "topics": [{"title": "What ITOps is and how it fits together", "for": "everyone", "body": [{"p": "ITOps is your organization's one place to ask IT and Operations for help, follow your requests, and find the how-to guides and procedures that apply to you."}, {"p": "The left-hand menu only shows the areas your role allows, so two people can see quite different menus. The groups are:"}, {"bullets": ["Dashboard: your starting page, with live counts and your most recent tickets.", "Service Desk: Tickets (requests and problems), plus Calendar, Reports, Scorecard and Standards & Audits for the teams that use them.", "Knowledge: Knowledge Base (how-to articles), Ask IT (a question-and-answer assistant), SOPs (procedures you read and acknowledge), Job Descriptions and My Signatures (documents waiting for your e-signature).", "Assets & Vendors: Equipment, My Equipment (gear on loan to you), Credentials, Contracts and Vendors.", "IT Operations, Administration and Logs & Integrations: tools for IT staff and managers."]}, {"h": "How a request travels"}, {"steps": ["A request comes in: you create a ticket in the app, fill in a web form, or email the help-desk mailbox.", "It gets a ticket number such as TK-2026-0142. Keep it; it links every message about that request.", "The support team sets the category and priority and assigns it to a person.", "You and the team talk through comments on the ticket (or by email). Files can be attached.", "The ticket is marked resolved, then closed."]}, {"tip": "If a menu item or button you expect is missing, your role doesn't include it. Ask your ITOps administrator; they manage access under Administration \u2192 Roles & Permissions."}]}, {"title": "About ITOps\u2060: ownership and license", "for": "everyone", "body": [{"p": "ITOps\u2060 is an IT Operations Management Platform. It is designed, developed and owned by Indisse-BTS, drawing on 30 years managing IT operations for multiple companies in Puerto Rico and Florida."}, {"p": "ITOps\u2060 is an independent product. It was developed by its owner as an independent developer, not as an employee, contractor or consultant of any company or organization, and it is not a work made for hire for any organization that uses it. Using it, testing it or asking for features gives no organization any ownership of it."}, {"p": "\u00a9 2026 Indisse-BTS. All rights reserved. ITOps\u2060 is proprietary software: it is licensed, not sold. Your organization uses it under the ITOps\u2060 Terms of Use and, where it has one, its own written license agreement with the owner."}, {"bullets": ["The name people see in the app can be your organization's own (Settings \u2192 Branding). The product, its owner and these notices stay as they are.", "Your organization owns its own data. The owner of ITOps\u2060 claims no right to it.", "A license does not transfer ownership of the software, its source code, design, database structure, documentation, or any change made to it.", "Unless your license agreement allows it in writing: no copying beyond the licensed installation and its backups, no redistribution, resale or hosting for others, no reverse engineering, and no removal of these notices.", "Names of other products (for example Microsoft 365 or vTiger) only identify the services ITOps\u2060 connects to. They belong to their owners and imply no affiliation or endorsement."]}, {"p": "Terms of Use: the first time you sign in, the app shows the Terms of Use with \u201cI agree\u201d and \u201cSign out\u201d, and the app opens once you agree. They are also accepted once for the whole organization, by a person whose role may do it (for now: Super Admin; Roles & Permissions \u2192 \u201cTerms of Use \u00b7 accept for the organization\u201d). Each acceptance is recorded with the date, the time and the version, and the Terms of Use page lists who has accepted (for the people who manage users). Read them again at any time from the Help Center: the \u201cTerms of Use\u201d button at the top."}, {"p": "About & ownership (the button at the top of the Help Center): everyone sees who owns the product, that it is licensed and to which organization. The license details (the agreement, its term, modules and users, the license terms, the installation ID, LICENSE.txt and the third-party components) are shown to the roles your organization gave \u201cLicense details\u201d (Administration \u2192 Roles & Permissions). Nothing on these pages can be changed in the app."}]}, {"title": "Signing in", "for": "everyone", "body": [{"p": "You sign in to ITOps with your work email and password, or with your Microsoft 365 account if your organisation has turned that on."}, {"steps": ["Open the ITOps link your administrator gave you.", "Type your email and password and choose \"Sign In\".", "Or, if you see \"Sign in with Microsoft 365\", choose it and pick your work account at the Microsoft prompt.", "If your account uses two-factor authentication, a \"Two-step verification\" box appears. Type the 6-digit code from your authenticator app and choose \"Verify\". Lost your phone? Choose \"Use a backup code instead\".", "If your organisation requires two-factor and you haven't set it up yet, you'll be asked to do it now before you can continue."]}, {"h": "Limits that protect your account"}, {"p": "Your session lives in a protected browser cookie that the page itself cannot read; nothing about your sign-in is kept in the browser's storage."}, {"bullets": ["After 8 wrong passwords within 15 minutes for the same account (from anywhere), or 30 wrong passwords from the same network for any accounts, you'll see \"Too many failed attempts. Please wait about 15 minutes and try again.\" Attempts sent at the same moment are taken one at a time.", "You have 10 minutes to enter your 2FA code after your password. After that, sign in again.", "A 2FA code works once. If a code was just used (or refused), wait for the next one in your authenticator app.", "6 wrong 2FA codes within 15 minutes pauses 2FA sign-in for about 15 minutes.", "ITOps signs you out after a period with no mouse or keyboard activity (30 minutes unless your administrator changed it). A warning appears about a minute before. The server ends the session too, so a tab left open does not stay signed in."]}, {"qa": [{"q": "I forgot my password. Is there a reset link?", "a": "No. ITOps has no self-service password reset. Ask your ITOps administrator to set a new one for you. If you normally use \"Sign in with Microsoft 365\", reset your Microsoft password the usual way instead."}, {"q": "It says \"Invalid email or password\" but I'm sure it's right.", "a": "Check for typos and Caps Lock. The same message appears if your account is inactive or was set up for Microsoft sign-in only; your administrator can check."}, {"q": "I don't see \"Sign in with Microsoft 365\".", "a": "Microsoft sign-in hasn't been set up for your organisation. Use your email and password."}]}, {"p": "Administrators: set a new password under Administration \u2192 Users \u2192 edit the user \u2192 \"Password\".", "mod": "users:edit"}]}, {"title": "Turning on two-factor authentication (2FA)", "for": "everyone", "body": [{"p": "Two-factor authentication adds a second check when you sign in with a password: a 6-digit code from an authenticator app on your phone. Use it to protect your account; your organisation may require it."}, {"steps": ["Click your name at the top right to open \"My profile\".", "Under \"Two-factor authentication\", choose \"Set up 2FA\".", "Open an authenticator app (Microsoft Authenticator, Google Authenticator, 1Password and similar) and scan the QR code. If you can't scan, type the \"Manual key\" shown under it.", "Type the 6-digit code the app shows and choose \"Verify & turn on\".", "ITOps shows 10 backup codes (like AB12-CD34). Choose \"Copy codes\" and store them somewhere safe, then choose \"Done\". They are not shown again."]}, {"p": "From then on, after your password you'll be asked for a code. Each backup code works once, in place of an app code."}, {"h": "Moving to a new phone or turning it off"}, {"steps": ["Open \"My profile\" and choose \"Turn off\" next to \"On \u2014 codes from your authenticator app\".", "Enter a current 6-digit code, or your password, and confirm. Your old backup codes stop working.", "Choose \"Set up 2FA\" again on the new phone. You get a fresh set of backup codes."]}, {"warn": "If your organisation requires 2FA, turning it off means you'll be asked to set it up again the next time you sign in."}, {"qa": [{"q": "I lost my phone and my backup codes.", "a": "Ask a Super Admin to reset your 2FA. You can then sign in with just your password and set it up again."}, {"q": "I sign in with Microsoft 365 and there's no \"Set up 2FA\" button.", "a": "Your second step is handled by Microsoft, so My profile says it's managed by your organisation's Microsoft account."}, {"q": "My code is always rejected.", "a": "Make sure the time on your phone is set automatically. Codes change every 30 seconds."}]}, {"p": "Super Admins: to reset someone's 2FA, open the person in Administration \u2192 Users and choose \"Reset 2FA\" under \"Two-factor authentication\" (it shows whether their 2FA is on). To require 2FA, go to Administration \u2192 Settings \u2192 General \u2192 Session security \u2192 \"Require two-factor authentication for\" and choose \"Admins only (Super Admin & Dept Admin)\" or \"All password (local) users\". Microsoft 365 sign-in users are always exempt.", "mod": "settings:edit"}]}, {"title": "My profile: password, two-factor and where you are signed in", "for": "everyone", "body": [{"p": "My profile holds your personal settings. Open it by clicking your name (with your initials) at the top right. It is a page of its own."}, {"bullets": ["Your details: name, email, role, department, how you sign in, your last sign-in. The role and department are set by an administrator.", "\"My name\": change your display, first and last name (accounts that sign in with email and password). Accounts that sign in with Microsoft 365 get their name from Microsoft.", "\"Password\": change your own password (see below).", "\"Two-factor authentication\": set it up, see that it is on, or turn it off. See \"Turning on two-factor authentication (2FA)\".", "\"Where you are signed in\": every browser and device signed in to your account, with its address and when it was last used. \"Sign out\" ends one; \"Sign out of the others\" ends all but this browser.", "\"Recent activity\": your last sign-ins and password changes. Something you don't recognise? Change your password, sign out of the other devices and tell IT.", "\"Preferences\": the language of the emails ITOps sends you, and light or dark mode."]}, {"h": "Changing your password"}, {"steps": ["Open My profile \u2192 \"Password\".", "Type your current password, then the new one twice.", "The new password needs at least 12 characters, a letter and a number, and must not contain your name, your email or a common word. The list under the fields turns green as each rule is met.", "Click \"Change password\". You are signed out everywhere else; this browser stays signed in."]}, {"p": "After five wrong current passwords, changing it waits about 15 minutes. If you sign in with Microsoft 365, your password is changed in Microsoft (myaccount.microsoft.com)."}, {"qa": [{"q": "I only see the two-factor section and a notice.", "a": "Your organisation requires 2FA and you haven't set it up. Finish the setup and the rest of ITOps opens."}, {"q": "Emails still arrive in the wrong language.", "a": "Check the email language in My profile \u2192 Preferences. \"Organisation default\" follows the setting your administrator chose."}, {"q": "I forgot my password.", "a": "Ask your ITOps administrator to set a new one (Administration \u2192 Users). Every session you have open ends when they do."}]}, {"p": "Administrators can also set a user's email language and password under Administration \u2192 Users. Super Admins reset someone's 2FA on that person: Administration \u2192 Users \u2192 open the person \u2192 \"Reset 2FA\".", "mod": "users:edit"}]}, {"title": "Finding your way around", "for": "everyone", "body": [{"p": "This topic explains the screen layout so you can find things quickly."}, {"h": "The left menu"}, {"bullets": ["Dashboard is always at the top, with \"Announcements\" right under it (a red number shows how many are new or waiting for your confirmation). Below them are groups: Service Desk, Knowledge, Assets & Vendors (Equipment, Credentials, Contracts, Invoices, IT Budget, Vendors), Microsoft 365 (Home, People \u2014 including onboarding and offboarding \u2014, Email, Devices, Licenses, Security, Posture, Collaboration & activity), IT Operations (Server Guardian, Server performance, Uptime, Backups), Administration (users, roles, categories, forms, import, onboarding templates, Settings) and Logs & Integrations (What's New first, then audit and event logs, integrations and Integration Audit). Click a group to open it.", "You only see the items your role allows. If you open a page you can't use, you'll see \"No access\" and a \"Back to Dashboard\" button.", "Click the logo or the menu icon (three lines) to shrink the menu to icons. On a phone, the menu icon opens and closes it."]}, {"h": "The top bar, left to right"}, {"bullets": ["The page name, then the search box \"Search tickets, KB, SOPs\u2026\". Type 2 or more letters to search tickets, articles, SOPs, vendors and contracts you're allowed to see. Choosing a result opens that page.", "The bell: your notifications, with a red count of unread ones. See \"Your notifications (the bell)\".", "Your name: opens Account (email language, 2FA, sign out).", "The camera: \"Capture\" a photo, video or screenshot and attach it to a ticket.", "The question mark: opens this Help Center in a side panel. The \u2197 button opens it in a full page.", "The half-moon: switches between light and dark mode.", "The door: signs you out."]}, {"tip": "A coloured banner across the top of the page is a short notice from your administrators, for example planned maintenance. A bar that says an announcement is waiting takes you to the Announcements page."}, {"p": "For your security, ITOps signs you out after a period with no activity (30 minutes unless changed). Anything you haven't saved is lost, so save forms before you step away."}, {"p": "Administrators set the idle sign-out time in Administration \u2192 Settings \u2192 General \u2192 Session security \u2192 \"Idle timeout (minutes)\", then \"Save\".", "mod": "settings:edit"}, {"h": "Dropdown lists"}, {"p": "Every dropdown list in ITOps looks and works the same way, on every computer and browser \u2014 in the app, on the public help and form pages, and in the separate editor window. Click the field to open the list and click a choice. The current choice is highlighted."}, {"bullets": ["The list always opens on top of the page, so a table or a panel never cuts it off. Near the bottom of the window it opens upward.", "Keyboard: move to the field with Tab, then \u2193 or \u2191 opens the list and moves through it; Home and End jump to the first and last choice; Enter or Space chooses; Esc closes without changing anything.", "Type the first letters of a choice to jump to it \u2014 handy in long lists such as people or roles.", "A click anywhere else, or scrolling the page, closes the list without changing the choice.", "A greyed-out dropdown cannot be changed right now, usually because something else on the screen has to be chosen first or your role does not allow it."]}, {"h": "Previews and times"}, {"bullets": ["Every report or document made in the newer areas (IT Budget, the budget document, Calendar reports, Uptime reports, the branding sample) opens as a preview first. Check it, then download it from the preview as PDF, Word or CSV. Previews are written to the Audit Log as previews; downloads as exports.", "All times are shown in the installation's time zone (Settings \u2192 General \u2192 Time zone) in 12-hour format with AM and PM \u2014 for example 10/10/2026 2:05 PM."]}]}, {"title": "Your notifications (the bell)", "for": "everyone", "body": [{"p": "The bell at the top right collects short in-app messages about things that need your attention, so you don't have to rely on email."}, {"h": "What you might see"}, {"bullets": ["\"New comment\": someone commented on a ticket you opened or are assigned to. It shows the ticket number and the start of the comment.", "\"Ticket assigned to you\": you are the new assignee of a ticket.", "\"Update \u00b7 TK-\u2026\" or a custom title: a support agent sent you a message about a ticket with the Notify button.", "\"Response SLA due soon\", \"Resolution SLA breached\" and similar: a ticket you are assigned to is close to, or past, its target time.", "Procedure reminders such as \"Please acknowledge SOP: \u2026\", signature requests, equipment return requests and overdue loans, and onboarding task reminders.", "Announcements sent to you, and reminders for the ones you have not confirmed. Clicking one opens the Announcements page."]}, {"h": "Using it"}, {"steps": ["Click the bell. Unread items are highlighted and listed first (the latest 50 are shown).", "Click an item to mark it read and jump to the related page, for example Tickets. Then open the ticket from the list.", "Choose \"Mark all read\" to clear the red count."]}, {"p": "The bell checks for new items every minute and each time you open it."}, {"qa": [{"q": "I replied by email but the assignee says they got no alert.", "a": "Email replies are added to the ticket, but they don't create a bell notification. For anything urgent, add a comment in the app instead."}, {"q": "Clicking a notification doesn't open the ticket itself.", "a": "It opens the Tickets page. Find the ticket number from the notification in the list."}]}]}, {"title": "Announcements: reading and confirming", "for": "everyone", "body": [{"p": "\"Announcements\" (second item in the menu, under Dashboard) holds the messages your organization sends to you: closures, maintenance, policy changes and similar. The same announcement may also reach you by email and in a Teams channel, but this page is where it always is."}, {"h": "How you notice a new one"}, {"bullets": ["A red number next to \"Announcements\" in the menu.", "An entry in the bell (top right). Click it to open the page.", "A bar across the top of every page when an announcement is waiting for your confirmation, or is urgent and you have not opened it. Click \"Open \u2192\".", "An email with the full text and an \"Open it in ITOps\" link, when the sender chose email.", "A card in your team's Teams channel, when the sender chose a channel."]}, {"h": "Reading and confirming"}, {"steps": ["Open \"Announcements\". What still needs you is listed first; a \"New\" tag marks the ones you have not seen. Opening the page records them as opened.", "Some announcements ask you to confirm. Read it, then click \"\u2713 I have read this\". The page then shows \"You confirmed on\u2026\" and the reminders stop.", "\"Earlier announcements\" at the bottom keeps the ones that ended or were archived."]}, {"bullets": ["The label shows how important it is: \"Announcement\", \"Important\" or \"Urgent\".", "If your email language is Spanish and the sender wrote a Spanish version, you see and receive that one. Set your language under your name (top right) \u2192 My profile.", "Until you confirm, you may get reminders in the bell and by email."]}, {"qa": [{"q": "I read it in my email (or in Teams). Do I still have to confirm?", "a": "Yes, when it asks for a confirmation. Use the link in the email or the card, sign in if asked, and click \"\u2713 I have read this\" on the Announcements page."}, {"q": "A colleague got an announcement and I did not.", "a": "Announcements can be sent to selected departments, roles or people. You only see the ones sent to you."}, {"q": "I confirmed by mistake.", "a": "A confirmation can't be undone. Tell the person who published it."}]}]}, {"title": "Getting help", "for": "everyone", "body": [{"p": "Use this Help Center first. If it doesn't answer your question, raise a ticket so the right person can help."}, {"bullets": ["In ITOps, click the question mark in the top bar to open the Help Center beside your work.", "Use the search box at the top of the Help Center to jump to any topic.", "The Help Center only shows topics for the features your role can use. If you aren't signed in you see the general topics; sign in to see the rest.", "The full User Guide, the Administrator Guide and the quick starts are Word files your IT team keeps outside the app. Ask them for a copy."]}, {"p": "Your team's own articles (for example how to connect to the office Wi-Fi) are in Knowledge \u2192 Knowledge Base. Search them with the top search box.", "mod": "kb"}, {"p": "Knowledge \u2192 Ask IT lets you type a question in plain words (for example \"I can't get my email on my phone\") and choose \"Send\". It answers from the published Knowledge Base.", "mod": "kb_assist"}, {"p": "Still stuck? Create a ticket in Service Desk \u2192 Tickets \u2192 \"+ New Ticket\", or use the request form or help-desk email address your team shared."}]}, {"title": "How New and Edit screens open", "for": "everyone", "body": [{"p": "When you create, edit or open a record (a ticket, an equipment item, a loan, a vendor, a policy, a finding and so on), it opens as a full page in place of the list. Nothing pops up over the screen."}, {"bullets": ["\"\u2190 Back\" (or \u2715) at the top returns you to the list exactly as you left it: the same filters, search and scroll position.", "Save and Cancel are always reachable: in the bar at the top next to \"\u2190 Back\", or pinned to the bottom of the screen on longer forms.", "Some screens lead to another one. For example, an equipment item's page has \"Loan this item\". The new page replaces it, and \"\u2190 Back\" returns to the item.", "Small questions still appear as a box: \"Are you sure?\" confirmations, file uploads, a one-time password or Temporary Access Pass that is shown only once, and choosing an icon."]}, {"h": "A list and the record side by side"}, {"p": "A few screens keep the list in sight while you work on one record:"}, {"bullets": ["Microsoft 365 \u2192 People: the account opens in a panel over the right part of the list, below the tabs. \"Edit Microsoft 365 info\" opens inside the same panel.", "Administration \u2192 Onboarding Templates: the templates are listed on the left, the one you work on is on the right.", "Logs & Integrations \u2192 What's New: the builds on the left, the notes of the one you pick on the right.", "When something was changed and not saved, opening another record or closing asks first: \"Leave without saving\" or \"Keep editing\".", "On a narrow screen or a phone the record takes the whole width, with a button to go back to the list."]}, {"h": "\"About this screen\""}, {"p": "Many screens have a round \u24d8 \"About this screen\" button in the top bar, next to the page title. Click it to read what the screen does, what it needs and what to expect. It opens over the page and never pushes the screen down; a click anywhere else or Esc closes it. When something the screen needs is missing, the button says so in red (\"1 missing\") without being opened. On a narrow screen only the \u24d8 is shown."}]}, {"title": "Using ITOps on a phone", "for": "everyone", "body": [{"p": "ITOps works in the phone browser. The menu icon (three lines) opens the left menu; tap a group, then a page."}, {"bullets": ["Every New, Edit and detail screen opens as a full page (see \"How New and Edit screens open\"). The Save / Cancel buttons stay on screen while you scroll: in the bar at the top next to \"\u2190 Back\", or pinned to the bottom of the screen for longer forms such as tickets and equipment.", "On the Tickets page the category panel starts collapsed on a phone. Tap the small arrow at the top left of the list to open it.", "On a narrow screen the top bar shows only the menu, search, notifications, your avatar, Capture and Help. Tap your avatar to switch light/dark mode or to sign out.", "If a button is still hidden behind the browser bar, scroll a little: the page fits itself to the visible area on current iPhone and Android browsers."]}]}, {"title": "Using ITOps inside Microsoft Teams", "for": "everyone", "body": [{"p": "If your organization added ITOps to Teams, you can use it without leaving Teams and without signing in: Teams tells ITOps who you are. Everything also keeps working in your browser, exactly as before."}, {"h": "Opening it"}, {"steps": ["In Teams, look for ITOps in the bar on the left (or under \"\u2026\" \u2192 more apps, where you can right-click it and choose \"Pin\").", "Click it. The first time, Teams may ask you to allow the app to use your account: accept. You are then signed in automatically.", "The app has two tabs at the top: the whole of ITOps, and \"Announcements\"."]}, {"h": "Notifications in Teams"}, {"bullets": ["New announcements (and, if your administrators switched them on, ticket updates and alerts) also appear in your Teams \"Activity\" feed. Click one to open the matching page inside Teams.", "The bell inside ITOps still holds everything. Teams notifications arrive a few minutes after the bell.", "An announcement posted in a Teams channel has a button that opens the Announcements page inside Teams, where you click \"\u2713 I have read this\".", "To mute them: Teams \u2192 Settings \u2192 Notifications and activity."]}, {"h": "What is different inside Teams"}, {"bullets": ["There is no sign-out button: you are signed in as the person signed in to Teams.", "If automatic sign-in does not work, a message at the top says why and the normal email and password form is shown. \"Sign in with Microsoft\" is not offered there; use it in the browser.", "Links to other sites open in your browser. If a download (CSV, PDF) does not start inside Teams, open ITOps in your browser for that step."]}, {"qa": [{"q": "I do not see ITOps in Teams.", "a": "It has not been added for you yet, or the change has not reached your Teams (it can take a few hours). Search for it under Apps, or ask IT."}, {"q": "It says \"Automatic sign-in from Teams did not work\".", "a": "Click \"Try again\". If it keeps failing, send the message to IT: it names the cause. You can still sign in with your email and password, or use the browser."}, {"q": "Does ITOps see my computer through Teams?", "a": "No. It only records which operating system and Teams client you opened it with, like any website can see, so IT knows what kinds of devices are in use."}]}]}, {"title": "Visual guides (interactive pages in the Help Center)", "for": "everyone", "body": [{"p": "Some people see a box \"Visual guides\" at the top of the Help Center. It holds interactive pages that show how the company\u2019s systems fit together, for example \"Company systems: the whole process\" and \"Integration map\". They are given to some roles and to some people, not to everyone."}, {"steps": ["Open the Help Center (the ? in the top bar).", "Under \"Visual guides\", click a page. It opens over the Help Center.", "Drag the picture to turn it; click a system or a step to read about it. The same facts are in tables under the picture.", "\"Light\" and \"Dark\" in the bar over the page switch its theme. The first time it follows the theme of the app; your choice is remembered on this computer.", "\"Full screen\" uses the whole screen; \"\u2715 Close\" or Esc closes the page."]}, {"qa": [{"q": "I do not see \"Visual guides\".", "a": "None of these pages has been given to your role or to you. Ask a Super Admin if you need one."}, {"q": "A colleague sees a page I do not.", "a": "Each page is given separately, to roles and to people. Ask a Super Admin."}, {"q": "Can I send someone the link?", "a": "The link opens the page only for people it was given to. Others get \"This page has not been given to you\"."}, {"q": "Why do both pages show the same systems?", "a": "They draw from one list, so they always agree. A system switched on under Settings \u2192 Company systems, or added there, shows on both pages by itself; one that is not used is marked \"not switched on here\"."}, {"q": "What does the ring under a system mean?", "a": "How ITOps works with it: green, ITOps acts in it by itself; teal, connected and read; purple, tracked by hand (a person does the work there and answers in ITOps); amber, planned and not in use yet; grey, no connection (it follows Microsoft 365 by itself)."}]}]}]}, {"cat": "Tickets & support", "topics": [{"title": "How support works (the flow)", "for": "everyone", "body": [{"p": "Every request for help becomes a ticket with its own number, so it can be tracked from the moment it arrives until it's closed. This topic explains each step and what you'll see."}, {"steps": ["Arrives. You create a ticket in the app, submit the \"Submit a Help Request\" page or another request form, or email the help-desk mailbox. Web page, form and email requests get a \"Request received\" email with the ticket number (if your organisation has these emails on).", "Numbered. Each ticket gets a number like TK-2026-0142. Quote it whenever you contact the team.", "Triaged. The support team checks the category and priority. The priority is how urgent it is: Critical, High, Medium or Low.", "Assigned. A support agent becomes the ticket's assignee. They get a bell notification and an email.", "Worked. The status moves to \"in progress\". The agent may ask you questions in a comment. If they are waiting on you or someone else, the status becomes \"pending\".", "Resolved. When it's fixed the status becomes \"resolved\". You may get a \"Resolved / closed\" email.", "Closed. The ticket is finished. A ticket that won't go ahead is set to \"cancelled\" instead."]}, {"h": "What you do along the way"}, {"bullets": ["Answer questions quickly. A comment in the app notifies the assignee straight away.", "Add screenshots, photos or recordings; they save a lot of back-and-forth.", "If a resolved ticket isn't really fixed, reply to it (in the app or to the email) rather than opening a new one. Your reply reopens it."]}, {"p": "Agents: every new ticket, whether created in the app or arriving by email, the public page or a form, gets automatic response and resolution due times (see \"Due dates, SLAs and business hours\").", "mod": "tickets:all"}]}, {"title": "Asking for help without signing in (web page, form or email)", "for": "everyone", "body": [{"p": "You can raise a request without an ITOps account. Use the \"Submit a Help Request\" page, a request form, or the help-desk email address, whichever your team shared with you."}, {"h": "The \"Submit a Help Request\" page"}, {"steps": ["Open the link. Enter \"Your name\" and \"Email\" (email is required so we can reply).", "Pick a \"Category group\" and \"Category\" if you see them.", "Type a short \"Subject\" and a \"Description\": what's happening, any error message, and when it started.", "As you type, ITOps may show \"These help articles might answer your question\". Click one to read it. If it fixes the problem, choose \"This solved it \u2014 no ticket needed\".", "Otherwise choose \"Submit request\". You'll see \"\u2713 Request received\" and your ticket number. Save it."]}, {"p": "This page has no attachment option. If you need to send a file, use a request form that has an upload field, or ask the team to add it to your ticket."}, {"h": "Request forms"}, {"p": "Some forms create a ticket when you submit them. They may include file, photo, video or screen-recording fields. Uploads can be images (PNG, JPEG, GIF, WebP), video (MP4, MOV, WEBM), audio (WEBM, OGG, MP3, M4A, WAV) or PDF, up to 25 MB each."}, {"h": "By email"}, {"p": "Send an email to the help-desk mailbox. A new message becomes a new ticket, with your email subject as the ticket subject. To add to an existing ticket, reply keeping the TK- number in the subject line."}, {"warn": "Files attached to emails are not saved to the ticket. Only the text of your message is added."}, {"tip": "Use your work email address. On the page and the forms, if the address belongs to an ITOps account, you get an email \"Please confirm your request\": open it and choose \"Yes, I sent this request\" and the ticket is filed under your account (sign in and it is in Service Desk \u2192 Tickets). Until then it is kept as from an outside person \u2014 so nobody can file requests in your name by typing your address. By email, the ticket is filed under your account at once. If you only get an account later, your earlier tickets move to it the first time you sign in."}, {"p": "The \"Request received\" email repeats your subject without any web links or addresses (they show as [link removed]); the ticket keeps your subject as you typed it. Files you attach to a form are kept with the ticket and opened by the team inside the app; a file you uploaded but never sent is deleted after 24 hours."}, {"qa": [{"q": "I didn't get a confirmation email.", "a": "Check your junk folder. Confirmation emails only go out if your organisation has them switched on; the ticket number shown on screen is still valid."}, {"q": "It says \"Too many submissions\".", "a": "The page accepts up to 5 requests from the same network in 10 minutes. Wait a few minutes and try again."}]}]}, {"title": "Creating a ticket inside the app", "for": "everyone", "mod": "tickets:create", "body": [{"p": "Create a ticket in ITOps when you are signed in and need help from IT or Operations. You can then follow it and add files."}, {"steps": ["Go to Service Desk \u2192 Tickets and choose \"+ New Ticket\".", "\"Subject\": choose the group that fits best (for example the area of the problem). The ticket's subject line is set to that group's name.", "\"Category\": choose the specific category within that group.", "\"Priority\": leave \"Medium\" unless it really is \"High\" or \"Critical\" (for example many people can't work). \"Low\" is for things that can wait, and \"Planning\" for scheduled work.", "\"Description\": explain what you need or what's wrong, any error message, when it started, and what you've tried. This is where the detail goes.", "The due times are set automatically from the SLA, and the owner from the category's routing. The help desk (Tickets \u00b7 All) can also choose the owner, the requester and the due times.", "Choose \"Create Ticket\"."]}, {"h": "What happens next"}, {"bullets": ["The ticket appears in your list with a number like TK-2026-0142, status \"open\".", "No confirmation email is sent for tickets created in the app; the ticket in your list is your record.", "If an assignee was chosen, they get a bell notification and an email.", "To add a screenshot or document, open the ticket and use \"Upload\". You can only attach files after the ticket is created.", "Without Tickets \u00b7 All you file tickets in your own name. On a ticket you asked for you can change the subject and the details, or cancel it; the help desk changes the priority, owner and due times. The ticket number is never changed."]}, {"qa": [{"q": "The \"Category\" list says \"Choose a subject first\".", "a": "Pick a \"Subject\" group first; its categories then appear."}, {"q": "I get \"Subject is required\".", "a": "Choose a group in the \"Subject\" list."}, {"q": "I don't see \"+ New Ticket\".", "a": "Your role can view tickets but not create them. Use the request form or email, or ask your administrator."}]}, {"p": "Agents: the priority and category set the automatic due times when the ticket is created. Changing them later doesn't recalculate the due times; edit \"Response due\" / \"Resolution due\" yourself if needed.", "mod": "tickets:all"}]}, {"title": "Finding and following your tickets", "for": "everyone", "mod": "tickets", "body": [{"p": "This topic shows where to see the tickets you raised, check their progress and pick up replies."}, {"h": "Where your tickets are"}, {"bullets": ["Dashboard \u2192 \"My Tickets\": your 8 most recent tickets with their status. Click one to open it.", "Service Desk \u2192 Tickets: every ticket you opened or that is assigned to you, newest first. Columns: Number, Subject, Priority, Status, Requester, Assignee and SLA.", "A link in a ticket email (\"Open TK-\u2026 in ITOps\") opens that ticket directly, after you sign in if needed.", "The bell: \"New comment\" tells you someone replied."]}, {"h": "Narrowing the list"}, {"bullets": ["The first drop-down chooses whose tickets: \"All my tickets\", \"Opened by me\" (requests you raised) or \"Assigned to me\" (work someone gave you).", "The second drop-down chooses the status: \"Any status\", \"Still open\" or \"Resolved / closed\".", "The search box (\"Search number, subject, person\u2026\") filters as you type: ticket number, subject, description, category, requester or assignee.", "The \"Categories\" panel on the left shows one group at a time; click it again (or \"All\") to clear. The arrow button hides the panel.", "The refresh button (circular arrow) reloads the list."]}, {"h": "Inside a ticket"}, {"p": "Click a row to open it. You'll see the number, subject, priority and status, your description, the response and resolution due badges, the category, department, requester and assignee, then \"Attachments\" and \"Activity & Comments\". \"Close\" returns to the list."}, {"qa": [{"q": "I can't see a ticket a colleague raised for me.", "a": "You only see tickets where you are the requester or the assignee. Ask the agent to check who is set as the requester."}, {"q": "An older ticket isn't in the list.", "a": "Set the filters to \"All my tickets\" and \"Any status\", then type its TK- number in the search box. If it came from an email or form you sent before you had an ITOps account, it appears once you sign in with that same email address."}, {"q": "I don't see the edit (pencil) or \"Delete\" buttons.", "a": "Your role lets you view and comment but not change or delete tickets, so those buttons are hidden. That's normal for most staff; use a comment to ask for changes."}]}, {"p": "Agents see every ticket in this list and have more filters (\"Mine\", \"Unassigned\", \"Assigned to \u2026\"); see \"Working the queue: filters, assigning and tracking\".", "mod": "tickets:all"}]}, {"title": "Priority and status explained", "for": "everyone", "mod": "tickets", "body": [{"p": "Every ticket has a priority (how urgent) and a status (where it is in the process). Here is what each one means for you."}, {"h": "Status"}, {"bullets": ["open: received, not yet being worked on.", "in progress: someone is working on it.", "pending: on hold. The ticket says what it is waiting on. When it says \"waiting on you\", the team needs your reply before it can carry on.", "resolved: the team believes it's fixed; the email says what was done. If it isn't, reply in the app or to that email within the business days it mentions and the ticket reopens. Otherwise it closes on its own.", "closed: finished. A reply no longer reopens it: open a new request if you need more help.", "cancelled: not going ahead, for example a request that was withdrawn, or a duplicate merged into another of your tickets (it then says where it continues)."]}, {"h": "Priority"}, {"bullets": ["Critical (P1): a whole service is down or a security incident is under way; many people or a critical part of the work are stopped and there is no workaround. Examples: email or the internet down for everyone at a site, ransomware, the payroll system unavailable when it is needed.", "High (P2): a key service is badly degraded, or a whole team (or one person with an urgent deadline) cannot work, with no reasonable workaround. Examples: the VPN failing for all remote staff, a director's laptop dead an hour before a board meeting.", "Medium (P3): one person or a small group is affected and can carry on with a workaround. The usual priority for a fault. Examples: one shared drive not opening, Outlook closing on one computer.", "Low (P4): a small problem, a question or a request with little effect on the work; it can wait. Examples: a second monitor, a how-to question.", "Planning (P5): planned work with a date agreed in advance; nothing is broken. Examples: a computer for a start date two weeks away, an office move."]}, {"p": "The rule behind it: priority = impact (how many people are affected) \u00d7 urgency (how quickly it hurts the work). When you create a ticket, the line under \"Priority\" says what the chosen priority means, its target times and examples; \"What do the priorities mean?\" shows all five. Your organization can adjust these words in Settings \u2192 SLA & Hours, so the form may say something slightly different from the examples here."}, {"h": "The due-time badges"}, {"p": "Inside a ticket you may see \"Response: \u2026\" and \"Resolution: \u2026\" badges, for example \"Due 3h\" or \"Met\". They show the team's target times for first replying and for fixing the ticket. \"Paused\" means the ticket is pending."}, {"p": "Agents: keep the status accurate. Moving a ticket off \"open\" records the first response. \"pending\" asks what the ticket is waiting on (the requester, a vendor, an approval or something else) and pauses the SLA clock until the ticket leaves it. \"resolved\" and \"closed\" need a resolution note (what was done); it stops the resolution clock and goes to the requester in the Resolved email. A reply from the requester reopens a resolved ticket; reopening starts the clock again. For badge colours, see \"Due dates, SLAs and business hours\".", "mod": "tickets:all"}, {"h": "Type: incident or service request"}, {"p": "Each ticket is also an incident (something is broken or not working) or a service request (something is asked for). It comes from the category you choose, and the help desk can change it. Incidents can have faster targets. See \"Incident or service request: the ticket type\"."}]}, {"title": "Incident or service request: the ticket type", "for": "everyone", "mod": "tickets", "body": [{"p": "Every ticket is one of two types. An incident: something is broken or not working as it should (\"the VPN keeps dropping\"); the goal is to restore the service quickly. A service request: someone asks for something standard (\"a laptop for a new hire\", \"access to a folder\"); the goal is to deliver it as agreed."}, {"p": "You never have to choose: each category says which type its tickets are (for example \"VPN Issue\" is an incident, \"Hardware Request\" a service request), and a new ticket takes its category's type, from the app, the public request page, forms and email alike."}, {"bullets": ["The help desk sees the type under each ticket number, can filter the list to incidents, service requests or major incidents, and can change the type on a ticket (Edit \u2192 Type). Changing it recalculates the due times when incidents have their own targets.", "Administrators set the type of each category (Ticket Categories \u2192 the category \u2192 Type of ticket) and, if wanted, faster priority targets for incidents (Settings \u2192 SLA & Hours \u2192 Incidents and satisfaction).", "Reports shows incidents and service requests side by side: how many, how many met the resolution target and how long they took."]}]}, {"title": "Major incidents: when many people are affected", "for": "everyone", "mod": "tickets", "body": [{"p": "A major incident is an outage that affects many people or a critical service: email down for an office, the VPN down for everyone at home. It is handled differently from a regular ticket: one person in charge, regular updates to everyone affected, and a review afterwards so it does not happen again."}, {"h": "Running one (help-desk leads)"}, {"steps": ["Open the first ticket about it and choose \"Declare major incident\u2026\". Write in one line what is down (everyone affected sees these words) and leave \"Show a banner to everyone\" ticked so people do not report it again. The ticket becomes Critical and the alert list is told at once.", "Link every other ticket about the same outage: type its number under \"Affected tickets\", or, on that ticket, choose \"Link to a major incident\u2026\". Anyone who edits tickets can link.", "Send updates with \"Send to everyone affected\": each one goes as a reply on every linked ticket and by email to each requester. Say what is known, what is being done and when the next update comes.", "Resolve the major ticket with a resolution note when the service is back. Every linked ticket that is still open is resolved with the same note and its requester gets the Resolved email. The banner goes back to what it was.", "Write the review: what happened, the cause as far as it is known, and what will be done so it does not happen again. Tick \"Open a problem investigation\" to start a case that looks for the cause and fixes it for good (it needs Cases & Projects \u2192 Create)."]}, {"bullets": ["Declaring, updating, standing down and the review need someone who sees every ticket (Tickets \u2192 All records); linking needs Tickets \u2192 Edit.", "\"Not a major incident\u2026\" turns it back into a regular ticket (with a reason): the links go and so does the banner.", "Requesters only see that their ticket is part of a known outage and its one-line summary, never the other tickets or people affected.", "Everything is in the Audit Log: declared, linked and unlinked tickets, each update, resolved, stood down, the review and anything refused."]}, {"p": "After the review, \"Add to the improvement register\u2026\" records what will be done so it does not happen again as an improvement with an owner and a target date (see \"Improvements: the continual improvement register\")."}, {"p": "Several tickets about the same smaller problem (one printer, one app for a few people)? Link them as related tickets instead: see \"Related tickets: answering several at once\"."}]}, {"title": "Related tickets: answering several at once", "for": "everyone", "mod": "tickets:edit", "body": [{"p": "When several people report the same thing (the copier on the 3rd floor, a slow application, a bad update), link their tickets. Everyone then hears the same thing at the same time, and the tickets are resolved together. Unlike a major incident there is no banner and no lead: any agent can use it, for any priority."}, {"h": "Link the tickets"}, {"steps": ["Open one of the tickets. Under its details, in \"Related tickets\", click \"Link related tickets\u2026\".", "Optional: say what they are about (for example \"Copier on floor 3\"). That name shows on every linked ticket.", "Type a ticket number, words of the subject or the requester's name, tick the tickets and click \"Link\". Each ticket gets an internal note saying it was linked.", "Open any of them: the same list of related tickets is there. The \u2715 next to a ticket takes it out of the group (a group left with one ticket ends)."]}, {"h": "Answer them together"}, {"bullets": ["\"Reply to all linked\u2026\": the same public reply on each open linked ticket; each requester gets the usual reply email and the first response is recorded.", "\"Resolve all linked\u2026\": each open linked ticket is resolved with the same resolution note and each requester gets the usual Resolved email. Time spent in Pending stays out of the clock.", "Only the tickets you work on are touched: with Tickets \u2192 All records, all of them; otherwise the tickets you own or back up. A major incident (it has its own steps) and a ticket that closes with its case are left alone. The message after sending says which tickets were skipped and why."]}, {"bullets": ["Linking needs Tickets \u2192 Edit, and you can link only tickets you can open. Linking a ticket that is already in another group brings that whole group along.", "Everything is in the Audit Log: linked, taken out, renamed, each reply to all, each resolve all, and anything refused."]}, {"tip": "For an outage that stops many people (email down, the internet down at a site), declare a major incident instead: it adds the banner, the alert list and the review afterwards."}]}, {"title": "How did we do? Rating a resolved ticket", "for": "everyone", "mod": "tickets", "body": [{"p": "When your ticket is resolved, the Resolved email asks \"How did we do?\" with two links: happy with how it was handled, or not happy. The link opens a short page where you can add a comment and send. You can also answer on the ticket itself in the app, and change your answer later (up to 30 days after it was resolved)."}, {"p": "A \"not happy\" answer is read at once: the person who handled the ticket and the help-desk leads are told, and your comment is added to the ticket for the team. Answers are counted in Reports (Satisfaction), so the team can see what to improve."}, {"bullets": ["Only the person who asked can rate a ticket. Each email link belongs to one ticket and only lets someone rate that ticket.", "Administrators can switch the question off under Settings \u2192 SLA & Hours \u2192 Incidents and satisfaction. If you changed the Resolved email template, add {{csat_line}} where the links should go."]}]}, {"title": "Replying, commenting and attaching files", "for": "everyone", "mod": "tickets", "body": [{"p": "Comments are the conversation on a ticket; attachments hold screenshots, photos, documents and recordings. Use them to answer questions and give the team what they need."}, {"h": "Add a comment"}, {"steps": ["Open the ticket from Service Desk \u2192 Tickets (or Dashboard \u2192 \"My Tickets\").", "In \"Activity & Comments\", type in \"Add a comment\u2026\".", "Press Enter or choose \"Post\" (once: a second press while it is sending is ignored, and an empty comment is not sent)."]}, {"p": "Your comment appears with your name and time. The other people on the ticket (the requester and the assignee) get a \"New comment\" bell notification. If an agent comments, the requester may also get a \"Reply from the help desk\" email."}, {"h": "Attach a file"}, {"steps": ["Open the ticket and choose \"Upload\" next to \"Attachments\".", "Drag a file into the box, or choose \"Browse\".", "Wait for \"Uploaded\". The file is listed with its size and who added it."]}, {"bullets": ["One file at a time, up to 50 MB each. Accepted: pictures (PNG, JPG, GIF, WEBP, HEIC), audio and video, PDF, Word, Excel, PowerPoint, CSV, TXT, XML and JSON. Other types (for example .exe, .zip or web pages) are refused.", "Use the download icon to save a file, and the bin icon to remove one (removing needs Edit permission on tickets; on a ticket you only asked for, you remove the files you added). Files marked INTERNAL are for the support team only.", "The camera icon in the top bar (\"Capture\") takes a photo, a video, or a screenshot of the ITOps page. Choose \"\ud83d\udcce Attach to ticket\", search for your ticket and click it."]}, {"warn": "A normal comment is visible to the requester and may be emailed to them. Never post passwords, even in an internal note."}, {"qa": [{"q": "\"No file uploaded\" appears for a big file.", "a": "The server's own upload limit may be lower than 50 MB. Try a smaller file or a shorter recording."}, {"q": "Can I reply by email instead?", "a": "Yes. Reply to any ticket email and keep the TK- number in the subject. Only the text is added; email attachments are not saved. See \"Emails about your ticket\"."}]}, {"p": "Agents: tick \"Internal note\" under the comment box to write something only the support team sees. See \"Public replies, internal notes and EXT requesters\".", "mod": "tickets:all"}]}, {"title": "Categories and groups", "for": "everyone", "mod": "tickets", "body": [{"p": "Categories describe what a ticket is about. They're arranged in two levels: a group (for example \"Hardware\") and categories inside it (for example \"Laptop\" or \"Printer\")."}, {"bullets": ["A group is the broad area (for example \"Hardware Request\"). A category sits inside one group (for example \"Printer\"). A category never holds other categories.", "The in-app ticket form, the public request page and the forms all ask in the same order: \"Group\", then \"Category\".", "Not sure of the category? Pick only the group (\"Not sure (the group is enough)\"): the ticket is filed under the group and goes to the group's owner.", "In Service Desk \u2192 Tickets, the \"Groups\" panel on the left filters the list by group. An open ticket shows its group and its category."]}, {"h": "Why the category matters"}, {"p": "Each category can have its own target times for the first response and for resolution. When a ticket is created (in the app, by email or from a form), ITOps uses the category's targets if it has them, otherwise defaults for the chosen priority. Choosing the right category also keeps reports accurate. Categories don't assign tickets to anyone automatically; the support team does that."}, {"tip": "If nothing fits, choose the closest category and explain in the description. The support team can change it."}, {"h": "Managing categories", "mod": "categories:edit"}, {"steps": ["Go to Administration \u2192 Ticket Categories. The grid shows every group and category, one per row.", "Choose \"Add group\" or \"Add category\", type the name and press Enter. To add many at once, paste a list (one name per line) into the new row.", "Click any cell to change it: Group, Name, Ticket type, Response (h), Resolution (h), Owner, Backup, Order or Status. Enter saves, Tab moves right, Esc cancels. Leave the hours empty to use the priority targets."], "mod": "categories:edit"}, {"warn": "A group can't be deleted while it still has categories. Move or delete its categories first. Set a category to \"Inactive\" to hide it from the public page without losing history.", "mod": "categories:edit"}, {"tip": "The order of the groups and categories is set by your administrators (Ticket Categories \u2192 \u25b2 \u25bc), so the list looks the same on the public page, the forms and inside the app."}]}, {"title": "Working the queue: filters, assigning and tracking", "for": "everyone", "mod": "tickets:all", "body": [{"p": "This topic shows agents how to use Service Desk \u2192 Tickets as a work queue: find what needs doing, assign it, and keep it moving."}, {"h": "Filtering the queue"}, {"bullets": ["The first filter: \"All tickets\", \"Mine (opened by me or assigned to me)\", \"Assigned to me\", \"Opened by me\", \"Unassigned\", or \"Assigned to\" a named person. The second filter: \"Any status\", \"Still open\" or \"Resolved / closed\". The search box matches number, subject, description, category, requester and assignee.", "The \"Categories\" panel on the left filters by group; it combines with the assignee filter.", "The heading shows how many tickets match, for example \"12 tickets \u00b7 live\". Use the refresh button to reload after others make changes.", "The SLA column shows each ticket's resolution badge (see \"Due dates, SLAs and business hours\"). In the Requester column, \"EXT\" marks people outside ITOps.", "The list loads up to the 1,000 most recently created tickets, newest first, and the filters work on those. Use the top search box to find an older ticket by number or text."]}, {"h": "Changing tickets right in the list"}, {"bullets": ["Roles with Tickets Edit can change \"Priority\", \"Status\" and the owner (\"Assignee\") straight from the list: click the value, pick the new one, and it is saved at once. The row fades while it saves and a message confirms it.", "\"Take it\" under an unassigned ticket makes you the owner in one click.", "Tick the boxes at the start of the rows (or the box in the header for every ticket shown) to change several at once: the bar above the list offers \"Set status\u2026\", \"Set priority\u2026\" and \"Assign to\u2026\". You confirm first, then each ticket is updated and a message says how many worked.", "Inline changes do exactly what the ticket editor does: status emails, \"Assigned to an agent\" emails, the first-response time and the resolution clock all follow the same rules. Click the subject (or anywhere else on the row) to open the ticket as before.", "Choosing \"pending\", \"resolved\" or \"closed\" in the list opens the ticket editor instead, so you can say what it is waiting on or write the resolution note before saving. In the bar for several tickets, \"Set status\u2026\" asks for the reason or the note first, then applies it to every ticket chosen."]}, {"h": "Assigning a ticket"}, {"steps": ["Open the ticket and choose \"Edit\" (or use the pencil icon in the list).", "Pick a person in \"Assignee\", or \"Unassigned\".", "Choose \"Save Changes\"."]}, {"p": "The new assignee gets a \"Ticket assigned to you\" bell notification and an \"Assigned to an agent\" email with the priority. Nobody is notified when you assign a ticket to yourself. Only active users can be assigned."}, {"h": "Merging a duplicate"}, {"p": "When the same person asks for the same thing twice, keep one ticket and merge the other into it. Only open tickets of the same requester can be merged; different people asking about the same problem are linked to a case instead."}, {"steps": ["Open the ticket you want to fold away and choose \"Merge\u2026\".", "Pick the ticket to keep. The list shows only that requester's other open tickets.", "Choose \"Merge\" and confirm."]}, {"bullets": ["The comments and files move to the kept ticket, with a team note naming the merged ticket and its original request.", "The merged ticket is cancelled and says where it continues; it cannot be reopened or written on. An email reply to its number lands on the kept ticket.", "The requester gets one email saying it was merged. The merge, and any refused attempt, is written to the Audit Log."]}, {"h": "Nudging someone"}, {"p": "\"\ud83d\udd14 Notify\" in the ticket header opens \"Send notification\" as a page. \"Assignee\" and \"Requester\" are preset; you can \"Add recipient\", write a \"Title\" and \"Message\", and tick \"Also send the people above an email\". The message goes to the bell only; it isn't added to the ticket. The help desk (Tickets \u2192 All records) can also email people outside the list under \"Also email people outside this list\": a Microsoft 365 group or distribution list (its members are read when you send) and addresses typed or pasted, up to 300 people. They get one email with your title and message and what the ticket is about (template \"Notice about a ticket\"); it has no link to the ticket and gives no access to it. The notice is written on the ticket as an internal note and in the Audit Log."}, {"tip": "Start each day on \"Unassigned\" to triage, then work \"Assigned to me\"."}, {"p": "From Service Desk \u2192 Reports, clicking a bar opens Tickets with a \"Filtered: \u2026\" chip (for example a status or a person). Click \u2715 on the chip to clear it.", "mod": "reports"}, {"p": "When the requester replies (in the app or by email) you get a \"New reply on TK-\u2026\" bell and a \"Requester replied\" email with their message and a button that opens the ticket."}, {"qa": [{"q": "Can I merge tickets or change several at once?", "a": "Yes. Merge a duplicate from the ticket with \"Merge\u2026\" (see \"Merging a duplicate\" above). Change several at once by ticking them in the list and using \"Set status\u2026\", \"Set priority\u2026\" or \"Assign to\u2026\" in the bar above it."}, {"q": "\"That user is not an active account and cannot be assigned\".", "a": "The person's account is inactive. Choose someone else or ask an administrator."}]}]}, {"title": "Who can see which tickets", "for": "everyone", "mod": "tickets:all", "body": [{"p": "Ticket access is set per role in Administration \u2192 Roles & Permissions. It controls whether people see the whole queue or only their own tickets."}, {"bullets": ["Roles with \"All records\" ticked for Tickets see and can work every ticket. That's the agent queue.", "Without it, people see only tickets they opened (requester) or that are assigned to them. The same limit applies in the ticket list, the top search, the Dashboard, Reports, the Calendar and the record history.", "Opening someone else's ticket directly gives \"You can only open tickets you created or that are assigned to you\".", "View lets people read and comment on their tickets and upload files. Create adds \"+ New Ticket\". Edit adds the \"Edit\" button (change ticket fields) and lets them remove attachments. Delete adds the \"Delete\" button. Buttons a role can't use are hidden."]}, {"h": "Internal notes"}, {"p": "Internal notes (yellow, marked INTERNAL) are shown only to people whose role has \"All records\" on Tickets, that is the support team. Requesters never see them, even on their own tickets, and they are never emailed."}, {"warn": "If a requester's role includes Edit on Tickets, they can change fields on their own tickets such as status, assignee and due times. Give requesters View and Create only."}, {"tip": "If someone says \"I can't find a ticket\", check whether their role has \"All records\" for Tickets, and whether they are the requester or assignee on it."}, {"p": "Presets in Roles & Permissions: \"Read-only\" gives Tickets View and Create; \"Help Desk Agent\", \"Manager\" and \"IT Administrator\" include \"All records\".", "mod": "roles"}]}, {"title": "Cases: when a ticket needs several people", "for": "everyone", "body": [{"p": "Most requests are one ticket worked by one person. When a request needs several people, steps in a set order or someone's approval (a new hire, an office move, a system change), a Manager or Director makes the ticket a case. The case coordinates the work; the ticket stays the requester's place to follow it and reply."}, {"p": "To start one, open the ticket and choose \"Make it a case\u2026\". Give the case a title, an owner and, if there is one, a target date, then choose \"Create case\". The ticket becomes the case's main ticket and the case opens under Service Desk \u2192 Cases & Projects (numbered CS-year-number). You can start it from a template (see \"Case templates: a case in one step\")."}, {"p": "Only people with Cases & Projects \u2192 Create (Managers and Department Admins by default) or named by a Super Admin in Settings \u2192 General can make and own cases. Everyone who works tickets can open the Cases & Projects page and work the tasks given to them."}, {"bullets": ["One case per ticket. A case can hold several tickets (for example the same project asked by different people); each linked ticket either closes with the case or closes on its own.", "The main ticket always closes with the case. Tickets that close with the case are resolved by resolving the case; they cannot be resolved one by one.", "A ticket that belongs to a case cannot be merged away; unlink it first."]}]}, {"title": "Running a case: tasks, approvals, updates and resolving", "for": "everyone", "body": [{"p": "The owner splits the work into tasks: one person, a due date and, when it must wait, the task it starts after. A task that waits shows \"Waiting for another task\" and its person gets a bell when it can start."}, {"bullets": ["Task: the person chooses Start, Done, or Waiting\u2026 (with what it waits for). Only the owner cancels a task (with a reason).", "Approval: the approver chooses Approve or Reject (a rejection needs a reason). If the approver answered outside the app, the owner records it and says how (for example \"approved by email\") \u2014 except for the approval of a planned change, which only the approver answers. A rejected approval keeps the tasks after it waiting.", "For the requester: a step only the requester can do (send a document, confirm a date). They see it on their ticket and mark it done; the owner gets a bell.", "Show to the requester as a step: tick it on a task to list it, under a plain name if you like, in the requester's progress.", "Meeting (Outlook / Teams): a meeting with the organizer and the people invited \u2014 see \"Case meetings, the calendar and case emails\"."]}, {"p": "Updates: anyone on the case can add a team update. The owner can tick \"Share with the requesters\": each requester gets it as a reply on their own ticket and by email; they never see each other. \"What the requester sees\" shows the plain view before you share."}, {"p": "Health: \"At risk\" when a task is past its due date or the target date has passed. A target date also sets the due time of the tickets that close with the case."}, {"p": "Resolve\u2026: when every task is done or cancelled and the tickets that close on their own are finished, write the resolution summary. The tickets that close with the case are resolved with it as their resolution note and the requesters get the Resolved email. A requester's reply reopens their ticket and the case. When every ticket is closed (they close on their own after the usual business days) the case closes. Cancel case\u2026 stops it: its tasks are cancelled and its tickets carry on as regular tickets."}, {"p": "Every change, and every refused attempt, is in the Audit Log under Cases & Projects."}, {"p": "See also \"My tasks: everything given to you\" and \"Board view and checklists\"."}]}, {"title": "The case timeline (Gantt): moving tasks by dragging", "for": "everyone", "body": [{"p": "On a case, choose Timeline next to Tasks to see each task as a bar from its start date to its due date, with an arrow from a task to the one that starts after it. Weekends and holidays are shaded, today is the blue line and the case target date the dashed line. A late task has a red outline; a task still waiting for another one is faded; a meeting is a rounded bar on its day. The page remembers whether you last used List or Timeline."}, {"p": "A task has a start date as well as a due date (\"Starts (optional)\" when you add or edit a task). Until it has one, the task starts on its due date. Tasks without a date have no bar."}, {"bullets": ["Drag a bar to move the task: both dates move by the same number of days.", "Drag its left end to change the start, its right end to change the due date. A meeting moves as a whole and keeps its time; its Outlook meeting moves too.", "When tasks wait for the one you moved and would now start too early, the app lists them with their new dates (they keep their length in business days) and moves them only when you choose \"Move them all\". Cancel leaves everything as it was.", "Moving a task earlier moves nothing else. Done and cancelled tasks keep their dates.", "Only the case owner (or a lead who manages every case) can drag; everyone else sees the timeline. The people whose task moved because of someone else's change get a bell, and every change is in the Audit Log."]}, {"p": "In a template, a task has a length (\"Lasts\", in business days) as well as its due day, so a case made from it gets the start dates too."}, {"tip": "A task that waits for another cannot start before that task is due. Move the first task and the ones that wait follow; moving a waiting task earlier than the task it waits for is refused."}]}, {"title": "My tasks: everything given to you", "for": "everyone", "body": [{"p": "Service Desk \u2192 My tasks lists every task, approval and meeting given to you in open cases and projects, so you don't have to open each case. Everyone has it; it is empty when nothing is given to you."}, {"bullets": ["The tasks are grouped: Late, Today, Next 7 days, Later, No due date, and Waiting. The line at the top counts each group.", "Each task shows its case (click the number to open the case), the due date (a meeting shows its day and time, with Join (Teams) when there is a link) and, when it waits for another task, which one.", "Start, Done and Waiting\u2026 work as in the case. Waiting\u2026 asks what the task is waiting for. Resume takes it back to In progress.", "Approvals have Approve and Reject; rejecting asks why.", "\u2611 opens the task's checklist: tick items, add one and press Enter, or remove one.", "\"Show what I finished in the last 7 days\" lists your recent work."]}, {"p": "Everything you change here is the same as changing it in the case: the case owner sees it, and it is in the Audit Log. The daily case digest email lists the same tasks."}]}, {"title": "Board view and checklists", "for": "everyone", "body": [{"p": "In a case or project, the Tasks card has three views: List, Timeline and Board. Board shows the tasks as cards in four columns: To do, In progress, Waiting and Done (cancelled tasks are left out)."}, {"bullets": ["Drag a card to another column to change its status. Dropping on Waiting asks what it waits for; dropping an approval on Done asks for the approval (or use its Approve and Reject buttons).", "A task that waits for another task cannot go to In progress or Done until that task is done.", "Only the person a task is given to, and the case owner (or a lead), can move it. The buttons on each card do the same as in the list."]}, {"h": "Checklists"}, {"p": "A task can hold a short checklist (up to 30 items): the steps to tick off, such as \"Patch panel A\", \"Patch panel B\". In the list view and on My tasks, \u2611 shows how many are ticked (for example 1/2); click it to open the checklist."}, {"bullets": ["The person the task is given to, and the case owner (or a lead), add, tick, rename and remove items. Hover a ticked item to see who ticked it and when.", "Approvals, meetings and steps for the requester don't have checklists.", "A task can be marked done with items not ticked; the count stays on the task.", "Checklist changes are in the Audit Log."]}]}, {"title": "Case meetings, the calendar and case emails", "for": "everyone", "body": [{"p": "A meeting that is part of a case (a kick-off, a desk setup, a training, a go-live check) is a task of the kind \"Meeting (Outlook / Teams)\". Give it a title, the organizer, the day and time and the length, and choose who else to invite; tick \"Invite the requester\" when they should come too."}, {"bullets": ["The meeting goes on the calendar with the organizer and the people invited. When the organizer's Outlook sync is on (Calendar \u2192 Outlook & Teams), it becomes an Outlook meeting with a Teams link and Outlook sends the invitations. The case page says when a meeting is only in the calendar of the app.", "Moved in Outlook or in the calendar: the task takes the new time and the organizer and the case owner get a bell. Cancelled or deleted there: the task waits with \"set a new time\"; change the time on the task and the meeting is back.", "Deleting the meeting task, or cancelling the case, cancels the meeting.", "The requester, when invited, sees \"Meeting: \u2026\" on their ticket with the time and, once there is one, the Teams link."]}, {"p": "The dates of case tasks show on the calendar of the person doing them, of the case owner and of the watchers (\"Case tasks\"), and the case target date on the calendar of the owner and the watchers (\"Case target dates\"). Click one to open the case. These dates stay in the app; only meetings go to Outlook."}, {"p": "Emails come at once only when it matters now: a case or a task is given to you (a step for the requester too), your task can start because the one before it is done, or an approval waits for you. Everything else is in the daily case digest: each business morning (7:00 AM by default) one email with what waits on you (late, due today, in the next 7 days, later), today's case meetings, and for owners and watchers how their cases are going. Nobody gets an empty digest. \"Email me my digest\" on the Cases & Projects page sends yours now."}, {"tip": "A case meeting belongs to its case: only the case owner (or a lead who manages every case) changes, moves or removes it \u2014 in the case, or on the calendar. People outside the case see it on the calendar as \"Case meeting\", without its text, place or people."}]}, {"title": "Case templates: a case in one step", "for": "everyone", "body": [{"p": "A template is a ready-made list of tasks for work that comes back: a new hire, a leaver, a desk or office move. Four come with the app (New hire, Offboarding, Desk or office move, and for projects \"IT project (Plan, Build, Roll out, Close)\"); they are under Cases & Projects \u2192 Templates."}, {"p": "To use one, open the ticket, choose \"Make it a case\u2026\", pick the template and give the date it asks for (the start date, the last day, the move day). If a task's person is \"chosen when used\" (for example who approves), choose them; nobody chosen means the case owner. \"What will be made\" lists every task with its date before you create the case. On a case that already exists, \"Apply a template\u2026\" adds the template's tasks after the ones there."}, {"bullets": ["Dates are counted in business days from the date asked: before it (a minus number) or after it. Weekends are skipped, and the business-hours days and holidays when business hours are on. A date already past is shown in red and the task is made late.", "Each task gets its person (the case owner, a named person, the one chosen, or the requester for a requester step), what it waits for, its meeting time and length, and what the requester sees.", "The target date comes from the template when the case has none.", "A requester step is left out when the requester has no account (the answer says which).", "A template task can name its phase (Plan, Build\u2026). Used for a project, the phases are made with their tasks and each milestone is the date of its last task; used for a case, the tasks come without phases. A project saved as a template keeps its phase names.", "A template can be marked \"Standard change\": a routine change that is pre-approved. A planned change made from it needs no approval."]}, {"p": "Keeping the templates: a Super Admin, and the people named for it under Roles & Permissions \u2192 Cases & Projects: people with extra rights, can add a template (\"New template\"), change it, take it out of use or delete it (cases made from it keep their tasks). They can also save a case as a template (\"Save as template\u2026\" on the case): each date is kept as business days from the date they choose, the owner's tasks go to \"the case owner\". Every change is in the Audit Log."}]}, {"title": "Cases & Projects: kinds of work", "for": "everyone", "body": [{"p": "ITOps handles requests, cases and projects the way IT departments commonly organize their work. Knowing which kind of work something is tells you where it starts and who follows it."}, {"bullets": ["Incident: something is broken or not working as it should (\"my laptop will not start\"). It is a ticket. Restore the service first; the root cause can come later.", "Service request: someone asks for something standard (\"a new hire needs a laptop\"). It is a ticket. When it needs several people or steps, the ticket becomes a case (service request fulfilment) and the requester follows it on their ticket.", "Change: a planned change to something IT runs (a firewall upgrade, a new system). It is a case without a ticket, \"Planned change\": plan it, have it approved, carry it out, check it worked. Larger changes are projects.", "Problem: the cause behind repeated or major incidents (\"the Wi-Fi drops every Monday\"). It is a case without a ticket, \"Problem investigation\": link the incident tickets to it, find the cause, fix it for good.", "Project: planned work with phases, milestones, a sponsor and a budget (an office Wi-Fi upgrade, a phone system replacement). It is a project (PR- number)."]}, {"p": "So a case or a project can start in two ways: from a ticket, when someone asked (a request or an incident; the requester keeps following it there), or without a ticket, when IT starts the work itself (a planned change, a problem investigation, an internal task, a project). The case shows what started it."}, {"p": "Other Service management practices already in the app: service level management (the SLA targets and alerts on tickets), knowledge management (the Knowledge Base and Ask IT), service configuration (Equipment & Assets), supplier management (Vendors and Contracts), and continual improvement (the Reports and the Scorecard). Also in place: the ticket type (incident or service request), major incidents and the \"How did we do?\" question (see their topics). Also: problem records with known errors, change records with approval by risk and change freezes, and equipment linked to tickets, problems and changes. Reports now measure the service (first-contact resolution, reopened tickets, changes that worked, satisfaction) and show how cases and projects are going (see \"Reports for Cases & Projects\"). And the continual improvement register (Service Desk \u2192 Improvements), where anyone can suggest how IT could work better."}]}, {"title": "Improvements: the continual improvement register", "for": "everyone", "body": [{"p": "Service Desk \u2192 Improvements is where anyone can suggest how IT could work better (continual improvement): something that wastes time, a question asked every week, a tool that would help. Each suggestion gets an IM- number and an answer."}, {"h": "Suggest an improvement"}, {"steps": ["Open Service Desk \u2192 Improvements and choose \"Suggest an improvement\".", "Say in a line what should be improved, what happens today and what should change, and what it would bring (time saved, fewer tickets).", "Choose \"Send\". The people who triage the register get a bell. You can change your suggestion until it is looked at."]}, {"p": "\"My suggestions\" shows yours and the answer: accepted (with its owner and target date), or not taken up (with the reason). You get a bell when it is accepted, declined or done. \"The register\" shows every accepted, in-progress and done improvement, so everyone sees what came of the ideas."}, {"h": "Triage (Super Admins and the people who may create cases)"}, {"bullets": ["\"To triage\" lists the new suggestions. Open one and choose \"Accept\u2026\" (priority, owner, effort, target date, and how we will know it worked) or \"Decline\u2026\" with the reason the author will read.", "\"Edit the plan\" changes the priority, owner, target date or measure later; \"Reopen\" brings a done improvement back.", "A major incident review, a problem investigation and a change that went through with issues or failed have \"Add to the improvement register\u2026\": the item names where it came from and, added by someone who triages, is accepted at once. The weekly review can add items directly too.", "\"Start a case for it\" (Cases & Projects \u00b7 Create) makes a case for bigger improvements; the case and the improvement link to each other."]}, {"h": "Carry it out"}, {"bullets": ["The owner finds it under \"Mine to do\", chooses \"Start\", and keeps \"Progress\" up to date.", "\"Done\u2026\" asks whether it worked (it worked, partly, or not) and what changed \u2014 what the measure shows now. The author is told.", "Reports \u2192 Service measures shows the register (waiting, open, late, done); the Scorecard can count improvements done each week."]}, {"tip": "Everything is in the Audit Log: suggestions, decisions, plan changes, progress, results and refusals."}]}, {"title": "Cases without a ticket: planned changes, problems, internal tasks", "for": "everyone", "body": [{"p": "Not every piece of work starts with somebody asking. When IT starts the work itself, choose Service Desk \u2192 Cases & Projects \u2192 \"New case\". Give it a title and say what started it:"}, {"bullets": ["Planned change: a change to something IT runs. Plan it in tasks, add an approval before the work, then a check that it worked.", "Problem investigation: the cause behind repeated incidents. Link the incident tickets to it (\"Link a ticket\"); when it is fixed, resolve it with the linked tickets that close with it.", "Internal task: maintenance, documentation, clean-up, anything IT does for itself."]}, {"p": "Owner, target date, description and a template work as for any case, and the case is numbered CS-year-number. There is no requester, so there are no requester steps; people are kept informed as watchers and through their tasks. What started it can be changed later (Edit). A request or an incident always starts from its ticket (\"Make it a case\u2026\") so that the person who asked can follow it."}]}, {"title": "Problem investigations and known errors", "for": "everyone", "body": [{"p": "A problem investigation (problem management) looks for the cause behind repeated or major incidents and fixes it for good. Start one with Cases & Projects \u2192 New case \u2192 \"Problem investigation\", or from the review of a major incident. Link the incident tickets to it (Link a ticket, closing on their own)."}, {"p": "Its Problem record holds the root cause, as far as it is known, and a workaround: what people can do until it is fixed. \"Publish as a known error\" puts the workaround in the Knowledge Base (category Known errors) with the symptoms; the help desk also sees it on every ticket linked to the problem. Changing the workaround updates the article. \"Withdraw\" archives it, and resolving the problem archives it as fixed."}, {"bullets": ["The owner of the case (or a lead) edits the record and publishes the known error; everything is in the Audit Log.", "Requesters do not see the problem or the known error on their ticket; they get the answer from the help desk.", "When the cause needs a change to something IT runs, plan it as a change (see \"Planned changes: risk, approval and change freezes\")."]}]}, {"title": "Planned changes: risk, approval and change freezes", "for": "everyone", "body": [{"p": "A planned change (change management) is a case started with Cases & Projects \u2192 New case \u2192 \"Planned change\". Its Change record says what kind of change it is, how risky, who and what it affects, how to undo it, and when it happens. Approval follows the risk."}, {"bullets": ["Type: Standard (a routine, pre-approved change; it comes only from a template marked \"Standard change\" \u2014 apply the template; a change cannot be marked standard by hand), Normal, or Emergency (urgent, with the reason written down).", "Risk and who approves: Low \u2014 the owner; Medium \u2014 a Manager the owner chooses (not the owner); High \u2014 every member of the Change Advisory Board, named by a Super Admin in Settings \u2192 General. An emergency change is approved by one approver the owner chooses (not the owner).", "Before asking for approval: the type, the risk, the window (when it happens) and the back-out plan (how to undo it). \"Ask for approval\" creates the approval tasks; the approvers get a bell and an email. From then on the type, risk, window, impact, back-out plan and emergency reason are locked \u2014 what is approved is what is done.", "Only the approver answers their approval: nobody cancels, moves, reassigns, deletes or records it for them. To change who approves, or a detail, the owner chooses \"Withdraw the approval request\" (with a reason): every approval task of the request is cancelled, the details open again, and approval is asked for again. Everything is in the Audit Log.", "One rejection rejects the change. Asking again after a rejection starts a new round (the rejection stays in the history). A change that has no type or is not approved cannot be resolved as done; it can be cancelled, or resolved as \"failed and backed out\".", "A standard-change template cannot be applied once approval was asked for (withdraw the request first), nor when the window falls in a change freeze.", "Change freezes: periods set in Cases & Projects \u2192 Settings when nothing should change (for example the year-end close). A normal or standard change cannot be planned in one; an emergency change can.", "When the work is done, \"Resolve\u2026\" asks how it went: successful, successful with issues, or failed and backed out (with what happened). Reports shows the share of changes that worked.", "Change windows and freeze days are on the calendar."]}, {"bullets": ["Change freezes are checked when the window is set, again when approval is asked for, and again when an approver approves (a freeze may be added in between).", "A decided approval stays decided: only the case owner asks for it again."]}]}, {"title": "Equipment linked to tickets, problems and changes", "for": "everyone", "body": [{"p": "The help desk can link the equipment a ticket is about (a laptop, a printer, the firewall): open the ticket and choose \"Link equipment\u2026\", then search by asset tag, make, model, serial number or the person who has it. Cases link the equipment a problem or a change touches in the same way (\"Equipment involved\")."}, {"p": "Each piece of equipment then shows its tickets, problems and changes under Equipment \u2192 the item \u2192 \"Tickets, problems and changes\", so it is easy to see a laptop that keeps coming back or what a change touched. People only see the tickets and cases they could open anyway."}, {"bullets": ["Linking on a ticket needs Tickets \u2192 Edit; on a case, its owner (or a lead).", "Every link and unlink is in the Audit Log, both on the ticket or case and on the equipment."]}]}, {"title": "Projects: phases, milestones, sponsor and budget", "for": "everyone", "body": [{"p": "A project is planned work bigger than a case. Choose Service Desk \u2192 Cases & Projects \u2192 \"New project\" (numbered PR-year-number), or turn a case that grew into one with \"Make it a project\u2026\" on the case: it gets a PR- number, keeps its CS- number as \"Was\", and its tasks, tickets and people stay. A project can start from a template; \"IT project (Plan, Build, Roll out, Close)\" comes with the app."}, {"bullets": ["Phases: split the project into phases (Plan, Build, Roll out, Close\u2026), each with a milestone date, the date the phase should be finished. Each task can belong to a phase (the Phase field of the task). The Phases card shows each phase's progress, its dates and its milestone: Late when the milestone has passed with work still open, which also puts the project At risk.", "Timeline: the project's timeline is grouped by phase. Each phase has a grey bar from its first to its last task and a diamond at its milestone (red when late, green when done). Milestones also appear on the calendar.", "Sponsor: the person the project is for. The sponsor sees the project, its phases, tasks and updates, and gets a bell when named; they do not change it.", "Team: anyone given a task, invited to a meeting or added as a watcher sees the project, including people outside IT. They see the projects they are part of, not the other cases and projects.", "Budget: people with access to the IT Budget see a Budget card on the project; its owner can link the IT Budget lines that pay for it (\"Link a budget line\") and see the planned cost. People without IT Budget access do not see amounts.", "Tickets linked to a project close on their own by default (each is its own piece of work); choose \"Closes with the project\" when it should wait for the end."]}, {"p": "Everything (the project made, a case made a project, phases added, changed or deleted, a task's phase, budget lines linked or unlinked, and anything refused) is in the Audit Log."}]}, {"title": "Following your request when it becomes a case", "for": "everyone", "body": [{"p": "When your request needs several people, the team may handle it as a case. Open your ticket: a box says \"Your request is being handled as CS-\u2026\", who coordinates it, the expected date and its status: On track, Waiting on you, Delayed or Done."}, {"p": "If the team needs something from you, it is listed as \"For you\" with a \"Mark as done\" button. The progress list shows the main steps, and the latest update the team shared with you. Keep replying on your ticket as usual: the team sees it."}, {"p": "If the team invites you to a meeting about your request (a desk setup, a training), it shows on your ticket as \"Meeting: \u2026\" with the day and time; the invitation itself comes by email from Outlook."}]}, {"title": "Due dates, SLAs and business hours", "for": "everyone", "mod": "tickets:all", "body": [{"p": "Each ticket can carry two target times: \"Response due\" (first reply) and \"Resolution due\" (fixed). ITOps shows them as coloured badges so agents can see what needs attention first."}, {"h": "How the due times are set"}, {"bullets": ["When a ticket is created, ITOps fills both times automatically: in the app (unless you type your own in \"Response due\" / \"Resolution due\"), and for tickets that arrive by email, from the \"Submit a Help Request\" page or from a form \u2014 the same rule for every channel.", "It uses the category's \"Response SLA (hours)\" and \"Resolution SLA (hours)\" if they are set. Otherwise it uses the priority targets (Settings \u2192 SLA & Hours \u2192 \"Priority targets\"; out of the box Critical 1h / 4h, High 2h / 8h, Medium 4h / 24h, Low 8h / 48h, Planning 24h / 120h).", "Critical and High get the shorter of the two: a Critical ticket in a category with an 8-hour target is due in 4 hours, as its priority promises. (Settings \u2192 SLA & Hours \u2192 \"Critical and High use the shorter clock\", on by default.)", "If business hours are on, those hours count only working time: evenings, non-working days and holidays are skipped.", "Changing the priority or the category later recalculates both times from when the ticket was created (the response time only while nobody has answered yet). A time you type in the same edit wins.", "Reopening a resolved or closed ticket clears its resolved time and gives it a new resolution due time, counted from the reopening with the same target as a new ticket of its priority and category (a time you type in the same edit wins)."]}, {"h": "Reading the badges"}, {"bullets": ["Blue \"Due 5h\": on track.", "Amber \"Due 45m\": due soon (response within 1 hour, resolution within 4 hours).", "Red \"Overdue 2h\": the target has passed, or it was met late.", "Green \"Met\": done in time.", "Purple \"Paused\": the ticket is pending (waiting on the requester). The clock stops: no SLA alerts are sent, and when the ticket leaves Pending its due times move on by the working time it spent there. A public reply from the requester ends Pending by itself (the ticket goes back to In progress). A Pending ticket resolved with its case or its major incident keeps that time too.", "No badge: no due time, or the ticket is cancelled."]}, {"p": "The list's SLA column shows the resolution badge. Inside a ticket you see both. The response target is met when someone other than the requester comments in public (also when the requester is someone from outside, even if their ticket is held by the admin account), or someone other than the requester sets it to Pending, Resolved or Closed (In progress or Cancelled alone is not an answer)."}, {"p": "Business hours are set in Administration \u2192 Settings \u2192 SLA & Hours \u2192 \"Business hours (SLA clock)\": tick \"Count SLA in business hours\", set \"Day starts\", \"Day ends\", \"Time zone\", \"Working days\" and \"Holidays\" (one YYYY-MM-DD date per line), then \"Save business hours\". They affect tickets created after you save.", "mod": "sla_cfg:edit"}]}, {"title": "Public replies, internal notes and EXT requesters", "for": "everyone", "mod": "tickets:all", "body": [{"p": "This topic explains who sees what you write on a ticket, and how ITOps handles people who don't have an ITOps account."}, {"h": "Public replies and internal notes"}, {"h": "Internal files"}, {"bullets": ["The support team for the ticket can tick \"Next upload is internal\" above the attachments before uploading. The file is shown with an INTERNAL tag and the requester never sees or downloads it.", "A requester never marks a file internal. Without being on the support team for the ticket, a person removes only the files they added.", "Every download of a ticket file is in the Audit Log."]}, {"bullets": ["A normal comment is a public reply. The requester sees it in the ticket and, if \"Email requester on reply\" is on, gets it by email. The first public reply from someone other than the requester also meets the response target.", "Tick \"Internal note (not shown to the requester, not emailed)\" under the comment box before you post, and the button changes to \"Add note\". The note is shown in yellow with an INTERNAL tag.", "Internal notes are visible to the support team for the ticket: people with \"All records\" on Tickets, and the ticket's owner and backup. They are never emailed, don't ring the requester's bell and don't count as a response. The assignee gets a \"New internal note\" bell notification.", "Transcripts added with \"Add as comment\" are public replies. Post a summary as an internal note instead if the recording contains private details."]}, {"warn": "An internal note can't be turned into a public reply, or the other way round, after posting. Check the box before you click the button. Never put passwords in any comment: store them in Credentials."}, {"h": "Internal notes from email"}, {"p": "If someone emails the help-desk mailbox quoting a ticket number but isn't the ticket's requester, contact or assignee (and isn't an ITOps user), their message is saved as an internal note starting \"(email from UNRECOGNISED sender \u2026 quoting this ticket number \u2014 review before acting)\". Check who they are before acting on it."}, {"h": "EXT requesters"}, {"bullets": ["Tickets from people who aren't ITOps users (from email, the public page or a form) show their name or address with an \"EXT\" tag in the list, and \"Requester: Name <email> \u00b7 external\" inside the ticket.", "Replies and status emails go to that address, in the organisation's default email language.", "They can't sign in to see the ticket. Email is their only channel, so write replies that make sense on their own.", "Their email replies (with the TK- number) are added as public comments starting \"(email reply from \u2026)\". No bell notification is created, so check your EXT tickets.", "Behind the scenes the ticket is filed under the system administrator account. In \"\ud83d\udd14 Notify\", the \"Requester\" preset is that account, not the outside person.", "If the sender's address matches an ITOps user, the ticket is linked to that user instead and has no EXT tag."]}, {"tip": "Email attachments are not saved. Ask external requesters to describe the problem in the email, or upload files they send you separately with \"Upload\"."}, {"qa": [{"q": "I don't see the \"Internal note\" box.", "a": "It appears only for roles with \"All records\" on Tickets (the support team). Ask an administrator to check your role."}, {"q": "Can a requester reply to an internal note?", "a": "No. They never see it. If you need their input, post a normal comment."}]}]}, {"title": "Emails about your ticket", "for": "everyone", "body": [{"p": "ITOps can email you about your ticket so you don't have to keep checking. Your organisation decides which of these emails are switched on."}, {"h": "Emails the requester can get"}, {"bullets": ["\"Request received\": when you raise a ticket by email, the \"Submit a Help Request\" page or a form. Not sent for tickets created inside the app.", "\"Reply from the help desk\": when someone else posts a comment on your ticket. It includes the comment.", "\"Status changed\": when someone else moves your ticket to a new status.", "\"Resolved / closed\": when your ticket is resolved or closed."]}, {"p": "If you have an ITOps account, these emails end with a \"Follow it online\" box and an \"Open TK-\u2026 in ITOps\" button. It opens the ticket so you can check the status, read every update, reply to the person working on it, or add files. People without an account just reply to the email."}, {"p": "You aren't emailed about your own comments or changes. The agent working your ticket gets a \"Requester replied\" email (and a bell notification) each time you reply, in the app or by email, so you can go back and forth until it's solved."}, {"h": "Replying by email"}, {"steps": ["Reply to the ticket email.", "Keep the ticket number (for example TK-2026-0142) in the subject line.", "Write your reply above the quoted text and send."]}, {"p": "Your reply is added to the ticket as a comment. Only the text is kept; attachments in the email are not saved, so upload files in the app. The agent is notified of your reply by bell and email."}, {"h": "Language"}, {"p": "Emails use the language in My profile \u2192 \"Email language\". People without an ITOps account get the organisation default: English, Espa\u00f1ol, or both in one email."}, {"qa": [{"q": "I got no emails at all.", "a": "Check your junk folder and your Account email language. Your organisation may have these emails switched off; you can still follow the ticket in the app."}, {"q": "I replied but it became a new ticket.", "a": "The subject line lost the TK- number, or your organisation creates a new ticket for every email. Next time keep the number, and mention the original number in the new ticket."}]}, {"p": "Administrators: the switches are in Administration \u2192 Settings \u2192 Email (\"Acknowledge new emails\", \"Email requester on reply\", \"Email requester on status change\", \"Email assignee when a ticket is assigned\"). Out of the box only the assignee email and the web page / form \"Request received\" email are on (outbound email must also be enabled). Each email can also be switched off, and its wording changed, in Settings \u2192 Email templates.", "mod": "email_cfg:edit"}]}, {"title": "Transcribing a voice or video attachment", "for": "everyone", "mod": "tickets:all", "body": [{"p": "Transcribe turns speech in an audio or video attachment (for example a narrated screen recording) into text, so you can read or search it instead of playing it."}, {"steps": ["Open the ticket and find the recording under \"Attachments\".", "Choose \"Transcribe\" beside it. The button shows \"\u2026\" while it works.", "The text appears under the file. \"(no speech detected)\" means there was nothing to transcribe.", "Choose \"Copy\" to copy it, or \"Add as comment\" to save it on the ticket as \"Transcript \u2014 file name:\"."]}, {"bullets": ["The button appears only for audio and video files, and only when an administrator has added a transcription key.", "Files over 25 MB can't be transcribed.", "The transcript isn't stored on the ticket unless you choose \"Add as comment\"."]}, {"warn": "\"Add as comment\" posts a public comment. The requester can see it and may get it by email."}, {"tip": "The AI assistant reads the subject and description only. To have it consider a transcript, paste the relevant part into the description."}, {"p": "Transcription uses an OpenAI (Whisper) key. Add it in Administration \u2192 Settings \u2192 Sign-in & AI \u2192 AI assist; if the provider is already OpenAI, its key is used.", "mod": "settings:edit"}]}, {"title": "Using the AI assistant on a ticket", "for": "everyone", "mod": "tickets:all", "body": [{"p": "The AI assistant reads a ticket and suggests a short summary, a category, a priority and a first reply. Use it to triage faster. Everything it produces is a suggestion for you to check."}, {"steps": ["Open a saved ticket and choose \"Edit\". The \"AI assist\" box appears under \"Description\".", "Choose \"Summarize & suggest\" and wait while it shows \"Thinking\u2026\".", "Read the \"Summary\".", "If the \"Suggested:\" category and priority look right, choose \"Apply to form\", then \"Save Changes\". Nothing changes until you save.", "Under \"Draft reply\", choose \"Copy\". Close the form, paste the reply into \"Add a comment\u2026\", adjust it, and \"Post\".", "\"Regenerate\" asks again if the first answer isn't useful."]}, {"bullets": ["It reads the subject, description, current category and current priority only. It doesn't read comments or attachments.", "It only suggests active categories and the priorities Critical, High, Medium and Low.", "The box doesn't appear on a new ticket, or when AI assist is off or has no key."]}, {"warn": "The ticket's subject and description are sent to the external AI provider your organisation set up. Always read the output before you use it; it can be wrong."}, {"warn": "If the suggested category belongs to another group, it may not show in \"Category\" after \"Apply to form\". Pick that group in \"Subject\" first; on an existing ticket this doesn't change the subject line."}, {"p": "AI assist is switched on in Administration \u2192 Settings \u2192 Sign-in & AI \u2192 AI assist (\"Enable AI assist\", \"Provider\", \"Model\", key, then \"Save AI settings\").", "mod": "settings:edit"}]}, {"title": "SLA alerts and the weekly digest", "for": "everyone", "mod": "tickets:all", "body": [{"p": "SLA alerts warn people before a ticket misses its response or resolution target, and again if it does. The weekly digest summarises how the team did."}, {"h": "Who gets what"}, {"h": "When they run"}, {"p": "Alerts are checked by the scheduled job (every 15 minutes is typical). ITOps also checks about every 3 minutes while someone has it open, unless an administrator has turned that off. The weekly digest only runs from its own scheduled job."}, {"tip": "An alert on a ticket you're working is a cue to post an update or adjust the due time; it isn't sent again for the same stage."}, {"h": "Settings", "mod": "settings:edit"}, {"steps": ["Go to Administration \u2192 Settings \u2192 SLA & Hours \u2192 \"SLA alerts & digest\".", "Tick \"Enable breach & approaching-deadline alerts\" and set \"Warn before response due (min)\" and \"Warn before resolution due (min)\".", "Tick \"Email a weekly SLA digest to admins\" if wanted, then \"Save SLA settings\".", "Copy the two commands under \"Cron jobs (cPanel \u2192 Cron Jobs)\" into your hosting control panel: every 15 minutes for alerts, weekly for the digest."], "mod": "sla_cfg:edit"}]}, {"title": "Self-service on the help portal (article suggestions)", "for": "everyone", "body": [{"p": "When you type a request on the \"Submit a Help Request\" page, ITOps looks for published help articles that match and shows them before you send anything. Often the answer is already there."}, {"steps": ["Start typing your \"Subject\" and \"Description\".", "After a moment a box may appear: \"These help articles might answer your question\", with up to four articles.", "Click an article to read it on the page. Click again to fold it away.", "If it solved your problem, choose \"This solved it \u2014 no ticket needed\". The form closes and no ticket is created.", "Use \ud83d\udc4d or \ud83d\udc4e under \"Helpful?\" to tell the team whether the article was useful.", "Still stuck? Carry on and choose \"Submit request\"."]}, {"tip": "Describe the problem in plain words, for example \"printer offline\", to get better suggestions."}, {"h": "For the knowledge team", "mod": "kb_gaps"}, {"bullets": ["\"This solved it\" counts as a deflected ticket. The thumbs feed the \"Help-portal performance\" panel in Knowledge \u2192 KB Content Gaps.", "Super Admins also see a \"Tickets deflected\" tile on the Dashboard.", "Only published Knowledge Base articles are suggested. Short, task-focused articles with the words people actually use work best."], "mod": "kb_gaps"}]}, {"title": "Dashboard tiles and jumping to a ticket", "for": "everyone", "mod": ["tickets", "reports", "kb", "sops", "creds", "contracts", "vendors"], "body": [{"p": "The Dashboard is your starting page. It shows live counts for the areas you can use, and your most recent tickets."}, {"h": "Tiles"}, {"bullets": ["\"Open Tickets\" (tickets that are open or in progress), \"KB Articles\", \"Credentials\" and \"Contracts\". You only see tiles for areas your role can view.", "Click a tile to go to that page.", "Super Admins get a second row: \"Open alerts\", \"Onboarding active\", \"Onboarding overdue\", \"Standards coverage\", \"KB gaps\" and \"Tickets deflected\"."]}, {"h": "Your tickets"}, {"p": "Under the tiles, \"My Tickets\" lists your 8 most recent tickets with their number, category and status. Agents with the whole queue see \"Recent Tickets\" instead. Click any row to open that ticket directly on the Tickets page."}, {"p": "If you own compliance items, a \"My standards items\" card shows how many are assigned to you, overdue and due within 14 days, with a link \"Open Standards & Audits \u2192\"."}, {"tip": "The numbers load when you open the Dashboard. Refresh the browser page to update them."}]}, {"title": "Who gets new tickets: owner, backup and the alert list", "for": "admin", "body": [{"p": "Every new ticket \u2014 created in ITOps, emailed to the help desk, sent from the public ticket page or an intake form \u2014 gets an owner (the assignee) and a backup, so a new ticket is never silent."}, {"h": "Set it up (Administration \u2192 Ticket Categories)"}, {"steps": ["\"Who gets new tickets\" card: choose a default owner and a default backup for tickets whose category has no rule of its own.", "Edit a group or a category and choose \"Owner of new tickets\" and \"Backup\". A category without its own inherits its group's; a group without its own uses the default.", "New-ticket alert list: people told about any new ticket that could not be assigned to anyone (for example nobody is set, or the owner is inactive and there is no backup). Empty = every Super Admin. Tick \"Alert the list about every new ticket\" if they want to hear about all of them."]}, {"h": "What the backup gets"}, {"bullets": ["Everything the owner gets: the assignment notice, replies from the requester, internal notes, and response / resolution deadline alerts \u2014 in the bell and by email.", "Access to the ticket even if their role cannot see all tickets.", "The \"Whose tickets\" filter has \"I am the backup\" and \"Assigned but no backup\"."]}, {"h": "Good to know"}, {"bullets": ["Choosing an owner or backup on the ticket always wins over the routing. Leave them on \"Automatic\" to use it.", "Only people who can work tickets get them: someone inactive, or whose role cannot edit tickets, is skipped (if the owner is skipped, the backup becomes the owner). Each skip is written to the Event Log and to the audit entry of the ticket.", "A category, a group or the default routing does not accept a new owner or backup whose role cannot edit tickets, and neither does a ticket. Give the role \"Tickets \u2192 Edit\" first, or choose someone else. People on the alert list only need an active account.", "The owner and the backup must be different people.", "Each automatic assignment is recorded in the audit log (\"ticket routed\") with the rule that chose it.", "Emails used: \"Assigned to an agent\", \"Backup on a ticket\" and \"New ticket \u2014 nobody assigned\" (Settings \u2192 Email templates). They need outbound email to be configured; the bell works regardless."]}, {"h": "Routing & SLA check"}, {"p": "The box at the top of Ticket Categories lists what would send a new ticket to nobody or to the wrong person, or let an SLA pass without anyone being told \u2014 each with how to fix it. Red: fix now. Amber: worth fixing. Blue: for information. \"Show all\" also lists what is fine; \"Check again\" reads it again after a change."}, {"bullets": ["The clocks: the database and ITOps must show the same time, or replies are recorded late and SLAs breach wrongly.", "Business hours off: SLA clocks then run 24/7, nights and weekends included.", "The SLA scan (cron-sla.php) never ran, or not in the last hour: nobody is warned before a target is missed.", "Owners and backups (categories, groups, default routing) who are inactive or whose role cannot edit tickets.", "Categories with nobody to route to, and who is told instead.", "Help Request forms that ask for no email, or where the email is optional: those people get no confirmation and no replies."]}], "mod": "categories:edit"}]}, {"cat": "Forms & intake", "topics": [{"title": "What forms are for", "for": "everyone", "mod": "forms", "body": [{"p": "Forms let anyone send information to the team through a web page, without logging in to ITOps. You build them under Administration \u2192 Forms."}, {"p": "There are two types. You pick one in the form's \"Settings\" tab under \"Type\":"}, {"bullets": ["Ticket \u2014 creates a ticket. Each submission becomes a new ticket in the service desk queue, with status Open and priority Medium. The person sees their ticket number (for example TK-2026-0123) on the thank-you screen.", "Data \u2014 stores submissions. Nothing goes to the ticket queue. Answers are saved so you can read them and export them to a spreadsheet. Use this for sign-ups, surveys, audits or collecting details."]}, {"p": "Each form has its own public link, in the form form.html?f=your-slug, and a snippet you can paste into another web page. People open the link, fill it in and press \"Submit\"."}, {"p": "Every submission is saved against the form, whatever its type. You can read submissions on the form's \"Responses\" tab or from \"Submissions\" on the Forms list."}, {"tip": "ITOps comes with a starter ticket form called \"Help Request\" (link slug \"support\"). It asks for name, email, category, subject and description. It is usually the best starting point for a new ticket form. See \"How form answers become a ticket\"."}, {"qa": [{"q": "I can't see Administration \u2192 Forms.", "a": "Your role needs the Forms permission (View to see the list; Create, Edit and Delete to change forms). An administrator sets this in Administration \u2192 Roles & Permissions."}, {"q": "Do people need an ITOps account to fill in a form?", "a": "No. Forms are public pages. Anyone who has the link can submit, as long as the form is Active."}]}]}, {"title": "Building a form", "for": "admin", "mod": "forms", "body": [{"p": "Use the form builder to create a new form or change an existing one. You need the Forms permission: Create to make new forms and Edit to change them."}, {"h": "Create the form"}, {"steps": ["Go to Administration \u2192 Forms and click \"New form\".", "On the \"Builder\" tab, the left panel is \"Add Field\". Open a group (\"Input Fields\", \"Choice Fields\", \"Date \u00b7 Media \u00b7 Input\" or \"Layout & Other\") or type in \"Search\u2026\", then click a tile to add that field.", "Click a field in the middle of the page to edit it in the right-hand panel. Set its \"Label\", \"Placeholder\", \"Description / help\" and tick \"Required\" if it must be answered.", "For choice fields, edit the entries under \"Options\" and use \"+ Add option\" to add more.", "Under \"Field Width\", choose \u00bc, \u2153, \u00bd, \u2154, \u00be or \"Full\". Two \u00bd fields sit side by side.", "To reorder fields, drag them by the \u283f handle. Click \u00d7 on a field to remove it.", "Open the \"Settings\" tab. Enter a \"Form name (internal)\" (required), choose the \"Type\", then set the \"Public title\", \"Intro text\" and, if you want, a \"Link slug\".", "Use the \"Preview\" tab to try the form with real controls.", "Click \"Save & publish\". After the first save the button just says \"Save\"."]}, {"h": "What happens next"}, {"p": "A new form is saved as Active (published). It is live at form.html?f=slug straight away, and it appears in the list on Administration \u2192 Forms. If you left \"Link slug\" empty, ITOps makes one from the form name."}, {"warn": "A new form goes live on the first save. Don't share the link until you have tested it on the \"Preview\" tab or with the \"Preview\" button on the Forms list."}, {"tip": "If you click \"\u2190 Back\" with unsaved changes, ITOps asks before it throws them away. Save often while you build."}, {"qa": [{"q": "I dragged a field but its conditional logic stopped working.", "a": "Conditions point at another field's key. The key is made from the label when you save. If you rename the trigger field after setting up a condition, open the dependent field and choose the trigger again."}, {"q": "I see \"Form name is required\" when saving.", "a": "Fill in \"Form name (internal)\" on the \"Settings\" tab."}]}]}, {"title": "Field types you can add", "for": "admin", "mod": "forms", "body": [{"p": "This is the full list of field types in the \"Add Field\" panel of the form builder, and what each one is for."}, {"h": "Input Fields"}, {"bullets": ["\"Text Input\", \"Textarea\" (long text), \"Email\" (checked for a valid address on submit), \"Phone\", \"Website / URL\" and \"Password\".", "\"Numeric\" and \"Num. Spinner\". Set \"Min\", \"Max\" and \"Step\" under \"Numeric config\".", "\"Hidden Field\". The person never sees it. Give it a \"Default value\", or turn on \"Set from URL param\" to fill it from the link, for example ?ref=newsletter."]}, {"h": "Choice Fields"}, {"bullets": ["\"Select Box\" (dropdown), \"Radio Button\" (pick one), \"Checkbox\" and \"Multiselect\" (pick several), and \"Tile\" (large pick-one buttons).", "\"Consent\". One tick box that uses the label as its text, for example \"I agree to the terms\".", "\"Ticket Category\". A two-step picker. The person first picks a group and then a category, or leaves \"General / not sure\". The groups and categories come from Administration \u2192 Ticket Categories. On a Ticket form, this sets the new ticket's category."]}, {"h": "Date \u00b7 Media \u00b7 Input"}, {"bullets": ["\"Date Picker\" (with optional \"Min date\" and \"Max date\") and \"Time Picker\".", "\"File Upload\" and \"Recording\". See \"Letting people attach photos, video or recordings\".", "\"Star Rating\" (1\u201310 stars, set under \"Number of stars\") and \"Range Slider\".", "\"Signature\" and \"Initials\". The person draws with a mouse or finger, or types their name and picks a font."]}, {"h": "Layout & Other"}, {"bullets": ["\"Section Heading\". A bold divider that splits a long form into parts.", "\"HTML Content\". A block of instructions or formatted text. It is not a question."]}, {"p": "Most question fields also have a \"Data\" section. \"Dynamic default (URL param)\" pre-fills the answer from the link, for example ?email=jane@example.com. \"Read only\" stops the person from changing it."}, {"warn": "Signature and Initials answers are saved as text. Long signature images may be cut short when stored. Don't rely on a form signature as your formal record. Use the e-signature feature on SOPs and job descriptions instead (see \"My Signatures\")."}]}, {"title": "Letting people attach photos, video or recordings", "for": "everyone", "mod": "forms", "body": [{"p": "Use a \"File Upload\" or \"Recording\" field when a picture or short video explains the problem better than words."}, {"h": "File Upload"}, {"bullets": ["Accepted files: pictures (PNG, JPG, GIF, WEBP, HEIC), audio and video (MP4, MOV, WEBM, MP3, M4A, WAV), PDF, Word, Excel, PowerPoint, CSV, TXT, XML and JSON. Anything else is refused, and so is a file whose content doesn't match its extension.", "Each file can be up to 25 MB. The form shows \"Max 25 MB each\" under the field.", "In the builder, turn on \"Allow multiple\" to accept more than one file.", "\"Allowed types\" narrows the picker: Any supported file, Pictures only, Video only, Pictures or video, PDF only, or Documents (PDF and Office / text files).", "On a phone, the normal file picker usually offers to take a photo or record a video directly."]}, {"h": "Recording"}, {"p": "A Recording field shows three buttons: \"Record screen\", \"Record video\" (webcam) and \"Record voice\". The person clicks one and allows the browser to use the screen, camera or microphone. They click \"\u25a0 Stop\" when they are done. A screen recording also records the microphone, if the person allows it, so they can talk through the problem. Each recording stops automatically after 2 minutes and is uploaded as a file."}, {"p": "If the browser can't record, the field shows \"Recording is not supported on this browser\" with a normal upload box, so the person can attach a video or audio file instead."}, {"h": "What happens next"}, {"p": "Files upload as soon as they are chosen or recorded, and each file shows under the field. On a Ticket form, every uploaded file is attached to the new ticket. On a Data form, the file names are stored with the submission."}, {"tip": "Screen recording needs a desktop browser such as Chrome, Edge or Firefox. On phones, use \"Record video\" or a File Upload field."}, {"qa": [{"q": "The upload says \"File too large (max 25 MB)\".", "a": "Send a shorter clip or a smaller photo. Most phones can trim a video before you share it."}, {"q": "It says \"Too many uploads. Please wait a few minutes.\"", "a": "One network can upload about 30 files in 10 minutes. Wait a few minutes and try again."}]}]}, {"title": "Showing a field only when it's relevant (conditional fields)", "for": "admin", "mod": "forms", "body": [{"p": "A conditional field stays hidden until another answer calls for it. For example, you can ask \"Which laptop?\" only when someone picks \"Hardware\" in a Select Box."}, {"steps": ["In the builder, click the field that should appear or disappear.", "In the right-hand panel, find \"Conditional logic\" and switch on \"Show this field only if\u2026\".", "Under \"Field\", choose the question that controls it.", "Under \"Is\", choose \"equal to\". Under \"Value\", type the answer exactly as it appears in that field's options.", "Click \"Save\". The field now shows a \u25c8 mark on the builder canvas."]}, {"p": "On the live form, the field appears and disappears as the person answers. Hidden fields are skipped: they are not required and are not saved."}, {"tip": "The controlling field needs a label, because its key is made from the label when you save. Save the form once before you set up a condition that points at a new field."}, {"warn": "Don't base a condition on a \"Ticket Category\" field. It sends a category number, not the category name, so a condition such as \"equal to Software\" never matches."}, {"qa": [{"q": "My conditional field never appears.", "a": "Check that \"Value\" matches the option text exactly, including capital letters and spaces, and that the operator is \"equal to\"."}]}]}, {"title": "How form answers become a ticket", "for": "admin", "mod": "forms", "body": [{"p": "This topic explains exactly what ITOps puts on the ticket when someone submits a Ticket-type form. Read it before you design a new intake form."}, {"h": "What the ticket gets"}, {"bullets": ["A new ticket number, in the form TK-year-number, with status Open and priority Medium.", "Category: the answer to the \"Ticket Category\" field, if the form has one. If the person chose \"General / not sure\", the ticket has no category.", "Subject: the form's \"Public title\", unless a field is linked to the subject (see below).", "Description: every answer, one per line, as \"Label: answer\".", "Attachments: every file from \"File Upload\" and \"Recording\" fields.", "A copy of the answers under the form's \"Responses\"."]}, {"h": "Name, email and subject fields"}, {"p": "Each field can fill a ticket field: click the field in the builder and, under \"Data\", choose \"Fills this ticket field\": Requester email, Requester name, Ticket subject or Ticket description. The starter \"Help Request\" form already has them. If no field is set as the requester email, ITOps uses the first Email field on the form, and a text field labelled \"Name\" / \"Your name\" as the requester name. Then:"}, {"bullets": ["The email is matched to an ITOps user (for example their Microsoft 365 address), and that user becomes the requester: they see the ticket when they sign in. If there is no match, the person's name and email are saved as the contact (shown as EXT), and the ticket moves to their account automatically if they get one later.", "The person gets a confirmation email with their ticket number (the \"Request received (web page / form)\" email, which you can edit under Administration \u2192 Settings \u2192 Email templates).", "The subject field becomes the ticket subject."]}, {"p": "A form with no Email field still creates tickets, but nobody is linked as the requester and no confirmation email is sent. Add an Email field so people get their ticket number and updates."}, {"tip": "Mark the email field \"Required\" so every request can be linked and confirmed."}, {"qa": [{"q": "Can a form set the ticket's priority?", "a": "No. Form tickets always start at Medium. An agent can change the priority afterwards."}, {"q": "Are agents notified when a form ticket arrives?", "a": "The form does not send a separate alert. The ticket appears in Service Desk \u2192 Tickets like any other new ticket."}]}]}, {"title": "Form settings and sharing", "for": "admin", "mod": "forms", "body": [{"p": "Use this topic to publish a form, put it on a web page, or copy an existing form."}, {"h": "The Forms list"}, {"p": "Administration \u2192 Forms shows every form with its type (Ticket or Data), its link (form.html?f=slug) and its number of submissions. Each form has these buttons:"}, {"bullets": ["\"Submissions (n)\": read the responses.", "\"Preview\": opens the live public page in a new tab.", "\"Copy embed\": copies an iframe snippet to paste into a website or intranet page.", "\"Duplicate\": makes a copy called \"(copy)\". The copy is inactive until you set it to Active.", "Pencil icon: open the form in the builder. Bin icon: delete the form."]}, {"h": "Sharing the link"}, {"steps": ["Click \"Preview\" and copy the address from the new tab, or build it yourself: your ITOps address + /form.html?f= + the slug.", "To pre-fill answers, add URL parameters for fields that have \"Dynamic default (URL param)\" turned on, for example &email=jane@example.com.", "To send people to another page after they submit, add &redirect= followed by the full web address. For safety it is only followed to ITOps itself, to redirect URLs set in ITOps, or to a host listed under Settings \u2192 \"Trusted redirect hosts\" (for example example.org); anything else is ignored."]}, {"h": "Settings tab"}, {"bullets": ["\"Link slug\": the last part of the link. Changing it breaks links and embeds you have already shared.", "\"Status\": \"Active \u2014 accepting responses\" means the form is live. \"Inactive\" takes it offline: anyone who opens the link sees \"Form unavailable\". Existing submissions are kept."]}, {"warn": "To pause a form temporarily (for example outside an enrolment window), set it to Inactive rather than deleting it. The Forms list shows \"inactive\" next to its name."}, {"warn": "Deleting a form also deletes all of its submissions. This can't be undone. Export the responses first."}, {"qa": [{"q": "Someone gets \"Too many submissions. Please try again in a few minutes.\"", "a": "Each network can submit about 5 times in 10 minutes to block spam. Everyone in one office shares a network, so wait a few minutes before trying again."}]}]}, {"title": "Reading and exporting form responses", "for": "admin", "mod": "forms", "body": [{"p": "Every submission to a form is stored, for both Ticket and Data forms. You can read submissions on screen or download them as a spreadsheet."}, {"steps": ["Go to Administration \u2192 Forms and click \"Submissions (n)\" on the form. You can also open the form and use its \"Responses\" tab.", "The table shows when each response was \"Submitted\", the person's \"Name\" and the first few answers.", "Click \"View\" on a row to see every answer. For Ticket forms, the ticket number is shown next to the date.", "Click \"Export CSV\" to download every response as a spreadsheet file."]}, {"p": "The export from \"Submissions (n)\" includes Submitted, Name, Email and Ticket columns, then one column per question. The export from the \"Responses\" tab doesn't include the Ticket column."}, {"tip": "The Name and Email columns are only filled when the form has fields linked to requester name and email, as the starter \"Help Request\" form does. For other forms, look for the answers in the question columns."}, {"p": "The list shows the latest 1,000 responses. For very busy forms, export regularly."}, {"qa": [{"q": "I can't open responses on a new form.", "a": "Save the form first. The \"Responses\" tab shows \"Save the form first to start collecting responses.\" until then."}]}]}]}, {"cat": "Knowledge & procedures", "topics": [{"title": "Using the Knowledge Base", "for": "everyone", "mod": "kb", "body": [{"p": "The Knowledge Base holds how-to articles written by the IT team and other departments. Use it to fix common problems yourself before you raise a ticket."}, {"steps": ["In the sidebar, open Knowledge \u2192 Knowledge Base.", "The list shows each article's \"Title\", \"Category\", \"Status\" and \"Views\". Click a row to open the article.", "To find something by keyword, type at least two letters in the search box at the top of the screen (\"Search tickets, KB, SOPs\u2026\"). Clicking a Knowledge Base result takes you to the Knowledge Base list. Open the article from there.", "The article opens as its own page. Click \"\u2190 Back\" to return to the list, where your place is kept. \"\u2b07 PDF\" downloads it; \"\u2197 Window\" opens it in a separate window, which is useful while you follow the steps."]}, {"p": "Articles marked Published are finished and checked. Draft and Archived articles may also appear in the list. Treat them as unfinished or out of date."}, {"p": "There is also a public version at help.html (\"IT Knowledge Base\"). It shows only Published articles, has a search box and category filters, and works without logging in. It's handy on a phone or when you can't sign in."}, {"tip": "Not sure what to search for? Try Ask IT (Knowledge \u2192 Ask IT) and describe the problem in your own words."}, {"p": "If you can write articles, you'll also see \"New Article\", \"\u270f Edit\" and the edit and delete icons (each follows your role: Create, Edit, Delete). Editing opens as its own page too; \"Save changes\" takes you back to the article, updated. See \"Writing good Knowledge Base articles\".", "mod": "kb:create"}, {"qa": [{"q": "I can't find an answer.", "a": "Ask IT, or raise a ticket from Service Desk \u2192 Tickets. Unanswered Ask IT questions are collected so the team knows which article to write next."}, {"q": "I clicked \"Edit\" or \"New Article\" and got \"Insufficient permissions\".", "a": "Reading articles only needs Knowledge Base View. Writing needs Create, changing needs Edit, and deleting needs Delete. Ask an administrator if you need more access."}]}, {"p": "Published articles are for everyone signed in. An article also appears on the public help portal (the page people use without signing in) only when its editor ticks \"Show on the public help portal\" \u2014 off for every article to start. The list shows \"public\" or \"staff only\" in the Help portal column. Votes on the portal (\"Was this helpful?\", \"This solved it\") count once per visitor."}]}, {"title": "Ask IT \u2014 the AI knowledge assistant", "for": "everyone", "mod": "kb_assist", "body": [{"p": "Ask IT is a chat assistant that answers questions from your published Knowledge Base articles. Use it when you don't know what an article is called, or when you want to describe a problem in your own words."}, {"steps": ["In the sidebar, open Knowledge \u2192 Ask IT.", "Type your question in the box, for example \"I can't get my email on my phone\", and press Enter or click \"Send\".", "Read the reply. If it used articles, buttons with the article titles appear under it. Click one to open the full article in a window.", "If the assistant needs more detail, it may show suggested follow-ups as small buttons. Click one to send it, or type your own answer."]}, {"h": "What to expect"}, {"bullets": ["Answers come from Published Knowledge Base articles first. Drafts are never used.", "If no article covers your question, the assistant says so and suggests raising a ticket. It does not create the ticket for you. Go to Service Desk \u2192 Tickets to do that.", "If your organisation allows it, the assistant may give general Microsoft 365 or IT guidance when no article exists. These answers have \"Verify with:\" links to trusted sites. Check the steps there.", "The chat is not saved. If you leave the page or refresh, the conversation starts again."]}, {"warn": "Don't type passwords, personal data or client details into Ask IT. Questions are sent to an outside AI service to be answered, and the start of each question is recorded in the Audit Log."}, {"p": "Admins: the assistant only works when AI is switched on under Administration \u2192 Settings \u2192 Sign-in & AI \u2192 \"AI assist\" (\"Enable AI assist\", provider and API key). Questions it couldn't answer from the Knowledge Base appear on Knowledge \u2192 KB Content Gaps. Super Admins can also allow general guidance and edit the \"Trusted sources\" list there.", "mod": "settings:edit"}, {"qa": [{"q": "It says \"The AI assistant is not enabled.\"", "a": "AI assist has not been switched on or has no API key. Ask an administrator."}, {"q": "I can see Ask IT but every question fails with \"Insufficient permissions\".", "a": "Your role needs Ask IT (or Knowledge Base View, which includes it). An administrator can add it in Administration \u2192 Roles & Permissions."}]}]}, {"title": "Writing good Knowledge Base articles", "for": "admin", "mod": "kb:create", "body": [{"p": "This topic shows how to write and publish an article that people can find and follow without help. You need Knowledge Base Create to add articles and Edit to change them."}, {"h": "Create the article"}, {"steps": ["Go to Knowledge \u2192 Knowledge Base and click \"New Article\". Use \"\u2197 New window\" instead if you want to write while looking at something else.", "Enter a \"Title\". Write it the way people ask, for example \"Set up Outlook on an iPhone\", not \"Mobile mail config\".", "Choose a \"Category\". The list is set up when ITOps is installed, and there is no screen to add new categories.", "Write the \"Content\". Use \"Heading\" and \"Subheading\" for sections, the numbered list for steps and \"Insert table\" for settings. Click \"Image\" to add a screenshot (PNG, JPG, GIF or WEBP, up to 8 MB).", "Leave \"Status\" as Draft while you work, then click \"Create Article\"."]}, {"h": "Publish it"}, {"p": "Open the article, click \"Edit\", set \"Status\" to Published and click \"Save Changes\". Published articles appear in:"}, {"bullets": ["the public IT Knowledge Base page (help.html), which anyone with the link can read without logging in;", "the suggestions shown on the public ticket page while someone types their request (with \"This solved it \u2014 no ticket needed\" and thumbs up and down buttons);", "Ask IT answers."]}, {"warn": "Published means public. Never put passwords, internal IP addresses, client names or anything confidential in a Published article. Keep that kind of information in Credentials or an SOP."}, {"h": "Tips for articles that work"}, {"bullets": ["One task per article. Say who it is for and what they need first.", "Write numbered steps using the exact button names people see on screen.", "Say what success looks like, and what to do if it fails (usually: raise a ticket)."]}, {"p": "Draft articles are hidden from the public page and from Ask IT, but colleagues with Knowledge Base access can still see them in the list. Setting an article to Archived, or deleting it, takes it off the public page. \"Delete\" actually sets the status to Archived, so you can still find the article afterwards."}, {"tip": "Check Knowledge \u2192 KB Content Gaps for questions people asked Ask IT that had no answer. Write the article, then click \"Mark covered\". The same page shows which articles readers found least helpful, and has \"Seed starter articles\" to add ready-made drafts."}, {"tip": "Tick \"Show on the public help portal\" only for articles meant for anyone (password reset, Wi-Fi, how to ask for help). Internal procedures, known errors and anything about your systems stay staff only."}]}, {"title": "What SOPs are", "for": "everyone", "mod": "sops", "body": [{"p": "SOPs (Standard Operating Procedures) are your organisation's official, step-by-step procedures. Unlike a Knowledge Base article, an SOP has version numbers, an owner who keeps it current, and an audience: the people who must read and acknowledge the current version."}, {"steps": ["In the sidebar, open Knowledge \u2192 SOPs. The list shows each SOP's \"Title\", \"Status\", version (\"Ver\"), \"Owner\", who it is \"For\" (Everyone or Selected people), your own status (\"You\": To read, Acknowledged or Not for you) and \"Next Review\".", "Click a row to open it. Switch between \"Document\" and \"Flowchart\" to read it as text or as a diagram.", "Use \"\u2b07 Word\" or \"\u2b07 PDF\" to download a copy, or \"\u2197 Open in window\" to keep it open while you work.", "Below the procedure you'll see how many staff have acknowledged this version, your own status, \"Show version history\" and \"Who acknowledged\"."]}, {"p": "Use the list filter to switch between \"All SOPs\", \"For me to read\" (SOPs whose audience includes you) and \"I own\" (SOPs you keep up to date)."}, {"h": "Statuses"}, {"p": "An SOP can be Draft, Under review, Approved, Published or Archived. Only Published SOPs count towards the compliance report. A Published SOP is the one you are expected to follow."}, {"p": "Each time the content of an SOP changes, its version number goes up by one. Your earlier acknowledgement then no longer counts, and you'll need to acknowledge the new version."}, {"tip": "An SOP may also have \"Signatures\" and \"Related items\" sections. Related items link it to job descriptions, credentials, contracts or vendors."}, {"qa": [{"q": "I only see \"Read-only access\" instead of \"New SOP\".", "a": "You can read and acknowledge SOPs but not write them. Creating SOPs needs the SOPs Create permission."}]}]}, {"title": "Creating and updating an SOP", "for": "admin", "mod": "sops:edit", "body": [{"p": "Use this topic to write a new procedure or change an existing one. You need SOPs Create to add SOPs and SOPs Edit to change them."}, {"h": "Create an SOP"}, {"steps": ["Go to Knowledge \u2192 SOPs and click \"New SOP\". To start from an example, click \"\ud83d\udccb Templates\". To draft it with AI, click \"\u2728 Build with AI\" (see the tip below).", "Under \"Who must read and acknowledge it\", choose \"Everyone who can open SOPs\", or \"Selected people or departments\" and tick the departments and people it applies to.", "Fill in \"Title\" (required), \"Owner \u2014 keeps it current and gets the review reminders\" (leave it empty to be the owner yourself), \"Category\", \"Department\", \"Review frequency (days)\" and \"Next review\".", "Write the procedure in \"Procedure / Content\" using the toolbar for headings, numbered steps and tables.", "Leave \"Status\" as Draft or Under review while it is being checked.", "Click \"\ud83d\udcbe Create SOP\". It is saved as version 1, \"Initial version\"."]}, {"h": "Update an SOP"}, {"steps": ["Open the SOP and click \"\u270f Edit\".", "Make your changes and describe them in \"Change note \u2014 saved to version history when content changes\".", "Set \"Status\" to Published when it is ready, and click \"\ud83d\udcbe Save changes\"."]}, {"h": "Owner and audience"}, {"bullets": ["The owner must be an active user whose role can create or edit SOPs. They get a bell notice when they are made owner, and the SOP review reminders 14 days before \"Next review\" and again once it is overdue (to the admins when there is no owner).", "Only people whose role can open SOPs (SOPs \u00b7 View) are ever asked to acknowledge an SOP, counted in the compliance report or reminded. If you pick someone whose role can't open SOPs, the editor warns you and they are skipped.", "A person is in the audience when they are picked by name or their department is picked. Changing the audience changes the compliance report straight away."]}, {"h": "What happens next"}, {"bullets": ["If you changed the content, the version goes up by one (for example v3 to v4). Your change note is saved in \"version history\".", "Everyone in its audience has to acknowledge the new version. Acknowledgements for older versions no longer count.", "Changing only the status, dates or category does not create a new version.", "People are not notified automatically when you publish. Use Compliance \u2192 \"Remind\" to ask its audience to acknowledge.", "People who can only read SOPs see published SOPs only; drafts, SOPs under review and archived SOPs are for editors.", "The text is cleaned when it is saved: scripts, frames, forms and javascript: links are removed."]}, {"warn": "The version is the app's own: it goes up by one when the text changes and cannot be set by hand (an attempt is refused and logged), so older acknowledgements never count again."}, {"tip": "\"\u2728 Build with AI\" opens the SOP Builder. Describe the process, pick a \"Format\" (for example Step-by-step or Checklist), or use \"\ud83d\udcc4 Paste existing\" and \"\u2728 Modernize\" to rework an old document. \"Insert\" puts the draft into a new SOP as Draft for you to check. The builder only works when AI assist is enabled."}]}, {"title": "Acknowledging an SOP", "for": "everyone", "mod": "sops", "body": [{"p": "Acknowledging an SOP records that you have read the current version and will follow it. Managers use these records to show who is up to date."}, {"steps": ["Open Knowledge \u2192 SOPs and click the SOP.", "Read the whole procedure, in the \"Document\" or \"Flowchart\" view.", "Below the procedure, click \"Acknowledge this version\"."]}, {"p": "The button is replaced by \"You acknowledged vN on\" and the date. ITOps records your name, the version, the time and your network address. Your name appears under \"Who acknowledged\"."}, {"h": "Which SOPs do I need to acknowledge?"}, {"p": "You need to acknowledge the Published SOPs that are for you: those set to \"Everyone who can open SOPs\", and those whose audience names you or your department. In Knowledge \u2192 SOPs, the \"You\" column says \"To read\" for each one still waiting, and the \"For me to read\" filter lists only yours. If a manager sends a reminder, you get a notification (bell icon at the top) and usually an email that says how many SOPs are waiting. Clicking the notification opens the SOPs list."}, {"p": "When an SOP's content changes, it gets a new version number and you need to acknowledge it again."}, {"tip": "Acknowledging is not the same as signing. If you were asked to e-sign a document, it appears in Knowledge \u2192 My Signatures, and signing it there does not acknowledge the SOP. You may need to do both."}, {"qa": [{"q": "I acknowledged last month but it's asking again.", "a": "The SOP was updated to a new version. Open it, check what changed under \"Show version history\", then acknowledge again."}, {"q": "I don't see an Acknowledge button.", "a": "If you see \"You acknowledged\u2026\", you're already up to date. If you can't open SOPs at all, your role needs SOPs View."}]}]}, {"title": "The SOP compliance report (managers)", "for": "admin", "mod": "sops:edit", "body": [{"p": "The compliance report shows, for every Published SOP, who has acknowledged the current version and who hasn't. Use it before audits, or after you publish an update. You need SOPs Edit to open it and to send reminders."}, {"steps": ["Go to Knowledge \u2192 SOPs and click \"Compliance\".", "The top line shows how many people can open SOPs and how many SOPs are Published. Each SOP shows its version, a progress bar and \"acknowledged / total \u00b7 %\", where total is the people that SOP is for.", "Click \"Missing (n)\" to see who hasn't acknowledged, with their department.", "Click \"Remind\" on one SOP to notify the people in its audience who are missing it.", "Click \"Remind everyone\" to send each person with any outstanding SOP one reminder that says how many are waiting.", "Click \"CSV\" to download the gap list: SOP, version, outstanding user, email and department."]}, {"h": "What people receive"}, {"p": "Each reminded person gets an in-app notification and an email. \"Remind\" uses the \"Please acknowledge an SOP\" email, and \"Remind everyone\" uses \"SOP acknowledgment reminder (all SOPs)\". You can reword both under Administration \u2192 Settings \u2192 Email templates, where they can also be switched off. A message shows how many people were reminded."}, {"bullets": ["\"Total\" means the active users in the SOP's audience whose role can open SOPs. People without SOPs \u00b7 View are never counted or reminded. Deactivating a leaver in Administration \u2192 Users takes them out of the count.", "Only acknowledgements of the current version count. After an update, everyone starts again at 0%.", "Draft, Under review, Approved and Archived SOPs are not listed."]}, {"tip": "For a single SOP, open it and click \"Who acknowledged\" to see names and times."}, {"qa": [{"q": "Clicking \"Compliance\" shows \"Insufficient permissions\".", "a": "The button is visible to everyone who can see SOPs, but the report needs SOPs Edit."}]}]}, {"title": "My Signatures \u2014 documents waiting for your signature", "for": "everyone", "mod": "my_signatures", "body": [{"p": "My Signatures lists every document someone has asked you to e-sign in ITOps, such as an SOP or your job description. Use it to sign them."}, {"steps": ["When someone asks you to sign, a \"Signature requested\" notification appears under the bell icon. Click it, or open Knowledge \u2192 My Signatures.", "Each document shows its title, when it was requested and any message from the sender.", "Click \"Sign now\". The window shows the document (and its version) exactly as it was when the request was sent. Read it there.", "Choose \"\u270d Draw\" to sign with the mouse or your finger, or \"\u2328 Type\" to type your name and pick a font. Use \"Clear\" to start again.", "Tick \"I agree that this is my electronic signature\u2026\" and click \"\u2714 Sign document\"."]}, {"warn": "If the document changed after the request was sent, the window says so and \"Sign document\" is off: a signature is always for the version you were asked to sign. Ask the sender for a new request. Cancelled and completed requests cannot be signed either."}, {"h": "What happens next"}, {"p": "The document disappears from your list. Your signature, time and network address are saved on the document's \"Signatures\" section, where people who can open the document can view it. When every signer has signed, the person who sent the request gets an \"All signatures collected\" notification."}, {"p": "If you have nothing waiting, the page says \"Nothing to sign right now.\"."}, {"tip": "Onboarding reading for new starters is sent by email with a signing link instead, so it doesn't appear here."}, {"h": "Asking others to sign (editors)", "mod": ["sops:edit", "job_descriptions:edit"]}, {"steps": ["Open the SOP or job description and scroll to \"Signatures\".", "Click \"\u270d Request signatures\". Add an optional \"Message\", then tick people under \"Signers\".", "For people without an ITOps account, click \"+ Add\" under \"External signers (by email)\". They get an email link and can read and sign without logging in.", "Click \"Send request\". The \"Signatures\" section then shows \"n of n signed\" and each signer's status.", "The request takes the document's title and version. Change the document after sending it and the request is marked \"the document changed since \u2014 send a new request\"."], "mod": ["sops:edit", "job_descriptions:edit"]}, {"qa": [{"q": "Is signing the same as acknowledging an SOP?", "a": "No. They are recorded separately. The SOP compliance report only counts \"Acknowledge this version\"."}, {"q": "How long does an emailed signing link work?", "a": "30 days. After that the page says the link has expired; the sender sends a new request."}]}]}, {"title": "Job Descriptions", "for": "everyone", "mod": "job_descriptions", "body": [{"p": "Job Descriptions is the library of official role descriptions. Each one has a status, a review date and version history. Use it to read a role, download it for HR, or collect signatures on it."}, {"steps": ["Open Knowledge \u2192 Job Descriptions. The list shows \"Title\", \"Status\" and \"Next Review\".", "Click a row to read it. Use \"\u2b07 Word\" or \"\u2b07 PDF\" to download it, or \"\u2197 Open in window\".", "Below the text, you'll see \"Signatures\", \"Version history\" and \"Related items\" (linked SOPs, credentials, contracts or vendors)."]}, {"p": "Statuses are Draft, Under review, Approved, Published and Archived. Every time the text changes, a new version is saved in \"Version history\"."}, {"h": "Building a job description", "mod": ["job_descriptions:create", "job_descriptions:edit"]}, {"steps": ["Click \"New Job Description\", or start from \"\ud83d\udccb Templates\".", "Fill in \"Job title\" (required), \"Department\", \"Reports to\", \"Employment type\" (Full-time, Part-time, Contract, Temporary, Intern or Per diem), \"Location\", \"Review frequency (days)\" and \"Next review\".", "Write the role in \"Job description\". Keep \"Status\" as Draft until HR has approved it.", "Click \"\ud83d\udcbe Create Job Description\". To change it later, open it, click \"\u270f Edit\" and then \"\ud83d\udcbe Save changes\"."], "mod": ["job_descriptions:create", "job_descriptions:edit"]}, {"tip": "\"\u2728 Build with AI\" opens the Job Description Builder. Give the role title and department, pick a \"Format\" (Standard, Concise, Comprehensive, Competency-based or Custom\u2026) and click \"Insert\" to open the draft as a new Draft job description. To rework an old job description, open it and click \"\u2728 Modernize\". Both need AI assist to be enabled.", "mod": ["job_descriptions:create", "job_descriptions:edit"]}, {"warn": "\"Delete\" asks you to type DELETE to confirm. Deleted job descriptions are archived rather than erased, but they are removed from normal use. Set the status to Archived instead if you only want to retire one.", "mod": "job_descriptions:delete"}, {"qa": [{"q": "I see \"Read-only access\".", "a": "Your role can view job descriptions but not create them. Building needs Job Descriptions Create, and changing needs Edit."}, {"q": "How do I get staff to sign their job description?", "a": "Open it, go to \"Signatures\" and click \"\u270d Request signatures\". See \"My Signatures\"."}]}]}]}, {"cat": "Vault, contracts & vendors", "topics": [{"title": "The Credentials vault: storing, revealing and copying secrets", "for": "everyone", "mod": "creds", "body": [{"p": "Assets & Vendors \u2192 Credentials is the encrypted vault for shared logins, service accounts, API keys and license keys. Use it whenever the team needs to share a password or key, instead of keeping it in a spreadsheet or email."}, {"h": "Add a credential"}, {"steps": ["Go to Assets & Vendors \u2192 Credentials and click \"New Credential\".", "Fill in \"Name\" (required) and, where useful, \"Category\", \"Department\", \"System URL\" and \"Environment\" (Production, Staging, Development or Other).", "Enter the secret fields: \"Username\", \"Password\", \"API key\" and \"Secure notes\". ITOps encrypts these four fields before saving them.", "To get rotation reminders, enter \"Rotate every (days)\". ITOps sets the next rotation date that many days from today.", "If the secret itself expires (a license, certificate or key with an end date), fill in both \"Term valid from\" and \"Term valid until\". Leave both empty if there is no fixed term.", "Click \"Create Credential\"."]}, {"p": "The record gets a reference such as CR-0012, and you become its owner. The owner is the person who gets the rotation reminders."}, {"h": "Reveal or copy a secret"}, {"steps": ["Click the credential in the list. The \"Details\" tab has a \"Stored secrets\" box.", "Click \"Reveal\" and re-enter your own ITOps password. If you use ITOps's 2FA, you are asked for a current code too (each code works once). If you sign in with Microsoft 365 only, leave the box blank: when your Microsoft sign-in is more than 15 minutes old, choose \"Sign in again\" first.", "Each value stays masked until you click \"Show\". Click \"Copy\" to put a value on your clipboard."]}, {"p": "Secrets are only sent to your browser when you reveal them. Every reveal is logged, with your name and IP address, and shows in the credential's \"Change history\" tab as \"Secrets revealed\". A wrong password shows there as \"Reveal denied (wrong password)\"."}, {"bullets": ["Without Credentials \u00b7 All records, you reveal only the secrets of your own department and those with no department. Every refused reveal is in the Audit Log.", "After 5 wrong passwords in 15 minutes, revealing waits for about 15 minutes."]}, {"h": "Change a stored secret"}, {"p": "Open the credential and click \"Edit\" (or the pencil icon in the list). The secret fields are empty and marked \"(blank = unchanged)\". Type only the values you want to replace, then click \"Save changes\". The old values are kept in \"Change history\"."}, {"warn": "Every reveal is audited, including admins' reveals. Only reveal a secret when you need it. Never paste a secret into a ticket, chat or email."}, {"qa": [{"q": "I don't see \"New Credential\". The page says \"Read-only access\".", "a": "Your role only has View on Credentials. An administrator can add Create (and Edit, to change records) under Administration \u2192 Roles & Permissions \u2192 Credentials."}, {"q": "Can a script or integration read passwords through the API?", "a": "No. Requests made with an API key are refused with \"Secrets cannot be revealed with an API key\". Only a signed-in person who re-enters their password can reveal a secret."}, {"q": "I get \"Password verification failed\".", "a": "Enter your own ITOps sign-in password, not the password stored in the credential. ITOps logs the failed attempt."}, {"q": "What happens when I delete a credential?", "a": "It is archived, not erased. It leaves the normal list and becomes read-only. To see it again, tick \"Show closed / renewed terms\" above the list. Deleting needs Delete on Credentials."}]}]}, {"title": "Rotation dates and reminders", "for": "everyone", "mod": "creds", "body": [{"p": "Rotation reminders make sure shared passwords and keys get changed on schedule. Use them for any credential your policy says must be changed regularly."}, {"h": "Set up rotation"}, {"steps": ["When you create the credential, enter \"Rotate every (days)\", for example 90. ITOps sets the next rotation date that many days from today.", "To change the date later, open the credential, click \"Edit\" and change \"Next rotation date (shows on Calendar)\". This field only appears when you edit a credential.", "The date shows in the list as \"Next Rotation\" and on Service Desk \u2192 Calendar as \"Credential rotation\"."]}, {"h": "What happens as the date gets close"}, {"bullets": ["14 days before the date, the owner gets a \"Credential rotation due in N day(s)\" notification in the bell, and by email if email is set up. The \"Rotation\" status changes from Current to Due soon.", "Once the date has passed, the owner gets a \"Credential rotation overdue\" notification and the status changes to Overdue.", "Each reminder is sent once per rotation date. If the owner's account is inactive, the reminders go to the Super Admins and Dept Admins.", "ITOps's scheduled job sends the reminders. It runs on the server's schedule, or every few minutes while someone has ITOps open."]}, {"h": "After you rotate the secret"}, {"steps": ["Change the password or key in the real system first.", "In ITOps, open the credential and click \"Edit\".", "Type the new value in \"Password\" or \"API key\".", "Set \"Next rotation date\" to the next due date.", "Set \"Rotation status\" back to \"Current\" and click \"Save changes\"."]}, {"warn": "Saving a new password does not reset the status or the date. If \"Rotation status\" stays on Due soon or Overdue, the credential keeps showing that status. Changing \"Rotate every (days)\" does not recalculate the date either."}, {"tip": "If the credential has a term (for example a license key with an end date), you can also renew it under \"Terms & renewals\". The new term starts as Current, with the next rotation date set to today plus \"Rotate every (days)\" (90 days if that is empty)."}, {"tip": "Set \"Rotation status\" to \"Disabled\" for a credential that is never rotated. Disabled credentials get no reminders and don't appear on the Calendar."}, {"qa": [{"q": "Who is the owner?", "a": "The person who created the credential. The credential form has no field to change the owner."}, {"q": "Can I move the date from the Calendar?", "a": "Yes. Drag the \"Credential rotation\" item to another day, or click it and use \"Reschedule\". You need Edit on Credentials. Moving the date does not change the \"Rotation status\"."}]}]}, {"title": "Tracking contracts and renewals", "for": "everyone", "mod": "contracts", "body": [{"p": "Assets & Vendors \u2192 Contracts records your subscriptions, licenses, service agreements, leases and maintenance agreements, so no renewal is missed. Add a contract as soon as it is signed."}, {"h": "Add a contract"}, {"steps": ["Go to Assets & Vendors \u2192 Contracts and click \"New Contract\".", "Enter \"Title\", \"Term start\" and \"Term end\" (all required).", "Pick the \"Vendor\" so the contract shows on that vendor's record. Add \"Contract #\", \"Type\", \"Total value\", \"Payment amount\", \"Payment frequency\" and \"Department\" as needed.", "Set \"Renewal notice (days)\": how many days before the end date you want to start the renewal. If you leave it empty, ITOps uses 90 days.", "Click \"Create Contract\"."]}, {"p": "The contract gets a reference such as CT-0005, and you become its owner."}, {"h": "How the status changes"}, {"bullets": ["Active: more time remains than the notice period.", "Expiring: the end date is within the notice period. The owner gets a \"Contract renewal due in N day(s)\" notification in the bell, and by email if email is set up.", "Expired: the end date has passed. The owner gets a \"Contract expired\" notification.", "You can't set the status by hand. It follows the dates, or changes when you renew or close the term. If you correct the end date of an expired contract to a future date, it becomes active again.", "If the owner's account is inactive, reminders go to the Super Admins and Dept Admins."]}, {"h": "The contract record"}, {"p": "Click a contract to open it. The tabs are \"Details\", \"Terms & renewals\" (see the next topic), \"Vendor\" (a summary of the linked vendor, with \"Open vendor \u2192\"), \"Documents\" and \"Change history\"."}, {"p": "On \"Documents\", click \"+ Attach file\" to upload the signed agreement, quotes or invoices. Each file can be up to 15 MB. Allowed types are PDF, Word, Excel, PowerPoint, PNG, JPG, GIF, WebP, TXT, CSV, ZIP, MSG and EML. Click a file name to download it."}, {"tip": "\"Auto-renew\" is only a note for your team. ITOps never renews a contract by itself. When the new term is confirmed, use \"Renew\" on the \"Terms & renewals\" tab."}, {"qa": [{"q": "I can't upload a document.", "a": "Uploading needs Edit on Contracts. Viewing and downloading need View. An administrator can change this under Administration \u2192 Roles & Permissions."}, {"q": "The Edit button is missing on a contract.", "a": "That term has been renewed or closed, and closed terms are read-only history. Open the current term instead: the newest reference, for example CT-0005-R1."}, {"q": "Who gets the renewal reminder?", "a": "The contract's owner, who is the person who created it. The contract form has no field to change the owner."}]}]}, {"title": "Terms & renewals (CT-0005 \u2192 CT-0005-R1)", "for": "everyone", "mod": ["contracts", "creds"], "body": [{"p": "Terms & renewals keeps a separate record for each period of a contract or credential. Use it when a contract or license is renewed, or when it ends and is not renewed."}, {"bullets": ["Each record is one term, with a start date and an end date. The first term is the original: CT-0005 for a contract, CR-0012 for a credential.", "Renewing creates the next term: CT-0005-R1, then CT-0005-R2 and so on. The old term is closed and kept as read-only history, with its own change history.", "The \"Term\" column shows active, expiring (within the renewal notice period, or 90 days if none is set), expired, renewed or ended. A credential without an end date shows open."]}, {"h": "Renew"}, {"steps": ["Open the current term and go to the \"Terms & renewals\" tab.", "Click \"\u21bb Renew \u2014 start a new term\".", "Check \"New term start\" and \"New term end\". They are pre-filled with the same length as the current term, starting the day after it ends.", "For a contract, update \"Contract # (new term)\", \"Total value\" and \"Payment amount\" if they changed. For a credential, you can enter a \"New username\", \"New password\" or \"New API key / license key\". Leave a field blank to keep the current value.", "Write the \"Renewal note\": how it was renewed, who approved it, the quote or PO number and any price change. The note is required.", "Click \"Create renewed term\". ITOps then opens the new term."]}, {"p": "All other details (title, vendor, type, department, notice period, notes) are copied to the new term. For a credential, rotation starts again from today."}, {"h": "Rules ITOps checks"}, {"bullets": ["The end date must be after the start date. A single term can't be longer than 10 years, and you get a warning above 5 years.", "The new term must start after the previous term started.", "Early renewal: if the new term starts before the current one ends, the current term's end date moves to the day before the new start.", "Gap: if the new term starts more than one day after the current one ends, you can still save it. The gap is recorded in the renewal note."]}, {"h": "Close a term without renewing"}, {"steps": ["On \"Terms & renewals\", click \"Close term without renewing\".", "Pick a \"Reason\": \"Not renewed \u2014 let it lapse\", \"Terminated early\" or \"Expired\". You can also set the \"Actual end date\".", "Write a \"Note\" (required), click \"Close term\" and confirm."]}, {"warn": "You can't undo a renewal or a closed term on screen. A closed term is read-only: you can no longer edit its details."}, {"tip": "Contract documents stay on the term they were attached to. To find the agreement for an earlier period, click \"Open\" on that term in \"Terms & renewals\" and look at its \"Documents\" tab. To include old terms in the Contracts or Credentials list, tick \"Show closed / renewed terms\"."}, {"qa": [{"q": "I don't see the Renew button.", "a": "Renewing needs Create on Contracts (or Credentials), and closing needs Edit. The buttons only show on the current term. On an older term you'll see \"A newer term exists\", so open the latest term."}]}]}, {"title": "Record history and past secrets", "for": "everyone", "mod": ["creds", "contracts", "vendors", "sops"], "body": [{"p": "Record history shows who changed a record, when, and what each field was before and after. Use it to find out who changed something, or to get back an old value."}, {"h": "Where to find it"}, {"p": "Credentials and contracts: open the record and choose the \"Change history\" tab.", "mod": ["creds", "contracts"]}, {"p": "Vendors: open the vendor and choose the \"History\" tab.", "mod": "vendors"}, {"p": "SOPs: open the SOP and click \"Show version history\" to list the earlier versions. Click a version to read it.", "mod": "sops"}, {"p": "The newest entries are at the top. Each entry shows what happened (for example Created, Updated or Deleted), the date and time, and who did it. For an update, a table lists each field that changed, with its value before and after. You only need View on the module to see the history. The tab shows up to the latest 300 events for a record.", "mod": ["creds", "contracts", "vendors"]}, {"h": "Past secrets (credentials only)", "mod": "creds"}, {"p": "Secret fields (username, password, API key, secure notes) never show their values in the history. They appear as \"secret changed\". To see what a secret was before a change:", "mod": "creds"}, {"steps": ["Open the credential and go to \"Change history\".", "On the \"Updated\" entry, click \"Values before this change\".", "Click \"Reveal\" and re-enter your ITOps password. If you use Microsoft 365 sign-in (SSO), leave it blank.", "Use \"Show\" or \"Copy\" next to each value, then click \"Close\"."], "mod": "creds"}, {"bullets": ["Every reveal of a past secret is logged and shows in the history as \"Past secrets revealed\".", "Past secrets can never be revealed with an API key.", "Each term of a renewed credential keeps its own history. Open an older term from \"Terms & renewals\" to see its history."], "mod": "creds"}, {"qa": [{"q": "Can I restore an old value?", "a": "There is no restore button. Copy the old value from the history, then click \"Edit\" on the record and paste it in."}], "mod": ["creds", "contracts", "vendors"]}]}, {"title": "Vendors: contacts, contracts and documents", "for": "everyone", "mod": "vendors", "body": [{"p": "Assets & Vendors \u2192 Vendors is the address book for the companies you buy from: who to call, how to reach support, and which contracts you have with them. Check it first when a supplier's system breaks or a renewal is coming up."}, {"h": "Add a vendor"}, {"steps": ["Go to Assets & Vendors \u2192 Vendors and click \"New Vendor\".", "Enter \"Name\" (required), \"Category\", \"Risk tier\" (Low, Medium, High or Critical) and \"Status\" (Active, Inactive or Under review).", "Add the \"Website\", the \"Account manager\", the main contact (\"Contact name\", \"Contact email\", \"Contact phone\") and the support details (\"Support URL\", \"Support email\", \"Support phone\").", "Enter \"SLA response (hrs)\" if the vendor promises a response time. Add the \"Department\" and any \"Notes\".", "Click \"Create Vendor\"."]}, {"h": "The vendor record"}, {"p": "Click a vendor in the list to open it. It has five tabs:"}, {"bullets": ["\"Details\": everything entered on the form.", "\"Contracts & renewals\": every contract with its \"Vendor\" set to this vendor, newest end date first, with its reference, dates, value and status. The newest one is marked LATEST. Click \"Documents\" to see a contract's files, or \"Open contract \u2192\" to go to the contract.", "\"Contacts\": as many people as you need. Click \"+ Add contact\" and fill in \"Name\" (required), \"Title\", \"Email\", \"Phone\", \"Role\" (General, Billing, Support, Sales, Technical or Escalation) and \"Notes\", then click \"Save contact\". Tick \"Primary contact\" to mark the main person. Only one contact can be primary.", "\"Documents\": click \"+ Attach file\" to add documents such as W-9s, security questionnaires and price lists. Each file can be up to 15 MB and must be a PDF, Office, image, TXT, CSV, ZIP, MSG or EML file.", "\"History\": who changed the vendor and what they changed."]}, {"tip": "You link a contract to a vendor from the contract: edit the contract and set its \"Vendor\". To connect a vendor to SOPs, credentials or other records, edit the vendor and use \"+ Link item\" under \"Related items\"."}, {"qa": [{"q": "A contract is missing from \"Contracts & renewals\".", "a": "Open the contract and check that its \"Vendor\" field is set to this vendor."}, {"q": "I can see vendors but can't add contacts or files.", "a": "Adding a contact needs Create on Vendors, and changing a contact or uploading a file needs Edit. An administrator can change this under Administration \u2192 Roles & Permissions."}, {"q": "What happens when I delete a vendor?", "a": "It is archived, not erased: it disappears from the Vendors list, but its history and any contracts that point to it are kept. Deleting needs Delete on Vendors. To stop using a vendor without hiding it, set its Status to Inactive instead."}]}]}, {"title": "Invoices and software licenses: Microsoft subscriptions as contracts, invoices from every vendor", "for": "admin", "mod": "contracts", "body": [{"p": "Assets & Vendors \u2192 Invoices keeps every vendor's invoices next to its contracts, and Microsoft 365 \u2192 Licenses \u2192 Subscriptions & contracts turns the Microsoft subscriptions into contracts."}, {"bullets": ["Subscriptions & contracts: each subscription Microsoft bills, with seats bought and assigned, its status and the date it renews or ends. \"Create the vendor Microsoft\" once, tick the subscriptions and create their contracts (the subscription id, the term to the renewal date, the amount from the price in IT Budget).", "When Microsoft changes something, the subscription shows what changed. \"Update\" brings the contracts up to date: a new term when Microsoft renewed, the amount when seats changed.", "New invoice: vendor, number, date, billing period, due date, and one line per item, tied to the vendor's contract (quantity \u00d7 unit price; billed monthly, yearly or once), plus tax. The total is computed by the app.", "Read a PDF\u2026: choose the vendor, pick the invoice PDF; its text is read by the AI integration (Settings \u2192 Sign-in & AI) and fills the form. Nothing is saved until you check it and press Add. The PDF is attached when you save. A scanned image without text cannot be read: type it in.", "Checks on each invoice: Microsoft seats billed vs bought vs assigned, the price vs IT Budget (\"Use this price in IT Budget\" saves it), the amount vs the contract, a period after the contract ended, a big change from the vendor's last invoice.", "Status: Received \u2192 Approve \u2192 Mark paid (with the date); Dispute (say what) and Back to approved. Marking paid records the total as spend in IT Budget; a paid invoice is locked until it is set back.", "Missing invoices: every active contract billed monthly, quarterly, twice a year or yearly whose invoice is not recorded for a period in the last 12 months (two weeks after the period starts). \"Enter it\" starts the invoice.", "A vendor's and a contract's window has an Invoices tab.", "Permission: \"Invoices\" (view, create, edit, delete), not given to existing roles automatically. Creating the Microsoft contracts also needs Contracts (create, edit) and Microsoft 365 (view); using a price needs IT Budget (edit)."]}]}]}, {"cat": "Calendar & reports", "topics": [{"title": "The Calendar", "for": "everyone", "mod": "calendar", "body": [{"p": "Service Desk \u2192 Calendar shows every IT date in one place: your team's events (meetings, maintenance and change windows, training, vendor visits, audits, deadlines, out of office, office closures) and the due dates of other modules \u2014 ticket deadlines, contract ends, SOP reviews, credential dates and equipment warranty ends. Use it to plan the week, to spot anything overdue, and to report on it."}, {"h": "What appears"}, {"bullets": ["Events, in the colour of their kind (or the colour chosen on the event). \u21bb marks a repeating event; a cancelled one is struck through.", "Tickets due (red; response due shows until the first response), contract ends, SOP reviews, credential rotations and terms, warranty ends (Equipment \u00b7 View).", "Anything past its date turns red and is marked OVERDUE.", "The chips under the toolbar hide or show a kind of event or a kind of due date (remembered on this computer); \"show all\" brings everything back."]}, {"p": "You only see dates your role allows. Ticket dates need Tickets (only the tickets you opened, are assigned to or back up, unless your role has All records); contract dates need View on Contracts; SOP reviews need View on SOPs; credential dates need View on Credentials. A role without a module never sees its dates, and the legend only lists what you can see."}, {"bullets": ["\"Everything\" shows all the dates your role can see. \"Only mine\" narrows it to your own items: tickets you opened, own or back up, contracts, SOPs and credentials you own, and events you organize or attend.", "An item you can view but not change opens as \"Details\": you can open the record or send a notification, but not drag or reschedule it.", "\"+ Add event\" needs Calendar \u00b7 Create; changing an event Calendar \u00b7 Edit; removing one Calendar \u00b7 Delete."]}, {"h": "Getting around"}, {"bullets": ["Switch between \"Month\", \"Week\", \"List\" and \"Reports\". Use \"\u2039 Prev\", \"Next \u203a\" and \"Today\", or click the month name to jump.", "Click a day to see its items in the side panel; drag an item to another day to move it (an event keeps its length; for a repeating event only that occurrence moves)."]}, {"h": "Add an event"}, {"steps": ["Click \"+ Add event\" (or \"+ Add\" in a day's panel). The event opens as a full page.", "Type the title and choose the kind of event: its usual length and reminders are filled in.", "Set when it starts and ends, or tick \"All day\". Status: Scheduled, Tentative, Cancelled or Done.", "Repeat (optional): daily, weekly on the days you tick, monthly (same day, same weekday such as the second Tuesday, or the last weekday) or yearly; every N; with no end date (five years at most), until a date, or a number of times. The sentence under it says it in plain words.", "Where: an office (from IT Budget \u2192 Offices), a room or place, and an online meeting link (https://\u2026).", "People: the organizer (you \u2014 only a Super Admin makes someone else the organizer), the department, and the attendees \u2014 people of the app, or outside email addresses. Only the organizer (or a Super Admin) changes who is invited, because the invitations go out from the organizer's mailbox. \"Who can see it\": everyone with the calendar, or private (only the organizer, the attendees and Super Admins).", "Reminders: up to five, from \"At the start\" to \"1 week before\". People of the app get them in the app and by email.", "Click \"Add event\"."]}, {"bullets": ["People you invite are told in the app and can answer Accept, Maybe or Decline on the event. A declined attendee gets no reminders.", "\"Add to Outlook (.ics)\" downloads the event (with its repeats for the next twelve months) for Outlook or any calendar \u2014 send it to outside guests too.", "Changing or removing one occurrence of a repeating event asks: only this one, this and the following, or the whole series."]}, {"h": "Kinds of event"}, {"p": "\"Kinds of event\u2026\" (Calendar \u00b7 Edit) changes the list: name, colour, usual length, all day, default reminders, and \"Window\" for maintenance and change windows (they make the windows report). A kind events use cannot be removed \u2014 hide it."}, {"h": "Reports"}, {"bullets": ["Events by type \u2014 how many events of each kind, the hours, the attendees.", "Upcoming deadlines and renewals \u2014 the due dates of every module in the period, with who owns them.", "Maintenance and change windows \u2014 each window with its time, length, office, organizer and people (evidence for change management).", "Attendance by person \u2014 events organized and attended, and the hours.", "Activity by office \u2014 events per office and kind.", "Overdue items \u2014 still-open items past their date.", "Full agenda \u2014 everything in the period, day by day."]}, {"p": "Choose the period (this month, next 30 or 90 days, a quarter, the year, or dates), and narrow by kinds, office, person or \"Only mine\". Click \"Preview and download\u2026\" to see the report on screen first, then download it as PDF or Word (with the organization's logo, Settings \u2192 Branding \u2192 Documents), CSV, or a calendar file. Give a report a name to save it with its filters; tick \"Shared\" to list it for everyone with the calendar. Every download is written to the Audit Log."}, {"tip": "Reminders are sent by the main scheduler (cron-sla.php). If they do not arrive, check Logs & Integrations \u2192 Scheduled jobs."}, {"h": "The Events report"}, {"p": "Calendar \u2192 Reports opens on \"Events\": every event in the period with when, kind, organizer, people, where, hours and status, as PDF, Word, CSV or a calendar file. Click a total \u2014 Scheduled, Tentative, Cancelled, Done \u2014 to show only those events; click it again (or \"show all\") to see them all. The kinds in \"Upcoming deadlines\" and \"Overdue items\", and \"Cancelled\" in the windows report, work the same way."}]}, {"title": "Outlook & Teams calendar", "for": "everyone", "mod": "calendar", "body": [{"p": "ITOps can put your calendar items into your Outlook calendar, so you see them in Outlook, in Teams (Teams shows your Outlook calendar) and on your phone, with Outlook's own reminders, without opening ITOps. It works both ways."}, {"h": "What goes to your Outlook calendar"}, {"bullets": ["Events you organize: as a real Outlook meeting. Everyone on the attendee list (outside guests too) gets the invitation from your calendar, and meetings get a Teams link automatically when they have no online link of their own. The Teams link also appears on the ITOps event.", "Events you attend whose organizer does not sync: a copy in your calendar that says who organizes it.", "Your tickets' due times: the response and resolution due times of the open tickets assigned to you (shown as free time, reminder 30 minutes before). They leave Outlook when the ticket is resolved or reassigned.", "Dates you own: contract ends, SOP reviews, credential terms and rotations, warranty ends, as all-day items with a reminder at 9:00 AM the day before."]}, {"h": "Choose what you get"}, {"steps": ["Calendar \u2192 \"Outlook & Teams\u2026\".", "Under \"My Outlook calendar\", tick \"Put my ITOps items in my Outlook / Teams calendar\" and the kinds you want. Kinds your role cannot see are greyed out.", "Click Save. Items reach Outlook at the next sync (about every 3 minutes), or click \"Sync my calendar now\"."]}, {"tip": "Switching it off removes the tickets, dates and copies from your Outlook at the next sync. Meetings you organized stay in Outlook, so your attendees keep their invitations; they are simply no longer synced."}, {"h": "Bring an Outlook or Teams event into ITOps"}, {"p": "Events you create in Outlook or Teams do not come into ITOps by themselves, so your personal appointments stay private. To bring one in, give it a category in Outlook. The categories to use are shown on your card on this page; by default they are the app's name and the product name, and upper or lower case does not matter."}, {"steps": ["In Outlook (on the computer, the web or the phone), open the event.", "Click Categorize and choose the category shown on your card. If it is not in your list yet, create it with exactly that name.", "Wait for the next sync (about 3 minutes), or click \"Sync my calendar now\". The event appears in your ITOps calendar."]}, {"bullets": ["Your own event becomes an ITOps event you organize, with its time, place, text, Teams link, reminder, repeat and attendees (people of the app are matched by email; everyone else is a guest). It stays linked to the Outlook meeting: a change made on either side reaches the other. Its Outlook text (the Teams join details) and categories are never replaced, and no new invitation is sent.", "An invitation from someone else becomes an event in your ITOps calendar that follows the organizer's changes and cancellation. ITOps never changes someone else's invitation: changes made in ITOps stay in ITOps, and the organizer's next change replaces them.", "Taking the category off later does not remove the event from ITOps. Deleting the event in Outlook cancels it in ITOps (it is kept).", "Not brought in: events already over, cancelled ones, ones further ahead than the organisation's \"How far ahead\", and anything ITOps itself put in your Outlook.", "You need a role that can add events (Calendar \u00b7 Create) and \"Events I organize or attend\" ticked."]}, {"tip": "The event page shows \"Came from Outlook\" or \"Came from an Outlook invitation\". The Audit Log records each event brought in, as \"(your name) (in Outlook)\"."}, {"h": "Changes in Outlook come back"}, {"bullets": ["Move, rename or relocate a meeting you organized in Outlook or Teams: the ITOps event follows (the Audit Log shows \"(in Outlook)\").", "Delete it in Outlook: the ITOps event is set to Cancelled (it is kept, not deleted).", "Attendees accept, decline or answer tentatively in Outlook or Teams: their answers show on the ITOps event. An answer given in ITOps is also sent to the invitation in the person's Outlook.", "Tickets and dates belong to ITOps: a change made to them in Outlook is put back; deleting one in Outlook hides it until its date changes. Change the ticket or the date in ITOps instead.", "A change made in ITOps reaches Outlook at the next sync; the event page says \"In Outlook and Teams \u2026 synced\" with the time."]}, {"h": "For administrators"}, {"steps": ["In Azure \u2192 App registrations \u2192 the ITOps app \u2192 API permissions, add Microsoft Graph \u2192 Application permissions \u2192 Calendars.ReadWrite and click \"Grant admin consent\".", "Calendar \u2192 \"Outlook & Teams\u2026\" \u2192 \"For the organisation\" (Integrations \u00b7 Edit): the box at the top says whether Calendars.ReadWrite is granted.", "Tick \"Sync ITOps with Outlook / Teams calendars\", choose whether it is on for people who have not chosen yet and what they get, whether meetings get a Teams link, and how far ahead (14 to 365 days). Save.", "Click \"Sync everyone now\" for the first run. After that it runs about every 3 minutes with the per-minute scheduled job (cron-uptime.php), or with the in-app scheduler."]}, {"bullets": ["The list shows each person: on or off (and whether it is their own choice), what they get, how many items are in Outlook, the last sync or the error (for example \"No Outlook mailbox for this email address\").", "\"Bring in events people tag in Outlook\" and \"Outlook categories\" (1 to 5 names, comma-separated; upper or lower case does not matter) decide which Outlook events come into ITOps. By default: the app's name and the product name. After a change of categories, the next sync reads everything tagged again.", "\"Remove\" (type REMOVE) takes ITOps's tickets, dates and copies out of everyone's Outlook; meetings are left in Outlook and no longer synced. If the sync is used again later, the same meetings are taken up again (never a second meeting).", "Every change of setting, every person's choice, every sync run started by hand and every change brought in from Outlook is in the Audit Log."]}, {"warn": "Calendars.ReadWrite lets the app use every mailbox's calendar. ITOps only touches the calendars of its own people who sync, only the items it made, and the events people tag with the organisation's categories. To limit the app in Exchange as well, use Exchange Online RBAC for Applications (or an application access policy) with a mail-enabled security group of those people."}]}, {"title": "Reports", "for": "everyone", "mod": "reports", "body": [{"p": "Service Desk \u2192 Reports shows how the service desk is doing: ticket volumes, SLA compliance, workload and backlog. Use it for team meetings and monthly reviews, and to see where tickets are getting stuck."}, {"h": "Filter the report"}, {"steps": ["Set any of the filters at the top: \"From\" and \"To\" (the date a ticket was created), \"Status\", \"Priority\", \"Category\" and \"Department\".", "Click \"Apply\". Click \"Reset\" to clear every filter."]}, {"h": "What you see"}, {"bullets": ["Summary tiles: \"Total tickets\", \"Open / active\", \"Resolved\", \"Overdue\", \"Avg resolution\", \"First response\" and \"SLA compliance\".", "\"SLA performance\": response and resolution compliance in %, how many tickets met or breached their target, how many are tracked, and \"Resolution SLA by priority\". Green means 90% or more, amber 75\u201389% and red below 75%.", "Bar charts: \"By Status\", \"By Priority\", \"By Category\", \"By Department\", \"By Assignee\" and \"By Requester\" (top 15).", "\"Open ticket aging\": open tickets grouped by age (\u2264 1 day, 1\u20133 days, 3\u20137 days, 7\u201330 days, 30+ days).", "\"Opened vs Resolved by month\": up to the last 12 months."]}, {"h": "Service measures"}, {"p": "The \"Service measures\" card shows how well the service desk works, for the same tickets as the rest of the page (the filters above):"}, {"bullets": ["First-contact resolution: resolved tickets that their first owner resolved without handing them to someone else, without Pending, and that were never reopened. A line under the tiles says why the others were not (handed on, waited in Pending, reopened).", "Reopened: resolved tickets that were opened again (a reply from the requester, or an agent).", "Changes that worked: planned changes finished as successful or successful with issues.", "Requesters happy: answers to \"How did we do?\".", "Tickets merged into another ticket are left out. Green, amber and red follow the targets in the SOP (first-contact 70%, reopened 5% or less, changes and satisfaction 90%)."]}, {"p": "People who can add to the Scorecard see \"Put a measure on the Scorecard\u2026\": choose the measure and its goal, and either a new row or a row typed by hand today. The row then fills in by itself every week (the last 13 weeks straight away). Under the tiles, \"Continual improvement\" counts the register (waiting to be triaged, open, past the target date, done in the period and how many worked) and opens it."}, {"p": "Next to Tickets, the \"Cases & Projects\" tab shows how cases and projects are going; see \"Reports for Cases & Projects\"."}, {"h": "Drill in"}, {"p": "Click a bar in By Status, By Priority, By Category, By Assignee or By Requester to open Service Desk \u2192 Tickets filtered to those tickets. You can't click the By Department and aging bars."}, {"h": "Export"}, {"p": "Click \"Export all (CSV)\" to download itops-tickets-DATE.csv. It has one row per ticket with the number, subject, status, priority, type (incident or service request), major incident, rating, category, department, requester, assignee, and the created, resolved and closed dates. The export uses the filters that are currently set, and every export is recorded in the Audit Log."}, {"tip": "Click \"Apply\" before exporting so the file matches what is on screen."}, {"p": "\"SLA targets\" sets response and resolution targets, in hours (decimals allowed), for each ticket category. New tickets use them to set their SLA due dates. Leave a box blank to use the priority target (Settings \u2192 SLA & Hours). To save targets you need Edit on Ticket Categories.", "mod": "categories:edit"}, {"qa": [{"q": "My numbers are lower than the team's totals.", "a": "Without All records on Tickets, Reports only counts tickets you opened or are assigned to. An administrator can add All records under Administration \u2192 Roles & Permissions \u2192 Tickets."}, {"q": "SLA compliance shows \"\u2014\".", "a": "No ticket in the filtered range has met or missed an SLA target yet, for example because every ticket is still open and not yet due."}]}, {"h": "The tiles at the top"}, {"p": "Click a tile to open the tickets behind its number, with the report's dates and filters: Total tickets, Open / active, Resolved, Overdue, Avg resolution (resolved or closed tickets), First response (tickets with a first response) and SLA compliance (tickets that missed the resolution SLA). Tickets shows \"Filtered: \u2026\"; click \u2715 to clear it."}]}, {"title": "Reports for Cases & Projects", "for": "everyone", "mod": "reports", "body": [{"p": "Service Desk \u2192 Reports \u2192 \"Cases & Projects\" shows how the work in cases and projects is going: for the weekly review and for continual improvement. The tab is there for people with Reports who also work with Cases & Projects."}, {"bullets": ["Tiles: open cases and projects, how many are at risk (a late task, a phase past its milestone, or the target date passed), overdue tasks, and the share finished on time (finished by their target date, in the period chosen).", "Health of open cases and projects: each one with its owner, target date, tasks done, late tasks, tickets and health; at-risk ones first. Click one to open it.", "Overdue tasks by person: who has open tasks past their due date, and the oldest one.", "Workload: each person's open case tasks and open tickets, what is due in the next 7 days, and what is late.", "Tickets per case: the cases holding the most tickets, with how many people they came from (the requests and incidents that touched the most people).", "Time per template: cases made from a template and finished in the period, the average time in business days from opening to resolving, and how many met their target date."]}, {"p": "\"Finished from\" and \"To\" choose the period for the finished cases and the time per template (the last 90 days when empty). Open cases are always shown as they are now."}, {"p": "Who sees what: people who see every case (Cases & Projects \u00b7 All records, or named in Roles & Permissions) see every case and everyone's workload. Others see the cases they own, sponsor, follow or have a task in, and only their own workload."}, {"p": "\"Put a measure on the Scorecard\u2026\" at the bottom adds \"Cases and projects closed on time (%)\" or \"Overdue case and project tasks (count)\" as a Scorecard row that fills in by itself."}]}]}, {"cat": "Equipment & loans", "topics": [{"title": "The equipment inventory", "for": "everyone", "mod": "assets", "body": [{"p": "Assets & Vendors \u2192 Equipment is the company inventory of laptops, phones, monitors and other gear. Use it to add items, see who has an item and look up its full history."}, {"h": "Add an item"}, {"steps": ["Go to Assets & Vendors \u2192 Equipment and click \"+ Add item\".", "Enter the \"Asset tag\" (required and unique, for example LT-0142) and pick a \"Category\": laptop, desktop, monitor, phone, tablet, headset, dock, printer, projector, badge, key or other.", "Fill in as much as you know: \"Make\", \"Model\", \"Serial number\", \"Condition\" (new, good, fair or poor), \"Purchase date\", \"Cost\", \"Warranty ends\", \"Location\" and \"Notes\".", "Click \"Add item\"."]}, {"h": "Find an item"}, {"bullets": ["The tiles at the top show how many items are \"Available\", \"On loan\" and in \"Maintenance\", plus the \"Inventory value\" (the total cost of every item that isn't retired).", "Search by tag, make, model or serial number. Filter by status (available, loaned, maintenance, retired, lost) or by category.", "Each row shows who has the item, its status and flags such as \"awaiting signature\" or \"return requested\"."]}, {"h": "The item window"}, {"p": "Click an item to open it. From here you can:"}, {"bullets": ["Use \"Loan this item\" (when it is available) or \"Check in\" (when it is on loan).", "Use \"Edit item\" to correct any detail.", "Use \"Retire\" to take the item out of active inventory. Its history is kept. You can't retire an item that is on loan, so check it in first.", "Under \"Photos & documents\", click \"+ Attach file\" for receipts, warranty papers or photos (up to 15 MB each). On a phone or tablet you also get \"Take photo\".", "Under \"Loan history\", see everyone who has had the item, when it went out and came back, its condition each way, and the signed acceptance record."]}, {"tip": "To move an item between Available, Maintenance, Lost and Retired (for example after a repair, or when a lost laptop turns up), open it \u2192 \"Edit item\" \u2192 \"Status\" \u2192 \"Save changes\". Items on loan must be checked in first."}, {"qa": [{"q": "I get \"That asset tag already exists.\"", "a": "Asset tags must be unique. Search for the tag to find the item that already uses it."}, {"q": "A button gives me a permission error.", "a": "Adding needs Create on Equipment & Assets. Editing, loaning and checking in need Edit, and retiring needs Delete. An administrator sets these under Administration \u2192 Roles & Permissions."}]}]}, {"title": "Loaning equipment to an employee", "for": "admin", "mod": "assets:edit", "body": [{"p": "A loan records who has a piece of equipment and gets their signed acceptance of the loan agreement. Create one every time a device leaves IT, including for new hires."}, {"steps": ["In Assets & Vendors \u2192 Equipment, click \"Loan\" on an available item, or open the item and click \"Loan this item\". The \"Issue equipment\" window opens.", "Under \"Employee\", pick the person from the user list. Their name and email fill in. For someone without an ITOps account, type their name and email instead.", "Set \"Return by\" if the loan has an end date. Check the \"Condition at issue\" (new, good, fair or poor).", "Click each of the \"Included accessories\" that goes with the item (charger, case, mouse, keyboard, docking station, video adapter). Type any other items, separated by commas.", "If you want, add \"Condition photos at issue\" with \"+ Add photo\" (or \"Take photo\" on a phone or tablet).", "Choose how the employee accepts, and finish as described below."]}, {"h": "Sign now (in person)"}, {"p": "Use this when the employee is with you. They type their full name in \"Type full name to sign\" and tick the acknowledgment. Drawing a signature in the box is optional. Click \"Issue & record signature\". The signed name, time and IP address are saved with the loan."}, {"h": "Send for acceptance"}, {"p": "Use this for remote staff. Click \"Assign & notify employee\". The loan is recorded straight away, and the item shows \"awaiting signature\" until the employee signs. If you picked an ITOps user, they get a bell notification. If an email address is filled in, they also get an \"Equipment assigned \u2014 please accept & sign\" email. They sign under Assets & Vendors \u2192 My Equipment. You then get an \"Equipment accepted\" notification."}, {"warn": "For \"Send for acceptance\", always pick the employee from the user list. My Equipment only shows loans linked to the person's ITOps account. Someone entered only by name and email gets the email but can't sign."}, {"h": "What else happens"}, {"bullets": ["The item's status changes to loaned, and the list shows who has it.", "ITOps creates a loan agreement from the item details and saves it with the loan. It covers care of the device, encryption and screen lock, no client or personal data stored on the device unless approved, reporting loss or theft, returning the item on request or when leaving, and liability for negligence.", "To see the signature and agreement later, open the item and, in \"Loan history\", click \"\u2713 Signed \u2026 \u2014 view acceptance record\". Use \"\ud83d\udda8 Print / save PDF\" to keep a copy.", "If the \"Return by\" date passes, the person who issued the item and the Super Admins and Dept Admins get an \"Equipment overdue\" notification in the bell. It repeats about once a day until the item is checked in.", "When someone is offboarded, their open loans are added to the offboarding run as equipment return steps."]}, {"qa": [{"q": "The \"Loan\" button is missing.", "a": "It only shows on available items. Items on loan show \"Return\" instead. Items in maintenance, lost or retired can't be loaned; set them back to Available first with \"Edit item\" \u2192 \"Status\"."}, {"q": "Is the drawn signature required?", "a": "No. The typed full name and the ticked acknowledgment are required, but the drawn signature is optional. If none was drawn, the acceptance record says \"Typed-name acceptance\"."}]}]}, {"title": "My Equipment \u2014 accepting, signing and returning", "for": "everyone", "mod": "my_equipment", "body": [{"p": "Assets & Vendors \u2192 My Equipment lists the company equipment loaned to you. Use it to sign for new equipment and to tell IT when you want to hand something back."}, {"p": "Each item shows its name, asset tag, issue date and return-by date, with one of these labels:"}, {"bullets": ["\"Awaiting your signature\": IT has assigned the item to you and needs you to accept it.", "\"In your care\": you have signed for it.", "\"Return requested\": you have told IT you want to return it.", "\"Returned\": IT has checked it back in. Returned items stay in the list as your history."]}, {"h": "Accept and sign"}, {"steps": ["Click \"Review & sign\" next to the item.", "Read the \"Equipment loan agreement\": what you received, the accessories, the return date and the terms of use.", "If you can, draw your signature in the box (optional). Then type your full name in \"Type your full name to sign\".", "Tick \"I confirm I received this equipment and agree to the loan terms above.\"", "Click \"Accept & sign\"."]}, {"p": "Your name, the time and your IP address are saved with the agreement, and the person who issued the item is notified."}, {"h": "Return an item"}, {"steps": ["Click \"Request return\" next to the item and confirm.", "Hand the item and its accessories to IT."]}, {"p": "IT gets a notification in ITOps. The item shows \"Return requested\" until IT checks it in. After that it shows \"Returned\"."}, {"warn": "Signing confirms that you received the equipment in the condition stated. If anything is missing or damaged, tell IT before you sign."}, {"qa": [{"q": "Something I have isn't listed.", "a": "Only loans linked to your ITOps account show here. Ask IT to check that the loan was issued to your account."}, {"q": "I don't see \"Request return\".", "a": "You have to sign for the item first. The button also goes away after you have requested the return."}]}]}, {"title": "Check-in, damage and condition photos", "for": "admin", "mod": "assets:edit", "body": [{"p": "Checking an item in closes the loan and records the condition the item came back in. Do it as soon as equipment is returned, including when an employee has used \"Request return\"."}, {"steps": ["In Assets & Vendors \u2192 Equipment, click \"Return\" on the item, or open it and click \"Check in\". Items waiting for you are flagged \"return requested\".", "Set \"Condition returned\": new, good, fair, poor or damaged.", "Set \"Set item to\": \"Available\" to lend it again, \"Maintenance\" if it needs repair or re-imaging, or \"Lost\" if it did not come back.", "Add photos with \"+ Add photo\" (or \"Take photo\" on a phone or tablet). Always photograph any damage.", "Add a \"Note\", for example \"scratched lid, missing charger\", and click \"Check in\"."]}, {"h": "What happens next"}, {"bullets": ["The loan is marked returned, with today's date and the returned condition. The item's condition is updated, and it is no longer assigned to anyone.", "The photos are saved on that loan, next to the signed agreement. In the item's \"Loan history\", click \"photos\" on any loan to see or add photos from when it went out and came back.", "The \"return requested\" flag clears, and overdue reminders stop."]}, {"warn": "Choosing \"Maintenance\" or \"Lost\" isn't final: when the item is repaired or found, open it \u2192 \"Edit item\" \u2192 set \"Status\" back to Available."}, {"tip": "The note is saved with the loan but isn't shown on the item screen. Record anything important about damage in a photo, or in the item's \"Notes\" using \"Edit item\"."}, {"qa": [{"q": "I get \"No active loan for this item.\"", "a": "The item has already been checked in. Refresh the list."}, {"q": "A photo is missing after check-in.", "a": "Photos upload after the check-in, and the screen doesn't tell you if an upload fails. Each photo must be a PNG, JPG, GIF or WebP file of up to 15 MB (HEIC files are refused). Open the loan's \"photos\" and add it again."}]}]}, {"title": "Printing labels and scanning tags", "for": "admin", "mod": "assets:edit", "body": [{"p": "Barcode labels let you find an item in seconds by scanning its tag. Print them when you add new equipment, and scan them during stock checks or at check-in."}, {"h": "Print labels"}, {"steps": ["In Assets & Vendors \u2192 Equipment, use the search box and filters so the list shows only the items you want to label. Every item in the list gets a label.", "Click \"Print labels\".", "Pick a template: \"Avery 5160 \u2014 30/sheet (2.6 x 1 in)\", \"Avery 5163 \u2014 10/sheet (4 x 2 in)\", \"Dymo 30252 \u2014 address (3.5 x 1.1 in)\" or \"Small asset tag (1.5 x 0.6 in)\".", "Click \"Print\". In the print dialog, set margins to None or Minimum and scale to 100% so the labels line up. Click \"Close\" to go back."]}, {"p": "Each label shows your organisation's name, the make and model, a Code 128 barcode and the asset tag in text."}, {"h": "Scan or look up a tag"}, {"bullets": ["At the top of Equipment is a highlighted box that says \"Scan or type an asset tag, then Enter\". Click in it and scan with a USB or Bluetooth barcode scanner, or type the tag and press Enter (or click \"Go\"). The item opens straight away.", "On a phone or tablet, tap \"Scan camera\" and point the camera at the barcode. If it finds no code within about 12 seconds, it stops.", "If no tag matches exactly, ITOps opens the first partial match. If nothing matches at all, you see \"No item matches\" followed by the tag."]}, {"tip": "\"Scan camera\" only works in browsers with built-in barcode detection. If you see \"Camera scanning is not supported on this browser\", use a scanner or type the tag."}, {"qa": [{"q": "\"Print labels\" is greyed out.", "a": "The list is empty. Clear the search box or filters."}]}]}]}, {"cat": "Administration & setup", "topics": [{"title": "Settings: the page and its four access areas", "for": "admin", "mod": ["settings", "branding", "email_cfg", "sla_cfg"], "body": [{"p": "Administration \u2192 Settings is where ITOps itself is configured. It has one tab per area, and Roles & Permissions grants each area separately, so a person only sees the tabs they are allowed to use."}, {"bullets": ["General (Settings \u00b7 General): backend connection and API base URL, About (build number), session security (idle timeout and the 2FA rule \u2014 Super Admin saves these), trusted redirect hosts.", "Branding (Settings \u00b7 Branding): application name, logo, favicon and the navigation icons.", "Email and Email templates (Settings \u00b7 Email): outbound mail, the help-desk intake mailbox, the notification switches and the English/Spanish templates.", "SLA & Hours (Settings \u00b7 SLA & Hours): SLA warning thresholds, the daily digest and the business-hours clock.", "Sign-in & AI (Settings \u00b7 General): Microsoft 365 sign-in (SSO) and the AI assistant. Changing the tenant, app or secret is Super Admin only.", "Help visuals: who sees each interactive page of the Help Center. Super Admin only.", "Maintenance: database updates. Super Admin only, always.", "Some settings are Super Admin only, whatever the role: who sees every case and the Change Advisory Board, the trusted redirect hosts and the public form redirect, the scheduler key, sign-in lockout and session rules, break-glass and Teams settings, Microsoft 365 (including the mailbox the app reads and sends mail from). A refused change is written to the Audit Log."]}, {"tip": "This page used to be called \"Connection\". Older screenshots and notes that say Administration \u2192 Connection mean Administration \u2192 Settings."}]}, {"title": "Branding", "for": "admin", "mod": "branding:edit", "body": [{"p": "Branding puts your organisation's name, logo and browser-tab icon on ITOps and on its public pages. Set it once after installing, and again whenever your logo changes."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"Branding\" tab. You need Settings with Edit to save changes."}, {"steps": ["Open Administration \u2192 Settings and click the \"Branding\" tab.", "Under \"Application name\", type the name people should see (for example \"Example Co. IT\") and click \"Save\". If you leave it blank, the product name \"ITOps\u2060\" is used.", "Under \"Logo\", click \"Upload\" and choose the image. Do the same under \"Favicon\". Click \"Remove\" to go back to none. (The logo and the icon are always uploaded; an address cannot be typed in.)", "Optional: in \"Public form redirect URL\", enter the page people should land on after they submit a web form and click Done, then click \"Save\". Leave it blank to send them back to the page they came from.", "Optional: in the \"Navigation icons\" card, click \"Change\" next to any menu item (the groups and the top bar too) to pick a different emoji below the list, or paste your own, then click \"Save icons\": the menu changes at once. Other windows already open \u2014 another browser tab, or the installed app on a Mac, Windows PC or phone \u2014 pick the change up when they come back to the front (and every 10 minutes): no need to sign out. \"Reset to defaults\" puts the original icons back."]}, {"h": "Where each item shows"}, {"bullets": ["Application name: everywhere people see the app \u2014 the menu, sign-in screen and browser tab, every screen and message, all emails (the [name] tag in subjects, the email header and the {{app_name}} placeholder), this Help Center, the public request, form and signing pages, the What\u2019s New page and the label in authenticator apps (for 2FA set up after the change). Names of the policies and rules the app creates in Microsoft 365 keep the product name \"ITOps\u2060\", because that is how the app finds them again.", "Logo: the sidebar, the sign-in screen, public forms, the request page and the help portal. It can also go at the top of every email: tick \"Show the logo (Branding tab) at the top\" under Email templates \u2192 \"Header, footer & language\".", "Favicon: the small icon in the browser tab.", "Navigation icons: the sidebar and top bar, for everyone."]}, {"h": "Documents (PDF and Word)"}, {"p": "The \"Documents (PDF and Word)\" part of the Branding tab sets what every document made by the app carries \u2014 the IT budget document and the calendar reports: the organization's name, its logo on the cover and at the top of each page, the footer (\"Confidential \u2014 for internal use\" to start) and the colour of headings and tables. Upload the organization's logo if it differs from the app logo (PNG or JPG; a wide logo prints best). \"Sample PDF\" and \"Sample Word\" show the result. Every change is in the Audit Log with the values before and after."}, {"p": "\"Preview a sample\" shows a one-page sample with the current name, logo, footer and colour before you make any real document; download it as PDF or Word from the preview."}, {"warn": "Use PNG, JPG, GIF, WEBP or ICO files up to 5 MB. SVG files are refused for security reasons, so convert an SVG logo to PNG first."}, {"qa": [{"q": "I uploaded a new logo but still see the old one.", "a": "Hard-refresh the page (Ctrl+Shift+R on Windows, Cmd+Shift+R on Mac). Other people see the new logo on their next page load."}, {"q": "I can see the Branding tab but saving gives an error.", "a": "Your role has Settings with View only. Ask a Super Admin to add Edit, or to make the change for you."}]}]}, {"title": "Sign-in page: the line under the logo and Microsoft first", "for": "admin", "mod": "branding:edit", "body": [{"p": "Administration \u2192 Settings \u2192 Branding \u2192 \"Sign-in page\" decides two things about the page people sign in on."}, {"bullets": ["The line under the logo: type your own (up to 80 characters) and click Save. Empty it to go back to \"IT Master Operations Hub\".", "How people sign in first: \"Email and password\" (the fields, with the Microsoft button under them) or \"Microsoft 365\" (only the Microsoft button; email and password appear after \"Sign in with a local account\")."]}, {"p": "With Microsoft 365 first, local accounts and the Super Admin can always still sign in through \"Sign in with a local account\". If Microsoft sign-in is not set up yet (Settings \u2192 Integrations \u2192 Microsoft 365), the page keeps showing email and password, so nobody is locked out. Inside Teams, people are signed in by Teams as before."}]}, {"title": "The license file: what it decides, the trial and the notice", "for": "admin", "mod": "license", "body": [{"p": "Each installation has a license file, itops-license.php, in its folder next to config.php. Indisse-BTS issues it for that installation (it names the installation ID shown in About & ownership). It says which plan and modules are included, how many users, and for how long."}, {"bullets": ["The file is signed by Indisse-BTS. Any change to it, even one character, makes the signature fail; About & ownership \u2192 License record shows \"Signature: Genuine\" when it is unchanged.", "Never edit the file. For a different plan, more users or a new term, ask Indisse-BTS for a new file and replace the old one.", "Settings \u2192 Modules shows what the file includes; a Super Admin can still switch included modules off."]}, {"h": "No file, or a file that is not valid"}, {"bullets": ["Without a valid file (none, edited, damaged, issued for another installation, or a term that ended more than 14 days ago), every module works as a 30-day trial.", "After the trial only the core stays on: sign-in, users, roles, settings, logs, Help and About & ownership. Nothing is deleted: the modules and their data come back as soon as a valid file is in place.", "When the term has ended, everything keeps working for 14 more days so there is time to renew.", "Super Admins and the people with \"License details\" see a notice at the top of every page saying what is wrong and until when."]}, {"h": "Installing a new license file"}, {"steps": ["Indisse-BTS sends the file itops-license.php.", "Upload it to the installation folder (next to config.php), replacing the old one.", "Open About & ownership: the License record shows the new number and \"Signature: Genuine\", and the notice at the top is gone."]}]}, {"title": "Ticket categories and SLA targets", "for": "admin", "mod": "categories", "body": [{"p": "Ticket categories sort requests into groups (for example Hardware \u2192 Laptop) and set how fast each kind of request should be answered and solved."}, {"p": "Where it lives: Administration \u2192 Ticket Categories. Ticket Categories: View lets you see the list; Create, Edit and Delete let you add, change and remove entries."}, {"h": "How groups and categories work"}, {"p": "There are exactly two levels. A group (for example \"Hardware Request\") is the first choice people make; the categories inside it (for example \"Printer\") are the second. A category always belongs to one group, and a group cannot sit inside another group or inside a category. Names are unique inside a group."}, {"h": "The grid"}, {"bullets": ["Every group and category is one row, with the columns Group, Category, Ticket type, Response (h), Resolution (h), Owner, Backup, Order, Status, Tickets and Open tickets. A group's own row has its name under \"Group\" and \"\u2014 the whole group \u2014\" under \"Category\"; a category's row has its group under \"Group\" and its name under \"Category\".", "Sort: click a column title (again to reverse, a third time to go back to the order people see). Filter: type or pick in the row under the titles, or use \"Search every column\". \"Clear the filters\" shows everything again.", "Change: click a cell. Enter saves and goes to the row below, Tab saves and goes right, Esc cancels. A change is saved at once and written to the Audit Log; a refused change (for example a duplicate name) shows why under the cell and is logged too.", "Add: \"Add group\" or \"Add category\" (or the + on a group's row) opens a new row at the top. Enter adds it and opens the next one, so you can type a whole list; pasting several lines adds one entry per line.", "Rename a group: click its name in the \"Group\" column on its own row. Move a category: click the \"Group\" on the category's row and pick another group. Turn a category into a group: pick \"\u2014 None: make it a group \u2014\" (it asks first). A group with categories cannot become a category until they are moved.", "\"Tickets\" and \"Open tickets\" show how many tickets use the entry. Inactive entries stay in the grid, so you can switch them back on.", "\"Export CSV\" downloads the rows shown, with the same columns as the grid.", "Collapse a group with the small arrow before its name (the number in brackets is how many categories it holds), or use \"Collapse all\" / \"Expand all\". Collapsing works in the order people see; while you sort, filter or search, every match shows. Your collapsed groups are remembered in this browser.", "Who gets a new ticket: the category's own owner and backup come first, then the group's, then the default routing. Owner and backup are found separately, so a category with only its own owner still gets the group's backup. Someone who is inactive or whose role cannot edit tickets is skipped, and the next level is used. An empty Owner or Backup cell shows who it resolves to, for example \"Pat Lee (group)\", \"Sam Diaz (default)\" or \"nobody\".", "\"Change the order\" opens one list, top to bottom: each group on one line (open it with its arrow to see its categories). Drag \u283f to move a group, to move a category within its group, or to drop a category on another group's line to move it into that group (it goes to the end). \u25b2 \u25bc move one step. Every move is saved at once and is the order people see on every form.", "\"Cards\" shows each group as a small card with its categories, two per row; each card folds to one line with its arrow, or use Collapse all / Expand all; \u25b2 \u25bc change the order and the pencil opens the full edit panel. The page opens on the grid; your choice of Grid or Cards is remembered for you (also under My profile \u2192 Preferences).", "At the top, side by side: the Routing & SLA check (click a problem to see its details and the fix) and Who gets new tickets (default owner, backup and alert list)."]}, {"steps": ["Set \"Response (h)\": how soon someone should first respond. Decimals are fine (0.5 = 30 minutes). Leave it blank to use the priority target.", "Set \"Resolution (h)\": how soon the ticket should be solved. Leave it blank to use the priority target.", "Set \"Order\" (lower numbers appear first) and \"Status\"."]}, {"h": "How the targets are used"}, {"bullets": ["When a ticket is created (in ITOps, by email, from the request page or from a form), its response and resolution due times come from its category.", "If the category has no hours of its own, the priority targets are used (Settings \u2192 SLA & Hours \u2192 \"Priority targets\"; out of the box: response Critical 1, High 2, Medium 4, Low 8, Planning 24 hours; resolution 4, 8, 24, 48, 120 hours).", "Critical and High get the shorter of the category's and the priority's hours, unless \"Critical and High use the shorter clock\" is switched off.", "If business hours are on (Settings \u2192 SLA & Hours), only working time counts.", "Changing a category's targets does not move the due times of existing tickets; a ticket whose priority or category changes gets new ones."]}, {"warn": "With \"Critical and High use the shorter clock\" switched off, the category's hours win over the priority: a Critical ticket in a category with a 24-hour resolution target gets 24 hours, not 4."}, {"warn": "Deleting a category makes its tickets uncategorised. A group can't be deleted until its categories are moved or deleted. Setting an entry to Inactive hides it from the forms and the ticket screens but keeps it in the grid, so you can switch it back on."}, {"tip": "You can also edit the targets for every category at once from Service Desk \u2192 Reports \u2192 \"SLA targets\"."}, {"p": "The owner and backup of a category must be people whose role can edit tickets (see \"Who gets new tickets: owner, backup and the alert list\"). Changes to a category are written to the Audit Log with the old and new values.", "mod": "categories:edit"}, {"qa": [{"q": "An older ticket that came in by email or a web form has no SLA due time. Why?", "a": "It should have one. Every new ticket gets due times from its category (or the mailbox's default category) and priority. Tickets created before build 0621-BT7 arrived without them; an agent can set \"Response due\" and \"Resolution due\" by hand."}, {"q": "I don't see \"Add group\".", "a": "Your role needs Ticket Categories with Create."}]}, {"h": "Changing the order"}, {"p": "Drag a row by its handle (\u283f) in the grid. A group moves with all its categories. A category moves inside its group, or into another group: drop it on that group's row or among its categories. From the keyboard, focus the handle and press Alt+\u2191 or Alt+\u2193. Dragging works in the order people see (clear any sorting and filters first). The new order applies everywhere at once: the in-app ticket form, the public \"Submit a Help Request\" page, forms and the category panel on the Tickets page. You can also type a number in the \"Order\" column.", "mod": "categories:edit"}, {"h": "Type of ticket"}, {"p": "Each category says whether its tickets are incidents (something is broken) or service requests (something is asked for); new tickets take this type. With the update to build 0621-BT81 the categories whose names speak of an issue, problem, outage, error, security and the like were set to Incident; check them in Ticket Categories, under each category's \"Type of ticket\". The list shows \"Incident\" next to those categories."}]}, {"title": "Priority targets", "for": "admin", "mod": "sla_cfg", "body": [{"p": "Priority targets say how long a ticket of each priority may wait for its first response and for its resolution. They apply to every ticket whose category has no hours of its own, and \u2014 while \"Critical and High use the shorter clock\" is on \u2014 to Critical and High tickets whenever they are shorter than the category's."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"SLA & Hours\" tab \u2192 \"Priority targets\" card. Saving needs Settings \u00b7 SLA & Hours with Edit."}, {"steps": ["Type the hours for each priority: \"Response (h)\" and \"Resolution (h)\". Decimals are fine (0.5 = 30 minutes).", "Click \"Save priority targets\". A resolution shorter than its response, or an empty or zero box, is not accepted.", "\"Back to the defaults\" puts the original values back in the boxes (Critical 1 / 4, High 2 / 8, Medium 4 / 24, Low 8 / 48, Planning 24 / 120); click Save to keep them."]}, {"bullets": ["New tickets use the new targets at once; so does a ticket whose priority or category changes. Existing due times are not moved.", "Counted in business hours when those are on.", "The change is written to the Audit Log."]}, {"h": "Incidents' own targets"}, {"p": "Under the priority targets, the card \"Incidents and satisfaction\" can give incidents their own, usually faster, targets: tick \"Incidents have their own priority targets\" and type the hours. Off, incidents use the priority targets like service requests. The same card switches the \"How did we do?\" question on or off. Changes are in the Audit Log."}, {"h": "What each priority means"}, {"p": "The card \"What each priority means\" (same tab) holds the plain words and examples for each priority, so everyone picks the same priority for the same situation. They show under \"Priority\" on the ticket form. \"Show the impact \u00d7 urgency table\" shows the usual rule: high impact (many people, a whole site or a critical service) and high urgency (work stopped, no workaround) is Critical; one person who can wait is Low."}, {"steps": ["Change \"What it means\" (up to 600 characters) and the examples (one per line, up to 8) of any priority.", "Click \"Save definitions\". \"Back to the standard words\" puts the original words back.", "Saving needs Settings \u00b7 SLA & Hours with Edit and is written to the Audit Log."]}, {"h": "On the Scorecard"}, {"p": "Scorecard \u2192 \"Priority targets\u2026\" puts \"First response on time\" and \"Resolved on time\" for any priority on the Scorecard. See \"The Scorecard: daily, weekly, monthly and yearly\"."}]}, {"title": "Business hours", "for": "admin", "mod": "sla_cfg:edit", "body": [{"p": "Business hours make SLA due times count working time only, so a ticket logged late on Friday isn't already overdue on Monday morning."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"SLA & Hours\" tab \u2192 \"Business hours (SLA clock)\" card. Saving needs Settings with Edit."}, {"steps": ["Tick \"Count SLA in business hours\".", "Set \"Day starts\" and \"Day ends\". The defaults are 09:00 and 17:00.", "Type the \"Time zone\" in the standard IANA format, for example America/New_York (the default) or America/Chicago.", "Click the \"Working days\" buttons to switch days on or off. Monday to Friday are on by default.", "In \"Holidays\", type one date per line as YYYY-MM-DD, for example 2026-12-25.", "Click \"Save business hours\"."]}, {"h": "What happens next"}, {"bullets": ["Only tickets created after you save use the new clock. Existing due times don't move.", "Evenings, non-working days and holidays are skipped. Example: with 9\u20135, Monday to Friday, an 8-hour target on a ticket created at 3 pm Friday is due at 3 pm Monday.", "To go back to plain calendar time, untick the box and save."]}, {"warn": "Check the time zone spelling carefully. If ITOps doesn't recognise it, it quietly uses UTC and every due time will be off by several hours. If \"Day ends\" is not later than \"Day starts\", ITOps uses 09:00\u201317:00 instead."}, {"tip": "Add next year's holidays in December. Lines that are not in YYYY-MM-DD format are dropped when you save."}, {"qa": [{"q": "A ticket's due time looks wrong.", "a": "Check the time zone first. Then check when the ticket was created: tickets created before you changed business hours keep their old due times."}, {"q": "The Save button gives an error.", "a": "Your role has Settings with View only. You need Edit."}]}]}, {"title": "SLA alerts and digest", "for": "admin", "mod": "sla_cfg:edit", "body": [{"p": "SLA alerts warn the right person before a ticket misses its response or resolution target, and again if it does. The weekly digest sends admins a summary of how the team did."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"SLA & Hours\" tab \u2192 \"SLA alerts & digest\" card. Saving needs Settings with Edit."}, {"steps": ["Tick \"Enable breach & approaching-deadline alerts\".", "Set \"Warn before response due (min)\" (default 60) and \"Warn before resolution due (min)\" (default 240).", "Tick \"Email a weekly SLA digest to admins\" if you want the weekly summary.", "Click \"Save SLA settings\".", "Make sure the scheduled work is running (see \"Scheduled jobs: cron and the in-app scheduler\"). The cron commands for this card are shown at its bottom."]}, {"h": "Who gets what"}, {"bullets": ["Each open ticket is checked for four events: response due soon, response breached, resolution due soon, resolution breached. Each event is sent only once per ticket.", "The alert goes to the assignee. If nobody is assigned, it goes to every active Super Admin, Admin and Department Admin.", "It appears in the notification bell. It is also emailed if outbound email is on and the \"SLA breached\" or \"SLA due soon\" email is switched on under Email templates.", "Response alerts stop once someone has responded. Resolved, closed and cancelled tickets are skipped.", "The weekly digest covers the last 7 days: tickets created and resolved, response and resolution SLA compliance, and how many open tickets are past due. It goes to Super Admins, Admins and Department Admins, in the bell and by email."]}, {"h": "Closing resolved tickets on their own"}, {"p": "On the same card, \"Close resolved tickets after (business days)\" (default 3) closes a resolved ticket when the requester has not replied for that many business days. Business days are the days and holidays of business hours when they are on, otherwise Monday to Friday. A reply before that reopens the ticket. 0 switches it off."}, {"bullets": ["The Resolved email tells the requester how many business days they have to reply.", "The closing is done by cron-sla.php (step \"Close resolved tickets\" under Logs & Integrations \u2192 Scheduled jobs) and written to the Audit Log as \"System (auto-close)\"."]}, {"warn": "The weekly digest is sent only by the cron job \"cron-sla.php digest\" (or the digest URL shown on the card). The in-app scheduler never sends it. Without that cron job, no digest arrives, even with the box ticked."}, {"tip": "The cron commands only appear on this card after the Email settings have been saved once. Saving them creates the cron token."}, {"qa": [{"q": "Nobody gets SLA alerts.", "a": "Check the alerts box is ticked, and that scheduled work is running: Settings \u2192 Email \u2192 \"Last automatic run\", or the Event Log (channel cron). Also check the tickets have SLA due times, and that they aren't pending (pending tickets don't alert)."}, {"q": "An IT Administrator doesn't get alerts for unassigned tickets.", "a": "Unassigned-ticket alerts and the digest go only to users with the built-in Super Admin, Admin or Department Admin role. Custom roles don't receive them, even with full access."}]}]}, {"title": "Setting up the AI assistant", "for": "admin", "mod": "settings:edit", "body": [{"p": "AI assist gives agents a ticket summary, a suggested category and priority, and a draft reply. The same key also powers Ask IT and the AI helpers for SOPs. It is optional and stays off until you turn it on."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"Sign-in & AI\" tab \u2192 \"AI assist\" card. Saving needs Settings with Edit."}, {"steps": ["Tick \"Enable AI assist\".", "Choose the \"Provider\": \"Anthropic (Claude)\" or \"OpenAI\".", "Type the \"Model\" name. If you leave it blank, ITOps uses claude-haiku-4-5-20251001 (Anthropic) or gpt-4o-mini (OpenAI) for ticket help.", "Paste your \"API key\" (only a Super Admin can save or replace keys). After saving, the label says a key is saved. Leave the field blank later to keep it.", "Optional: paste a \"Transcription key \u2014 OpenAI Whisper\" so agents can transcribe audio and video attachments. With OpenAI as the provider, you can leave it blank and the main key is used.", "Click \"Save AI settings\"."]}, {"h": "What happens next"}, {"bullets": ["Agents with access to Tickets see the AI options on a ticket. Each use sends one request to the provider you picked, which may cost money.", "Keys are stored encrypted on your server and are never shown again in the browser.", "Ask IT answers from your published Knowledge Base. Questions it can't answer collect under Knowledge \u2192 KB Content Gaps."]}, {"warn": "Your server must be able to reach api.anthropic.com or api.openai.com. If a firewall blocks it, the AI buttons return an error."}, {"qa": [{"q": "Agents say the AI gives an error about the key.", "a": "The message \"No AI API key is configured\" means no key has been saved. Paste it again and click \"Save AI settings\"."}, {"q": "Transcription doesn't work with Anthropic.", "a": "Transcription uses OpenAI Whisper. Add a \"Transcription key \u2014 OpenAI Whisper\"."}]}]}, {"title": "Outbound email: how ITOps sends mail", "for": "admin", "mod": "email_cfg:edit", "body": [{"p": "Outbound email is how ITOps sends every system email: ticket acknowledgements and replies, SLA alerts, reminders, signature requests and onboarding emails. Set it up first, because nothing is sent until it's on."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"Email\" tab, in the lower half of the card, \"Outbound email \u2014 acknowledgements & replies\". Saving needs Settings with Edit."}, {"steps": ["Tick \"Enabled\" next to \"Outbound email \u2014 acknowledgements & replies\". It is off on a new install.", "Enter the \"From name\" (default IT Help Desk) and the \"From address\".", "Choose \"Send via\": \"Server mail (PHP mail)\", \"SMTP\" or \"Microsoft 365 (Graph)\".", "For SMTP, fill in \"SMTP host\", \"Port\" (587), \"Security\" (STARTTLS), \"SMTP user\" and \"SMTP password\". For an Office 365 mailbox, click \"Use Office 365 preset\" first. A blank SMTP user or password reuses the mailbox username or password from the intake section.", "For Microsoft 365 (Graph), fill in the \"Microsoft 365 / Azure\" card on the \"Integrations\" tab, including \"Help-desk mailbox (Graph send/receive)\".", "Choose the ticket emails you want with the tick boxes (see below).", "Click \"Save settings\", then click \"Send test email to myself\"."]}, {"h": "The tick boxes"}, {"bullets": ["\"Acknowledge new emails\": whoever emails the help desk gets a \"Request received\" reply. Off by default.", "\"Email requester on reply\": the requester gets agent replies. Off by default.", "\"Email requester on status change\": the requester hears when the status changes, including resolved and closed. Off by default.", "\"Email assignee when a ticket is assigned\": on by default.", "All other emails (web-form acknowledgements, SLA alerts, reminders, signatures, onboarding) are switched on or off one by one under the \"Email templates\" tab."]}, {"h": "The outbound email log"}, {"p": "The table at the bottom shows the last 40 send attempts: When, To, Subject, Type, Via and Result. A failed row shows the error message. With Microsoft 365, sent emails also appear in the mailbox's Sent Items."}, {"warn": "Emails that are skipped because outbound email is off, or because that email is switched off under Email templates, are not written to the log. If an email is missing and not in the log, check those two switches first."}, {"qa": [{"q": "Nobody is receiving emails.", "a": "Check that \"Enabled\" is ticked and saved, then use \"Send test email to myself\" and read the Result column in the log."}, {"q": "Sending through Microsoft 365 fails with a permissions error.", "a": "The Azure app needs the Mail.Send application permission, with admin consent. See \"Microsoft 365 sign-in\"."}, {"q": "Requester replies create new tickets instead of threading.", "a": "The reply subject must still contain the ticket number (for example TK-2026-0142), and \"Replies\" in the intake section must be \"Thread onto existing ticket\"."}]}]}, {"title": "Email-to-ticket intake (help-desk mailbox)", "for": "admin", "mod": "email_cfg:edit", "body": [{"p": "Email intake turns every unread message in your help-desk mailbox into a ticket, and adds replies to the right ticket. Use it if staff email IT at an address such as helpdesk@yourcompany."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"Email\" tab \u2192 \"Email-to-Ticket Intake\" card (top half). Saving needs Settings with Edit."}, {"steps": ["Tick \"Enabled\" at the top right of the card.", "Choose the \"Inbound source\": \"IMAP mailbox\" or \"Microsoft 365 (Graph)\". Microsoft 365 mailboxes must use Graph, because Microsoft no longer accepts passwords over IMAP.", "For IMAP, fill in \"IMAP host\", \"Port\" (993), \"Encryption\" (SSL), \"Username\", \"Password\" and \"Folder\" (INBOX). For Graph, the mailbox and Azure app come from the \"Microsoft 365 / Azure\" card on the \"Integrations\" tab. The saved password is only used with the server it was saved for: to change the host, port, encryption or username, or to test another server, type the password again (only a Super Admin enters it).", "Choose defaults for new tickets: \"Default category\", \"Default department\" and \"Default priority\" (Medium).", "Choose \"Replies\": \"Thread onto existing ticket\" (recommended) or \"Always create new ticket\".", "Click \"Save settings\", then \"Test connection\". Click \"Run now\" to check the mailbox straight away."]}, {"h": "What happens to each message"}, {"bullets": ["Only unread messages are read. Each one is marked as read afterwards. With Graph, up to 25 messages are handled per run.", "A new message becomes a ticket numbered TK-YYYY-NNNN with status Open. \"Re:\" and \"Fwd:\" are removed from the subject, and the sender's name and address go at the top of the description.", "Only the message text is kept, up to 8,000 characters. Attachments are not imported.", "If the sender's address matches an ITOps user, that user is the requester. Otherwise the ticket is filed under the first administrator account and the sender is saved as the contact.", "The receiving mail server's sender checks are read (DMARC, DKIM, SPF; Microsoft's \"compauth\"). A message that fails them may be forged: it is treated as from an unknown sender \u2014 a new ticket is filed under the first administrator with \"Unverified sender (failed DMARC)\" and a warning, nothing is emailed back, and a reply on a ticket becomes an internal note that does not reopen it. The Audit Log records it as mail_spoof_suspected. Mail with no sender checks (inside your organization) is handled as before.", "A message whose subject contains an existing ticket number is added to that ticket as a comment. If the sender isn't the requester, contact, assignee or an ITOps user, it is added as an internal note marked \"UNRECOGNISED sender\" for the team to check.", "Messages from the help desk's own address, and from mailer-daemon, postmaster or no-reply addresses, are ignored."]}, {"h": "How often the mailbox is checked"}, {"p": "Under \"SCHEDULE\", \"Run automatically while ITOps is open\" checks the mailbox about every 3 minutes, but only while someone has ITOps open. For round-the-clock intake, add the cPanel cron job shown there (cron-mail.php)."}, {"qa": [{"q": "The card warns that the PHP IMAP extension isn't enabled.", "a": "Ask your host to enable it, or use Microsoft 365 (Graph) instead."}, {"q": "\"Test connection\" works, but no tickets appear.", "a": "Check \"Enabled\" is ticked and saved, and that the messages are still unread. Messages someone has already opened in Outlook are skipped."}]}]}, {"title": "Editing the emails ITOps sends (English & Spanish)", "for": "admin", "mod": "email_cfg:edit", "body": [{"p": "The Email templates screen lets you change the wording of every email ITOps sends, in English and Spanish, and switch individual emails off."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"Email templates\" tab. Settings with View lets you read the templates; changing them needs Edit."}, {"p": "There are 41 emails in five groups: Tickets (9, including \"Requester replied\", \"Backup on a ticket\" and \"New ticket \u2014 nobody assigned\"), SLA & digests (5), Reminders (8), People & equipment (10, including the two device-setup invitations) and Security rollout (9 \u2014 the Business Premium rollout communications, sent from Microsoft 365 \u2192 Home \u2192 Rollout). Each one shows On, Off, or \"Off (switch)\"."}, {"steps": ["Pick an email in the list on the left.", "Use the On/Off switch at the top to turn that email on or off.", "Choose the English or Espa\u00f1ol tab and edit \"Subject\" and \"Message\".", "To add a value such as the ticket number, click where it should go, then click a chip under \"Placeholders \u2014 click to insert at the cursor\". The {{app_name}} chip inserts your app name (Settings \u2192 Branding), so the emails follow it if you rename the app later.", "Check the live preview, which uses sample data. Click \"Send test to me\" to receive it.", "Click \"Save\". \"Discard changes\" throws away unsaved edits.", "To undo your edits, click \"Reset English to default\" or \"Reset Spanish to default\". \"History\" lists past changes. Click \"Load this version\" to bring one back, then Save."]}, {"h": "Formatting you can use"}, {"bullets": ["**bold** for bold text.", "[link text](https://\u2026) for a link. Plain https:// addresses become links automatically.", "A line starting with \"- \" becomes a bullet. A blank line starts a new paragraph.", "Values typed by people (subjects, comments, names) always appear as plain text, never as links or formatting."]}, {"h": "Header, footer & language"}, {"p": "Click \"Header, footer & language\" to set the \"Language for people without their own setting\" (English, Espa\u00f1ol, or both), the \"Brand colour\", \"Show the logo (Branding tab) at the top\", and an optional header and a footer for each language. Header and footer can only use the common placeholders. A person's own Email language (under their Account, or on their user record) always wins over the organisation default."}, {"p": "The {{portal_link}} placeholder is the \"Follow it online\" box with an \"Open TK-\u2026 in ITOps\" button that opens the ticket in the app. It appears only for people who have an ITOps account; outside requesters don't see it. The five requester ticket emails include it at the end, and it is added back automatically if an edited template leaves it out. Ticket links in agent emails ({{link}}) also open that exact ticket."}, {"warn": "Ticket email subjects must keep {{ticket_number}}. Replies are matched to tickets by it, so Save stays blocked until it's back."}, {"qa": [{"q": "An email shows \"Off (switch)\".", "a": "The email is on here, but its master switch on the \"Email\" tab is off (for example \"Email requester on reply\"). Turn that on too."}, {"q": "People still get the old wording.", "a": "Check you saved both languages. People with Espa\u00f1ol as their email language get the Spanish text."}]}]}, {"title": "Microsoft 365 sign-in", "for": "admin", "mod": "settings:edit", "body": [{"p": "Connecting an Azure (Entra ID) app registration lets staff sign in with their Microsoft 365 account. The same app can also send and receive help-desk email through Microsoft Graph."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"Sign-in & AI\" tab \u2192 \"Microsoft 365 / Azure\" card. Saving needs Settings with Edit."}, {"steps": ["In the Azure portal, open App registrations and create (or open) the ITOps app.", "Under Authentication, add the Web platform and enter the Redirect URI: your ITOps address, as shown greyed-out in the \"Redirect URI (SSO)\" field.", "Under API permissions, add delegated User.Read for sign-in. For Graph email, also add application Mail.Send and Mail.ReadWrite. Then click Grant admin consent.", "Create a client secret and copy its value.", "In ITOps, fill in \"Directory (tenant) ID\", \"Application (client) ID\", \"Client secret\" and \"Redirect URI (SSO)\". For Graph email, also fill in \"Help-desk mailbox (Graph send/receive)\".", "Tick \"Enable SSO\", click \"Save\", then click \"Test Graph connection\"."]}, {"warn": "Changing the tenant, client ID, redirect URI, secret or turning SSO on/off is Super Admin only \u2014 these decide who can sign in to ITOps."}, {"h": "What happens when someone signs in with Microsoft"}, {"bullets": ["They are matched to an ITOps user: first by their Microsoft account ID once linked, otherwise by email address. The first sign-in links the two only when the Microsoft account is a member of your organisation (not a guest) and the ITOps account is not an administrator and does not use ITOps's own 2FA. For any other account, a Super Admin ticks \"Allow Microsoft sign-in to link\" on the user (Administration \u2192 Users \u2192 edit); the next Microsoft sign-in links it and the tick clears itself. After that, only that same Microsoft account can sign in to that ITOps user.", "Only accounts from YOUR tenant are accepted: the \"Directory (tenant) ID\" must be your tenant's ID, not \"common\".", "If there is no matching user, an account is created for them automatically with the Viewer role. Change their role under Administration \u2192 Users if they need more.", "Accounts with a status other than Active are refused.", "Microsoft handles their multi-factor sign-in. ITOps's own 2FA policy doesn't apply to them.", "When a Microsoft or Teams sign-in fails, the screen gives a short message; the details for the administrator are in the Audit Log (o365_login_rejected, teams_login_rejected, o365_link_refused)."]}, {"p": "One app registration, one configuration: the tenant, client ID and client secret entered here are the same ones used by the Microsoft 365 area and the Server Guardian page (Logs & Integrations \u2192 Integrations \u2192 \"System\" \u2192 \"Microsoft 365 connection\"). Saving the secret in either place replaces it everywhere. The secret is stored encrypted and never shown again."}, {"tip": "Save before you test. The client secret is write-only: once saved, leave the field blank to keep it."}, {"qa": [{"q": "The card says PHP cURL isn't available.", "a": "Microsoft 365 needs the PHP cURL extension. Ask your host to enable it."}, {"q": "Sign-in fails with a redirect error from Microsoft.", "a": "The Redirect URI in Azure must match \"Redirect URI (SSO)\" exactly, including https and the trailing slash."}]}]}, {"title": "Security: 2FA policy and idle timeout", "for": "admin", "mod": "settings:edit", "body": [{"p": "These two settings decide who must use two-factor authentication (2FA) and how long an unused session stays signed in."}, {"p": "Where it lives: Administration \u2192 Settings \u2192 \"General\" tab \u2192 \"Session security\" card. Only a Super Admin can save these settings. Anyone else gets an error."}, {"steps": ["Set \"Idle timeout (minutes)\". The default is 30.", "Choose \"Require two-factor authentication for\": \"Nobody (opt-in)\", \"Admins (roles that manage people, settings, the vault or Microsoft 365 / vTiger accounts)\" or \"All password (local) users\".", "Click \"Save\"."]}, {"h": "What happens next"}, {"bullets": ["Idle timeout: a person who does nothing gets a warning about a minute before the limit, then is signed out. The server checks it too (the bell and other background checks do not count as activity). The new value applies on each person's next sign-in or page load.", "2FA: people in scope who haven't set up 2FA must do it at their next sign-in, before they can use ITOps. They scan a QR code with an authenticator app and get 10 backup codes.", "\"Admins\" covers every role that can manage people (Users), settings, integrations, the vault (Credentials), Microsoft 365 accounts or vTiger accounts, whatever the role is called, and the Super Admin.", "People who sign in with Microsoft 365 are always exempt. Microsoft handles their MFA.", "After 8 wrong passwords in 15 minutes the account is blocked for about 15 minutes (from any network), and a network location with 30 wrong passwords waits as well. After 6 wrong 2FA codes, the account is blocked for about 15 minutes. A 2FA code works once."]}, {"h": "Resetting someone's 2FA"}, {"p": "If someone loses their phone, a Super Admin opens the person in Administration \u2192 Users and clicks \"Reset 2FA\" under \"Two-factor authentication\". The person can then sign in with just their password and set up 2FA again. Resetting someone's 2FA also signs them out everywhere."}, {"warn": "Setting 0 turns the idle sign-out off completely. That's convenient on a shared kiosk you watch, but risky on laptops: prefer a longer value such as 240."}, {"qa": [{"q": "Saving gives \"Only a Super Admin can change ...\".", "a": "These are protected settings. Ask a Super Admin to change them."}]}]}, {"title": "Users: adding people and giving them a role", "for": "admin", "mod": ["users", "roles"], "body": [{"p": "The Users page is where you add people to ITOps, choose how they sign in, and give them a role that decides what they can see and do."}, {"p": "Where it lives: Administration \u2192 Users. Your role's Users permission decides what you can do: View to see the list, Create to add, Edit to change, Delete to remove."}, {"steps": ["Click \"+ New User\".", "Fill in \"Display name\" and \"Email\" (both required), and optionally \"First name\" and \"Last name\".", "Pick a \"Role\". See \"Recommended role setups\" if you're unsure.", "Pick a \"Department\".", "Set \"Status\": Active, Inactive or Pending. Only Active users can sign in.", "Set \"Auth provider\" (Super Admin only): Local (ITOps password), Microsoft 365, or Both.", "Optional: set \"Email language\" (Organisation default, English or Espa\u00f1ol).", "For Local or Both, type a \"Password\" and give it to the person securely. Then save."]}, {"h": "Good to know"}, {"bullets": ["Without Users \u00b7 All records (the Department Admin role, for example) you see and manage the people of your own department only: new people are added in your department, and accounts cannot be moved to another one. Roles that managed everyone's accounts before this version kept that (All records was ticked for them).", "People who sign in with Microsoft 365 for the first time get an account automatically with the Viewer role. Check Users regularly and change their roles.", "To stop someone signing in, set Status to Inactive. Deleting a user turns the account off (status Inactive) and ends its sessions straight away: it can no longer sign in, and its history (tickets, cases, the Audit Log) keeps the name. You can't delete your own account.", "Only a Super Admin can give someone the Super Admin role, change or delete a Super Admin's account, change \"Auth provider\" or tick \"Allow Microsoft sign-in to link\".", "A new role takes effect on the person's next page load.", "To add many people at once, use Administration \u2192 Bulk Import."]}, {"qa": [{"q": "Someone can't sign in.", "a": "Check their Status is Active and their Auth provider matches how they sign in. After 8 wrong passwords they're blocked for about 15 minutes. If they lost their authenticator, a Super Admin can reset their 2FA."}, {"q": "I don't see \"+ New User\".", "a": "Your role needs Users with Create."}, {"q": "Saving gives \"Only a Super Admin can grant the Super Admin role\".", "a": "Pick a different role, or ask a Super Admin."}]}]}, {"title": "Roles & Permissions: how the permission grid works", "for": "admin", "mod": ["users", "roles"], "body": [{"p": "A role is a set of permissions, module by module. Every user has one role, and it controls which menu items they see and which actions ITOps accepts from them."}, {"p": "Where it lives: Administration \u2192 Roles & Permissions. Roles: View shows the list read-only. Only a Super Admin can create, change or delete roles, so nobody can give themselves more access."}, {"steps": ["Click \"New Role\", or click an existing role to edit it.", "Enter a \"Role name\" and a short \"Description\". The \"Slug\" fills itself in.", "Optional: under \"Start from a preset\", click Read-only, Help Desk Agent, Manager, Auditor or IT Administrator. \"Clear all\" empties the grid.", "Tick the boxes in the grid. Each group has \"View all\", \"Full\" and \"None\" buttons, and each row has an \"All\" box.", "Check the \"Sidebar preview\" on the right: it lists exactly what a user with this role will see.", "Click \"Create Role\" or \"Save Changes\". People get the new access on their next page load."]}, {"h": "What the columns mean"}, {"bullets": ["View: the page appears in the menu and can be opened. Without View it is hidden, and blocked even if someone has the link.", "Create: add new records. Edit: change existing ones.", "Delete: remove records.", "All records (Tickets only): see every ticket, which is the agent queue, and read and write internal notes. Without it, people see only tickets they opened, own or back up, and never see internal notes.", "Ticking any other box ticks View too, and unticking View clears the row. \"\u2014\" means that action doesn't exist for the module."]}, {"h": "Personal pages and sensitive modules"}, {"bullets": ["PERSONAL (My Signatures, My Equipment): on for every role by default, showing only the person's own items. Untick to hide.", "SENSITIVE (Credentials, the Microsoft 365 change permissions \u2014 Accounts, Credentials, Directory roles, Tenant configuration \u2014, Users, Integrations, Integration Audit, Settings \u00b7 General, Settings \u00b7 Email): grant with care. Credentials View reveals stored passwords.", "Everyone always has the Dashboard, their own profile and notifications.", "\"Full access to everything\" makes the role the same as Super Admin. Use it sparingly."]}, {"h": "Always Super Admin only"}, {"p": "Changing roles; granting Super Admin; the Maintenance tab (database updates); Server Guardian server actions; the 2FA policy and idle timeout; resetting someone's 2FA; vTiger provisioning and Integrations \u2192 \"System\"."}, {"h": "The Settings page has four access areas"}, {"bullets": ["Settings \u00b7 General: the General and \"Sign-in & AI\" tabs (backend connection, session security, Microsoft 365 sign-in, AI assist). Secrets, the 2FA policy and the idle timeout are still saved by a Super Admin only.", "Settings \u00b7 Branding: application name, logo, favicon and the navigation icons.", "Settings \u00b7 Email: the Email and Email templates tabs (outbound mail, the help-desk mailbox, notification switches, the English & Spanish templates). Mailbox passwords and the cron token stay Super Admin only.", "Settings \u00b7 SLA & Hours: SLA warning thresholds, digests and the business-hours clock.", "A person sees only the tabs of the areas they hold. Give a help-desk lead \"Settings \u00b7 SLA & Hours\" and \"Settings \u00b7 Email\" without opening the connection settings, for example.", "Roles saved before this change kept exactly the access they had: the old single \"Settings\" grant was copied to all four areas by the database update."]}, {"tip": "System roles can't be deleted, and a role still held by users can't be deleted either. The Super Admin role always has full access. Only its name and description can change. A role saved by an older version shows a notice: review it and click Save to convert it."}]}, {"title": "Recommended role setups", "for": "admin", "mod": ["users", "roles"], "body": [{"p": "These four setups cover most organisations. Build each one under Administration \u2192 Roles & Permissions (Super Admin only), starting from the preset named, then adjust."}, {"h": "Requester (all staff)"}, {"p": "Start from \"Read-only\" (the same as the built-in Viewer role)."}, {"bullets": ["Tickets: View + Create. No Edit and no All records, so they only see their own tickets and never see internal notes.", "Knowledge Base, Ask IT, SOPs (to read and acknowledge), Job Descriptions, Calendar, What's New: View.", "My Signatures and My Equipment: leave on.", "The preset also gives View on Equipment, Contracts and Vendors. Untick them if staff shouldn't browse those lists."]}, {"h": "Support agent"}, {"p": "Start from \"Help Desk Agent\"."}, {"bullets": ["Tickets: all five boxes, including All records (the queue).", "Calendar: full. Reports: View. Ticket Categories: View.", "Knowledge Base: View, Create, Edit. Consider adding KB Content Gaps (View + Edit) so agents can turn unanswered questions into articles.", "Equipment: View, Create, Edit. Contracts and Vendors: View.", "Leave Credentials off unless the agent really needs vault passwords."]}, {"h": "IT manager"}, {"p": "Start from \"IT Administrator\" for someone who runs the system, or \"Manager\" for a team lead who shouldn't touch settings."}, {"bullets": ["IT Administrator gives every module, including Users, Credentials, every Microsoft 365 change permission except Directory roles, Integrations, all four Settings areas, Audit Log and Event Log. It can't change roles or run database updates.", "Manager is the agent set plus Scorecard, Standards & Audits (View + Edit), SOP and Job Description authoring, full Contracts and Vendors, Onboarding templates & history, the two vTiger Provisioning permissions, KB Content Gaps, and View on Credentials, Users, Microsoft 365 and Server Guardian.", "Unassigned-ticket SLA alerts, the weekly digests and the \"Admins only\" 2FA rule apply only to the built-in Super Admin, Admin and Department Admin roles. If your IT manager should get those alerts, give them the built-in Department Admin role and adjust its grid."]}, {"h": "HR / People Ops"}, {"p": "Start from \"Read-only\", then add:"}, {"bullets": ["Onboarding templates & history: View (to follow joiners and leavers in Microsoft 365 \u2192 People \u2192 History). Add Edit if HR maintains the onboarding templates.", "Job Descriptions: View, Create, Edit. SOPs: View.", "Equipment: View, to see what a person has been issued.", "Leave the Microsoft 365 change permissions off unless HR onboards and offboards people themselves. Onboard / Offboard need \"Microsoft 365 \u00b7 Accounts\"; the license, group and vTiger parts need \"Microsoft 365 \u00b7 Licenses\", \"\u00b7 Groups\" and the two \"Provisioning\" permissions. Otherwise IT runs them.", "Leave Credentials and Users off."]}, {"tip": "Anyone who reviews activity (for example an external auditor) can use the \"Auditor\" preset: read-only everywhere, including the Audit Log and Event Log."}]}, {"title": "Cases & Projects: who can create cases and projects", "for": "admin", "body": [{"p": "Roles & Permissions \u2192 Service Desk \u2192 Cases & Projects has three actions. View: open the Cases & Projects page and work the tasks given to you (given to every role that edits tickets). Create: make cases (from a ticket or without one) and projects, and own them (Managers and Department Admins). All records: see every case; with Create too, manage every case (Department Admins)."}, {"p": "To give someone the same without changing their role, a Super Admin names them in Roles & Permissions \u2192 Cases & Projects: people with extra rights: \"May create and own cases\" and \"See every case\". The change is in the Audit Log with the names before and after. A third list, \"Keep the case templates\", names who besides the Super Admins may add, change and delete case templates and save a case as a template."}, {"p": "Cases & Projects \u2192 Settings (Super Admin) holds the change freezes and the daily case digest: on or off, the hour it is sent (7:00 AM by default) and Monday to Friday only. The emails sent at once (\"Case given to you\", \"Case task given to you\", \"Your case task can start\", \"Approval waiting for you\") and the digest itself are under Settings \u2192 Email templates (group Cases), where each can be reworded or switched off. Changes to the digest settings are in the Audit Log."}, {"p": "Who sees and does what, case by case:"}, {"bullets": ["Super Admin, and roles with Create + All records: see and manage every case and project.", "Roles with All records only: see every case and project, work the tasks given to them.", "Owner: manages the case or project (people, tasks, phases, tickets, resolve, make it a project). A new owner must be able to create cases.", "Roles with Create: make cases (from a ticket or without one) and projects; they see the ones they own or are part of.", "Watchers, people given a task and people invited to a meeting: see that case or project, work their own tasks and add team updates. This works whatever their role, so people outside IT (HR, Facilities) take part without a role change; they see only what they are part of.", "A project's sponsor: sees the project (phases, tasks, updates) and gets it in the daily digest; does not change it.", "The requester of a linked ticket: follows the case on their ticket only (the steps and updates shared with them).", "Budget card: needs IT Budget \u2192 View as well; linking lines also needs to manage the project. Without it, no amounts are shown and a try is refused and logged.", "Templates: Super Admins and the people named under \"Keep the case templates\"."]}, {"p": "When an account is deactivated while it still owns open cases or projects, sponsors a project or has open tasks, the admin who deactivated it gets a bell \"Case work to hand over\" (also in the Audit Log), and the cases show the account as inactive with a note to hand it over."}, {"p": "The same card names the Change Advisory Board (the people who approve high-risk changes) and the change freezes (a name, a first and a last day; no normal or standard change can be planned in them). Both are in the Audit Log."}]}, {"title": "Bulk import", "for": "admin", "mod": "import", "body": [{"p": "Bulk Import creates many users, vendors, contracts or vault credentials at once from a CSV file, instead of entering them one by one."}, {"p": "Where it lives: Administration \u2192 Bulk Import. You need Bulk Import with View, plus Create on the module you are importing into (Users, Vendors, Contracts or Credentials)."}, {"steps": ["Click the type you want: \"Users\", \"Vendors\", \"Contracts\" or \"Credentials\".", "Click \"Download template\" to get a CSV with the right header row.", "Fill it in with a spreadsheet program and save it as CSV. Columns can be in any order.", "Click \"Upload CSV file\", or paste the rows into the box.", "Check the \"Preview\". It shows how many rows were found and the first three.", "Click the \"Import \u2026\" button.", "Read the \"Result\": how many rows were created, skipped as duplicates, or had errors, with the row number and reason."]}, {"h": "What each type needs"}, {"bullets": ["Users: email and display_name are required. role is a role name or slug; if it's blank or not recognised, Viewer is used. status is active, inactive or pending. If password is blank, a random one is set, so the person signs in with Microsoft 365 or gets a password from you. Existing emails are skipped.", "Vendors: name is required. risk_tier is low, medium, high or critical (medium if blank). Existing names are skipped.", "Contracts: title, start_date and end_date are required (use YYYY-MM-DD). vendor must match an existing vendor name. owner is a user's email.", "Credentials: name is required. username, password, api_key and notes are encrypted as they are imported. owner is a user's email (you, if blank). rotation_days defaults to 90."]}, {"warn": "Contracts and credentials are not checked for duplicates. Importing the same file twice creates everything twice."}, {"warn": "A credentials CSV holds passwords in plain text. Delete the file from your computer as soon as the import is done."}, {"tip": "Up to 5,000 rows can be imported at a time. Each import is recorded in the Audit Log."}, {"qa": [{"q": "The Users button fails with \"Insufficient permissions\".", "a": "Your role has Bulk Import but not Create on Users. The same applies to the other types. A row with the Super Admin role is refused unless a Super Admin runs the import."}]}, {"p": "Every record an import creates is in the Audit Log (\"imported\", with its values; never a password or secret), plus one summary line. Without Users \u00b7 All records, people are added to your own department only."}]}, {"title": "Updating ITOps to a new build", "for": "admin", "mod": "settings:edit", "body": [{"p": "Every ITOps release comes as one full zip, and the same zip is used for new installs and for updates. Follow these steps to update without losing settings or files."}, {"p": "Who can do it: someone with cPanel access to the server, plus a Super Admin in ITOps for the database step."}, {"h": "Why it's safe"}, {"p": "Since 0621-BT90 the app comes compiled (app.js) and its libraries are in the vendor folder: the browser loads nothing from other sites. The source of the app is in the src folder (closed to the web)."}, {"bullets": ["The zip never contains config.php, only config.sample.php, so your configuration can't be overwritten.", "The zip never contains files inside public/uploads/, so uploaded logos, attachments and evidence are untouched."]}, {"steps": ["Read the new build's entry at the top of CHANGELOG.txt in the zip.", "In cPanel File Manager, upload the zip into the same ITOps folder and choose Extract, letting it overwrite existing files. Files must sit at the folder root, not in a subfolder.", "If the entry says \"DB UPDATE REQUIRED\": signed in as a Super Admin, open https://YOUR-SITE/db-update.php and click \"Apply updates now\". Or use Settings \u2192 Maintenance \u2192 \"Apply updates now\".", "If the entry says a new vTiger bridge build is needed: upload vtiger-bridge/itops-bridge.php from the zip to the vTiger web root, replacing the old file. Keep the same URL and the same secret (itops-bridge.secret stays as it is). Then click \"Test bridge\" in the vTiger provisioning card (Administration \u2192 Onboarding Templates).", "Hard-refresh the browser (Ctrl+Shift+R or Cmd+Shift+R).", "Check the build stamp. Settings \u2192 General \u2192 About \u2192 Version (for example \"build 0621-BT6\") must match the CHANGELOG entry. Logs & Integrations \u2192 What's New should show the new entry at the top."]}, {"tip": "Take a backup before you extract: the database with Settings \u2192 Maintenance \u2192 \"\u2b07 Download backup\" (or cPanel), and the ITOps folder in cPanel. After the update, open https://YOUR-SITE/api/health. It should show {\"status\":\"ok\",\"database\":true}."}, {"warn": "If the version still shows the old build after a hard refresh, the files didn't land in the right folder. Check that app.js and index.html in the ITOps folder have a new modified date."}, {"qa": [{"q": "Do I need to run the installer again?", "a": "No. The installer is only for new installs and refuses to run once ITOps is installed."}, {"q": "Which vTiger bridge build is current?", "a": "It's named at the top of vtiger-bridge/READ-ME.txt and in the CHANGELOG (currently build o8). If the CHANGELOG says no new bridge file, leave the vTiger server alone."}]}]}, {"title": "Database updates", "for": "admin", "mod": "settings:edit", "body": [{"p": "Some ITOps updates change how data is stored. A database update applies those changes, and you run it after installing a build whose CHANGELOG entry says \"DB UPDATE REQUIRED\"."}, {"p": "Who can run it: Super Admin only. Other roles don't see the Maintenance tab."}, {"steps": ["Open Administration \u2192 Settings and click the \"Maintenance\" tab.", "The \"Database Updates\" card shows either \"Your database is up to date.\" or how many updates are available.", "Click \"Apply updates now\".", "Wait for the message: \"Applied N updates\", \"Already up to date\", or an error."]}, {"p": "Or open https://YOUR-SITE/db-update.php in the same browser while you're signed in as a Super Admin. It lists the pending updates and has its own \"Apply updates now\" button."}, {"h": "Good to know"}, {"bullets": ["It's safe to run as often as you like. It only applies what is missing.", "It never changes config.php or your uploaded files.", "Each run is recorded in the Audit Log.", "Some screens tell you to run it, for example if the integration tables or the outbound email log don't exist yet."]}, {"qa": [{"q": "db-update.php says \"Please sign in to ITOps as an administrator first\".", "a": "Sign in to ITOps as a Super Admin in the same browser, then reload the page."}, {"q": "An update shows an error.", "a": "Copy the message, don't keep retrying, and send it with the build number (Settings \u2192 General \u2192 About \u2192 Version) to whoever supports your install."}]}, {"p": "Under \"Update history\" the card lists every database update with the date it was applied (pending ones first). Below it, \"Database health\" shows the database itself \u2014 see \"Database health, housekeeping and backup\"."}]}, {"title": "Database health, housekeeping and backup", "for": "admin", "body": [{"p": "Administration \u2192 Settings \u2192 \"Maintenance\" shows what is happening inside the database, so you can watch it and look after it without going to the server, cPanel or phpMyAdmin. Super Admin only."}, {"h": "What you see"}, {"bullets": ["Tiles: total size of the ITOps tables (and how much it grew in the last 7 days), number of tables, rows, open connections against the server limit, how long the database server has been up and how many checks need a look. Sizes and row counts come from the server's own statistics, so they are close estimates.", "\"Size over time\": a small chart of the size, from one snapshot saved each day by the scheduled job (it starts filling in the day after you install this build).", "\"Health checks\": core tables present, database updates applied, every table on InnoDB, one collation for all tables, no large wasted space, ID counters far from their limit, connections below the limit, and the database clock agreeing with the web server. Anything amber or red says what to do.", "\"Server settings\": version, character set, time zone, buffer pool, slow queries, SQL mode and other server values, read-only.", "Some shared hosts hide the server counters; the connection and uptime tiles then show \"\u2014\" and everything else still works."]}, {"h": "Tables"}, {"bullets": ["Every ITOps table with what it holds, its rows, size, index size, free space, growth over 7 days and when it last changed. Click a column header to sort, or search by name.", "\"Maintain\u2026\" on a row: \"Check for errors\", \"Analyze (refresh statistics)\" \u2014 helps the server plan queries after big changes \u2014 and \"Optimize (reclaim space)\", which rebuilds the table and locks it briefly (do it outside working hours). \"Fix collation\" appears on a table whose collation differs from the rest. The \"Mixed collations\" warning means some tables were created with the server default (utf8mb4_general_ci) instead of utf8mb4_unicode_ci. It is harmless \u2014 nothing is lost and ITOps works the same \u2014 but \"Fix collation\" on each flagged table (one at a time, outside working hours; the table is locked while it is rebuilt) makes the warning go away. From build BT35 a new installation creates every table with utf8mb4_unicode_ci, so it never appears on a fresh install.", "If other applications share the same database, their tables are hidden; tick \"Show other apps' tables\" to see them. They can't be changed from here.", "Every action is written to the Audit Log."]}, {"h": "Housekeeping"}, {"bullets": ["Logs that only grow \u2014 expired sign-in sessions, read notifications, the Event Log, the outbound email log and finished webhook deliveries \u2014 show their row count, oldest entry and how many rows would be removed with the number of days you keep.", "\"Remove now\" deletes those rows at once (you confirm first). Unread notifications and queued webhooks are never removed; each log keeps at least 30 days.", "Tick \"Clean up automatically once a day\" and \"Save\" to let the scheduled job (cron-sla.php) do it every day with the days you set. The last run and what it removed are shown next to the switch and in the Event Log.", "The Audit Log is a compliance record: it is never removed here."]}, {"h": "Backup"}, {"steps": ["Click \"\u2b07 Download backup\".", "Type BACKUP and confirm. A .sql.gz file with every ITOps table \u2014 structure and data \u2014 downloads to your computer.", "Keep it somewhere safe: it contains password hashes and encrypted secrets. To restore, import it with phpMyAdmin (Import) or the mysql command into an empty database."]}, {"warn": "The download is a copy for your records, not a replacement for your host's scheduled backups. Uploaded files (attachments, logos, evidence) are on disk in public/uploads and are not in the file \u2014 back that folder up with cPanel."}, {"qa": [{"q": "The size chart is empty.", "a": "One snapshot is saved per day, by the scheduled job or when this page is opened. The line appears from the second day."}, {"q": "\"Mixed collations\" is amber.", "a": "Some older tables were created with utf8mb4_general_ci. It does no harm today; use \"Maintain\u2026\" \u2192 \"Fix collation\" on those tables outside working hours to align them."}, {"q": "The backup is slow or stops on a very large database.", "a": "Large databases can hit the host's time limits. Use cPanel \u2192 Backup or phpMyAdmin \u2192 Export instead."}]}]}, {"title": "Security checklist after installing or updating", "for": "admin", "mod": "settings:edit", "body": [{"p": "Work through this list after a new install and after each update, so the server and ITOps's powerful settings stay locked down."}, {"h": "On the server"}, {"steps": ["Delete the install/ folder, or deny web access to it. The installer already refuses to run once ITOps is installed (\"ITOps is already installed. The installer is disabled.\"), but removing it is safer.", "In a browser, open https://YOUR-SITE/config.php and https://YOUR-SITE/sql/. Both must return 403 Forbidden.", "Open https://YOUR-SITE/api/health. It should show {\"status\":\"ok\",\"database\":true}.", "Leave public/uploads/.htaccess in place. It stops uploaded files from running as scripts or web pages.", "If the CHANGELOG entry says \"DB UPDATE REQUIRED\", run the database update (Settings \u2192 Maintenance)."]}, {"h": "Inside ITOps"}, {"steps": ["Settings \u2192 General \u2192 \"Session security\": require 2FA (\"All password (local) users\" is the safest), and set an idle timeout.", "Administration \u2192 Users: check who has the Super Admin role, and set leavers to Inactive.", "Administration \u2192 Roles & Permissions: check which roles have SENSITIVE modules (Credentials, the Microsoft 365 change permissions, Users, Integrations, Settings).", "Logs & Integrations \u2192 Integrations: revoke API keys nobody uses.", "Logs & Integrations \u2192 Audit Log: look for login_lockout, mfa_failed and settings_updated entries you don't recognise."]}, {"h": "What ITOps protects for you"}, {"bullets": ["Stored secrets (mailbox, SMTP, Azure, AI, vTiger) are never shown back in the browser. A blank field keeps the saved value.", "Only a Super Admin can change: the Microsoft 365 and vTiger connections (Settings \u2192 Company systems \u2192 Set up\u2026), Guardian settings, the 2FA policy and idle timeout, and any stored secret (mailbox and SMTP passwords, the Microsoft 365 sign-in secret, the AI keys).", "An API key can never have more access than the person who created it, and can't reveal vault passwords.", "Password hashes and 2FA secrets are never sent to the browser, the audit log or webhooks."]}, {"tip": "Keep the vTiger bridge secret in itops-bridge.secret on the vTiger server (permissions 600, web access denied), and change it from time to time with \"Rotate secret\u2026\" in the vTiger provisioning card."}]}, {"title": "Security fixes in this version", "for": "admin", "mod": "settings", "body": [{"p": "An October 2026 code audit of the whole app found places where a person could do more than their role should allow. This version closes the most urgent ones; nothing needs to be set up, but a few things now work differently."}, {"bullets": ["Planned changes: standard (pre-approved) only from a standard-change template; approvals are answered by their approver only; the owner withdraws the whole request to change it; the details are locked once approval is asked for; the owner never approves their own medium-risk or emergency change; a change needs a type and an approval to be resolved as successful. Run the database update: standard changes marked by hand before need approval (the update says how many).", "Calendar: the person adding an event is its organizer (a Super Admin can name someone else); only the organizer or a Super Admin changes who is invited. Outlook sends invitations only for events their organizer made.", "Tickets: without Tickets \u00b7 All, tickets are filed in your own name with the app's due times and routing; the requester of a ticket changes its subject and details (or cancels it), the person working it also its category, priority and status. The ticket number and the response / resolve / close times are the app's own.", "Bell notifications: the help desk and Super Admins message anyone; others only the people on a ticket they work (up to 50 people, 20 messages an hour).", "Settings: security settings and any setting outside a role's areas are Super Admin only; the logo and icon are uploaded only; only a Super Admin changes the Microsoft 365 mailbox.", "Deleting a user turns the account off and ends its sessions."]}, {"h": "Public pages and email (second part)"}, {"bullets": ["Requests from the public page and forms sent with the address of a person of the app wait for that person to confirm them by email; until then they are from an outside contact, marked \"not confirmed yet\".", "The acknowledgement email no longer repeats links from the subject.", "Form files: the server decides the file name and type; files are reached only inside the app; files never sent are removed after 24 hours.", "Email intake: messages that fail DMARC are treated as from an unknown sender (internal note only, nothing sent back).", "Email settings: the saved password is only used with its server \u2014 changing or testing another server needs it typed again.", "Every CSV export is safe to open in a spreadsheet (no cell starts a formula).", "Knowledge Base: only articles marked public are on the public help portal (off for all articles at first \u2014 mark the ones meant for everyone); one vote per visitor.", "Scheduled jobs: the token only in the header; the app calls itself at its own address (APP_URL), never at the address in the request; a public rating can be changed a few times only."]}, {"h": "Microsoft 365 and integrations (third part)"}, {"bullets": ["Actions on Microsoft 365 admin accounts (password, MFA, block, sign-out, offboard) are Super Admin only, including roles held through groups or eligible in PIM; the high-risk directory roles too.", "Bulk licence removal asks for REMOVE, switching a Conditional Access rule off for OFF.", "Every Microsoft Graph address and report period is checked; Microsoft's \"slow down\" is waited out; the cached token is private and encrypted.", "Webhooks and the assistant's trusted sources only reach public addresses; the AI provider is switched only by a Super Admin, with that provider's key.", "Rollout emails typed by address stay inside your organization; a BitLocker key is shown only when Microsoft confirms its device."]}, {"h": "Onboarding, offboarding and vTiger (fourth part)"}, {"bullets": ["vTiger steps (create the vTiger user, move the records, deactivate the user) need the Provisioning permissions, not only Onboarding \u00b7 Edit; a vTiger admin is handled by a Super Admin only.", "The new owner of a leaver's records is fixed on the step; only a Super Admin changes it.", "Steps change only while the process is in progress, run one at a time, and a done step stays done; a completed process cannot be cancelled.", "Each person sees the onboarding and offboarding records they started and those of their department; tick Onboarding \u00b7 All records for the roles that should see every one.", "The vTiger bridge build o8 refuses a copied request, passwords over plain http, vTiger's own tables and creating admins. Upload it after this version (see \"Connecting vTiger provisioning\")."]}, {"h": "Sign-in and the browser (fifth part)"}, {"bullets": ["Wrong passwords are counted per account and per network, and attempts on one account are taken one at a time; a 2FA code works once; re-typing a password or code (2FA set-up and switch-off, the vault) is limited too.", "Microsoft and Teams sign-in link an existing account by email only for a member of your organisation without ITOps 2FA, never an administrator; a Super Admin can allow one link per person.", "The vault reveals the secrets of your own department unless your role has Credentials \u00b7 All records; each reveal asks again (password, 2FA code, or a recent Microsoft sign-in).", "Department Admins manage the people of their own department only.", "The session is in a protected cookie only; the app is compiled before it is shipped and its libraries come with it, so the browser runs no code from other sites and no inline scripts.", "The idle sign-out is checked on the server; a 2FA reset by a Super Admin signs the person out everywhere; sign-in errors no longer show technical details on screen."]}, {"h": "IT operations and documents (sixth part)"}, {"bullets": ["Uptime checks go to the address the name had when it was checked, and never to link-local or \"this network\" addresses, also when written as IPv6.", "The WHM token is sent only to a WHM whose certificate is checked: a public certificate, or the one a Super Admin trusted under Server Guardian settings \u2192 WHM certificate. Do this once after the update if your WHM uses its own certificate.", "A server action WHM refuses shows as failed; \"Restart a service\" takes only WHM's own service names.", "Links between records show only what you may open; making or removing a link needs Edit on the record (Standards & Audits \u00b7 Edit for a requirement); an API key is never the owner of a requirement.", "Signature requests take the title and version from the document and can no longer be signed once the document changed; outside signing links work for 30 days; cancelled requests cannot be signed.", "The version of an SOP or job description moves only when its text changes; readers see published SOPs only; the HTML of articles, SOPs and job descriptions is cleaned when saved.", "Smaller fixes: announcements keep their wording once someone confirmed them; a budget line is approved by someone else than who added it; Knowledge Base votes count once per person; vendor contacts, equipment and bulk imports are logged with their values."]}, {"h": "Tickets and cases (seventh part)"}, {"bullets": ["A ticket's owner and backup read and write its internal notes; files can be internal too (the requester never sees them), and a requester removes only the files they added.", "A reopened ticket gets a new resolution due time; a reply from the requester ends Pending; only an answer to the requester (Pending, Resolved, Closed, or a public reply) counts as the first response.", "A major incident that is cancelled, merged or deleted stands down (banner back, linked tickets unlinked); merging is done in one step; a deleted ticket's files leave the server.", "A case links only tickets its owner may open; a case's meeting is changed only through the case, and its text is for the case's people; requesters no longer see change windows and milestones.", "A decided approval is reopened only by the case owner; change freezes are checked again when approval is asked for and given; timeline moves keep the order of tasks that wait for each other.", "Connecting an existing Scorecard row to a measure needs Scorecard \u00b7 Edit; satisfaction is shown to the help desk only; the Audit Log withholds private-event details and budget amounts from people without those rights."]}, {"p": "Every refused attempt is in the Audit Log (case_refused, calendar_refused, ticket_field_refused, notification_refused, settings_refused, ob_task_refused, ob_refused, vtiger_admin_target_refused, user_refused, credential_reveal_denied, o365_link_refused, whm_cert_refused, guardian_action_refused, std_refused, link_refused, signature_refused, sop_refused, announcement_refused, budget_refused, document_refused, attachment_refused, case_refused, scorecard_refused). The other findings of the audit follow in the next versions."}]}, {"title": "Renewal and rotation reminders (how they fire)", "for": "admin", "mod": ["contracts:edit", "creds:edit"], "body": [{"p": "ITOps reminds record owners before a contract ends, before a credential needs rotating, before an SOP review is due and before a compliance review is due. The reminders run on their own, with no extra setup."}, {"h": "When each reminder fires"}, {"bullets": ["Contracts: when the end date is within the contract's \"Renewal notice (days)\" (90 if blank), the owner gets \"Contract renewal coming up\" and the status changes from Active to Expiring. After the end date, they get \"Contract expired\" and the status changes to Expired.", "Credentials: 14 days before \"Next rotation date (shows on Calendar)\", the owner gets \"Credential rotation coming up\" and the status becomes Due soon. After that date, they get \"Credential rotation overdue\" and the status becomes Overdue.", "SOPs: 14 days before \"Next review\" the SOP owner gets \"SOP review due soon\", and \"SOP review overdue\" once the date has passed (Published, Approved and Under review SOPs).", "Compliance requirements: 14 days before \"Next Review\", and again once it's overdue.", "Each reminder is sent once per date. If you change the date (for example after renewing), the reminders start again for the new date."]}, {"h": "Who gets them"}, {"p": "The record's owner, if that user is active. If there's no owner, every active Super Admin, Admin and Department Admin gets it instead. Each reminder appears in the notification bell, and is emailed when outbound email is on and that email is switched on under Settings \u2192 \"Email templates\"."}, {"h": "What makes them run"}, {"p": "They run with the SLA scheduled job (cron-sla.php), or with the in-app scheduler while someone has ITOps open. If neither is running, nothing is sent. See \"Scheduled jobs: cron and the in-app scheduler\"."}, {"tip": "Give every contract, credential and SOP an owner. Otherwise all the admins get every reminder."}, {"warn": "There's no on-screen switch that turns all reminders off. To stop the emails only, switch off the reminder emails under Settings \u2192 \"Email templates\". The bell notifications continue.", "tip": null}, {"qa": [{"q": "A contract passed its end date but nobody was told.", "a": "Check the contract had status Active or Expiring, that it has an end date, and that scheduled work is running (Event Log, channel cron)."}]}]}, {"title": "Scheduled jobs: cron, the in-app scheduler and the run history", "for": "admin", "mod": "settings", "body": [{"p": "Some ITOps work runs on a timer rather than when someone clicks: reading the help-desk mailbox, SLA alerts, reminders, digests and scheduled offboarding. This topic explains how to keep that work running."}, {"h": "Are they running? Logs & Integrations \u2192 Scheduled jobs"}, {"bullets": ["The page has three tabs. Scheduled jobs: the jobs on the left with their state; click one to see it on the right \u2014 the last run with its steps, the last success and failure, when it is expected next, its last runs (click one to open it), this month's history and the monthly report. Set up: the cron lines for cPanel. Alerts: who is told, the expected interval per job, and the outside monitor.", "A job that has not had its first run yet (for example the weekly digest before its first Monday) shows \"Waiting for first run\" for a full interval; only after that does it count as \"never ran\".", "History: the runs of the current month are kept. When a month starts, last month's runs become one line per job in the monthly report (runs, % finished OK, runs where a step failed, failed runs, runs with nothing to do, average and longest time) and are cleared. The newest run of each job is always kept. Runs that had nothing to do are counted into the report after a day."]}, {"bullets": ["Every run of cron-sla.php, cron-sla.php digest, cron-mail.php, cron-audit.php, cron-uptime.php and the in-app scheduler is recorded: when, how it started (cron, web call, in-app scheduler, Run now), how long, the result, and each step with its own result. A run stopped by a PHP error is closed as failed, with the error.", "Each job shows: running normally, a step failed, failing, late (no run for twice its interval + 5 minutes; a weekly job: a day), stuck, never ran, or not needed (its feature is off). Click \"last run\" or a bar of the last 48 runs to see the steps.", "Administrators are told once when a job is late, failing or stuck (bell and email), and once when it runs normally again. Change the expected interval and switch alerts per job under \"Alerts\"; \"Send me a test alert\" checks they arrive.", "\"Run now\" starts the main scheduler or the email intake straight away.", "\"Set up the cron jobs\" shows the exact lines for cPanel \u2192 Cron Jobs with this server's PHP and folder. If cron runs another PHP version than the website, the page says so.", "Outside monitor: \"Make the URL\" gives a private address for an uptime service (UptimeRobot, Better Stack\u2026). It answers 200 when every job is fine and 503 when one is late or failing, with job names and states only \u2014 it catches the case nothing inside the app can see: cron not running at all. The address is shown once; \"Stop\" ends it.", "It needs the Scheduled jobs permission (View; Edit for alerts, Run now and the monitor). Super Admins have it."]}, {"h": "Two ways to run it"}, {"bullets": ["In-app scheduler: Settings \u2192 \"Email\" tab \u2192 \"SCHEDULE\" \u2192 \"Run automatically while ITOps is open\" (on by default). About every 3 minutes, while anyone has ITOps open in a visible tab, it reads the mailbox and runs the SLA job. \"Last automatic run\" shows when it last worked.", "cPanel cron jobs (recommended): they run even at night when nobody is signed in."]}, {"h": "Setting up the cron jobs"}, {"steps": ["Save the Email settings at least once. This creates the cron token that the scheduler and the URL versions need.", "In cPanel \u2192 Cron Jobs, add: */5 * * * * php /home/USER/public_html/itops/cron-mail.php (mailbox to tickets).", "Add: */5 * * * * php /home/USER/public_html/itops/cron-sla.php (everything else).", "Add: 0 7 * * 1 php /home/USER/public_html/itops/cron-sla.php digest (weekly SLA digest, Monday at 7:00).", "Change /home/USER/public_html/itops to your real folder. If you can't run php commands, use the curl commands shown on the Email tab \u2014 they send the token in an \"X-ITOps-Cron-Token\" header so it never appears in web-server logs (older lines with ?token= keep working)."]}, {"warn": "The cron token runs every scheduled job, including scheduled offboarding. Only a Super Admin can see it, and a Super Admin can issue a new one with \"Rotate token\" on the Email tab (update your cron lines afterwards)."}, {"h": "What cron-sla.php does on each run"}, {"bullets": ["Contract, credential, SOP review and compliance review reminders.", "SLA due-soon and breached alerts.", "Scheduled offboarding that has reached its time.", "Onboarding task reminders and overdue equipment loan reminders.", "Server Guardian and Microsoft 365 alert checks, webhook retries and queued webhooks.", "Scorecard auto-measurables, the monthly access re-check, and the daily alert and weekly operations digests if they're switched on under Server Guardian.", "Announcements: publishing the scheduled ones, automatic reminders and the queued emails.", "Teams notifications, when the Teams app is switched on.", "Once a day: the database size snapshot (and the log cleanup, if you switched it on) and the Microsoft 365 device inventory sync."]}, {"warn": "The weekly SLA digest runs only from \"cron-sla.php digest\". Scheduled offboarding at an exact time (for example 5 pm on someone's last day) needs a cron job, or someone with ITOps open at that moment."}, {"tip": "To check it's working, open Logs & Integrations \u2192 Event Log and filter the channel to cron. Each run adds an Info entry, \"SLA scan complete\"."}, {"qa": [{"q": "The SLA & Hours tab doesn't show any cron commands.", "a": "Save the Email settings once to create the token, then reload."}]}, {"p": "All times on this page, like everywhere in the app, are in the installation's time zone in 12-hour format (2:05 PM)."}, {"qa": [{"q": "What is the Integration audit collectors job?", "a": "The Integration Audit area can collect evidence by itself (server logs, metrics) through collectors. A collector runs only after an administrator approves it and switches it on (Integration Audit \u2192 Collectors). Until then cron-audit.php does nothing, and its cron line can be left out; the job then shows \"Not needed\"."}, {"q": "Do the cron lines need the token?", "a": "No. Lines that start with the PHP path (for example /usr/local/bin/php \u2026/cron-sla.php) run on the server itself and need no token. Only the web versions (curl or wget to an address) need the token."}, {"q": "The page says cron runs a different PHP version than the website.", "a": "Use the website's PHP in the cron commands: the lines on the Set up tab already start with it (on cPanel, /opt/cpanel/ea-phpXY/root/usr/bin/php, XY being the website's version, for example ea-php81 for PHP 8.1). Or switch the website to the other version in cPanel \u2192 MultiPHP Manager \u2014 that changes every app on that domain, so test them first."}]}, {"warn": "Over HTTP, the cron token goes only in the X-ITOps-Cron-Token header (as the lines shown in the app). Since this version an address with ?token= is refused (it would put the token in web logs): if one of your cron jobs still uses ?token=, replace it with the command shown in Settings \u2192 SLA & Hours or with the php command line. Backup check-ins from other servers now show the key in a header too; older ?key= addresses keep working."}, {"tip": "The jobs print nothing when cron runs them, and the lines shown here end in \">/dev/null 2>&1\", so the server does not email you after every run (cPanel sends the output of every cron job to its \"Cron Email\" address). Every run is in Logs \u2192 Scheduled jobs instead. If you already receive one email per run, edit only the ITOps lines in cPanel \u2192 Cron Jobs and add >/dev/null 2>&1 at the end; other jobs keep their emails."}]}, {"title": "Standards & Audits", "for": "admin", "mod": "standards", "body": [{"p": "Standards & Audits tracks readiness for the standards your organization follows (an accreditation, a certification or your own internal standards): each requirement, its status, its owner, its evidence and when it's next reviewed. ITOps ships no external standard: you load or write the requirements that apply to you."}, {"p": "Where it lives: Service Desk \u2192 Standards & Audits. Standards & Audits: View lets you look. Adding or changing requirements and evidence needs Edit (Create alone isn't enough). Deleting needs Delete."}, {"h": "The two tabs"}, {"bullets": ["\"Overview\": counts of Requirements, Met, With evidence and Gaps, a \"Status breakdown\", and \"Reviews due (next 30 days & overdue)\". Click a count to open the matching requirements.", "\"Requirements & Evidence\": the full list, where you add and update requirements."]}, {"steps": ["Open Service Desk \u2192 Standards & Audits \u2192 \"Requirements & Evidence\" and click \"+ Add requirement\".", "Fill in \"Title\", \"Standard Ref\" (for example IT-01), \"Status\" (Met, In progress, Not met or N/A), \"Owner\", \"Last Reviewed\", \"Next Review\" and \"Notes\". Save.", "Add evidence: upload files under \"Evidence files\", or link SOPs, Job Descriptions or KB articles under \"Linked documents (evidence)\". Both count as evidence.", "Repeat for each standard. A requirement counts as a gap if it's Not met or has no evidence (N/A ones are ignored)."]}, {"h": "Related pieces set up at install"}, {"bullets": ["A Knowledge Base category called \"Accreditation Evidence\", for articles you want to use as evidence.", "A Compliance department and an SOP category called Compliance.", "A calendar event, \"Accreditation Survey Window Opens\". Open it in Service Desk \u2192 Calendar and set your real date."]}, {"tip": "Give every requirement an Owner and a Next Review date. The owner is reminded 14 days before the review and again when it's overdue. Requirements without an owner remind the Super Admins, Admins and Department Admins."}]}, {"title": "Announcements: writing, publishing and following up", "for": "admin", "body": [{"p": "An announcement is written once and goes out through up to three channels: the app (always), email to each person, and a card in a Teams channel. No channel is the only one, and ITOps keeps the record: who it was sent to, who opened it and who confirmed."}, {"h": "Who can do what"}, {"bullets": ["Everyone reads the announcements sent to them. That needs no permission.", "Administration \u2192 Roles & Permissions \u2192 \"Announcements\": View shows the \"Manage\" tab and the read reports; Create writes drafts; Edit publishes, schedules, reminds, archives and corrects; Delete removes an announcement with its report.", "After installing this build only Super Admins can publish. Tick the permission for the roles that should."]}, {"h": "Write and publish"}, {"steps": ["Open Announcements \u2192 \"Manage\" \u2192 \"\uff0b New announcement\". The editor opens as a full page.", "Title and text. The text is plain so it reads the same everywhere: leave an empty line between paragraphs, start a line with \"- \" for a list, put **two asterisks** around bold text; links become clickable. \"preview\" shows the result.", "Optional: tick \"Add a Spanish version\" and write the Spanish title and text. People whose language is Spanish get that version; in Teams both are posted.", "Level: \"Announcement\", \"Important\" or \"Urgent\". \"Show until\" (optional) is when it leaves people's lists.", "\"Who is it for\": \"Everyone\", or selected departments, roles and people. The line underneath says how many people it reaches and names the first ones.", "\"Where it goes\": the app is always on; tick \"Email to each person\"; pick a Teams channel or \"Do not post to Teams\".", "Optional: \"Ask people to confirm they have read it\", with a \"Confirm by\" date and automatic reminders (every 1, 2, 3 or 7 days, up to 5 times).", "\"Send me a test\" saves the draft and sends it only to you (bell and email).", "\"\ud83d\udce3 Publish now\" asks you to confirm and sends it. Or choose \"Publish later\", set the date and time, and click \"\ud83d\udd52 Schedule\"."]}, {"warn": "The list of recipients is fixed when you publish. People added to a department, role or the organization afterwards do not get that announcement. A Teams post is seen by everyone in that channel, whatever audience you selected."}, {"h": "Follow up"}, {"bullets": ["The \"Manage\" list shows, for each announcement, who it was for, the channels, the status and how many people opened and confirmed it.", "Click a published announcement for its report: totals, where it went (including whether Teams accepted the card), and every recipient with the time they opened and confirmed it and the state of their email. Filter by \"Not opened\" or \"Not confirmed\"; \"\u2b07 CSV\" exports the list.", "\"\ud83d\udd14 Remind\" sends a bell notice (and an email, when Email was ticked) only to the people who have not opened or confirmed it.", "\"\u270f Correct text\" fixes the wording, level, dates or reminders of a published announcement. Nothing is sent again, and the recipients and channels stay as they were.", "\"Archive\" stops showing it (it moves to \"Earlier announcements\" for its readers and queued emails are cancelled). \"Delete\" removes it and its report.", "A draft or a scheduled announcement opens in the editor when you click it. \"Publish later\" announcements are published by the scheduled job, within about 5 minutes of the time you set."]}, {"h": "Connect a Teams channel"}, {"steps": ["In Teams, open the channel \u2192 \u2022\u2022\u2022 (More options) \u2192 \"Workflows\".", "Choose \"Post to a channel when a webhook request is received\", confirm the team and channel, and finish. Teams shows a URL: copy it.", "In ITOps: Announcements \u2192 \"Manage\" \u2192 \"Teams channels\" \u2192 \"\uff0b Add channel\". Give it a name people will recognise (for example \"All staff\") and paste the URL. Click \"Save channels\".", "Click \"Send test\" and check that a test card appears in the channel."]}, {"bullets": ["Only a Super Admin (or a role with Integrations \u00b7 Edit) can add or change channels. The URL is stored encrypted and is never shown again; to replace it, paste a new one.", "Only Microsoft's own workflow addresses are accepted.", "The workflow posts as the person who created it (or as \"Flow bot\"). If that person leaves the organization, recreate the workflow and paste the new URL.", "If Teams refuses a card, the announcement is still published in the app and by email, and the report shows \"failed\" with the reason."]}, {"h": "Email"}, {"bullets": ["Announcement emails use two templates you can edit under Settings \u2192 Email templates \u2192 \"Announcements\": \"New announcement\" and \"Announcement reminder\", in English and Spanish.", "They are sent in small batches: the first ones at once, the rest by the scheduled job within a few minutes. The report shows how many are sent, queued or failed.", "If outbound email is switched off, the announcement is still published in the app and the editor warns you before you publish."]}, {"qa": [{"q": "What is the difference with the announcement banner?", "a": "The banner (Integrations \u2192 System) is one line shown to everyone across the top, with no tracking. Announcements have a full text, an audience, three channels and a record of who read them."}, {"q": "Someone joined after I published.", "a": "They did not receive it. Publish a new announcement for them, or for everyone."}, {"q": "Can people confirm from Teams or from the email?", "a": "The email and the Teams channel card carry a link to the Announcements page, where they confirm. When the Teams app is set up (see \"Setting up the Teams app\"), the card opens that page inside Teams, already signed in."}, {"q": "The scheduled announcement did not go out.", "a": "Scheduled publishing and automatic reminders need the scheduled job (cron-sla.php) or someone with ITOps open. See \"Scheduled jobs: cron and the in-app scheduler\"."}]}, {"tip": "Once someone has confirmed reading an announcement, its title and text stay as they were (that is what they confirmed). The level, dates and reminders can still change. For new wording, archive it and publish a new one."}, {"h": "People outside the app (Microsoft 365 groups and email addresses)"}, {"p": "With \"Selected departments, roles or people\", the section \"People outside the app\" adds a Microsoft 365 group or distribution list (type the start of its name and pick it) and email addresses typed or pasted (from Outlook too, up to 500)."}, {"bullets": ["The members of each group, nested groups and outside contacts included, are read from Microsoft 365 when it is published. Disabled accounts and members without an email address are left out. The line under the audience says how many people with an account and how many outside the app it reaches.", "Anyone with an account in the app gets it as usual: bell, email and the Announcements page.", "Everyone else gets their own email (template \"Announcement to someone without an account\") with a personal link. Opening the link counts as opened; \"I have read this\" confirms it, without an account. The link is for that person only.", "The read report lists them with everyone else, tagged \"outside the app\". \"Remind\" emails the ones who have not confirmed (or opened). Archiving closes their links.", "It needs \"Email to each person\", the Microsoft permission GroupMember.Read.All (or Group.Read.All) for groups, and outbound email on. If a group cannot be read, the announcement is not published and the message says why."]}]}, {"title": "Audit Log", "for": "admin", "mod": "audit", "body": [{"p": "The Audit Log records who did what, and when: record changes, sign-ins, settings changes and admin actions. Use it to answer \"who changed this?\" or to give an auditor evidence."}, {"p": "Where it lives: Logs & Integrations \u2192 Audit Log. You need Audit Log with View (included in the Auditor and IT Administrator presets). It's read-only: nobody can edit or delete entries from the screen."}, {"steps": ["Open Logs & Integrations \u2192 Audit Log. The newest entries are first, 50 per page, with Time, User, Action and Item.", "To search, type in \"Search user, action, item\u2026\" and press Enter or click \"Search\".", "To narrow by kind of record, use the \"All types\" list (for example ticket, credential, user, role, auth or settings).", "Under the headings, each column has its own filter: a date range for Time (from, to; both days included), and a box for User, Action and Item. Typed filters apply after a short pause or on Enter; \"Clear filters\" empties them.", "\"Newest first\" and \"Oldest first\" choose the order, so the first or the last entry of a filtered list is at the top. Clicking a heading sorts by that column; click again to reverse it.", "Click a row with \u25be to expand it. You see the IP address, the record number, and for edits each changed field as old \u2192 new.", "Use \"\u2039 Prev\" and \"Next \u203a\" to page. Click \"CSV\" to download the entries that match your search and filters, in the order shown (up to 5,000)."]}, {"h": "What you'll find in it"}, {"bullets": ["Records created, updated and deleted across ITOps, with the changed fields.", "Sign-ins, under the person who signed in: login_first (the very first sign-in of an account), login_success (email and password), o365_login (Microsoft), teams_login (Teams); also login_failed, login_lockout, logout, and the 2FA events (mfa_enabled, mfa_failed, mfa_reset).", "People: user_role_changed and user_department_changed show the old and the new role or department by name; created, updated and deleted show the person's name.", "Settings: settings_updated (with the setting names), mail_settings_updated, o365_settings_updated, ai_config, branding uploads.", "Admin actions: bulk_import, db_update, o365_auto_provision (a new Microsoft sign-in), notification_sent, onboarding and offboarding steps, access re-checks.", "Automatic work, such as each mailbox check (mail_poll). These show the user as System."]}, {"h": "Microsoft 365 and vTiger changes"}, {"bullets": ["Choose \"m365\" (or \"vtiger\") in the \"All types\" list to see only those, or search a person's sign-in name to see everything done to that account.", "m365_user_update: contact information, manager or custom fields were changed. Open the row to see each field as old \u2192 new. One save can be several rows, one for each part (main fields, phone numbers, fax, custom fields, manager), each written as soon as Microsoft answered it.", "m365_user_update_refused: a part of a change was not made. The row shows the value that was wanted and why: \"not changed\" (Microsoft refused it, or a manager removal did not match the account), \"outcome not known\" (no clear answer came back, so check the account) or \"not sent\" (the time for one save ran out; nothing was changed).", "m365_users_bulk_update: a bulk edit ran. The row shows the instruction, the accounts and the result. Each changed account also has its own m365_user_update row, named \"\u2026 (bulk edit <run>)\".", "m365_custom_fields_save: the custom field definitions or the company-wide values were changed, with the list before and after.", "The same entries appear on the account itself: Microsoft 365 \u2192 People \u2192 pick a person \u2192 \"+ Show change history\".", "\"Show change history\" on an account is for people who edit accounts (\"Microsoft 365 \u00b7 Accounts\" with Edit) or who can read the Audit Log."]}, {"tip": "Password hashes and 2FA secrets are never written to the log, and vault passwords are only ever stored encrypted."}, {"qa": [{"q": "I don't see Audit Log in the menu.", "a": "Your role needs Audit Log with View."}, {"q": "What's the difference from the Event Log?", "a": "The Audit Log is about people's actions. The Event Log is about the system itself: scheduled runs, integration errors and background jobs."}]}, {"h": "What each role sees"}, {"p": "A role reads only the entries of the areas it can open: Credentials entries need Credentials \u00b7 View, Contracts need Contracts \u00b7 View, Equipment needs Equipment \u00b7 View, tickets need Tickets \"All records\", and so on. A person always sees what they did themselves. Entries that belong to no area are shown to Super Admins only. The type filter lists only the kinds the role may read; searching and the CSV export follow the same rule."}, {"p": "An entry follows the rights of the record it is about. The details of a private calendar event show only to the people who can open the event (others see \"Private event\"), and the amounts of a project's IT Budget lines only to people with IT Budget \u00b7 View. A Super Admin, and the person who made the change, read every entry in full."}]}, {"title": "Event Log", "for": "admin", "mod": "event_log", "body": [{"p": "The Event Log shows what ITOps's background parts did: scheduled runs, Microsoft 365 and Server Guardian actions, onboarding outcomes, webhook failures and alerts. Look here first when something automatic didn't happen."}, {"p": "Where it lives: Logs & Integrations \u2192 Event Log. You need Event Log with View (included in the Auditor and IT Administrator presets). It's read-only."}, {"steps": ["Open Logs & Integrations \u2192 Event Log. You see the latest 100 matching events, newest first, with When, Level, Channel and Message.", "Pick a level: \"Error\", \"Warning\", \"Info\" or \"Debug\" (or \"All levels\").", "Pick a channel. The list only shows channels that have events, for example cron, onboarding, m365, guardian, webhook, backup or mailq.", "To search, type in \"Search message\u2026\" and press Enter. Click the refresh icon to reload."]}, {"h": "Useful checks"}, {"bullets": ["Is scheduled work running? Channel cron should show \"SLA scan complete\" every few minutes.", "Did a scheduled offboarding run? Channel onboarding shows \"Scheduled offboarding ran for \u2026\" and the result.", "Did the monthly access re-check find anyone? Channel onboarding shows \"Monthly access recertification: \u2026\".", "Why did a Microsoft 365 action fail? Filter the m365 channel to Warning or Error.", "Is a webhook failing? Look at the webhook channel, then Logs & Integrations \u2192 Integrations \u2192 \"Delivery log\"."]}, {"tip": "Only 100 events are shown at a time. Use the level, channel and search filters to find older ones."}]}, {"title": "Sent emails", "for": "admin", "mod": "event_log", "body": [{"p": "Logs & Integrations \u2192 Sent emails lists every email the app tried to send: when (in the installation's time zone), to whom, the subject, which email it was (for example \"Backup alert\" or \"Reply on a ticket\"), whether it went out \u2014 with the error when it did not \u2014 the linked ticket and who sent it (or \"the app\" for automatic emails)."}, {"bullets": ["Search an address or a subject; filter to sent or failed, to one kind of email, or to a period. The tiles count today, this month, failures in the last 7 days and everything kept.", "\"Export CSV\u2026\" shows the filtered list first (up to 10,000 rows); download it from the preview. The preview and the download are written to the Audit Log.", "The text of the emails is not kept on purpose: some carry a temporary password or a sign-in link.", "How long the list is kept is set in Settings \u2192 Maintenance \u2192 Housekeeping (Outbound email log)."]}, {"p": "Permission: Event Log (view)."}]}, {"title": "KB Content Gaps", "for": "admin", "mod": "kb_gaps", "body": [{"p": "KB Content Gaps is your Knowledge Base to-do list: the questions people asked Ask IT that your articles couldn't answer, most-asked first."}, {"p": "Where it lives: Knowledge \u2192 KB Content Gaps. View lets you see the list; Edit lets you mark gaps covered or delete them. The Manager and IT Administrator presets include both."}, {"h": "Working through the gaps"}, {"steps": ["Open Knowledge \u2192 KB Content Gaps and scroll to \"Content gaps\".", "Each row shows the question, how many times it was asked, when it was last asked, and whether the assistant answered from general guidance or had no answer.", "Write and publish a Knowledge Base article that answers the question.", "Click \"Mark covered\". If someone asks the same question again later, it comes back on the list.", "Click \"Delete\" for questions that don't need an article (tests, typos, off-topic)."]}, {"h": "Other cards on this page"}, {"bullets": ["\"Assistant knowledge sources\" (Super Admin only): tick \"Allow general/official guidance when the KB has no answer\" and list trusted websites. The assistant always tries your published articles first and only contacts the sites you list. Click \"Save sources\".", "\"Starter content\": \"Seed starter articles\" adds a set of plain-language Microsoft 365, security and template articles as drafts. Nothing is published until you review it. Articles that already exist are skipped. Needs Knowledge Base with Edit.", "\"Help-portal performance\": how many tickets self-service articles prevented, the articles that prevented the most, and the ones readers found least helpful."]}, {"tip": "Ask IT needs AI assist to be set up (Settings \u2192 Integrations \u2192 \"AI assist\"). With no key saved, no questions are answered and no gaps are collected."}, {"qa": [{"q": "The list is empty.", "a": "Gaps only appear once people use Ask IT and it can't answer from the Knowledge Base."}]}]}, {"title": "What's New (release notes)", "for": "everyone", "mod": "changelog", "body": [{"p": "What's New shows the release notes for the ITOps build installed on your server, so you can see what changed and whether an update needs extra steps."}, {"p": "Where it lives: Logs & Integrations \u2192 What's New. You need What's New with View. Every preset includes it. In a role built with the permission grid, it must be ticked."}, {"h": "Reading it"}, {"bullets": ["It reads the CHANGELOG.txt file in the ITOps folder live. The builds are listed on the left, newest first; click one to read its notes on the right. A \"DB UPDATE\" tag marks a build that needs the database update.", "Each entry starts with a build ID, such as 0621-BT6. It matches the version under Settings \u2192 General \u2192 About \u2192 Version.", "The tag after the title tells admins what to do. \"[DB UPDATE REQUIRED]\" means run the database update. Some entries also say a new vTiger bridge file must be uploaded.", "Entries list security fixes, new features and changed behaviour in plain words.", "The search box looks in every build: the list keeps the builds that mention the words, and the words are highlighted in the notes."]}, {"tip": "After an update, compare the top entry here with Settings \u2192 General \u2192 About \u2192 Version. If they don't match, hard-refresh the browser (Ctrl+Shift+R or Cmd+Shift+R)."}, {"qa": [{"q": "It says \"Couldn't load the changelog\".", "a": "CHANGELOG.txt is missing from the ITOps folder (the folder that holds index.html). Upload it from the install zip."}, {"q": "I don't see What's New in the menu.", "a": "Ask a Super Admin to tick What's New: View on your role."}]}]}, {"title": "Help visuals: who sees the interactive pages", "for": "admin", "mod": "help_visuals", "body": [{"p": "Administration \u2192 Settings \u2192 \"Help visuals\" (Super Admin only) decides who sees each interactive page of the Help Center. Nobody sees a page until it is given; a Super Admin always sees every page."}, {"steps": ["Open Administration \u2192 Settings \u2192 \"Help visuals\". There is one card per page.", "Under \"Roles\", tick the roles that may see it. Everybody with that role sees it, also people given the role later.", "Under \"People\", type a name or an email and pick the person. That person sees it whatever their role. \u2715 takes a person off.", "Click \"Save\". \"Not saved\" shows until you do; \"Undo\" goes back to what was saved."]}, {"bullets": ["The line \"Seen by\" says who sees the page now.", "\"Open it in the Help Center\" shows the page as the others will see it.", "Every change is written to the Audit Log (action help_visual_access) with the roles and the people before and after, and who changed it. An attempt by someone who is not a Super Admin is refused and written there too (help_visual_access_refused).", "A person who is no longer active keeps no access; a role that is deleted gives none.", "Opening a page needs signing in. The page is sent only to people it was given to, and it runs in a closed frame that cannot reach the person\u2019s session.", "\"Who sees them\u2026\" in the Help panel of the app closes the panel and opens this page in the app."]}, {"qa": [{"q": "Why can I not give it to \"Super Admin\"?", "a": "A Super Admin always sees every page, so the role is not in the list."}, {"q": "Where do the pages come from?", "a": "They are part of the installation (the install zip). A new build can add pages or bring them up to date; who sees them is kept."}]}]}, {"title": "Modules and plans: what this installation includes", "for": "admin", "mod": "license", "body": [{"p": "ITOps is built from modules: Service Desk, Cases & Projects, Knowledge Base, Microsoft 365, Servers, Equipment and so on. Administration \u2192 Settings \u2192 \"Modules\" lists every module, what it covers, whether this installation's license includes it, and whether it is on. Super Admins and the roles with \"License details\" see the page; only a Super Admin changes it."}, {"h": "Where the list comes from"}, {"bullets": ["The license decides which modules are included. The license record names a plan (Complete, Service Desk, Microsoft 365 Admin or IT Operations) and may add modules one by one.", "An installation without a license record, or with a record that names no plan, includes every module.", "A Super Admin can switch an included module off, and on again. A module the license does not include cannot be switched on in the app.", "Some modules need another one: Cases & Projects needs Service Desk, Onboarding & offboarding needs Microsoft 365. Switching the needed one off switches the other off too; the page says so before you save."]}, {"h": "Switching a module off"}, {"steps": ["Open Administration \u2192 Settings \u2192 \"Modules\".", "Untick the module. The page shows which other modules go off with it.", "Click \"Save\". The change is written to the Audit Log (\"modules_changed\") with the names of the modules."]}, {"h": "What happens while a module is off"}, {"bullets": ["Its pages leave the menu, and its permissions are refused for everyone, Super Admin included. The Roles page marks them \"MODULE OFF\"; what a role was given is kept.", "The scheduled jobs skip its work and say so in Logs \u2192 Scheduled jobs (\"Skipped: \u2026 is not part of this installation\"). Examples: no SLA alerts without Service Desk, no uptime or backup checks without Servers, no renewal reminders without Contracts & Vendors.", "The emails it would send are not sent, and they leave Settings \u2192 Email templates (their wording is kept).", "Bell and Teams notifications that open it are not shown.", "Its Help Center topics, dashboard tiles and search results are left out.", "Nothing is deleted. Switching the module on again brings back its data, its settings and its notifications."]}]}]}, {"cat": "Microsoft 365: onboarding & offboarding", "topics": [{"title": "Onboarding & offboarding: how it works", "for": "admin", "mod": ["m365", "onboarding"], "body": [{"p": "Joiners and leavers are handled in Microsoft 365 \u2192 People: \"Onboard\" creates the person in Microsoft 365 and vTiger in one go (optionally from a template), \"Offboard\" runs one guided departure, and \"History\" keeps a record of every one of them."}, {"bullets": ["Templates live in Administration \u2192 Onboarding Templates. A template pre-fills Microsoft fields, picks the licenses and groups, and says whether to create the vTiger user (with its role and status).", "Onboarding: the account is created, then the template groups are added, then the vTiger user is created with the same username, email and temporary password. The result and anything that failed are saved in History.", "Offboarding: vTiger records are reassigned first (while the user is still active), then Microsoft 365 is closed down, then the vTiger user is deactivated. ITOps adds the auto-reply, mail forwarding, OneDrive handover, equipment check-in and \"schedule for their last day\".", "History shows the records you started and those of your department; a Super Admin and roles with Onboarding \u00b7 All records see every one. A step changes only while its process is in progress; a done step stays done, a required step is not skipped, and only a process in progress can be cancelled.", "History lists every process (including ones from earlier builds) with each step's result, the access check and the metrics panel.", "Every change is written to the Audit Log. Passwords are never stored."]}, {"p": "Upgrading converted the old onboarding templates: their Microsoft 365 account, license, group and vTiger steps became the new template fields. Checklist-only steps (equipment, reading and signature, welcome email, manual tasks) were dropped \u2014 processes already started keep all their steps in History."}]}, {"title": "Onboarding templates (Microsoft 365 + vTiger defaults)", "for": "admin", "mod": "onboarding", "body": [{"p": "Administration \u2192 Onboarding Templates bundles the defaults for one kind of new hire, for example \"Sales Rep\". Picking it on the Onboard screen fills the form; everything stays editable."}, {"steps": ["The templates are listed on the left; the one you work on opens on the right, beside the list. On a wide screen the first template is already open. Click a template (or its \"Edit\") to open it, or \"New template\" for a new one.", "Enter the \"Template name\" and an optional \"Description\".", "Under \"Microsoft 365 \u00b7 the person\u2019s details\": the \"Usage location\" (two letters, required for licensing) and an optional \"Default manager\" (type a name).", "\"Field defaults\": job title, department, company, office, phones and employee ID are always there; add more with \"Add a Microsoft field\u2026\" (employee type, address, city, state, postal code, country, fax, preferred language). Empty fields are not saved.", "\"Custom fields\": your organization's own fields (an extension, a cost center) are always listed here, without adding them; a field with choices is a dropdown. Type a value when it is the same for everyone of this kind. Leave it empty when it differs per person: it is still on the Onboard screen to fill in.", "Click \"+ Licenses\" to open the list and tick; click \"+ Groups\" to search for groups to add. Folded, each heading says how many are chosen and names them.", "\"Default password\" (optional): the first password every new person of this kind starts with. See \"A default password\" below.", "Under \"vTiger defaults\": \"Create a vTiger user by default\u2026\", the vTiger \"Role\" and \"Status\".", "Click \"Save template\". The template stays open beside the list."]}, {"h": "Working on several templates"}, {"bullets": ["Click another template in the list to open it. If the one you were on has changes that are not saved (\"Not saved\" shows next to the title), ITOps asks first: \"Leave without saving\" or \"Keep editing\".", "\"\u2715 Close\" (or \"Cancel\") closes the template, asking first the same way.", "On a wide screen the template is laid out in two columns: the person\u2019s details on the left; licenses, groups, the first password, other company systems and vTiger on the right.", "On a narrow screen or a phone the template takes the whole width; \"\u2190 Templates\" goes back to the list."]}, {"h": "A default password"}, {"bullets": ["When the template is picked on the Onboard screen, \"Use the default password of the template\" is the choice. The person creating the account can still choose \"Generate a strong temporary password\" or \"Type another password\" for that one account.", "It needs at least 8 characters and three of these four: a lower-case letter, a capital letter, a digit, a symbol. Microsoft 365 refuses anything weaker.", "It is stored encrypted. It is never shown on the template again and never sent back to a browser: an open template shows \"saved \u00b7 leave empty to keep it\". Type a new one to replace it. \"Remove the saved password\" takes it off when you save.", "An account created with it must always change it at first sign-in, because several people start with the same one. That tick cannot be taken off.", "It is shown once, in the result after the account is created, so you can give it to the person.", "The Audit Log records who set, replaced or removed a default password, on which template and when. It never holds the password."]}, {"p": "\"Other company systems\" lists the systems switched on under Administration \u2192 Settings \u2192 Company systems. Tick the ones a person of this kind needs: they are pre-ticked on the Onboard screen and each becomes a step done by hand in that system. See \"Company systems in onboarding and offboarding\".", "mod": ["onboarding"]}, {"p": "The list shows each template's licenses, groups, location and vTiger role, and \"default password set\" when it has one. \"Delete\" asks first; it cannot be undone. The \"vTiger provisioning\" tab on the same page is where the vTiger connection is set up."}, {"qa": [{"q": "The template says \"Usage location must be a 2-letter country code.\"", "a": "Use the two-letter code (US, PR, MX\u2026) or leave it empty."}, {"q": "No vTiger roles in the list.", "a": "Roles are read from vTiger through the bridge. The bridge isn't set up or can't be reached \u2014 the message under the list says why. Open the \"vTiger provisioning\" tab and click \"Test bridge\"."}, {"q": "Under \"Custom fields\" it says \"None yet\".", "a": "No custom field has a name yet. Name the ones you use with the \"Custom fields\" button next to \"New template\". Once named, they are listed on every template and on the Onboard screen."}, {"q": "A custom field I used to see is gone from the template.", "a": "It was switched off or removed under \"Custom fields\". A template keeps values only for fields that are in use."}, {"q": "\"The default password needs at least 8 characters and three of these four\u2026\"", "a": "The password is too short or too simple for Microsoft 365. Nothing was saved; the page stays open so you can type another."}, {"q": "\"This installation cannot store secrets\".", "a": "The default password is kept encrypted with the VAULT_ENCRYPTION_KEY in config.php, the same key that protects the Vault. It is missing or not valid. The template was not saved; save it without a default password, or have the key set first."}, {"q": "I forgot what the default password is.", "a": "It cannot be shown again. Type a new one on the template and save."}]}]}, {"title": "Onboarding a new hire (the Onboard tab)", "for": "admin", "mod": "m365_users:edit", "body": [{"steps": ["Go to Microsoft 365 \u2192 People \u2192 \"Onboard\".", "Pick a \"Template\" (optional). It fills job title, department, location, manager, more details, licenses, groups and the vTiger settings.", "Type the \"First name\" and \"Last name\". \"Display name\" and \"Username\" fill themselves (first.last); change them if needed. Pick the \"Domain\" \u2014 \"Sign-in:\" shows the full address.", "Check job title, department, \"Manager\" and \"Usage location\". Open \"+ More details\" for phones, company, employee ID, address, language and your organization's custom fields (an extension, for example). A template opens it by itself when it fills any of them.", "Click \"+ Licenses\" and tick the licenses (each shows the seats left). Folded, the heading says how many are selected and names them. The groups of a template are under \"+ Groups from the template\".", "Tick \"Also create a vTiger user\" and pick its role and status if they need vTiger.", "Under \"First password\" choose one: \"Use the default password of the template\" (offered, and already chosen, when the template has one), \"Generate a strong temporary password\", or \"Type another password\". Leave \"Require change at first sign-in\" ticked; for a template's default it is always on.", "Click \"Create account\"."]}, {"p": "The result shows the new account, the password (the temporary one to copy now, or \"The template's default password \u2014 give it to the person\"), any warnings (for example \"License not assigned\"), the vTiger user that was created and each template group (\u2713 or \u2715). \"Onboard another\" clears the form; \"See History\" opens the record."}, {"bullets": ["The vTiger user gets the same username, the Microsoft 365 address as email and the same first password.", "Groups need \"Microsoft 365 \u00b7 Groups\" and the vTiger user needs \"Provisioning \u00b7 Onboard to vTiger\"; without them those parts show \u2715 with the reason, and the account is still created.", "New accounts take a few seconds to appear everywhere in Microsoft; ITOps waits and retries the manager, license and group steps for you.", "Other company systems (phone, fax, forms, CRM\u2026): tick them under \"Other company systems\". After the account is created each one shows a box to answer once the account is set up there. See \"Company systems in onboarding and offboarding\"."]}, {"tip": "On a wide screen (1500 pixels and more) the Onboard form is in two columns: the person on the left (names, sign-in name, job, manager, usage location, more details); licenses, groups, the vTiger user, other company systems and the first password on the right. \"Create account\" is under both."}, {"p": "The new account is on Microsoft 365 \u2192 People at once, without reloading the page. Microsoft's own list of accounts can take a little while to include a new one; until it does, the account is shown marked \"new\", and the list is read again from Microsoft every 20 seconds until the mark goes."}]}, {"title": "Temporary passwords (shown once)", "for": "admin", "mod": ["m365", "onboarding"], "body": [{"p": "When ITOps creates an account or resets a password, it shows the temporary password once, with a \"Copy\" button, so you can hand it over."}, {"p": "A generated temporary password has 16 characters with upper and lower case letters, digits and symbols. A password typed for a new vTiger user needs at least 12 characters with letters and digits. ITOps sends a new vTiger password only when the bridge address is https://."}, {"bullets": ["Onboard: in the result, under \"Temporary password \u2014 copy it now, it won't be shown again\". The same password is used for the vTiger user. When the template's default password was used, the box reads \"The template's default password \u2014 give it to the person\"; it must be changed at first sign-in.", "Accounts \u2192 \"Reset password\": in the person's panel, right after \"Generate & reset\". It stays there while you keep working on that person.", "Temporary access pass: shown once in the person's panel."]}, {"warn": "ITOps never stores a temporary password. If one is lost, reset the password again (Microsoft 365 \u2192 People \u2192 the person \u2192 \"Reset password\"). The only first password ITOps keeps is the default password of an onboarding template: encrypted, and never shown on the template again."}]}, {"title": "Offboarding a leaver (the Offboard tab)", "for": "admin", "mod": "m365_users:edit", "body": [{"steps": ["Go to Microsoft 365 \u2192 People \u2192 \"Offboard\" and type the person's name in \"Who is leaving?\". The card shows their status, licenses, groups and vTiger link.", "Microsoft 365: sign-in is always blocked; choose \"Revoke active sessions\", \"Remove all licenses\" and \"Remove from all groups\".", "Mailbox & files (ITOps): an auto-reply, forwarding new email to a colleague, and sharing their OneDrive with a colleague.", "vTiger: \"Reassign vTiger records first\" \u2014 pick who receives them and all or some modules \u2014 and \"Deactivate the vTiger user\".", "Equipment: add a check-in step for each item still on loan.", "When: \"Run now\", or \"Schedule for their last day\" with a date and time.", "Click \"Run offboarding\" (or \"Schedule offboarding\")."]}, {"p": "The steps run in a safe order and appear one by one with \u2713 or \u2717. Then click \"Verify offboarding\" to re-read Microsoft 365, vTiger and Equipment. \"Open in History\" shows the saved record."}, {"bullets": ["A scheduled run waits in History and runs by itself at that time (it needs the scheduled job, or someone having ITOps open).", "Equipment is checked in by hand, with its condition, when it comes back (History, or Assets \u2192 Equipment).", "You can also do a quick offboard from the person's panel in Accounts (\"Offboard\u2026\").", "Other company systems (phone, fax, forms, CRM\u2026) are listed under \"Other company systems\" with the accounts recorded for the person. Each ticked one becomes a step you do by hand in that system and answer on the screen. For a connected system (JustCall) the step is done when that system no longer lists the person. See \"Company systems in onboarding and offboarding\"."]}, {"warn": "The vTiger parts need \"Provisioning \u00b7 Offboard from vTiger\". Without it the screen says the vTiger steps are skipped \u2014 deactivate them in vTiger separately."}]}, {"title": "Company systems in onboarding and offboarding (phone, fax, forms, CRM\u2026)", "for": "admin", "mod": ["m365_users:edit", "onboarding", "access"], "body": [{"p": "A person has accounts outside Microsoft 365 and vTiger: a phone number in JustCall, a fax login, a seat in HubSpot, a place in the Jotform team, an extension, a door badge. Once a system is switched on under Administration \u2192 Settings \u2192 Company systems \u2192 \"Systems\", every onboarding and offboarding has a step for it."}, {"p": "A system is either tracked by hand or connected. Tracked by hand: ITOps does not sign in to it. It shows what to do there, with a link, keeps your answer on the person's record, and remembers which account the person has, so offboarding can name exactly what to remove. Connected (JustCall can be): ITOps reads the system, and the step is done when the system itself shows it. The steps below describe a system tracked by hand; for a connected one see \"JustCall connected: reading its users instead of typing them\"."}, {"h": "At offboarding"}, {"steps": ["On Microsoft 365 \u2192 People \u2192 \"Offboard\", pick the person. Under \"Other company systems\" each system is listed with the accounts recorded for the person, or \"(no account recorded)\". A system is ticked when an account is recorded, or when it is set to ask at every offboarding.", "Run the offboarding. The Microsoft 365 and vTiger steps run by themselves. Each ticked system then shows a box: your instructions, \"Open \u2026 \u2197\" (a new tab) and the accounts by name.", "Do the work in that system, then answer: \"Removed there\", \"Handed over to a colleague\u2026\" (a number or an extension that stays in use: type the colleague's work email) or \"Checked: no account there\". A note is optional.", "The line turns into the record of what was done. The recorded account is closed (or moved to the colleague)."]}, {"bullets": ["You can answer later: the boxes are also on the record in History, on the step itself. The offboarding stays \"in progress\" until every system is answered.", "\"Mark done\" is not offered on these steps: the step asks what was done, so an account is never left open in the records by a tick.", "A scheduled offboarding runs the Microsoft 365 and vTiger steps at the set time and leaves the system steps for a person.", "\"Verify offboarding\" has a line per system, \"Account removed (recorded by hand)\": \u2717 while an account is still recorded as open or the step is unanswered, \u2713 with your answer once it is. Recorded by hand means ITOps reports what was answered, not what it read in that system."]}, {"h": "At onboarding"}, {"steps": ["On \"Onboard\", tick the systems the new person needs under \"Other company systems\". An onboarding template can tick them for you.", "After the account is created, the result shows \"Other company systems to set up\" with a box per system: your instructions and the link.", "Set the account up in that system, optionally type its name (the extension, the user name), and click \"The account is set up\". Or \"Not needed for this person\".", "The account is recorded for the person. Until every box is answered the onboarding stays open in History, where the same boxes are."]}, {"qa": [{"q": "The section \"Other company systems\" is not on the screen.", "a": "No system is switched on, or none is set to take part in onboarding (or offboarding). A Super Admin, or a role with Integrations \u00b7 Edit, sets that under Administration \u2192 Settings \u2192 Company systems \u2192 \"Systems\"."}, {"q": "No account is recorded for the person, but the system is ticked.", "a": "That system is set to ask at every offboarding. Look in the system anyway and answer \"Removed there\" or \"Checked: no account there\". An account nobody recorded is the one that gets forgotten."}, {"q": "\"Handed over to a colleague\u2026\" is not offered.", "a": "It appears when an account is recorded for the person: there has to be something to hand over. Record the account first, or answer \"Removed there\"."}, {"q": "I answered wrongly.", "a": "Open the person under Microsoft 365 \u2192 People. In the block \"Systems\" choose \"+ Show closed accounts\" and \"Open again\", or record the account anew with \"+ Record an account\". Someone who has no Microsoft 365 account any more is opened from Microsoft 365 \u2192 People \u2192 \"Needs attention\". The Audit Log keeps both the answer and the correction."}, {"q": "Will ITOps do these steps by itself later?", "a": "JustCall can be connected now: ITOps reads who has a user there, and the step is done when JustCall shows it (the user is still added and removed by hand in JustCall, because its API cannot do that). For HubSpot, eFax, Jotform and the phone system a direct connection is planned."}]}]}, {"title": "Offboarding in vTiger: reassign, then deactivate", "for": "admin", "mod": ["m365", "onboarding"], "body": [{"p": "Before a leaver's vTiger user is switched off, move the records they own to a colleague so nothing is left with an inactive owner. The Offboard tab does it first; older processes in History still have their own reassign and deactivate steps."}, {"steps": ["In Offboard, tick \"Reassign vTiger records first\". ITOps shows how many live records they own.", "Choose who receives them (active vTiger users only) and \"All modules\" or tick the modules.", "Leave \"Deactivate the vTiger user\" ticked and run the offboarding.", "From a person's panel in Accounts (\"Offboard\u2026\" \u2192 \"Reassign this user's vTiger records first\") you can move them on their own with \"Reassign N record(s)\"."]}, {"p": "Deactivation is blocked while the person still owns records. ITOps shows how many and asks for a reason. If you type a reason, the user is deactivated anyway and the reason is saved in the Audit Log. Users are deactivated, never deleted, so vTiger history stays intact."}, {"bullets": ["ITOps looks for the vTiger user by the person's email first. If no vTiger user has it, it looks for a vTiger user whose user name is the part of the sign-in name before the \"@\" (jdoe@example.org \u2192 \"jdoe\"). When it finds the user that way, the screen and the result say \"matched by vTiger user name\" and show the email on the vTiger record, and the \"Deactivate the vTiger user\" box starts unticked.", "If neither finds anyone, ITOps says so and the steps finish with nothing to do.", "You cannot deactivate your own vTiger account from here."]}, {"h": "Leaving the records for later"}, {"p": "Sometimes the records should not go to one person yet (for example, Sales will split them by region). On the \"Reassign vTiger records\" step in History, click \"Leave them with \u2026 for now\u2026\", say why and who will move them, and click \"Leave the records for now\"."}, {"bullets": ["The step finishes as \"Left for later\" with the number of records and your reason (also in the Audit Log as ob_vtiger_records_left). Nothing changes in vTiger.", "Deactivating the vTiger user then does not ask for a reason again: the user is inactive and keeps the records. They stay in vTiger, visible to admins and to the people your vTiger sharing rules allow.", "Move them later by hand: in vTiger (select the records in a list, mass edit \"Assigned To\"), or with \"Reassign vTiger records\" on the person's panel in Microsoft 365 \u2192 People.", "Every day ITOps checks whether the records were moved. Once none are left, the step says \"moved\" (ob_vtiger_records_moved). Until then, the process shows \"vTiger: N record(s) not moved\" in History (tick \"Only vTiger records not moved yet\" to list just those), and the person who started the process gets a reminder every 14 days (setting vtiger_left_remind_days, 0 = no reminders).", "Moving records keeps working as before: one update per batch plus vTiger's change history, without running vTiger workflows, so the new owner does not get one email per record."]}, {"h": "Who can do it, and the new owner"}, {"bullets": ["These steps need Provisioning \u00b7 Offboard from vTiger (creating the vTiger user at onboarding needs Provisioning \u00b7 Onboard to vTiger). Onboarding \u00b7 Edit alone works the other steps only.", "When the person leaving is a vTiger admin, only a Super Admin moves their records or deactivates them.", "The new owner is fixed on the step: the one chosen in the Offboard tab or in the template, or the first one chosen on the record in History. The list on the step shows it and cannot be changed; a retry or a scheduled run uses the same owner. A Super Admin can change it (written to the Audit Log).", "Records move in rounds; when there are many, the step says how many are left: click Run again to continue. Each moved record has \"Assigned To\" in its vTiger history (bridge build o8)."]}, {"h": "When the vTiger user was found by user name"}, {"p": "A match by user name is a hint, not proof: a person on another domain can have the same user name. So ITOps shows that vTiger user but never deactivates it, or moves its records, by itself. A person has to say it is the same person, once, for that departure:"}, {"bullets": ["In Offboard: ticking \"Deactivate the vTiger user\" or \"Reassign vTiger records first\" for the user shown is that confirmation. The run then goes through without asking again.", "In History, on a record: \"Run\" on a vTiger step asks \"Same person?\" and names the vTiger user, the email on its record and its status. \"Yes, the same person\" runs the step; cancelling leaves everything as it was. \"Reassign vTiger records\" has a box to tick instead: \"I checked: this vTiger user is \u2026\".", "If a run stops in the Offboard tab with \"Deactivate vTiger user stopped: Not run\", answer there: \"Yes, the same person: continue\" or \"Not sure or not the same: skip this step\".", "A scheduled offboarding never answers for you: the vTiger step is left undone, the summary says why, and you confirm it on the record in History."]}, {"p": "Both answers are written to the Audit Log with your name, the person, the vTiger user, the email on its record and how it was found: \"offboarding_vtiger_confirmed\" when you confirm, \"offboarding_vtiger_refused\" each time a step was held back. A vTiger user found by email needs none of this and works as before."}, {"tip": "If it is not the same person, there is nothing to do in vTiger for this departure: skip the step. \"Verify offboarding\" will keep saying that a vTiger user with the same user name is still active and may be somebody else, so you know it was looked at."}, {"tip": "These steps need the vTiger bridge (build o5 or later; o8 recommended) on the vTiger server. \"The vTiger bridge on the server is an older build (o4)\" means the file there was never replaced: upload vtiger-bridge/itops-bridge.php from the install package to the vTiger web root (next to config.inc.php), keeping the same secret. See \"Connecting vTiger provisioning\"."}]}, {"title": "Equipment check-in and the older Exchange steps", "for": "admin", "mod": ["m365", "onboarding"], "body": [{"p": "Two jobs are finished by hand: getting equipment back, and the Exchange mailbox changes that older offboarding templates included. Both are done on the record in Microsoft 365 \u2192 People \u2192 History."}, {"h": "Equipment return"}, {"steps": ["On the offboarding, find the \"Return <tag>\" step for each item on loan.", "Choose the condition (good, new, fair, poor, damaged).", "Choose where it goes: \"Back to: available\", \"Back to: maintenance\" or \"Not returned \u2014 mark lost\". Add a note if useful.", "Click \"Check in\". The loan is closed and the item's status is updated. An item checked in as \"damaged\" goes to maintenance unless you mark it lost."]}, {"bullets": ["If items were loaned after the process started, a banner lists them. Click \"Add return steps\".", "Checking in needs Equipment & Assets (edit)."]}, {"h": "Exchange steps"}, {"steps": ["On the Exchange step, read which action it is (shared mailbox, hide from address book, litigation hold, or remove mobile devices).", "Click \"Copy commands\". The person's address is already filled in.", "Run the commands in PowerShell with the ExchangeOnlineManagement module. Replace admin@yourdomain.com in the first line with your admin account.", "Click \"Mark done\"."]}, {"tip": "The shared-mailbox commands include an optional line (starting with #) that gives the manager full access. Put in the manager's address and remove the # to use it."}]}, {"title": "When a step stops: Continue anyway, Skip or finish it in History", "for": "admin", "mod": ["m365", "onboarding"], "body": [{"bullets": ["A failed step shows \u2717 and the reason; the rest of the run continues.", "If the vTiger user still owns records, deactivation stops and asks for a reason: type it and click \"Continue anyway\" (it is saved in the Audit Log), or \"Skip this step\".", "Open the record in Microsoft 365 \u2192 People \u2192 History to \"Retry\" a failed step, \"Mark done\" work you did another way, or \"Skip\" an optional one.", "In Onboard, a failed group or vTiger part shows \u2715 with the reason; add the group in Accounts or create the vTiger user in vTiger, then note it."]}, {"warn": "\"Mark done\" changes nothing in Microsoft 365 or vTiger. Use it only when the work is really done."}]}, {"title": "Verify offboarding and the monthly access re-check", "for": "admin", "mod": ["m365", "onboarding"], "body": [{"p": "The \"Access verification\" card on every offboarding proves that the leaver's access is really gone. It re-reads each system instead of trusting the step results."}, {"steps": ["In Offboard, click \"Verify offboarding\" after the run (or \"Re-check\").", "In History, open the offboarding \u2014 the card runs by itself when it completes; click \"Verify offboarding\" to check again.", "Read each line: \u2713 passed, \u2715 failed, \u2013 not checked."]}, {"bullets": ["Microsoft 365 \u00b7 Sign-in blocked, and Licenses removed (a deleted account passes both).", "vTiger \u00b7 User deactivated, and Records reassigned (no records still owned).", "ITOps \u00b7 Equipment returned (nothing still on loan).", "Each company system in use \u00b7 Account removed (recorded by hand): \u2717 while an account is still recorded as open for the person or the step is unanswered; \u2713 with the answer that was given. ITOps reports what was recorded, not what it read in that system.", "A connected system (JustCall) \u00b7 Account removed (read from JustCall): the system is asked at that moment. \u2717 when it still lists a user for the person or cannot be read; \u2713 with the time of the reading."]}, {"p": "The card border is green for \"Clean\", red for \"Issues found\" and amber for \"Nothing could be checked\". The Onboarding list shows \"\u2713 verified\" or \"\u2715 access remains\". Every result is saved in the Audit Log as evidence."}, {"h": "What \"unchecked\" means"}, {"p": "\"Nothing could be checked (no connected system / no accounts found)\" means no check passed or failed. Usually Microsoft 365 or the vTiger bridge is not connected, or the person never had an account there. It is not a failure, but it is not proof either."}, {"h": "Monthly access re-check"}, {"bullets": ["\"Re-check all offboardings\" on the Onboarding page re-verifies every completed offboarding now (up to the latest 300). Nothing is changed.", "The same check runs once a month through the scheduled job. If anyone still has access, Super Admins, Admins and Department Admins get an in-app alert and the email \"Access re-check found a problem\"."]}, {"tip": "A \u2715 after completion usually means someone re-enabled the account or re-added a license. Fix it in that system, then click \"Re-check\"."}, {"p": "When the vTiger user was only found by user name and nobody confirmed it is the same person, a result \"is still Active\" adds \"It may be somebody else with the same user name\". If it is the person who left, run \"Deactivate vTiger user\" on the record and confirm; if it is somebody else, nothing needs to be done in vTiger."}]}, {"title": "Offboarding summary and access re-check emails", "for": "admin", "mod": ["m365", "onboarding"], "body": [{"p": "ITOps sends a few emails during onboarding and offboarding. You can change their wording under Settings \u2192 Email templates."}, {"p": "Templates no longer send a welcome email or reading to sign \u2014 hand the new hire their sign-in details with the temporary password. Processes started before the upgrade still send theirs."}, {"bullets": ["\"Welcome \u2014 first-day information\": sent by the \"Send welcome email\" step to the new mailbox, or to the address set on the step (e.g. a personal email). It includes the start date, sign-in address, job title, manager and the extra text from the step. It never includes the password.", "\"Onboarding document to sign\": one email per document from an \"Assign reading + signature\" step, with a private signing link.", "\"Offboarding summary\": sent to whoever started the offboarding, whoever scheduled it, and the manager, when it completes or after a scheduled run. It lists every step and the access-check result.", "\"Access re-check found a problem\": sent to Super Admins, Admins and Department Admins when the monthly re-check finds remaining access."]}, {"tip": "The manager only gets the summary if the process has a manager email. For offboarding there is no manager field on the start form, so the summary goes to you (and the scheduler) only."}, {"p": "Each email goes out in English or Spanish: the recipient's own ITOps language if they have an account, otherwise the default language. Editing the wording needs Settings (edit)."}]}, {"title": "Troubleshooting onboarding and offboarding", "for": "admin", "mod": ["m365", "onboarding"], "body": [{"p": "Real messages from Onboard, Offboard and History, and what to do about each."}, {"qa": [{"q": "\"License not assigned: License assignment cannot be done for user with invalid usage location.\"", "a": "Microsoft licenses only an account that has a usage location (the two-letter country, for example US). Since build 0621-BT52 the location on the Onboard form is sent with the new account, and ITOps retries for a few seconds if Microsoft has not caught up yet; a license with no location is refused before anything is created. For an account created earlier without one: Accounts \u2192 open the account \u2192 set \"Usage location\" \u2192 assign the license."}, {"q": "\"The Azure app is missing the \"User.ReadWrite.All\" Application permission\u2026\" (or another permission)", "a": "In Azure \u2192 App registrations \u2192 your ITOps app \u2192 API permissions, add that Application permission and click \"Grant admin consent\". Then, as a Super Admin, go to Microsoft 365 \u2192 Home \u2192 Diagnose \u2192 \"Refresh token & re-test\" and run the pre-flight again."}, {"q": "\"Graph write access denied (HTTP 403)\u2026\"", "a": "Same cause: the Azure app lacks the write permission for that step. See \"What Microsoft 365 permissions ITOps needs\"."}, {"q": "\"\u2026 NO seats available. Buy or free a license first.\" or \"NOT assigned \u2014 no seats left\"", "a": "All seats of that license are used. Remove the license from a former employee or buy more, then \"Retry\". Microsoft 365 \u2192 Licenses \u2192 Licenses shows seats per license."}, {"q": "\"Microsoft 365 is not connected\" or \"Microsoft 365 is not configured\"", "a": "A Super Admin must enter the Tenant ID, Client ID and Client secret under Settings \u2192 Company systems \u2192 Microsoft 365 (Set up\u2026)."}, {"q": "\"vTiger bridge: Could not reach bridge\u2026\" or \"The vTiger bridge is not configured\"", "a": "Check the Bridge URL under Settings \u2192 Company systems \u2192 vTiger (Set up\u2026) and click \"Test bridge\". The vTiger site must be reachable from the ITOps server."}, {"q": "\"Bad signature.\", \"Bridge secret not set\" or \"Stale request (check server clocks)\"", "a": "The secret in ITOps and on the vTiger server don't match, the itops-bridge.secret file is missing, or the two servers' clocks differ by more than 5 minutes. Fix it, then \"Test bridge\"."}, {"q": "\"The vTiger bridge is build \u2026 \u2014 upload itops-bridge.php build o5.\"", "a": "Upload the itops-bridge.php from the install package to the vTiger web root. The secret stays the same."}, {"q": "\"\u2026 still owns N record(s)\u2026 Run \"Reassign vTiger records\" first\"", "a": "Run \"vTiger: reassign records\" first, or type a reason when asked to deactivate anyway."}, {"q": "\"You do not have permission for this (m365_users)\" (or m365_credentials, m365_licenses, m365_groups, m365_roles, provision_offboard\u2026)", "a": "Your role lacks that Microsoft 365 permission. See \"Microsoft 365 permissions: who can do what\"."}, {"q": "\"Usage location must be a 2-letter country code.\"", "a": "Fix it in the template (or the Onboard form) \u2014 two letters such as US."}, {"q": "\"A vTiger user with that email already exists.\"", "a": "The person is already in vTiger. ITOps links it by email; no second user is made."}, {"q": "\"Pick a target user for reassignment.\" or \"Source and target users are the same.\"", "a": "Choose a different active vTiger user to receive the records."}, {"q": "\"You cannot offboard your own account.\" / \"You can't remove roles from your own account.\"", "a": "Lock-out protection: ask another administrator."}, {"q": "\"Not run. No vTiger user has this person's email. The vTiger user \u2026 was found by user name only\"", "a": "ITOps found a vTiger user with the person's user name but another email, and will not deactivate it or move its records until someone confirms it is the same person. Look at the user it names. If it is the same person, answer \"Yes, the same person\" (Offboard tab), or click \"Run\" on the step in History and confirm. If it is somebody else, skip the step. Either answer is in the Audit Log."}, {"q": "\"The vTiger user shown on the screen is not the one linked to this person now. Reload the page\u2026\"", "a": "The page was showing a vTiger user that no longer matches this person (the page was open for a long time, or the vTiger record changed). Nothing was started. Reload the page, pick the person again and check the vTiger user shown before you run the offboarding."}, {"q": "\"No vTiger user matches that email. A vTiger user named \u2026 exists with another email\"", "a": "An action was asked for by email only, and the only vTiger user that fits was found by user name. Reload the page so the screen shows that user, check it is the same person, and act from there."}]}]}, {"title": "Company systems: every connection in one place", "for": "admin", "mod": "", "body": [{"p": "Settings \u2192 Company systems is the one place where every connection is set up. Click Set up\u2026 on a system to open its connection."}, {"bullets": ["Microsoft 365 \u2192 Set up\u2026: the app registration (tenant, client, secret), the Permissions tab (every permission the app can use, what it is for, whether it is needed, and whether your tenant granted it), Sign-in with Microsoft and the Teams app.", "vTiger \u2192 Set up\u2026: the bridge, the Web Services account and the read-only database.", "WHM / cPanel \u2192 Set up\u2026: the WHM host, the API token and the certificate.", "HubSpot, Jotform, eFax (Documo) and JustCall \u2192 Set up\u2026: the key box comes first, then the instructions (where the key is made, who can make it, what it must be allowed to do). Save the key and test; then set Use to Connected and the users are read and matched to people by email. Read only.", "Every system's row says what it is and how it connects. Opening a system to read its instructions does not switch it on.", "360 Monitoring \u2192 Set up\u2026: its API key and alerts \u2192 tickets.", "Other connections lists the rest with where each one is set up: email, the AI provider, sign-in with Microsoft, API keys and webhooks, Microsoft invoices."]}, {"h": "The Microsoft 365 permissions list"}, {"bullets": ["It comes with the build, so it follows every update. A check in every build makes sure it names every permission a feature uses.", "In Azure: App registrations \u2192 the app \u2192 API permissions \u2192 Add a permission \u2192 Microsoft Graph \u2192 Application permissions, then Grant admin consent. \"Copy the application permissions\" copies the list.", "Granted is read from the app's own token. After granting, use Microsoft 365 \u2192 Home \u2192 Diagnose \u2192 Refresh token. Exchange, directory and billing roles are given elsewhere; each row says where."]}]}, {"title": "Time zone of the installation", "for": "admin", "mod": "", "body": [{"p": "Every time in the app is recorded and shown in the installation's time zone, in 12-hour format: tickets and their due times, business hours, the scheduler, emails, reports and the calendar sync. It is chosen in the installer and shown in Settings \u2192 General \u2192 Time zone."}, {"steps": ["Settings \u2192 General \u2192 Time zone (a Super Admin changes it).", "Pick the zone from the list, or choose Other and type its name (for example America/Guatemala).", "Click Save, then reload the page to see every screen in the new zone."]}, {"bullets": ["Once the installation holds records, a change asks you to type CHANGE: created and updated times follow the new zone, but times the app wrote as clock values (due times, schedules, many logs) keep them and can look shifted by the difference. Choose the zone before going live.", "Business hours have their own time zone field; it starts as the installation's.", "A server administrator can fix the zone in config.php (ITOPS_TIMEZONE); the card then says so and cannot change it."]}]}, {"title": "Updates: installing a new build", "for": "admin", "mod": "", "body": [{"p": "Administration \u2192 Updates (Super Admin) installs a new build from a signed update bundle (a file ending in .itops-update) made by the License Hub."}, {"steps": ["Choose the bundle and click Check. Its signature, its package, the build, the free disk space and write access to every file are checked. Nothing changes yet.", "Read the notes and any problem. Type INSTALL and click Install.", "The app makes a database backup and a copy of the files it replaces, shows \"being updated\" for about a minute, puts the new files in place and runs the database update. Then click Reload now."]}, {"bullets": ["Never touched: config.php, the license file, data/ and people's uploads.", "If something fails while the files are put in place, the previous files are put back at once.", "Backups before updates keeps the three newest: \"Put the previous build back\" (type PUT BACK) restores the files; the database backup taken before the update can be downloaded there.", "A bundle signed by a key this build does not carry, or changed after it was signed, is refused. A build with no release key cannot check where a bundle comes from: install that build once by uploading the files.", "A build offered by the License Hub appears at the top with its notes: \"Download and check\" checks it the same way; installing still needs INSTALL."]}]}, {"title": "Data: the data dictionary and the data grid", "for": "admin", "mod": "", "body": [{"p": "Administration \u2192 Data (Super Admin only) shows every table of this installation: what it is for, its columns and its rows. Other roles, Admin included, do not see it."}, {"p": "Overview and report: the number of tables and columns, the reference lists that can be changed (marked \u270e), the tables that are empty right now, the tables no code of this build uses, and families of similar tables with advice on whether they could be merged. Nothing is merged or removed from here: such a change is made by a database update in a new build, after the report."}, {"p": "Download the dictionary (on the overview) gives every table and its columns as one document you can open in any editor or keep with your records. Downloading it is in the Audit Log."}, {"steps": ["Pick a table on the left (\"Find a table\" and the chips narrow the list).", "Data tab: type under a column to filter it. =value means exactly, !value not, >10 and <10 compare, ^start begins with, empty and !empty. Click a column name to sort.", "Group by: counts per value; click a count to filter by it.", "Export to Excel or CSV: the rows that match the filters and the sort, up to 50,000.", "Dictionary tab: each column with its type, default, keys, the table it points to and what it holds."]}, {"p": "Changing data: only the reference lists (departments, categories and similar) can be changed here, and only their marked columns. Double-click a \u270e cell, then press Enter to save or Esc to cancel. Values are checked (colors as #RRGGBB, statuses from their list, names not empty). If someone changed the value since you opened it, the change is refused and you reload."}, {"warn": "Passwords, tokens, keys and other secrets are never shown, filtered, sorted, grouped or exported: they read \"\u2022\u2022\u2022\u2022 hidden\". Opening a table's rows (once an hour), every export, every change and every refusal is in the Audit Log."}]}, {"title": "Deleted items: put back what was deleted", "for": "admin", "mod": "", "body": [{"p": "Deleting anything in the app (a ticket, an article, an SOP, a credential, a contract, a vendor, an invoice, a form, a calendar entry, a role, a template, a file\u2026) does not erase it. It moves to Administration \u2192 Deleted items, with what belongs to it: comments, files, versions, lines, tasks. A Super Admin sees everything there. A role with the permission Deleted items sees the deleted records of the parts of the app it can see: View to see them, Edit to put them back, Delete to delete them for good, each together with the same action on that part (for example Edit on Tickets to put a ticket back)."}, {"p": "Put back returns the record exactly as it was, with the same number and its links. If something it pointed to is gone (for example its category), that field is left empty and the page says so. If another record took its name or number meanwhile, it is not put back until that one is renamed."}, {"p": "Delete for good (type DELETE) removes one entry and its files from the disk. Empty Deleted items (type EMPTY) does it for all. Entries older than the kept days (30 unless changed on the page; 0 keeps them until emptied) are deleted for good once a day by the scheduled job."}, {"p": "A record that other records still use cannot be deleted: a vendor with contracts, a contract with invoice lines, a role people have. The message says what uses it; change those first, or set the record inactive instead. Every delete, put back and delete for good is in the Audit Log."}]}, {"title": "Maintenance window: automatic updates", "for": "admin", "mod": "", "body": [{"p": "Off by default. When it is on, the scheduler installs a build the License Hub offers inside the days and hours chosen, with the same backup and way back as installing by hand."}, {"steps": ["Link the installation to the License Hub (Updates \u2192 License Hub).", "Updates \u2192 Maintenance window: choose the days and the hours (the app's time zone), then Switch on.", "The scheduler downloads the offered build, checks it and, when nothing is in the way, installs it inside the window. The result is in the Audit Log and under Last update."]}, {"bullets": ["A bundle with any problem is never installed automatically; it waits for a person.", "A bundle uploaded by hand is never installed automatically.", "Needs the scheduler (cron-sla.php) to run from the command line (a cPanel cron job with php)."]}]}, {"title": "License Hub: the daily check-in", "for": "admin", "mod": "", "body": [{"p": "Once a day each installation asks the License Hub for its license, so a renewal, a change of plan or a revocation arrives by itself. It is set on Administration \u2192 Updates \u2192 License Hub (Super Admin), or in the installer."}, {"steps": ["The owner of the License Hub makes a link code (License Manager \u2192 Installations). For an installation not installed yet, leave the installation ID empty: the first installation that uses the code within 30 days is linked.", "Paste the link code in the installer (step \"License Hub\") or in Updates \u2192 License Hub and click Link. It carries the hub's address and a token; the token is stored encrypted and never shown again.", "Click Check in now to try it. After that the check-in runs by itself once a day."]}, {"bullets": ["A license that arrives is used only if its signature matches the license key in this build and it is for this installation. Otherwise it is refused, nothing changes, the refusal is in the Audit Log and the hub is told at the next check-in.", "The license file is written by this installation from the checked fields; the previous one is kept in data/updates/licenses.", "A revocation counts only when it is signed with that same license key and names this installation and the license in use, so an address that is not the real hub cannot take a license away.", "Sent: the installation ID, the build, the PHP and database versions, the number of active users, the last update's result, and the license number and state. Nothing about people, tickets or settings.", "Switch check-in off to stop it (for example on a server with no internet access), or Unlink (type UNLINK) to remove the address and the token. Licenses can still be uploaded as a file.", "On the License Hub, Installations lists every installation (from the licenses issued and from check-ins) with its license, users used and allowed, build and last check-in, and what needs attention: a term ending within 30 days or ended, more users than allowed, silent for 7 days, an older or revoked license still in use, a license it refused, not linked."]}]}, {"title": "Installing the main installation (License Hub)", "for": "admin", "mod": "", "body": [{"p": "There is only one main installation, run by Indisse-BTS: it issues the licenses and update bundles of every other installation. It is installed with install/hub.php; every organization uses install/ (the regular installer)."}, {"steps": ["Open https://YOUR-SITE/install/hub.php and follow the same steps as the regular installer.", "License Hub setup: the hub's public HTTPS address (it goes into every link code), the organization it belongs to, and a backup passphrase (12+ characters, twice).", "Finalize. The installer switches the License Manager on in config.php, creates the license key and the release key, and issues the hub its own license (Complete, no end date).", "On the last page, download both key backups (they are offered once) and send the two key lines to be put into the builds. Open ITOps becomes available once both backups are downloaded."]}, {"bullets": ["Keep the backup files and the passphrase in two different safe places. Later backups: License Manager.", "The installer locks itself once installed, like the regular one."]}]}, {"title": "License Hub: clients, releases and channels", "for": "admin", "mod": "", "body": [{"p": "On the main installation, License Manager keeps the client profiles, the licenses and the releases."}, {"bullets": ["Clients: organization, contact, email, phone, address and notes. When you issue a license, pick the client; the plan and modules are set on the license.", "Releases start in Pilot: installations marked Pilot (Installations, one click) are offered them at once; the others after the waiting period (7 days by default) or when you click Promote to Stable.", "Pause stops offering a release, Resume starts again, Withdraw (type WITHDRAW) stops it for good.", "Each release shows how many linked installations already run it."]}]}, {"title": "License Hub: billing", "for": "admin", "mod": "", "body": [{"p": "On the main installation, License Manager \u2192 Billing keeps the price list, the charges of each license and the payments you record. No money moves through the app."}, {"steps": ["Price list: set a monthly and/or annual price for each plan and extra module (base price with the users it includes, plus a price per extra user).", "Issue a license with Billing monthly or annual. The list price is shown; give a discount % or type the amount. The price stays with the license.", "Charges are made for each period a few days ahead and are due some days after the period starts (Billing \u2192 Settings).", "When a client pays, open the charge and click Record payment: amount, date, method and reference. Partial payments are fine."]}, {"bullets": ["A charge is due, partly paid, paid or overdue. Billing shows the totals, the aging and each client's balance; export charges or payments as CSV for your accountant.", "A client with overdue charges is flagged in Clients and Installations, and issuing or renewing its license warns first. Nothing is held or revoked.", "Mistakes are voided with a reason (a charge only when it has no payment); nothing is deleted. Everything is in the Audit Log.", "Once a day the scheduler makes the charges coming due and notifies the Super Admins."]}]}, {"title": "HubSpot on a person (People)", "for": "admin", "mod": "", "body": [{"p": "When HubSpot is connected (Company systems \u2192 HubSpot), each person on Microsoft 365 \u2192 People shows their HubSpot user under Systems, found by email. Adding people to HubSpot stays in HubSpot: once a user has the person's email, it shows here and is recorded on the person at once."}, {"steps": ["Edit HubSpot info: change the first and last name, the role and the teams. The email cannot be changed through HubSpot's API.", "Remove from HubSpot\u2026: type REMOVE. The user can no longer sign in to HubSpot; their records stay there. Reassign them in HubSpot first if needed.", "Offboard\u2026: \"Remove HubSpot user\" is ticked when the person has one. The offboarding step for HubSpot also has \"Remove from HubSpot now\"."]}, {"p": "A HubSpot Super Admin is never changed in role or removed from here. A role with a paid seat needs the billing-write scope on the key. The key needs settings.users.read, settings.users.teams.read and settings.users.write. Every change and every refusal is in the Audit Log."}]}, {"title": "Threats & vulnerabilities (Defender)", "for": "admin", "mod": "", "body": [{"p": "Microsoft 365 \u2192 Security \u2192 Threats & vulnerabilities shows the vulnerable software on your devices (from Defender advanced hunting), which devices have each vulnerability, Microsoft's details and write-ups about it, and Microsoft's threat write-ups. It is read only."}, {"p": "Microsoft has no API for the Threat analytics reports of the Defender portal; the button at the top opens them there."}, {"steps": ["Permissions: ThreatHunting.Read.All for the vulnerabilities; ThreatIntelligence.Read.All for the write-ups and a vulnerability's details (Settings \u2192 Company systems \u2192 Microsoft 365 \u2192 Permissions).", "The vulnerabilities need Defender vulnerability management (Defender for Endpoint Plan 2 or the add-on) and devices onboarded to Defender. Without it the list is empty and the page says why.", "Devices \u2192 Compliance \u2192 More on a Windows device shows its Defender antivirus state from Intune (real-time and tamper protection, definitions, scans)."]}]}, {"title": "Personal computers protected by Defender", "for": "admin", "mod": "", "body": [{"p": "Microsoft 365 \u2192 Devices \u2192 Personal computers lets people protect the computer they own with Microsoft Defender, by choice. Their computer is not enrolled in Intune: no apps, no wipe, no access to their files."}, {"steps": ["Set up once: confirm the two switches Microsoft has no API for (Defender portal enforcement scope; Intune \"Allow Microsoft Defender for Endpoint to enforce Endpoint Security Configurations\"), create the device group, send the antivirus and firewall rules, upload the connection files from Defender (Settings \u2192 Endpoints \u2192 Onboarding / Offboarding \u2192 Local script).", "Invite people. Each gets a personal link: they read what it means, agree by typing their name, and run a read-only check in PowerShell that reports their Windows edition and Defender state.", "Windows Pro, Enterprise, Education and Mac: they download the connection file on their page and run it. The rules reach the computer through Defender.", "Windows Home cannot join Defender for Endpoint. The page shows them how to keep the Defender built into Windows on; their check shows here.", "Withdrawing: on their page; the disconnect file is offered there and Super Admins are notified."]}, {"p": "Change the rules here, not in Intune: sending again replaces changes made there (the screen warns when Intune was changed afterwards). Real-time protection always stays on; exclusions of a whole disk or of Windows itself are refused. Every step, change and refusal is in the Audit Log."}]}, {"title": "Announcements to everyone in Microsoft 365", "for": "admin", "mod": "announcements", "body": [{"p": "An announcement can go beyond the people who have an account here. Under \"Who is it for\":"}, {"steps": ["Everyone in Microsoft 365: tick the domains (the default one is ticked to start). Every enabled account with a mailbox in those domains gets it; \"Only accounts with a Microsoft 365 license\" leaves out service and test accounts. Guests, shared mailboxes and rooms are left out.", "Selected: pick departments, roles and people here, search people in Microsoft 365 by name, add Microsoft 365 groups or distribution lists, or type addresses.", "People without an account here get it by email with their own link to read it and confirm; tick \"Email to each person\". Outbound email and the email \"Announcement to someone without an account\" must be on (Settings \u2192 Email)."]}, {"p": "The list is fixed when you publish: people added to Microsoft 365 afterwards do not get it."}]}]}, {"cat": "Monitoring & scorecard", "topics": [{"title": "Server Guardian \u2014 health checks", "for": "admin", "mod": "guardian", "body": [{"p": "IT Operations \u2192 Server Guardian is a read-only health screen for the web server, its cPanel accounts and Microsoft 365 security. Use it to spot problems before users do."}, {"steps": ["Open IT Operations \u2192 Server Guardian. A scan runs when the page opens; click \"Run scan\" to repeat it.", "Read the cards. Each has a coloured dot and a level: OK (green), WARNING (amber), ERROR (red) or OFF (grey, not set up).", "Click \"Details\" on cards that have it (cPanel accounts, services, SSL, bandwidth, MySQL, inodes, domains) for a per-item table.", "Check \"Active alerts\" at the top for conditions that are still open."]}, {"h": "Server & WHM cards"}, {"bullets": ["Server vitals: disk free (warning under 15%, error under 5%), load per CPU core and PHP memory.", "cPanel accounts, Server services, Server load, Server backups (cPanel), Brute-force protection (cPHulk), cPanel version, Updates & reboot, Bandwidth, MySQL databases, Domains & subdomains, Inodes & mailboxes, SSL certificates (all domains): from the WHM API.", "TLS certificates: the hosts you list. Warning at 30 days or less, error at 14 days or less or expired.", "Malware scan (Imunify) and Mailbox reachability (IMAP).", "Mail queue (Exim): warning over 100 queued messages, error over 1000.", "Backup assurance (see \"Logging backup verifications\") and PHP version (end-of-life warning)."]}, {"h": "Microsoft 365 cards"}, {"bullets": ["Microsoft Defender (Secure Score, incidents, alerts), Device compliance (Intune) and 2FA adoption. They need Microsoft 365 connected and the matching Graph permissions."]}, {"p": "Most server cards show OFF until a Super Admin fills in \"Configure server checks\" (see the next topic). A WHM token with fewer privileges simply shows \"unavailable\" for what it can't read."}, {"qa": [{"q": "The Mail queue card says \"not exposed by the WHM API on this host\".", "a": "Your host doesn't publish the queue through WHM. A server cron can POST the output of exim -bpc to /api/guardian/mailq_check; the card then shows it for an hour after each report."}, {"q": "I don't see Server Guardian.", "a": "Your role needs Server Guardian (view)."}]}]}, {"title": "Server performance: finding out why the server is slow", "for": "admin", "mod": ["guardian"], "body": [{"p": "IT Operations \u2192 Servers \u2192 Server performance is the management dashboard of the server this app runs on: how busy it is, what is using it, its web traffic, database, disks and network, minute by minute, and for each spike the accounts, processes, visitors, sites and pages behind it. The samples are taken by the app's own scheduled jobs; nothing is installed on the server."}, {"h": "Reading the page"}, {"bullets": ["The page has two tabs. Status shows what is happening now (the colored banner, the gauges, the tiles and \"Right now\"); Details holds everything else in smaller tabs. Each tab is remembered.", "The colored banner says how the server is doing at the last sample: green all good, yellow busy but coping, orange under pressure, red overloaded. The word is always written next to the color.", "The gauges show CPU, memory, load, waiting on disk, disk space (the fullest disk) and swap now, with their color bands. The tiles under them show the database, web requests, how busy the disk is, the network and how long the server has been up.", "Under each gauge a small line shows that measure over the time written beneath it (for example \"last 4 h\"), with its lowest and highest values: the shape tells whether it is rising or steady.", "On the Status tab, \"Right now\" shows who is using the server: CPU and memory by account (donuts), visitors, sites, pages, what ran in that second (short php-cgi runs included) and the busiest processes of the minute.", "Two tiles on Status, \"Unusual traffic\" and \"Sign-ins from outside (24 h)\", open the Security tab. The map of where the load came from is on Details \u2192 Visitors (IP).", "\"Busy hours\" colors each hour of the period by its average CPU: the same hour busy every day points to a scheduled job or a backup."]}, {"h": "The tabs"}, {"bullets": ["Spikes & graph: on top, side by side, the accounts that weighed most in the period's spikes (average CPU of the server) and the spikes themselves (when, how long, peak, accounts, visitors, sites \u2014 \"Why\u2026\" opens the moment); under them the graph over time (click a line's name above it to hide or show it, \"only\" for one line alone, \"All lines\" for all); then the visitors, sites and pages of the spikes. The busy hours are on History.", "Error logs: the error logs of every account on the server, read every 10 minutes through Server Guardian's WHM connection \u2014 each site's PHP error log and the web server's error lines of its sites. The same error repeated is one row with its count and when it last happened; click a row for its latest lines (passwords and keys masked); click an account to see only its errors. The Status tab shows the serious errors of the last hour; click the tile to open them. \"Read now\" reads every account at once (Server Guardian \u00b7 Edit).", "Security: the sign-ins to vTiger (its read-only database connection) and to this app from outside the allowed countries \u2014 the United States and Puerto Rico to start \u2014 checked every 5 minutes, worked or failed, with who, the city, the network and the address. \"Allow\u2026\" lets a person sign in from a country until a day (for a trip); their sign-ins there are then kept as allowed without alerts, and the check starts again by itself after that day. Below: unusual traffic hour by hour (far more addresses than the same hour of the previous 7 days, countries outside the allowed ones seen for the first time, many addresses asking for sign-in pages, one network holding most addresses), and the settings: the allowed countries (type to add one), what is checked, and the alerts (bell, Teams when its alerts are on, Event Log, and e-mail if switched on). The sign-ins from outside and the exceptions sit as two small boxes beside the tiles; the full list opens from the box.", "Visitors (IP): the 4 tiles on top; the map on the left and the addresses on the right, the one that kept the server busiest first, with its share of the load, sites and pages, and marks (Login page, Search engine, Data center, Slow requests). Drag the bar between the map and the list to give one more room; \"Map\" and \"List\" hide either. \"Columns\" chooses what the list shows. \"Connected now\" shows only the last 5 minutes. A button per site shows who visited that site alone. The map: the United States with Puerto Rico first, \"World\" for every country; zoom with + and \u2212 or the mouse wheel, drag to move; a dot per city sized and colored by its share of the load, a dashed purple ring for a new place, a red ring for a sign-in from outside the allowed countries; \"Show the people signed in to vTiger now\" adds a blue pin per person. Click a place for its card (its coordinates are the centre of the city the address is registered to, not a street address; \"Open on OpenStreetMap\") and to list only its addresses. \"Choose sites\u2026\" picks which sites get a button (for everyone). \"Outside \u2026\" shows only the addresses located in other countries; \"check \u2197\" opens an address on ipinfo.io to verify its country and network. Who signed in from an address (vTiger or this app) shows under it, and as a blue count on the map.", "Processes & accounts: what runs right now, the memory split (programs, cache, free, swap), and the accounts over the period with their average and peak CPU and their site. Send this list to a site's owner or the hosting provider.", "Web traffic: requests a second, workers busy and the requests in progress (visitor, site, page, how long it has run). Many requests from one address may be a robot: block it in WHM (CSF or Imunify360). The charts fill the width of the page.", "Database: queries a second (split into reads and writes), queries running, full table scans a second (reads of whole tables: a missing index), the share of data found in memory, slow queries, and new and refused connections a second, each with its chart. \"People signed in to vTiger\": who is signed in now (name, vTiger user, address, since when), the day's sign-ins and failed attempts, from vTiger's own sign-in history (through the vTiger bridge, build o11 or later, or vTiger's read-only database connection, Integrations \u00bb vTiger). \"Queries that cost the most\": each kind of query (values replaced by ?) with how often it ran in the last hour, 24 hours or 7 days, the time it took in all, its average and longest time, the rows it read and whether it used an index \u2014 where the database spends its time. It needs the database's statistics on (a server setting; the guide Server Performance and Monitoring, 9.3) and the monitoring user allowed to read them. When something is missing the card says so in one line; its \"Help\" button shows how to create or change the monitoring user in WHM, with the commands to copy (step 3 is the one GRANT for the statistics, no restart). Then the connections one by one (who, which database, from where, doing what, for how long) and the queries running, caught in five quick looks a fifth of a second apart. Most connections are idle: programs keep them open, not people. To see every database and not only this app's, save a MySQL user with only the PROCESS privilege on the Settings tab; under that box, \"How to set up, change or remove this user\" gives every step, in WHM (phpMyAdmin's SQL tab, with the commands ready to copy) and in this app. \"Signed in now\" (one row per person whose latest sign-in is still open) and \"Sign-ins in the period\" (every sign-in and attempt) sit side by side; each folds away and has its own columns.", "Disk & network: a colored bar per disk (yellow from 70%, orange 85%, red 95%), activity per disk and traffic per network interface. The charts fill the width of the page.", "History: the busy hours first (a square an hour, all 24 labeled, the same hour every day points to a scheduled job or a backup), then eleven charts, four a row on a wide screen (fewer on a narrow one); they grow with the screen. Hover any chart for the time and the values.", "Daily history: one row a day, kept 3 years (Settings). \"Busy hours\" shows \"The average week\" (weekday \u00d7 hour) or \"Day by day\" in one card with one legend; click a weekday or a day to see it beside: its CPU hour by hour and its busiest accounts and addresses. Then the months compared and every day (Download CSV)."]}, {"h": "Finding the cause of a spike"}, {"steps": ["Choose the period (6 hours to 30 days). Red dots are minutes above the CPU level (75% to start).", "Look at \"What weighed most in the spikes\": the account, visitor IP, site and page that come back most often are usually the cause.", "On the Details tab, under Spikes & graph, click \"Why\u2026\" on a spike, or click any point of the graph: the moment opens on the Status tab with the busiest processes, the accounts using the CPU and memory, who the web server was answering, and the database activity.", "Open Visitors (IP) to see which addresses load the server most over the period, where they are and whose network they use.", "Act on what you find: block an IP that hammers a login page (in WHM or the firewall), fix or slow down a heavy script or cron job, or ask the hosting provider about an account that uses too much."]}, {"h": "Good to know"}, {"bullets": ["CPU is the average since the previous sample (every minute when cron-uptime.php runs every minute, else every five minutes). The shaded area also counts the highest one-second reading, so short bursts show.", "Load is shown as a percentage of the CPU cores: 100% means every core is busy; above 100% means work is waiting.", "Waiting on disk (iowait) high with low CPU usually means the disk, a backup or the database, not the visitors.", "Alerts are off to start. Switch them on under \"Levels and alerts\": a bell goes to the administrators once when the server stays above a level, and once when it is back below.", "If the server hides other accounts' processes, or does not run Apache, the page says so; those parts are then empty rather than guessed.", "The page only reads. The firewall, killing a process and restarting services need root and stay in WHM.", "A grey line at the top names what this page cannot read on your server (for example the web server's status page, or other databases' queries); \"What it means\" explains each and what to ask the hosting provider. The rest of the page is not affected.", "The page refreshes itself every minute while it is open (\"Auto-refresh every minute\", top right), so it can stay open on a screen. \"Sample now\" measures the server at once; \"Refresh\" only reloads what is already recorded.", "Swap is colored by its activity (memory moved in and out a second), not by how full it is: a server that has been up for months keeps idle memory in swap without being slowed by it.", "Every small chart places its points by time, with round hours or days along the bottom; hover a chart to read the time and the values of any point. A gap in the line means no sample was taken then.", "The map and the Security tab need the location lookup (Settings \u2192 Visitors' location and network), which sends the addresses seen to ipinfo.io and keeps the answers 30 days. Without a token the app stays under 900 lookups a day (the free service answers about 1,000); a free ipinfo.io token raises it to 1,600 a day. Places are approximate (city level): phones on mobile data, VPNs and cloud servers often show their company's location, and a VPN can hide the real country either way. The network shown usually tells.", "The traffic check is a sample taken each minute from the web server's status page: it catches a sustained flood or a crowd of new addresses, not a burst of seconds; and a network flood that never reaches the web server can only be seen and stopped by the hosting provider. The Security tab only warns; to block a country or an address use WHM (cPHulk or the firewall, CSF / Imunify360)."]}, {"h": "vTiger check (configuration and security)"}, {"p": "Details \u2192 \"vTiger check\" reads vTiger's configuration through the vTiger bridge (build o12 or later) and looks at vTiger from the internet the way a visitor does. Nothing secret is read or kept \u2014 never the database password, the application key or the CSRF secret, only whether they are set \u2014 and nothing is changed."}, {"steps": ["Upload vtiger-bridge/itops-bridge.php of this release (build o12) over the old one in the vTiger folder; the secret stays the same.", "Server performance \u2192 Details \u2192 \"vTiger check\" \u2192 \"Check now\" (Server Guardian \u00b7 Edit). It takes up to a minute.", "The four tiles count the findings: Risk, To improve, Info and Good. The list opens on the risks and the things to improve; filter by level or by area (From the internet, config.inc.php, config.performance.php, Logging, PHP, Files and folders, Scheduler, Accounts).", "Click a finding: why it matters and how to change it, ready to copy. Make the change in WHM or cPanel, then \"Check now\" again."]}, {"bullets": ["From the internet: https and http \u2192 https, the security headers (HSTS, X-Frame-Options, X-Content-Type-Options, Referrer-Policy), the PHP version shown, the session cookie's flags, and whether vTiger's log, its folders, the bridge's secret file or a backup left in the web root can be downloaded (only the status is kept).", "config.inc.php: the address, the folder, the application key's length, the database user (not root), the file types refused on upload, who may export, the upload size against PHP, the time zone.", "config.performance.php and log4php.properties: debug logging off, the log level.", "PHP as vTiger runs it: the version and its end of security fixes, PHP-FPM, errors not shown on pages, session settings, max_execution_time, memory_limit, max_input_vars, OPcache.", "Files and folders: the permissions of config.inc.php and the secrets (640), no folder open to everyone (777), storage/.htaccess, files left in the web root.", "Scheduler: whether vtigercron.php runs and tasks that are late or stuck.", "Accounts: the administrators, a user still named \"admin\", active users not signed in for 90 days, failed sign-ins."]}, {"tip": "Under the list: \"The important vTiger files and what they do\" and a recommended .htaccess block for the vTiger folder. Every check is written to the Audit Log with its counts."}]}, {"title": "Guardian settings, alerts and server actions", "for": "admin", "mod": "guardian", "body": [{"p": "The \"Server Guardian settings\" panel at the top of Server Guardian holds the check configuration, alert options and the two server actions. Only a Super Admin can use it."}, {"h": "Configure server checks"}, {"steps": ["Open IT Operations \u2192 Server Guardian and expand \"Server Guardian settings\".", "Under \"Configure server checks\", fill in what you have: Host label, CPU cores, WHM host, WHM port (2087), WHM user, WHM API token, Imunify binary path, IMAP host, IMAP test mailbox, IMAP password, and \"TLS hosts to watch (comma-separated)\".", "Click \"Save check settings\". Values apply on the next scan. Secret fields are write-only; leave them blank to keep the saved value."]}, {"h": "WHM certificate"}, {"p": "The WHM token can do anything on the server, so ITOps sends it only to a WHM whose certificate it can check. A certificate that browsers trust (for example from Let's Encrypt) needs nothing. WHM's own self-signed certificate has to be trusted once:"}, {"steps": ["Under \"Configure server checks\", find \"WHM certificate\" and click \"Check certificate\".", "Compare \"Issued to\", \"Issued by\", \"Expires\" and \"Key\" with what WHM shows (WHM \u2192 SSL/TLS \u2192 Manage Service SSL Certificates, the cpsrvd certificate).", "Click \"Trust this certificate\" and confirm. The status becomes \"Trusted here (this key is saved)\"."]}, {"bullets": ["Until the certificate is trusted, WHM checks and server actions stop with a message saying so; the token is not sent.", "When WHM gets a new certificate (renewed or replaced key), the status shows \"Another key is saved\": check it and trust it again.", "\"Remove saved certificate\" goes back to checking WHM like any https site. Trusting, refusing and removing are in the Audit Log."]}, {"h": "Alerts"}, {"bullets": ["The scheduled job checks Guardian and Microsoft 365. A check that starts failing raises an alert once: an Event Log entry, an in-app notification to Super Admins, Admins and Department Admins, and the \"alert.raised\" webhook. When it recovers it clears the same way.", "\"Raise alerts for\": \"Warnings and above\" or \"Errors only\".", "Tick \"Email admins a daily digest of open alerts\" and/or \"Email admins a weekly operations digest (Mondays)\". Both need the scheduled job."]}, {"h": "Server actions"}, {"steps": ["Pick \"Restart a service\" (type the service: dovecot, exim, httpd, mysql, named, ftpd, spamd, cpsrvd, nginx, crond, imap or pop) or \"Unblock an IP\" (removes it from cPHulk blocking).", "Click \"Preview\" and read what will happen.", "Click \"Confirm & run\". When WHM refuses the action (for example a service that is switched off), the message says \"WHM did not do it\" and the failure is in the Audit Log."]}, {"warn": "Server actions change the live server and are always Super Admin only. Restarting a service briefly interrupts it. They need the WHM host and token."}]}, {"title": "Uptime: websites and WHM/cPanel accounts", "for": "admin", "mod": "uptime", "body": [{"p": "IT Operations \u2192 Servers \u2192 Uptime checks websites and every WHM/cPanel account on a schedule, records each check, and tells you when something goes down and when it comes back. It also reports availability to the Scorecard."}, {"h": "Add a website"}, {"steps": ["Click \"+ Add a website\".", "Type the address (http:// or https://). Optional: a name, how often to check (minutes), how long to wait for an answer, the answer codes that count as up, a word that must be on the page, when to warn before the certificate expires, and how many failed checks in a row make an outage (2 by default).", "Click \"Test now\". The result shows straight away \u2014 up or down, the answer code, the response time, the certificate expiry, and in plain words why a check failed (the name does not resolve, the connection was refused, the word is not on the page\u2026). Nothing is saved by a test.", "Click \"Add and check\". The monitor is saved, checked at once, and written to the Audit Log with its settings."]}, {"tip": "Servers on your own network can be monitored. Addresses that are never a website \u2014 link-local (169.254.x.x, where cloud servers keep their secrets), \"this network\" (0.x.x.x), multicast and broadcast \u2014 are refused, also when written as IPv6. A name is looked up once per check and the check goes to that address."}, {"h": "WHM / cPanel accounts"}, {"bullets": ["Connect WHM first: Server Guardian \u2192 Server actions \u2192 WHM host and API token. The token is entered in the app and stored encrypted; it is never shown again.", "\"Read the WHM accounts now\" makes a monitor for the main domain of every account, plus one for the WHM server itself. The accounts are read again every 6 hours (switch it off under the card).", "A suspended account shows as Suspended and is not checked, so it never counts as an outage. An account removed from WHM stops being checked; its history is kept.", "WHM monitors cannot be deleted (they would come back on the next read) \u2014 pause them instead. Choose whether accounts are checked over https and how often."]}, {"h": "How an outage is decided"}, {"bullets": ["A failed check is checked again on the next run, about a minute later. When the number of failed checks in a row reaches the monitor's threshold, it is down; the outage starts at the first failed check.", "The outage ends at the first good check, with how long it lasted. Open a monitor to see its outages and add a note to each (audited).", "Administrators are told once when a monitor goes down and once when it is back (bell, and email if switched on) \u2014 not at every check. A certificate that expires within the days set on the monitor (14 by default) is reported once per expiry date."]}, {"h": "The list"}, {"bullets": ["Each monitor shows its state, availability for 24 hours, 7 days and 30 days, when it was last checked, the response time, the certificate expiry and the last 48 checks as green and red bars.", "The chips filter websites, WHM / cPanel, down, and paused or removed. \"Check all now\" checks every active monitor at once."]}, {"h": "Report"}, {"steps": ["Click \"Report\u2026\" and choose the period.", "Click \"Preview\". The report opens on screen: availability, downtime and response time of every monitor, and every outage with its cause.", "From the preview, download it as PDF, Word or CSV."]}, {"h": "Report to the Scorecard"}, {"steps": ["Under \"Servers on the Scorecard\", tick the servers that should count (the chips pick all websites, all WHM/cPanel, or none) and click \"Save the choice\". Servers that are not ticked are still monitored; they just don't count on the Scorecard.", "Choose what to measure. \"Uptime \u2014 the servers chosen for the Scorecard (%)\" is the availability of the ticked servers; the same is available for their outages and their minutes down. All sites, websites only, cPanel accounts only and one server are there too.", "In \"Put it in\", choose \"A new row\", or connect a row you type by hand today, such as \"System uptime\". A connected row keeps its name and owner and starts filling in by itself; weeks someone already typed are kept.", "Click \"Add to the Scorecard\" (or \"Connect\"). The last 13 completed weeks are filled straight away. \"One row per chosen server\" adds a separate row for each ticked server instead."]}, {"h": "Keeping the checks running"}, {"p": "Add the cron line for cron-uptime.php (every minute) from Logs & Integrations \u2192 Scheduled jobs \u2192 \"Set up the cron jobs\". Each monitor is still checked only at its own interval. Until that line is added, the main scheduler and the in-app scheduler run the checks too, less often. Scheduled jobs shows the job as \"Uptime checks\"."}, {"qa": [{"q": "A cPanel account shows down with \"Answered HTTP 500\".", "a": "The server answered, but the website itself failed (an internal server error: a PHP error, a broken .htaccess, a database the site cannot reach). Open the address in a browser and look at cPanel \u2192 Metrics \u2192 Errors or the error_log file in the account's public_html. If the account is not meant to have a working website (email only, for example), open the monitor and untick \"Active\" so it stops counting as an outage."}]}, {"tip": "Addresses inside the cloud metadata range (169.254.x.x) and anything other than http/https are refused, also when a site redirects there. Redirects are followed up to 5 times."}, {"p": "Permissions: Uptime (view) to see it; (edit) to add, change, test, check, read WHM, change settings, choose the servers for the Scorecard and add to it (which also needs Scorecard \u00b7 Create). Refusals are written to the Audit Log too."}, {"h": "Who sees which monitors"}, {"steps": ["On Uptime, click \"Who sees which\u2026\" (needs Uptime \u00b7 Edit).", "For each role that only views Uptime choose: All monitors, Only the servers chosen for the Scorecard, or Only the monitors ticked here (then tick them).", "To give one person something different from their role, use \"Add a line for a person\u2026\". A person's line replaces their role's.", "Click Save. The change is in the Audit Log."]}, {"p": "A limited person sees only those monitors in the list, the outages, a monitor's page and the report, and the page says \"You see the monitors chosen for you\". The tiles at the top of the page filter the list: Monitors, Down now, Availability (below 100%), cPanel accounts, Suspended accounts."}]}, {"title": "Backups: WHM backups and backup scripts", "for": "admin", "mod": "backups", "body": [{"p": "IT Operations \u2192 Servers \u2192 Backups tells you whether the backups ran. It watches two kinds: the backups WHM makes, and your own backup scripts (for example copyBackups.sh), which check in when they finish. Late, failed or switched-off backups are reported once, and so is a backup that works again."}, {"h": "Watch the WHM backups"}, {"steps": ["Connect WHM first (Server Guardian \u2192 Server actions \u2192 WHM host and API token).", "Click \"+ Watch the WHM backups\", then \"Add and read WHM\".", "ITOps reads WHM \u2192 Backup Configuration and the dates that have a backup, then once an hour. A new backup date counts as a backup done, with how many accounts it holds and any account that is not in it. Backups turned off in WHM count as a failure.", "How often a backup is expected follows the days WHM runs them (every day = 24 hours; Mon, Wed, Fri = 72 hours). Set the grace time (default 3 hours) to allow for how long the backup takes."]}, {"h": "Add a backup script"}, {"steps": ["Click \"+ Add a backup script\". Give it a name, a short name (used by the command), how often it runs (hours) and a grace time.", "Click \"Add\". The check-in lines are shown: copy them now. The private address for another server is shown only once.", "Add the lines at the end of the script. On the same server no key is needed:\nif [ $? -eq 0 ]; then php \u2026/backup-checkin.php <short name> ok; else php \u2026/backup-checkin.php <short name> failed \"what went wrong\"; fi", "A script on another server uses the private address with curl (\u2026/api/backups/checkin?key=\u2026&status=ok or status=failed; size_mb and duration_s are optional). Lost it? Open the backup and click \"New check-in key\u2026\" \u2014 the old address stops working."]}, {"h": "The easiest way for a script run by cron (for example copyBackups.sh)"}, {"steps": ["Open the backup in ITOps. Under \"Easiest: change the cron line\", paste the command the cron job runs now (cPanel \u2192 Cron Jobs \u2192 Command), for example /bin/bash /home/account/dumps/copyBackups.sh.", "Copy the new command it shows and put it in place of the old one in cPanel (Edit on that cron job; keep the same time).", "From then on, each night the backup reports \"ok\" when the script ends without an error and \"failed\" when it ends with one. Nothing inside the script changes."]}, {"h": "What you see"}, {"bullets": ["Each backup: OK, Late, Failed, Turned off or Waiting for the first backup; the last good backup; when the next one is due by (red when overdue); the share on time over 30 days; and the last 14 days as green and red marks.", "Open a backup for its history: every result, where it came from (WHM, a check-in from this server or from the address, or ITOps noticing it was late) and the detail.", "A backup is late when nothing successful arrived within its interval plus the grace time. Pausing a backup (untick \"Watching\") stops the alerts; switching it back on starts the wait again.", "Every result is also written to the Event Log (channel backup), so Server Guardian's \"Backup assurance\" card sees it."]}, {"h": "Report to the Scorecard"}, {"p": "The WHM backups count on the Scorecard from the start; a backup script (such as copyBackups.sh, a copy of the backups) is only watched and alerted unless you tick \"On the Scorecard\" on it. In \"Report to the Scorecard\", choose \"Backups on time \u2014 the backups chosen for the Scorecard (%)\" (or missed backups, or one backup), and either add a new row or connect your \"Backup success rate\" row. Each week shows the share of expected backups that arrived on time; the last 13 weeks are filled straight away."}, {"p": "The checks run with the Uptime cron line (cron-uptime.php, every minute). Permissions: Backups (view) to see it; (edit) to add, change, remove, make keys, read WHM and report to the Scorecard (which also needs Scorecard \u00b7 Create). Every change and refusal is written to the Audit Log."}, {"h": "When a WHM backup counts as done"}, {"p": "WHM makes a backup's date when the nightly run starts and adds each account as it finishes. So a new date counts as done only once every account WHM is meant to back up is in it. Until then the list shows \"Running\" with how many accounts are in so far and which ones it is waiting for, and WHM is read again every 20 minutes. Accounts still missing 12 hours after the date appeared (or when the next backup starts first) make it a failure that names them. Accounts with backups off in WHM, and suspended accounts when WHM does not back them up, are not counted as missing."}, {"h": "What WHM has now"}, {"bullets": ["Open the WHM backup: \"What WHM has now\" shows WHM's backup settings (type, days, copies kept, folder, suspended accounts) and where the copies also go \u2014 or that they are only on this server.", "The backup dates kept are listed; click one to see its accounts: in it, missing (with what WHM says), or not backed up on purpose and why.", "\"Read again\" reads WHM now. Nothing is changed in WHM: ITOps only reads."]}, {"tip": "If the copies are only on this server, a disk failure loses the server and its backups together. Add an additional destination in WHM \u2192 Backup Configuration (for example Amazon S3, Backblaze B2 or another server over SFTP)."}]}, {"title": "Logging backup verifications", "for": "admin", "mod": "guardian", "body": [{"p": "Log a backup verification each day after you have checked that last night's backups ran. It feeds the Backup assurance card and the scorecard."}, {"steps": ["Check your backups in your backup tool.", "In ITOps, go to IT Operations \u2192 Server Guardian and expand \"Server Guardian settings\".", "Under \"Configure server checks\", click \"Log backup verified today\"."]}, {"h": "What it changes"}, {"bullets": ["Backup assurance card: OK if the last verification is under 26 hours old, WARNING after 26 hours, ERROR after 48 hours or if any failure was logged in the last 8 days.", "Scorecard: a measurable with the data source \"Backup verification success (%, from logged checks)\" shows the share of the 7 days in the week with a successful logged check. Days where only a failure was logged don't count."]}, {"h": "Automating it"}, {"p": "A backup script can POST to /api/guardian/backup_check with {\"ok\":true}, or {\"ok\":false,\"note\":\"what failed\"} to log a failure. The caller needs Server Guardian (edit)."}, {"warn": "The \"Log backup verified today\" button is Super Admin only. The New key form under Integrations does not offer a Server Guardian permission, so an API key can't call this endpoint yet. Log it by hand for now."}]}, {"title": "The Scorecard: daily, weekly, monthly and yearly", "for": "admin", "mod": "scorecard", "body": [{"p": "Service Desk \u2192 Scorecard is a weekly grid. Each row is a measurable with an owner and a goal, each column is a week (ending Sunday), and green meets the goal while red misses."}, {"h": "Daily, weekly, monthly, yearly"}, {"bullets": ["The chips at the top switch the view: Daily (7, 14 or 31 days), Weekly (8, 13, 26 or 52 weeks), Monthly (6, 12 or 24 months) or Yearly (3 or 5 years). The view and the number of columns are remembered.", "The last column is the current day, week, month or year so far (in italics, with a dashed outline). Automatic rows show a value there straight away, so a row connected today (uptime, backups) shows today and this week at once.", "Automatic rows are worked out for each period from the live data. Rows that only know \"now\" (open alerts, Secure Score, Intune, MFA, TLS) and typed rows combine their weekly values in the monthly and yearly views: the average, the total, or the latest week. Choose it under \"edit\" \u2192 \"Over a month or a year\" (Automatic picks the total for counts and the average for percentages and times). Typed rows show nothing in the daily view.", "Goals are weekly. A total (for example tickets created) is judged against the weekly goal \u00d7 the number of days \u00f7 7; hover a cell to see the goal for that period and where the value came from. Values are typed only in the weekly view.", "Column widths: drag the right edge of a column header to make it wider or narrower (dragging one date column sizes all of them). \"Fit to screen\" sizes the columns to the page. The widths are remembered on this computer."]}, {"h": "Set it up"}, {"steps": ["If the grid is empty, click \"Install a default IT scorecard\".", "Set \"Starts\" to your first week. Columns appear as each week completes.", "Click the name of a measurable (or the pencil beside it, or \"edit\" under it) to change its name, goal, owner, unit or \"Data source\". Click \"+ Measurable\" to add one."]}, {"h": "Each week"}, {"steps": ["Auto rows (marked AUTO) fill in for the last completed week through the scheduled job. Click \"Refresh from ITOps\" to recompute that week now.", "For manual rows, click the cell, then \"Type this week\u2019s value\" in the panel underneath; type the number and press Enter. Leave it blank to clear it.", "In your weekly meeting, discuss only the red cells. \"How it works\" explains each default measurable."]}, {"bullets": ["Automatic sources: P1 / critical tickets, avg first-response time, tickets closed within SLA, tickets created, on-time onboarding provisioning, open server alerts, server uptime from Server Guardian alerts, backup verification success, Microsoft Secure Score, Intune device compliance, 2FA / MFA adoption, TLS cert fewest days to expiry.", "service management and Cases & Projects sources (from Service Desk \u2192 Reports, \"Put a measure on the Scorecard\u2026\"): first-contact resolution, reopened tickets, changes that worked, requesters happy (%), cases and projects closed on time (%), overdue case and project tasks (a count of now: only the current week fills in), and improvements done (a total per week).", "Uptime sources (from IT Operations \u2192 Uptime): availability of all monitored sites, of the websites only, of the WHM/cPanel accounts only, or of one monitor (%), the number of outages, the minutes down, and the average response time (ms). The quickest way to add one is \"Report to the Scorecard\" on the Uptime page.", "Backup sources (from IT Operations \u2192 Backups): backups on time for the backups chosen for the Scorecard (%), missed or late backups (count), or one backup (%).", "The Microsoft 365 sources need Microsoft 365 connected. For TLS, set the goal to \"\u2265 at least\" 30 so the cell turns red before a certificate lapses."]}, {"warn": "The default scorecard installs \"System uptime\" and \"Backup success rate\" as rows you type by hand. To fill them automatically, connect them: Uptime \u2192 Report to the Scorecard \u2192 \"Put it in\" \u2192 \"System uptime\", and Backups \u2192 Report to the Scorecard \u2192 \"Put it in\" \u2192 \"Backup success rate\". Or click \"edit\" on the row and choose a data source. Weeks someone typed are kept; the other past weeks fill in straight away."}, {"tip": "If you type over a value in an AUTO row, the next refresh of that week replaces it."}, {"p": "Every change to the Scorecard is written to the Audit Log: rows added, changed (with before and after) or removed, and every value typed into a week (with the value before)."}, {"p": "Permissions: Scorecard (view) to see it, (create) to add, (edit) to change, refresh or type values, (delete) to remove. Changing \"Starts\" also needs Settings (edit)."}, {"h": "Who can change it, and who sees each measurable"}, {"bullets": ["Scorecard \u00b7 View only: the Scorecard is read-only \u2014 no \"+ Measurable\", \"Refresh\", \"edit\", \"remove\" or typing in the cells; the page says \"View only\". Adding needs Scorecard \u00b7 Create, changing and typing values Edit, removing Delete. A refused change is written to the Audit Log.", "\"Who sees it\" (on edit or add): everyone who can open the Scorecard, or only chosen roles and people. The owner of the measurable and whoever can edit the Scorecard always see it; for them a limited measurable shows a \"limited\" mark."]}, {"h": "The data behind a number"}, {"p": "Click any value in the grid. A panel opens under the grid (not a pop-up) with what supports that number. Click the value again or \u2715 to close it."}, {"bullets": ["How it is counted: what the number means and the exact rule (what is counted, what counts as on time, what is left out).", "This period: the count behind it, for example \"2 on time of 3 resolved = 66.7%\", the goal and by how much it is met or missed, and how many could have missed while still meeting the goal (\"To meet \u2265 95% with 20 counted, up to 1 could miss; 4 did\").", "The records counted: each ticket (or onboarding) with its dates and the result (\"On time\", \"Late by 2 h 15 min\", \"No response yet \u2014 overdue\", \"Not counted yet\"). Filter by result, click a ticket number to open it, or \"\u2b07 CSV\" to take the list away. The tickets are listed for people who see every ticket (Tickets \u2192 All records); the others see the numbers and the rule.", "A typed value shows who typed it and when (from the Audit Log). A month or a year of a typed row shows the weekly values it is made of. A reading taken at refresh (Secure Score, open alerts) says so.", "A saved week that no longer matches the records (a priority changed, a ticket reopened) says what counting again today gives; \"Refresh from \u2026\" saves the new count."]}, {"h": "Priority targets on the Scorecard"}, {"steps": ["Click \"Priority targets\u2026\" (needs Scorecard \u00b7 Create and Edit).", "Tick \"First response on time\" and/or \"Resolved on time\" for the priorities you want. Each tick adds a row with the goal \u2265 95% and fills its past weeks; change the goal with the pencil.", "Untick to hide a row. Its weeks are kept and come back if you tick it again."]}, {"bullets": ["First response on time: tickets of that priority created in the period. On time = the first response came by the response due time on the ticket; late = after it, or none yet and the due time has passed. Tickets still inside their response time are not counted yet.", "Resolved on time: tickets of that priority resolved in the period, on time = by the due time on the ticket. Tickets still open past their due time are counted when they are resolved (the panel says how many there are right now).", "The due times are the ones on each ticket, so business hours, Pending time and a category's own hours are already in them."]}]}, {"title": "Integration Audit: what it is and the golden rule", "for": "admin", "body": [{"p": "Logs & Integrations \u2192 Integration Audit keeps the record of every system that connects to vTiger and the server \u2014 Microsoft Fabric, Power BI, Power Automate, n8n, scripts, backups, reports and ITOps itself \u2014 and the evidence of what they actually did. It is a system of record, not a monitoring agent: it works from evidence you import, and reads nothing from production unless a collector has been approved and switched on."}, {"h": "The golden rule: identifiers attribute, timing only correlates"}, {"bullets": ["CONFIRMED \u2014 an identifier ties the activity to one integration: its DB account, its source host / IP, a job identifier, or the file is that integration's own run history.", "PROBABLE \u2014 only a pattern matches (endpoint or user agent), with no account, host or job identifier.", "UNKNOWN \u2014 nothing matches the registry. It goes to Unknown activity for triage.", "REQUIRES INVESTIGATION \u2014 the identifiers point to more than one integration, or the evidence conflicts.", "EXPECTED / UNEXPECTED is a separate check on attributed activity: did it use the documented account and host, and happen when its schedule says?", "\"Fabric refreshed at 02:03, the database got busy at 02:04 and CPU rose at 02:05\" is temporal correlation. It is shown to help the investigation, and never turns into Confirmed on its own."]}, {"tip": "The single most useful step for the audit is organisational: give every integration its own database account. Then every session names its owner."}], "mod": "integration_audit"}, {"title": "Integration Audit: the five tabs", "for": "admin", "body": [{"bullets": ["Timeline \u2014 pick Previous night (the intensive window, 00:00\u201307:00 by default), Daytime, Last 24 hours, Today or a custom range. Lanes show Fabric, database, API/PHP, cron, backups, ITOps's own log, unknown and unexpected activity; the shaded area is the intensive window; dashed bars are documented schedules (expectations, not evidence); server CPU/load/iowait from sar appears underneath. Click a lane or bar to list it, click a row for the details, its evidence and a temporal-correlation view.", "Registry \u2014 every integration with owner, purpose, connection, identifiers (DB accounts, source hosts, job identifiers, endpoint and user-agent patterns), expected schedule and expected tables. Candidates are leads, not conclusions.", "Unknown activity \u2014 one row per pattern (source, account, host, target) with first/last seen and a count. Add notes, resolve it by linking it to an integration (Confirmed needs the identifying evidence written down), or dismiss it with a reason.", "Evidence \u2014 upload or paste a file, check the preview, then import. Also the Collector Safety Matrix, the monitoring periods, the retention policy and the log of every collector run.", "Reports \u2014 window report, all activity, unexplained activity, evidence gaps, inventory and findings, on screen, as Print / PDF or CSV (exports are recorded in the audit log)."]}, {"h": "Findings"}, {"p": "Correlations are computed on screen and never stored. What a person concludes is saved as a finding: a draft until someone else reviews it (reviewing your own needs an explicit acknowledgement). A Confirmed finding must name the integration and the identifying evidence."}, {"h": "Fill the Registry from the cron list"}, {"steps": ["Registry \u2192 \"Fill from the cron list\u2026\".", "Type the cPanel account (it is filled in with the account the app runs under) and click \"Read from the server\" \u2014 this uses the Server Guardian WHM connection. Or paste the list: crontab -l, or the Current Cron Jobs table copied from cPanel (the header and the Edit / Delete words are ignored).", "Click \"Preview\". \"Where the jobs go\" lists the registry entries that receive jobs, each with its name in a box \u2014 if a name is wrong (for example a hand-made entry called after the wrong product), type the right one there. Leftover guesses whose job now belongs to another entry are listed to be retired (ticked). \"Show the jobs one by one\" opens the detail: each job, when it runs in plain words, and where it goes. A job that matches several entries goes to the one that takes more of the jobs, then to an Active entry over a Candidate; only a real tie is left for you to decide. The jobs one script runs stay together: a new job of a script an entry already runs (for example cron.php audit_export, when \"Main site \u2014 scheduled jobs\" runs the other cron.php jobs) joins that entry \u2014 the entry shows the job names that will be added to its identifiers \u2014 and an entry an earlier fill made for just one of those jobs is listed to be retired as \"merged into\" that entry. When no entry runs the script yet, its jobs become one new entry (\"ops.example.com/cron.php \u2014 scheduled jobs\"). Two entries you made yourself that share a script are left as they are.", "Click \"Apply\". The names you typed are saved, each entry's old cron schedules are replaced by the ones on the server, a Candidate becomes Active, and Unverified becomes Partial (configured on the server, a run not yet seen as evidence). Verified is never lowered. When the WHM backups are watched in IT Operations \u2192 Backups, \"Server backups (cPanel / WHM)\" is linked to it and becomes Verified when a backup arrived in the last 2 days.", "Open each new entry and say what it does and who owns it. Applying the same list again doubles nothing."]}, {"tip": "Tokens and passwords in commands are masked before anything is stored. Reading and applying are written to the Audit Log."}, {"tip": "Untick \"Retire\" to keep a merged entry as it is: its jobs still move to the script's entry. Retired entries keep their history."}], "mod": "integration_audit"}, {"title": "Integration Audit: expected schedules (8 kinds)", "for": "admin", "body": [{"p": "Each integration can have one or more expected schedules. Only activity the schedule can judge is ever marked Unexpected because of the time."}, {"bullets": ["Cron expression \u2014 e.g. 30 2 * * * with a tolerance (default 15 min): expected if it starts within that long after a scheduled time.", "Fixed time window \u2014 e.g. Microsoft Fabric 01:30\u201303:30, daily (days optional; windows may cross midnight).", "Recurring interval \u2014 e.g. n8n every 30 minutes. Not judged by the clock unless you add a window.", "Event-driven \u2014 e.g. Power Automate, irregular. Never judged by the clock unless you add a window.", "Business hours \u2014 Mon\u2013Fri 08:00\u201318:00 unless you set other days/times.", "Ad hoc / manual \u2014 e.g. manual reporting; add a window (business hours) if it should only happen then.", "Continuous \u2014 always expected.", "Unknown / under investigation \u2014 not judged at all (the default for every candidate)."]}, {"tip": "After changing identifiers or schedules, press \"Re-evaluate range\" on the Timeline so evidence already imported is judged against the new registry. Reviewer decisions are never overwritten."}], "mod": "integration_audit"}, {"title": "Integration Audit: importing evidence", "for": "admin", "body": [{"p": "Evidence \u2192 Add evidence. Choose the format, fill in the options it asks for, upload a text file (or paste), and press Upload & preview. Nothing is stored as activity until you press Import. The same file cannot be imported twice by accident."}, {"bullets": ["MariaDB processlist (phpMyAdmin CSV) \u2014 enter when the snapshot was taken; each session's start is estimated from its Time column. Idle connections are skipped unless you tick them.", "Performance Schema digest summary \u2014 only if Performance Schema is already on (ITOps never turns it on).", "MariaDB userstat (USER_/CLIENT_/TABLE_STATISTICS) \u2014 cumulative counters; import two snapshots to compare. Only if userstat is already enabled (an approval item).", "Apache / vTiger access log \u2014 static files are skipped; you can keep only certain paths and ignore office IPs. Query-string values are dropped.", "Cron inventory \u2014 crontab -l or the cPanel list. Records what is scheduled, not what ran.", "sar (sysstat) \u2014 CPU %user/%system/%iowait/%idle, load averages, run queue, memory; stored as server metric samples.", "Fabric / Power BI run history \u2014 JSON from the REST API or a CSV export. Link it to the Microsoft Fabric integration: those runs are then Confirmed as Fabric's runs (they are its own history) \u2014 this says nothing yet about which database queries Fabric made.", "Other CSV \u2014 map the columns yourself (WHM exports, backup logs\u2026), as activity or as metric samples."]}, {"h": "What is never stored"}, {"bullets": ["SQL text: only a digest with the literal values replaced by ?.", "Tokens, keys and passwords in commands and URLs are masked \u2014 in the observations and in the stored copy of the file.", "Evidence files are kept in a folder the web server refuses to serve; downloading one needs Edit permission and is recorded in the audit log."]}, {"tip": "Every timestamp is stored in UTC next to the original value and its timezone. If a file has no timezone in it, the importer uses the one you give (default: server time)."}], "mod": "integration_audit:edit"}, {"title": "Integration Audit: collectors, approval and retention", "for": "admin", "body": [{"p": "Imports are always available and never touch production. The automated collectors \u2014 server load (WHM), MariaDB processlist, MariaDB userstat \u2014 ship OFF. To run one on a schedule:"}, {"steps": ["Its prerequisite must exist: the WHM token (server load), or a DEDICATED MariaDB monitoring account with the PROCESS privilege only, created by the database administrator (processlist, userstat). ITOps never creates accounts, grants privileges, enables userstat or changes any logging.", "A Super Admin records the approval, with a reference (change ticket, email).", "An Integration Audit admin sets a frequency for the intensive period and for the daytime period (both configurable; nothing is pre-set; \"Off in this period\" is allowed).", "A Super Admin presses Enable and types ENABLE.", "An administrator adds cron-audit.php to cron (it only accepts the X-ITOps-Cron-Token header). Until then nothing runs."]}, {"p": "\"Test connection\" only checks the login. \"Run once\" is a real read of production and therefore also needs the approval. The Fabric API collector is a later phase (it needs its own reviewed app registration) \u2014 use the history import meanwhile."}, {"h": "Retention"}, {"p": "Nothing is purged until an admin saves a retention policy with purge switched on (starting point: 90 days of raw observations and server metrics, 1 year of evidence files and collector runs). Raw observations are rolled up per hour before deletion. Findings, unknown-activity decisions, the registry and the audit log are never purged."}], "mod": "integration_audit:admin"}, {"title": "360 Monitoring: outside checks beside Uptime", "for": "admin", "mod": "uptime", "body": [{"p": "360 Monitoring is an outside service that watches servers (with its agent) and websites from its own locations. Its results are shown beside the checks this server runs itself: IT Operations \u2192 Uptime \u2192 360 Monitoring."}, {"h": "Connect it (Super Admin, or Integrations \u00b7 Edit)"}, {"steps": ["In 360 Monitoring: your profile menu \u2192 API Keys \u2192 create a key. API access needs its Business or Enterprise plan.", "Settings \u2192 Company systems \u2192 Company tools \u2192 360 Monitoring \u2192 Set up\u2026 \u2192 Connection and alerts.", "Paste the key and click \"Test and save\". A wrong key is refused and nothing is saved. The key is stored encrypted, sent only in the request header and never shown again."]}, {"h": "Alerts \u2192 tickets"}, {"bullets": ["Tick \"Open a ticket for each problem\", choose the ticket category and the priority, and Save. The alerts are checked every 5 minutes.", "One ticket per problem: while its ticket is open, the same alert again is added to it as a note, and a note says when the alert ended.", "Alerts that are over within the minutes you set (5 by default) are only recorded, without a ticket.", "\"Check alerts now\" runs the check at once. Every check that made or changed a ticket, every setting change and every refusal is in the Audit Log."]}, {"tip": "360 Monitoring allows 1,500 requests an hour per key. Its lists are kept for two minutes and each check reads at most 60 servers and monitors; the rest are read on the next check."}]}]}, {"cat": "Microsoft 365 & integrations", "topics": [{"title": "Microsoft 365 data kept fresh in the background", "for": "everyone", "mod": "m365", "body": [{"p": "The Microsoft 365 pages read Microsoft. To spare you the wait, the server reads them ahead of time and keeps what it read, so pages open at once. Since build BT72 this starts as soon as you sign in: for someone whose role sees Microsoft 365, the app asks the server to read every Microsoft 365 page that role can open (two at a time, in the background) and again every 15 minutes while the app is open. The scheduled job keeps the chosen pages fresh too, also when nobody is signed in."}, {"h": "How a page opens (BT72)"}, {"bullets": ["A copy younger than 10 minutes (or kept fresh by the background job) opens at once.", "An older copy, up to 24 hours, also opens at once; the app then asks the server for a new read in the background, so the next look is current. Nothing to click.", "With no copy at all (the very first time), the page reads Microsoft and keeps the answer.", "This covers every Microsoft 365 page: Home (also Rollout), People, Email (also Email security), Devices (also Device policies), Licenses, Security (also Alerts & actions, Access & sign-in) and Collaboration & activity.", "Not kept: Diagnose and the scans you start with a button (Scan mailboxes, Check Copilot, Coverage, the license check): those always read now.", "Anything changed through the Microsoft 365 pages drops every kept copy at once, so a change is never hidden behind an old copy. The \"Refresh\" button of a page always reads Microsoft.", "Only people whose role has Microsoft 365 \u00b7 View are given these pages; a kept copy is never shown to anyone else."]}, {"h": "The line at the top"}, {"bullets": ["\"Microsoft 365 data updated 10:45 (2 min ago) \u00b7 next about 11:00\": when the pages were last read, and when the next read is due.", "\"Refresh now\" reads everything chosen at once. It runs in the background; when it is done, the pages read again. A form you are filling in and the Accounts list stay as they are.", "Amber: a read failed (it is named, with Microsoft's words) or the scheduled job seems not to run. The last good copy of that page is kept.", "Each page's own \"Refresh\" still reads Microsoft at once. Anything you change here (an account created, edited or licensed) shows at once."]}, {"h": "Settings", "mod": "integrations:edit"}, {"steps": ["Click \"Settings\" on the line (needs Integrations with Edit).", "Tick \"On\", choose how often in business hours (10, 15, 30 or 60 minutes) and outside them (30 minutes to 4 hours, or not at all).", "Tick what to keep fresh: Accounts, Licenses, Devices, Security, Service health, Groups, Guests (on by default); Apps and Usage reports (Microsoft updates those once a day).", "Click \"Save\". The change is in the Audit Log."], "mod": "integrations:edit"}, {"p": "Business hours are the ones under Settings \u2192 SLA & Hours; when those are not set, Monday to Friday 7:00 to 19:00. The reading is done by the scheduled job (cron-sla.php every 15 minutes, or the in-app scheduler). Reads only: nothing is changed in Microsoft. Each read is written to the Event Log (channel m365)."}, {"qa": [{"q": "The line says the data is late.", "a": "The scheduled job is not running. Check the cron job (Settings \u2192 SLA & Hours) or that the in-app scheduler is on (Settings \u2192 Email \u2192 Schedule)."}, {"q": "A page shows data older than I expected.", "a": "Use the page's own \"Refresh\" or \"Refresh now\" on the line. A change made directly in the Microsoft 365 admin center shows within about 10 minutes (the next read), or at once after \"Refresh\"."}, {"q": "Several pages showed \"Something went wrong on the server\" at the same moment.", "a": "Usually the database was busy for a moment (the hosting account's connection limit, a restart or a nightly backup). From build BT55 the app rides out a short blip by itself, reads try once more on their own, and a longer one says \"The database is busy or not answering right now (MySQL error n)\" with a reference. Give that reference to IT: the same reference is in the server error log. The Microsoft 365 pages also read at most 4 things at a time, so they no longer cause such a burst."}, {"q": "Security shows \"Needs SecurityEvents.Read.All\" on Microsoft's next recommended actions.", "a": "The app registration does not have that permission yet. In Entra: App registrations \u2192 your app \u2192 API permissions \u2192 Add \u2192 Microsoft Graph \u2192 Application permissions \u2192 SecurityEvents.Read.All \u2192 Add, then \"Grant admin consent\". The card shows at the next read."}]}]}, {"title": "The Microsoft 365 area", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 has its own section in the menu, organised by what you manage. Each fact has one home; other pages link to it. Each page has a row of tabs at the top."}, {"bullets": ["Home: \"Needs attention\" (every problem in one prioritised list \u2014 Critical, Warning, Info \u2014 each with \"Fix \u2192\"), \"Overview\" (cards for licenses, reclaimable seats, directory sync, device compliance, Secure Score, alerts, MFA gaps, service health, mailboxes, Teams, storage, Copilot, recommendations, app secrets, personal computers; click a card to open its screen), \"Service health\" (services, issues and Message center posts), and after a thin line \"Rollout\" and \"Diagnose\" (Super Admin).", "People: \"Accounts\" (search the directory and manage one person), \"Onboard\", \"Offboard\", \"Groups\" (owners and members), \"Guests\", \"MFA\" (who is registered), \"At risk\" (the people the security assessment finds at risk, their follow-up and the changes waiting for approval) and \"History\".", "Email: \"Mailboxes\" (every user, shared, room and equipment mailbox; click one for its \"send on behalf\" delegates and calendar access), \"Distribution lists\" (and who is in each), \"Message trace\" (was it sent, delivered or blocked) and \"Email security\" (SPF, DKIM and DMARC per domain, the mailbox scan for forwarding and hidden rules, and the Exchange Online controls).", "Devices: \"Device inventory\" (every device in Entra and Intune, with its actions and recovery keys), \"Compliance\" (Intune compliance; Sync, Lock, and \"More\" for restart, Defender scan, retire, wipe and fresh start), \"Apps\" (apps Intune installs, and the software found on devices), \"Configuration\" (configuration profiles), \"Update rings\" (Windows updates: pause and resume), \"Device policies\" (compliance and app-protection policies, device security, back up and restore) and \"Wipe & retire\" (the requests waiting for a second person's approval).", "Licenses: \"Licenses\" (seats per subscription; click one for its holders), \"Reclaim\" (disabled or idle accounts that still hold licenses), \"Reconcile\" (Microsoft 365 \u2194 vTiger \u2194 ITOps sign-ins, matched by email) and \"Coverage\".", "Security: \"Alerts & actions\" (the one list of Defender alerts and incidents, which you can work and resolve), \"Secure Score\" (the score and Microsoft's next recommended actions), \"Access & sign-in\" (Conditional Access, sign-in methods, admin roles), \"App secrets\", \"Enterprise apps\" and \"Recommendations\".", "Posture: the security assessment (findings, history, schedule).", "Collaboration & activity: \"Teams\", \"Storage\" (OneDrive and SharePoint), \"Copilot\" and \"Audit log\" (the Entra directory audit log)."]}, {"p": "Old bookmarks and links still open the right place: the former Overview, Accounts, Licensing, Entra ID, Usage & health, Security assessment and Risky people pages open Home, People, Licenses, People, Collaboration & activity, Posture and People \u2192 At risk."}, {"bullets": ["Reports are kept for 10 minutes so the screens open fast. The description then ends with \"\u00b7 cached\"; click \"Refresh\" to read Microsoft again.", "When a screen needs a Graph permission your Azure app doesn't have yet, it says \"Permission not granted\" and names the permission. Add it in Azure with admin consent, then click Refresh.", "Dates are shown as MM/DD/YYYY in the installation's time zone.", "Anything that changes accounts or licenses clears the cache, so a removed license disappears from the lists right away."]}, {"tip": "Tabs you have opened stay ready while you move between them, and the data behind the other tabs of a page loads in the background, so switching is instant."}, {"qa": [{"q": "I don't see Microsoft 365 in the menu.", "a": "Your role needs \"Microsoft 365 \u00b7 View\". People also shows for roles that only have \"Onboarding templates & history\" (just the History tab) or \"Security assessment\" (just At risk)."}, {"q": "A tab I expect is missing.", "a": "Onboard and Offboard need \"Microsoft 365 \u00b7 Accounts\"; History needs \"Onboarding templates & history\" (view); Diagnose is Super Admin only."}, {"q": "Where did Entra ID, Usage & health and Risky people go?", "a": "Their tabs moved to where they are used: MFA, Groups and Guests to People; Device inventory to Devices; App secrets, Enterprise apps, Recommendations and Access & sign-in to Security; the Entra audit log, Teams, Storage and Copilot to Collaboration & activity; Service health to Home; Mailboxes to Email; Risky people to People \u2192 At risk. The Overview cards and the \"Fix \u2192\" links open them there, and old links still work. Permissions did not change."}]}]}, {"title": "Connecting Microsoft 365", "for": "admin", "mod": ["m365_admin", "settings:edit", "m365"], "body": [{"p": "ITOps talks to Microsoft 365 through one Azure (Entra ID) app registration. Connect it once and the whole Microsoft 365 area, Server Guardian's Microsoft 365 cards and onboarding / offboarding all work."}, {"steps": ["In Azure \u2192 App registrations, create or open the ITOps app. Note its Directory (tenant) ID and Application (client) ID, and create a client secret.", "Under API permissions, add the Application permissions you need (see \"What Microsoft 365 permissions ITOps needs\") and click \"Grant admin consent\".", "In ITOps, go to Logs & Integrations \u2192 Integrations \u2192 \"System\" tab \u2192 \"Microsoft 365 connection\".", "Enter the \"Tenant ID\", \"Client ID\" and \"Client secret\", then click \"Save Microsoft 365 settings\".", "Open Microsoft 365 \u2192 Home \u2192 \"Diagnose\" and click \"Refresh token & re-test\". Each capability should show \u2713 OK."], "bullets": ["The \"System\" tab is Super Admin only.", "The client secret is write-only and stored encrypted. Leave it blank to keep the saved one.", "Microsoft sign-in (SSO) uses the same configuration \u2014 there is one tenant, one client ID and one secret for both. If the upgrade found two different saved secrets, a yellow note asks you to save the current one once."]}, {"warn": "When the Azure client secret expires, every Microsoft 365 feature stops and Diagnose shows a token error. Create a new secret in Azure and save it here (and in Settings \u2192 Sign-in & AI too if you use SSO or Graph mail)."}, {"tip": "After you add a permission in Azure, click \"Refresh token & re-test\". ITOps caches the token, so a new consent is not seen until the token is refreshed."}]}, {"title": "Setting up the Teams app", "for": "admin", "body": [{"p": "Logs & Integrations \u2192 Integrations \u2192 \"Microsoft Teams\" turns ITOps into an app inside Teams: a tab with automatic sign-in, notifications in each person's Teams activity feed, and announcements that are confirmed inside Teams. Super Admin only. Nothing changes for people who keep using the browser."}, {"h": "What you need first"}, {"bullets": ["ITOps served over HTTPS (the page checks this).", "Microsoft 365 sign-in already working (Settings \u2192 Sign-in & AI). Teams uses the same Azure app registration and the same rules: a person without an ITOps account gets one with the Viewer role on first use, and a disabled or inactive account is refused.", "Microsoft Graph connected, for the Teams notifications. The tab and the sign-in work without it.", "The current .htaccess from the install package on the server: it allows Teams, and only Teams and Microsoft 365, to show ITOps in a frame."]}, {"h": "1. In Azure (once)"}, {"steps": ["Entra admin center \u2192 App registrations \u2192 your ITOps app \u2192 \"Expose an API\".", "Set \"Application ID URI\" to the value shown on the page (api://your-address/client-id). Use \"Copy\".", "\"Add a scope\" named access_as_user, for admins and users.", "\"Add a client application\" for the two Teams client IDs shown on the page, ticking the scope. The IDs for Outlook and the Microsoft 365 app are optional.", "Under \"Manifest\", set requestedAccessTokenVersion to 2 and save."]}, {"h": "2. Switch it on and add it to Teams"}, {"steps": ["Click \"Switch on\", then \"\u2b07 Download the app package\". The zip contains the app description and two icons, named after your ITOps.", "Teams admin center \u2192 Teams apps \u2192 Manage apps \u2192 Actions \u2192 \"Upload new app\" \u2192 choose the zip.", "Teams apps \u2192 Setup policies \u2192 your policy \u2192 add the app under \"Installed apps\" and \"Pinned apps\". Everyone then has it without installing it themselves; allow a few hours.", "To try it alone first: Teams \u2192 Apps \u2192 Manage your apps \u2192 Upload an app \u2192 Upload a custom app (your tenant must allow custom app uploads)."]}, {"tip": "If you rename ITOps or move it to another address, download the package again and upload it as an update. The version number goes up by itself, which Teams requires."}, {"h": "3. Notifications in Teams"}, {"bullets": ["Three switches choose what is copied to each person's Teams activity feed: \"Announcements\" (on), \"Tickets\" and \"Alerts and reminders\" (off until you tick them).", "They are sent by the scheduled job a few minutes after the bell, only to people who have the app in Teams. Switching a kind on never sends older notifications.", "\"Send me a test\" sends one to you and explains a refusal. The line under it shows the last run: sent, people without the app, failures.", "Normally nothing is needed in Azure for this: the permission travels in the app package. If the test reports a refusal after you uploaded the current package, add the Graph application permission TeamsActivity.Send with admin consent."]}, {"h": "4. Device inventory"}, {"p": "\"Add the device people open ITOps on to the Device inventory\" records, at sign-in, the operating system and the browser or Teams client as the browser reports them \u2014 in Teams and in a normal browser. See \"Device inventory: every computer that signs in\"."}, {"h": "If something does not work"}, {"qa": [{"q": "The tab stays blank or Teams says the app cannot be reached.", "a": "Check that the server has the .htaccess from this build (Teams must be allowed to frame the page) and that the address in the package is the HTTPS address people can reach."}, {"q": "\"The token was issued for another application\".", "a": "The Application ID URI on the Azure app is not the value shown on the setup page. Copy it again; the address part must be in lower case."}, {"q": "\"The token does not carry the access_as_user scope\".", "a": "Add the scope under \"Expose an API\", and tick it for each client application."}, {"q": "Teams asks every person for consent.", "a": "The Teams client IDs are not pre-authorized. Add them under \"Expose an API\" \u2192 \"Add a client application\"."}, {"q": "Notifications do not arrive.", "a": "The person must have the app in Teams (setup policy, or installed by hand), the package must be the current one, and the scheduled job must be running. \"Send me a test\" names the cause for your own account."}, {"q": "How do I turn it off?", "a": "\"Switch off\" stops the sign-in from Teams and the Teams notifications at once. Remove the app in the Teams admin center when you no longer want it listed."}]}]}, {"title": "What Microsoft 365 permissions ITOps needs", "for": "admin", "mod": ["m365_admin", "settings:edit", "onboarding:edit", "m365"], "body": [{"p": "The Azure app needs Application permissions (not Delegated), each with \"Grant admin consent\". Add only what you use. The onboarding \"Pre-flight check\" names any permission a step is missing."}, {"h": "Onboarding, offboarding and Microsoft 365 \u2192 People"}, {"bullets": ["User.ReadWrite.All: create, update and disable users, edit contact information and custom attributes 1 to 15, set and remove the manager, assign and remove licenses, revoke sessions. Phone numbers of accounts that hold an administrator role are the exception: Microsoft refuses an application there, whatever the permission.", "GroupMember.ReadWrite.All (or Group.ReadWrite.All): add to and remove from groups. Group.ReadWrite.All is also what changing group owners and creating groups on People \u2192 Groups need; it is optional.", "Organization.Read.All: read licenses and seat counts.", "MailboxSettings.ReadWrite: auto-reply and the forwarding rule.", "Files.ReadWrite.All (or Sites.ReadWrite.All): share a leaver's OneDrive.", "UserAuthenticationMethod.ReadWrite.All: \"Reset MFA\", sign-in methods and Temporary access pass on Microsoft 365 \u2192 People."]}, {"h": "Read-only pages and Guardian"}, {"bullets": ["User.Read.All: Users tab and offboarding verification.", "Reports.Read.All: Usage tab. Reports.Read.All or AuditLog.Read.All: MFA registration (2FA adoption card and scorecard).", "ServiceHealth.Read.All: Service Health tab (optional).", "SecurityEvents.Read.All and SecurityIncident.Read.All: Microsoft Defender card.", "DeviceManagementManagedDevices.Read.All: Intune device compliance.", "GroupMember.Read.All (or Group.Read.All): announcements and ticket notices to a Microsoft 365 group or distribution list read its members when they are sent."]}, {"h": "Email through Graph"}, {"bullets": ["Mail.Send to send, and Mail.ReadWrite to turn mailbox messages into tickets."]}, {"tip": "Check your work in Microsoft 365 \u2192 Home \u2192 Diagnose: \"Permissions in token\" lists what the token really carries, \"App registration in Azure\" shows what is still waiting for admin consent or was added as Delegated, \"Permissions that change something\" says for each kind of change whether it is Granted, Not granted or Not granted (optional), and the capability table shows which read tests pass \u2014 with the reason next to each one that fails. See \"I added a permission and it still says 403\"."}, {"h": "Optional extras (reports)"}, {"bullets": ["DeviceManagementManagedDevices.Read.All \u2014 the Devices tab (DeviceManagementManagedDevices.PrivilegedOperations.All adds the Sync and Lock buttons).", "DeviceManagementConfiguration.ReadWrite.All \u2014 read AND edit compliance policies, the All-policies inventory, backup/restore/clone and baseline seeding.", "DeviceManagementApps.ReadWrite.All \u2014 app-protection (MAM) policies for personal phones (edit, back up, clone) and the phone-apps column of Rollout \u2192 Readiness (Read.All is enough for that).", "Policy.Read.All \u2014 the Conditional Access card; Policy.ReadWrite.ConditionalAccess \u2014 create sign-in rules from templates and change their state; Policy.ReadWrite.SecurityDefaults \u2014 turn Security Defaults off.", "MailboxSettings.Read (ReadWrite to disable rules) \u2014 the mailbox forwarding/rules audit. Mail.ReadWrite is only needed for email-to-ticket through Graph; scope it to the help-desk mailbox with RBAC for Applications.", "SecurityEvents.Read.All / SecurityIncident.Read.All / SecurityAlert.Read.All \u2014 the Defender panel (SecurityAlert.ReadWrite.All to resolve alerts from ITOps).", "AuditLog.Read.All \u2014 the MFA registration report, idle-license detection and the sign-in log behind Devices \u2192 Device inventory (idle detection and the sign-in log also need an Entra ID P1 licence in the tenant).", "Device.Read.All \u2014 the Entra device list behind Devices \u2192 Device inventory (read-only).", "Device.ReadWrite.All \u2014 disable, enable and remove Entra devices from the Device inventory (replaces Device.Read.All). Disabling may also need the Entra role \"Cloud Device Administrator\" on the ITOps enterprise application.", "BitlockerKey.Read.All \u2014 show a BitLocker recovery key (BitlockerKey.ReadBasic.All only lists that a key exists). DeviceLocalCredential.Read.All \u2014 show the local administrator password kept by Windows LAPS.", "People \u2192 Groups needs nothing new when GroupMember.ReadWrite.All (listed above) is granted. With only Group.Read.All the list works, read-only.", "People \u2192 Guests needs nothing new: it uses User.Read.All, and User.ReadWrite.All to block or remove a guest.", "Directory.Read.All \u2014 the delegated permissions (what administrators and people consented to) on Security \u2192 Enterprise apps. The applications themselves and their application permissions use Application.Read.All.", "Collaboration & activity \u2192 Audit log uses AuditLog.Read.All, already listed above.", "TeamsActivity.Send \u2014 only if Teams refuses the notifications of the Teams app (normally the permission comes with the app package). The Teams sign-in itself needs no Graph permission: it uses \"Expose an API\" on the same app.", "Application.Read.All \u2014 the app-registration secret/certificate expiry list.", "Policy.ReadWrite.AuthenticationMethod \u2014 allow or turn off sign-in methods (Security \u2192 Access & sign-in \u2192 Sign-in methods). UserAuthenticationMethod.ReadWrite.All (already listed for Reset MFA) also covers Temporary pass and removing a single method.", "Without them, those panels show a card naming the missing permission; everything else keeps working.", "DeviceManagementServiceConfig.Read.All \u2014 reads the enrolment restrictions so the Devices tab can warn when personal Windows PCs are allowed to enrol (BT15). DeviceManagementConfiguration.ReadWrite.All (already listed for the compliance editor) is what \"Seed device security\" uses."]}, {"p": "RoleManagement.Read.Directory (or Directory.Read.All) \u2014 the admin-roles list, and the check that stops non-Super Admins from resetting the password, issuing a Temporary pass or resetting MFA for an account that holds a Microsoft 365 admin role. Without it, those actions are Super Admin only."}, {"warn": "High-value permissions \u2014 review them monthly and keep only what you use: User.ReadWrite.All, UserAuthenticationMethod.ReadWrite.All, Policy.ReadWrite.ConditionalAccess, DeviceManagementConfiguration.ReadWrite.All, Files.ReadWrite.All / Sites.ReadWrite.All, Mail.ReadWrite, Device.ReadWrite.All, BitlockerKey.Read.All and DeviceLocalCredential.Read.All. Check what the token really carries under Microsoft 365 \u2192 Home \u2192 Diagnose \u2192 \"Permissions in token\"."}, {"p": "Limiting mail access: Microsoft's current way to restrict an app to certain mailboxes is Exchange Online \"RBAC for Applications\" (Application Access Policies are now legacy). Scope Mail.ReadWrite / Mail.Send to the help-desk mailbox that way and remove the tenant-wide Mail.* consent in Entra. The mailbox-rule audit uses MailboxSettings.Read/ReadWrite, so it keeps working across all mailboxes."}, {"p": "The full list \u2014 every permission, what uses it and whether it can be removed \u2014 is in BT14-SECURITY-VALIDATION.md in the support files pack (Reference folder)."}]}, {"title": "I added a permission and it still says 403", "for": "admin", "body": [{"p": "You added a permission in Azure, came back, and the feature still says \"403\" or \"token doesn't have the required permissions\". Microsoft 365 \u2192 Home \u2192 Diagnose tells you which of four things happened, so you do not have to guess. Click \"Refresh token & re-test\" first: it throws away the saved token and asks Microsoft for a new one."}, {"h": "Where to look"}, {"bullets": ["\"App registration in Azure\" (the card names your app): \"Waiting for admin consent\" lists the permissions that are on the app but not in the token. \"Delegated permissions\" lists the ones added with the wrong type.", "\"Live capability tests\": every test that fails with 401 or 403 has a boxed line under Microsoft's message that names the cause.", "\"What to do\" at the top repeats the actions in order."]}, {"h": "The four causes"}, {"qa": [{"q": "\"Admin consent missing\"", "a": "The permission is on the app as an Application permission, but nobody clicked \"Grant admin consent for (your organization)\". Until then Microsoft leaves it out of the token. In Azure \u2192 App registrations \u2192 your app \u2192 API permissions, click that button \u2014 it needs a Global Administrator or a Privileged Role Administrator \u2014 and wait until the Status column shows a green tick \"Granted for \u2026\". Then \"Refresh token & re-test\"."}, {"q": "\"Added as Delegated\"", "a": "Azure offers every permission twice: \"Delegated permissions\" (for a person who signs in) and \"Application permissions\" (for an app that works on its own). ITOps works on its own, so only Application permissions reach it \u2014 a Delegated one does nothing here, even with consent. Add it again: Add a permission \u2192 Microsoft Graph \u2192 \"Application permissions\" \u2192 the same name, then Grant admin consent. You can remove the Delegated one."}, {"q": "\"Not on this app\"", "a": "The permission is not on this app registration at all. If you did add it, it went to another app: compare the Application (client) ID in Azure with \"Client (app) ID\" on Diagnose. Organizations often have two apps with similar names."}, {"q": "\"Permission is granted\"", "a": "The permission is in the token and Microsoft still said no, so it is not a permission problem. Usual reasons: the organization does not have the licence the feature needs (Entra ID P1 for sign-in data, Intune for device policies), the feature is switched off, or the change is still spreading inside Microsoft \u2014 wait a few minutes and re-test."}]}, {"h": "Good to know"}, {"bullets": ["Diagnose only reads. Nothing on this screen changes your organization.", "Reading the app registration uses Application.Read.All (the same permission the \"App registrations\" secret-expiry check uses). Without it the card says so and the tests below still work; the boxed line then tells you what to check by hand.", "A new consent normally shows up within a minute. If the permission is still \"waiting\" after you granted it, look at the Status column in Azure: \"Not granted for \u2026\" means the click did not go through.", "The names Diagnose asks for are the exact names to pick in Azure, for example BitlockerKey.Read.All, DeviceLocalCredential.Read.All and DeviceManagementServiceConfig.Read.All."]}, {"tip": "Messages in the browser's developer console such as \"Permissions policy violation: unload is not allowed\" from a file called frame.js come from a browser extension or from Microsoft Teams, not from ITOps, and can be ignored."}]}, {"title": "Accounts: the list (search, filter, columns, changing a cell, actions)", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 People \u2192 \"Accounts\" is a grid: every account, one per row, like a spreadsheet. The first view is the domain your organization chose in Settings \u2192 Company systems \u2192 \"Microsoft 365 \u00b7 People \u2014 the domain shown first\" (else Microsoft's default domain, for example \"@example.org\"); guests and the other domains are under \"All domains\"."}, {"h": "Finding accounts"}, {"bullets": ["The search box looks in the name, the sign-in name, the email and the columns shown.", "Under every heading is a filter. A column with a short list of values (Sign-in, Licenses, vTiger, a field with choices\u2026) offers them to pick, with \"(empty)\" for the rows without a value. Any other column takes a part of the text; type (empty) to see the rows without one.", "Click a heading to sort by it. Click again for the other direction, a third time to go back to the name.", "The domain list next to the search box shows one domain, with how many accounts it has: the domains Microsoft lists and those the accounts use. Your choice, \"All domains\" too, is remembered on that browser. \"Show all\" brings everyone back.", "\"Clear filters\" removes the search and every filter.", "Under the grid: where you are (\"1\u201350 of 758\"), \"\u2190 Previous\", \"Next \u2192\" and \"Rows per page\" (25, 50, 100 or 250)."]}, {"h": "Choosing the columns"}, {"steps": ["Click \"Columns\" and tick the ones to show: sign-in state, job title, department, company, office, phones, fax, your own custom fields, manager, email, first and last name, employee ID and type, the address, usage location, licenses, vTiger, other systems, type, created, last sign-in.", "\"Manager\" and \"Last sign-in\" are marked \"slower\": they are read from Microsoft only while their column is shown, and take a few seconds more.", "The order: \"Columns\" lists the columns shown under \"Shown, left to right\", numbered. \u25b2 moves one to the left, \u25bc to the right. You can also drag a heading in the list and drop it on another. A column you tick under \"Hidden\" takes its usual place; move it from there.", "\"Back to the standard columns\" undoes your choice and the order. The name is always first. Your columns and their order are remembered on that browser."]}, {"h": "Changing a value in the grid"}, {"steps": ["Click the cell: job title, department, company, office, a phone, the fax, a custom field, the address\u2026 A box opens in the cell. A custom field with choices opens as a list.", "Type the value and press Enter, or click elsewhere. Esc leaves the cell as it was.", "The cell is saved exactly as \"Edit Microsoft 365 info\" saves it: checked by the same rules, sent to Microsoft 365, and written to the Audit Log with your name, the account, the old value and the new one.", "If Microsoft 365 refuses the value, the reason shows under the cell and nothing changes. \"Leave it as it was\" closes the box."]}, {"bullets": ["Not changed in the grid: the sign-in name and the email (they change the mailbox), the manager, licenses and groups. Open the account for those.", "An account copied from an on-premises directory cannot be changed here; change it in that directory.", "Changing a cell needs \"Microsoft 365 \u00b7 Accounts\"."]}, {"h": "Actions on a row"}, {"p": "The last column, \"Actions\", does the common things without opening the account. Each one asks first."}, {"bullets": ["\"Open the account\" and \"Edit contact information\u2026\".", "\"Reset password\u2026\": a strong temporary password, to be changed at next sign-in. It is shown once in a box above the grid, with \"Copy\".", "\"Reset MFA\u2026\" and \"Revoke sessions\u2026\".", "\"Block sign-in\u2026\" or \"Restore sign-in\u2026\". You cannot block your own account.", "\"Offboard\u2026\" opens the Offboard tab with that person.", "The result of each action stays above the grid until you remove it with \u2715."]}, {"h": "The account, in a panel on the right"}, {"p": "Click a name. The account opens in a panel that slides over the right part of the list, below the tabs, with everything described in \"Accounts: managing one person\". The list underneath stays as it was: search, filters and page. \u2039 and \u203a go to the previous and the next account of the list. \"Edit Microsoft 365 info\" opens inside the same panel; \"\u2190 Back to the account\" returns to it. \"\u2715 Close\" or Esc closes the panel. When you changed something and did not save, ITOps asks first. On a phone the panel takes the whole screen; \"\u2190 Back to the list\" returns."}, {"h": "Several accounts at once"}, {"p": "Tick the rows: the box in the heading ticks the page, and \"Select all N\" takes every row that matches. \"Edit selected\u2026\" opens the page described in \"Editing several accounts at once\"."}, {"h": "Export"}, {"p": "\"Export CSV\" saves the rows that match, on every page, with the columns shown."}, {"qa": [{"q": "The list is not what Microsoft 365 shows right now.", "a": "The list is read from Microsoft 365 and kept for five minutes; the line under the search box says when it was read. \"Refresh\" reads it again. A change you make here shows at once."}, {"q": "\"Last sign-in\" says \"not available\".", "a": "Sign-in dates need Entra ID P1 and the permission AuditLog.Read.All."}, {"q": "I cannot click a cell.", "a": "Your role needs \"Microsoft 365 \u00b7 Accounts\"; or the account is copied from an on-premises directory; or that column is not a value of the account (the sign-in state, licenses, vTiger, other systems)."}, {"q": "I see no boxes to tick.", "a": "Ticking rows is for changing several accounts, which needs \"Microsoft 365 \u00b7 Accounts\"."}, {"q": "A person I expect is missing.", "a": "Look at the domain list: guests and the accounts of another domain are under \"All domains\". Then click \"Clear filters\"."}, {"q": "Where is the column \"Other systems\"?", "a": "It needs the permission \"Company systems\" (View)."}, {"q": "The page opens on \"@example.org\". I want everybody.", "a": "Choose \"All domains\" once. It is remembered on that browser."}, {"q": "My custom fields are not in the list.", "a": "Click \"Columns\": your own fields are marked \"\u00b7 custom\". A ticked one is in the list, after the standard columns, so on a narrow screen it may be off to the right: scroll the list, or move the column to the left with \u25b2 in \"Columns\" (or drag its heading). An empty cell means the account has no value in that field yet; a value kept somewhere else, for example an extension typed in \"Department\", is not copied by itself."}]}]}, {"title": "Accounts: managing one person (password, MFA, licenses, groups, roles)", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 People \u2192 \"Accounts\" lists your directory as a grid, one account per row (see \"Accounts: the list\"). Click a name: the account opens in a panel over the right part of the list. The green or amber dot before a name shows whether sign-in is enabled; the column \"vTiger\" shows the linked vTiger user (\u2605 = vTiger admin, \"no vTiger\" = nobody matched)."}, {"p": "The panel on the right starts with the person's name and \"Actions\": the ones your role allows. Under them: the profile in three columns (job title, department, company, manager, office, phone numbers, your own custom fields), the block \"Systems\", then licenses, groups, sign-in methods, directory roles and recent sign-ins. \"Edit Microsoft 365 info\" at the top opens the edit page; \"+ Show change history\" lists what was changed on this account from ITOps, by whom and when. To change several accounts together, tick their rows in the list and choose \"Edit selected\u2026\". \u2039 and \u203a at the top of the panel go to the previous and next account; \"\u2715 Close\" or Esc closes it. On a phone the panel opens full width; \"\u2190 Back to the list\" returns. The change history is shown to people who edit accounts or who can read the Audit Log."}, {"h": "Systems: every system for this account"}, {"bullets": ["One row per system. Microsoft 365: sign-in enabled or blocked, how many licenses and groups. vTiger: the linked user and its status, in red with \"still active while Microsoft 365 is blocked\" when that is so. Then every company system in use (HubSpot, JustCall, eFax\u2026) with the person's account there.", "A system tracked by hand: \"+ Record an account\" opens a box for the account name and a note, in place. \"Edit\" corrects it. \"Close\" records that the account was removed in that system; ITOps does not remove it there. \"+ Show closed accounts\" lists what was closed, by whom and when, and offers \"Open again\".", "A connected system (JustCall) shows what was read from it, with \"Read from JustCall: change it there.\"", "In the list, the column \"Other systems\" says \"+2 system accounts\": how many accounts the person has in the other systems. It is red, with \"still open\", when their sign-in is blocked.", "The rows of the company systems need the permission \"Company systems\" (View; Edit to record, correct and close). Without it the block shows Microsoft 365 and vTiger only.", "There is no second list of the people under Company systems. The ones to look at are under Microsoft 365 \u2192 People \u2192 \"Needs attention\"."]}, {"h": "Showing one domain only"}, {"p": "When the organization has more than one verified domain, a list next to the search box lets you pick one. The first view is your default domain, for example \"@example.org\". The list then holds only the accounts whose sign-in name ends with that domain, and a line says how many there are. The search and the filters keep working inside the domain."}, {"bullets": ["\"All domains\" (or \"Show all\") brings everyone back.", "Your choice, \"All domains\" too, is remembered on that browser, so the screen opens the same way next time.", "Guests sign in with another organization's address, so they appear under \"All domains\" (and under the \".onmicrosoft.com\" domain), not under your own domains.", "An organization with a single domain does not get the list."]}, {"h": "Editing the account and the vTiger user"}, {"p": "At the top right of the account panel: \"Edit Microsoft 365 info\" changes the person's Microsoft 365 contact information, and \"Edit vTiger user\" (shown when the person has a vTiger user and your role has vTiger \u00b7 Users) opens their vTiger profile, employee record and password inside the panel. \"\u2190 Back to the account\" returns to the account. Everything about a person's accounts is in one place."}, {"h": "How a person is linked to their vTiger user"}, {"steps": ["By email: a vTiger user whose email is the person's email or sign-in name. This is the normal case and the badge reads \"vTiger: jdoe\".", "By user name, only when no email matched: a vTiger user whose user name is the part of the sign-in name before the \"@\" (jdoe@example.org \u2192 \"jdoe\"). The badge then adds \"\u00b7 by user name\", and hovering it shows the email that is on the vTiger record."]}, {"bullets": ["A match by user name is a strong hint, not proof: two people on different domains can share the same first part. So when you offboard, \"Deactivate linked vTiger user\" starts unticked for these, with a note asking you to check it is the same person. Matches by email start ticked, as before. ITOps never deactivates such a vTiger user, or moves its records, until a person has confirmed it is the same person (see \"Offboarding in vTiger: reassign, then deactivate\").", "Guests are matched by email only.", "If two vTiger users match, the active one is used, then an admin, then the oldest.", "The same rule is used by Reconcile, the Offboard tab and the offboarding steps in History, so they always agree with this screen."]}, {"warn": "\"vTiger users are not shown.\" in amber at the top of the list means ITOps could not read vTiger at all \u2014 the message says why. The usual reason is an older bridge file on the vTiger server: upload vtiger-bridge/itops-bridge.php (build o5) from the install package to the vTiger web root, next to config.inc.php. Same secret, nothing else to change; then Integrations \u2192 vTiger provisioning \u2192 \"Test bridge\" should say build o5."}, {"h": "Actions, at the top of the panel (each asks to confirm in place)"}, {"bullets": ["\"Reset password\" \u2014 generates a strong 16-character temporary password. Tick or untick \"Require change at next sign-in\", then \"Generate & reset\". The password is shown once, with \"Copy\".", "\"Reset MFA\" removes every MFA method; they register again at next sign-in. \"Revoke sessions\" signs them out everywhere.", "\"Block sign-in\" / \"Restore sign-in\". You can't block your own account.", "\"Offboard\u2026\" \u2014 a quick offboard from the panel: sign-in is always blocked; choose revoke sessions, remove all licenses, remove from all groups, deactivate the linked vTiger user and (optionally) reassign their vTiger records first. For auto-reply, forwarding, OneDrive handover, equipment or a scheduled last day use the Offboard tab.", "Licenses and groups are folded: the heading says how many (\"+ Licenses (2)\") and the line under it names them. Click the heading to open the list. Licenses: \u2715 removes one; \"+ Add license\" lists subscriptions with seats left.", "Groups: \u2715 removes; \"+ Add to group\" searches groups. Dynamic and on-prem-synced groups are greyed out (they can't be changed here).", "Directory roles are folded like licenses and groups: \"+ Directory roles (1)\" with the names on one line, in red when one is high-risk. Click the heading to open the list. \"+ Assign role\" \u2192 pick the role \u2192 \"Yes, grant\". High-risk roles (Global Administrator and similar) are marked. Nobody can remove roles from their own account.", "\"+ Manage methods\" lists sign-in methods with \u2715 to remove one (a lost key or old phone). \"+ Temporary access pass\" issues a one-time pass (1\u20138 hours), shown once."]}, {"p": "Every action is recorded in the Audit Log and the Event Log. Accounts are blocked, never deleted."}, {"qa": [{"q": "Which permission does each button need?", "a": "Edit contact information / Block / restore / Offboard / Onboard: \"Microsoft 365 \u00b7 Accounts\". Custom fields (the definitions): \"Onboarding\" with Edit. Password, MFA, sessions, methods, Temporary access pass: \"\u00b7 Credentials\". Licenses: \"\u00b7 Licenses\". Groups: \"\u00b7 Groups\". Directory roles: \"\u00b7 Directory roles\". vTiger deactivate / reassign: \"Provisioning \u00b7 Offboard from vTiger\"."}, {"q": "Last sign-in says \"unknown\".", "a": "Sign-in dates need Entra ID P1 and AuditLog.Read.All."}]}, {"h": "Admin accounts are Super Admin only"}, {"bullets": ["Reset password, reset MFA, Temporary access pass, block sign-in, sign out everywhere and Offboard: when the account holds a Microsoft 365 admin role \u2014 directly, through a group that can hold roles, or eligible in PIM (Privileged Identity Management) \u2014 only a Super Admin can do it. The app checks the roles each time; when Microsoft does not answer, a Super Admin must do it. Every refusal is in the Audit Log.", "A password reset done by someone other than a Super Admin always asks the person for a new password at the next sign-in.", "Directory roles: the high-risk roles (Global Administrator, Privileged Role Administrator, Security, User, Exchange, SharePoint, Intune, Helpdesk, Password Administrator and similar) are assigned and removed only by a Super Admin; nobody gives a role to their own account. Groups that can hold admin roles are changed in the Entra admin center."]}]}, {"title": "Editing an account: name, job, phones, address, manager", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 People \u2192 pick a person \u2192 \"Edit Microsoft 365 info\" opens in the account panel, in place of the account, with everything Microsoft 365 keeps about the person that an administrator normally changes. \"\u2190 Back to the account\" returns; with unsaved changes ITOps asks first. You do not need the Microsoft 365 admin center for it."}, {"h": "What you can change"}, {"bullets": ["Name: First name, Last name, Display name. \"Use \u2026 as the display name\" builds it from the first and last name.", "Organization: Job title, Department, Company, Office, Employee ID, Employee type, Manager (search a person; \u2715 on the manager removes it; \u2715 on a person you just picked takes the pick back), and your custom fields for this section.", "Contact information: Office phone, Mobile phone, Fax number, Street address (it can have more than one line), City, State or province, ZIP or postal code, Country or region, and your custom fields for this section.", "Settings: Usage location (two letters, for example US) and Preferred language."]}, {"steps": ["Change what you need. Every field you changed gets a blue outline and a line \"was: \u2026\" with \"undo\".", "The Save button counts the changes (\"Save 3 changes\") and the line next to it names them. Nothing is sent until you press it.", "Press Save. Only the fields you changed are sent to Microsoft. The page closes and the account panel says what was saved.", "To check later who changed what, open \"+ Show change history\" on the account, or search the person's sign-in name in the Audit Log."]}, {"h": "Fill from company-wide values"}, {"p": "If your administrator saved company-wide values (Onboarding Templates \u2192 \"Custom fields\"), the button \"Fill N empty fields from company-wide values\" puts them into the fields that are still empty, for example the company name, the office address or the main phone. It never replaces a value the account already has, and nothing is saved until you press Save. This is checked again when you save: if somebody filled the field in meanwhile, it is left alone and the message says which field. The button offers only fields that are empty on the account itself: a field you have just emptied on the page is being cleared, and the button does not fill it again. If a save is partly refused and the page stays open, a line under the results names the filled fields that were left alone."}, {"h": "When Microsoft refuses part of it"}, {"p": "Phone numbers, the fax number, custom fields and the manager are each sent on their own. If Microsoft refuses one of them, the others are still saved. The page stays open with a box that says, for each part, \"\u2713 Saved\", \"\u2717 Refused\", \"? Outcome not known\" or \"\u2013 Not sent\", Microsoft's own message and what to do. The refused fields keep their blue outline so you can try again or undo them. If no clear answer came back from Microsoft (a timeout), the part is marked \"? Outcome not known\": open the account again to see the values it has now."}, {"bullets": ["Phone numbers of an account that holds an administrator role: Microsoft does not let an application change them. Change that number in the Microsoft 365 admin center.", "\"Insufficient privileges\" on everything: the app is missing User.ReadWrite.All with admin consent. Check Microsoft 365 \u2192 Home \u2192 Diagnose \u2192 \"Permissions that change something\".", "An account that is copied from an on-premises directory is read-only here. The page says so at the top; change it in that directory."]}, {"h": "The page shows the account as it is now"}, {"p": "The page keeps only what you changed. Everything else is the account as it was last read from Microsoft 365. So when the account is read again while your page is open (after a save that was partly refused, or because a colleague changed it), you see the new values, your own changes stay outlined, and nothing you did not type is sent."}, {"bullets": ["A value a colleague changed meanwhile is shown as it is now and is not sent back.", "A part Microsoft confirmed is shown as saved at once, even if the next reading of the account is a few seconds behind.", "The manager is removed only by clicking its \u2715, and only while the account still has the manager your page showed. If it has another manager by the time you save, nothing is changed: the page says so, forgets the removal and reads the account again. To remove the manager the account has now, click its \u2715 again.", "When a save sends several parts (a job title, a phone number, the manager), the manager is read once more right before it is removed. If somebody gave the account another manager in those seconds, the other parts are saved and the removal is not sent; the results box says \"Not removed: the account got another manager while this save was running\".", "While a save is running, no manager can be searched or picked.", "If the manager could not be read when the page opened, the page says so and does not offer to remove it. You can still set a new one.", "A page left open from an older build is told to reload (Ctrl+F5) when it tries to remove a manager."]}, {"h": "Dynamic groups"}, {"p": "A group in Microsoft 365 can have a rule instead of a member list, for example \"everyone whose department is Sales\". When you change a value such a rule reads (department, job title, company, office, country, usage location, a custom attribute), Microsoft takes the person into the group or puts them out, usually within minutes, sometimes hours. Licenses, teams and access given through that group follow. Check People \u2192 Groups for groups marked \"Dynamic\" before changing those values for people who depend on them."}, {"h": "If saving takes too long"}, {"p": "The web host ends a request after about a minute, so a save gives each part a limited time. A part that could not be sent in time is shown as \"\u2013 Not sent\": it was certainly not changed. Press Save again; only what is still different is sent. If no answer comes back at all, the page says it is not known whether the changes were saved and reads the account again. Once it has, it tells you so: what is still outlined may not have been saved, and you can press Save again, because only what is still different from the account is sent. If the account cannot be read either, close the page and open the account again to see what it has. The Audit Log has an entry for every part that was sent."}, {"h": "What is not edited here"}, {"bullets": ["Email address and sign-in name: changing them changes the mailbox addresses, so that stays in the Microsoft 365 admin center.", "Hire date: Microsoft does not let an application write it.", "Email aliases, shared mailboxes, mailbox permissions and distribution lists are Exchange settings that Microsoft does not offer to this kind of app."]}, {"tip": "Email signatures: tools that read Microsoft 365, such as CodeTwo, pick up a new title or phone number by themselves. CodeTwo reads the accounts again about every 20 minutes. Outlook and Teams address books can take up to a day."}, {"p": "Every part of a save is written to the Audit Log as soon as Microsoft answers it (action m365_user_update), with the old and the new value of each field. One save that changes a job title, a phone number and the manager is therefore three entries. A part that was refused, whose outcome is not known, or that was not sent is written too (m365_user_update_refused) with the value that was wanted and the reason. A refused removal of a manager is logged the same way. When the value that was wanted is \"nothing\" (a field you cleared, a manager you removed), the entry says \"wanted: empty\"."}, {"qa": [{"q": "I do not see \"Edit Microsoft 365 info\".", "a": "Your role needs \"Microsoft 365 \u00b7 Accounts\" with Edit."}, {"q": "Save is grey.", "a": "Nothing differs from what the account already has, or the account is copied from an on-premises directory."}, {"q": "Can I change several accounts at once?", "a": "Yes: tick their rows in the list and click \"Edit selected\u2026\". See \"Editing several accounts at once\"."}, {"q": "I cleared a field and saved. What happened in Microsoft 365?", "a": "The value was removed from the account. Two values cannot be emptied: the display name, and the usage location once it is set (change it to another country instead)."}, {"q": "\"The manager was not removed and nothing else was changed\u2026\"", "a": "The account has another manager now than the one your page showed, or the page is from an older build. Nothing was changed. The page forgets the removal and reads the account again; if you still want to remove the manager the account has, click its \u2715 and save. A page from an older build is told to reload (Ctrl+F5)."}, {"q": "I do not see \"Show change history\" any more.", "a": "The change history is a piece of the Audit Log. It is shown to people who edit accounts (\"Microsoft 365 \u00b7 Accounts\" with Edit) or who can read the Audit Log. It shows what was done to that account only; entries about groups, devices, settings and bulk-run summaries are in the Audit Log itself."}, {"q": "A value I pasted looks the same but was saved a little shorter.", "a": "Invisible characters (zero-width spaces, direction marks) and control characters are removed, and repeated spaces become one. They make two values look the same and compare different, which breaks signatures and group rules."}]}]}, {"title": "Editing several accounts at once", "for": "admin", "mod": "m365", "body": [{"p": "When the same value belongs on many accounts (a department that was renamed, a new office address, a new manager for a team, the company name on everyone), change them together instead of opening each account."}, {"steps": ["Open Microsoft 365 \u2192 People. Every row of the list has a box to tick at its start.", "Tick the accounts. Search, filter or pick a domain to find them; the selection is kept meanwhile. The box in the heading ticks every row of the page, and \"Select all N\" in the bar takes every row that matches.", "Click \"Edit selected\u2026\". A full page opens with the accounts at the top; \u2715 takes one out.", "Under \"What to change\", choose for each field you want: \"Set for everyone\", \"Set only where empty\" or \"Clear\", and type the value. Fields left on \"Do not change\" are not touched.", "Click \"Preview\". ITOps reads every account and shows, per account, each value as old \u2192 new. Nothing is changed yet.", "Type the confirmation it asks for (for example CHANGE 12: the number of accounts the run will change) and click \"Change 12 accounts\".", "Read the result: every account is Changed, Skipped, Failed or Not known, with the reason. Click \"Done\"."]}, {"h": "What can be changed this way"}, {"bullets": ["Organization: Manager, Job title, Department, Company, Office, Employee type, and your custom fields for this section.", "Contact information: Office phone, Fax number, the address, and your custom fields for this section.", "Settings: Usage location and Preferred language.", "Not offered, because they belong to one person: first name, last name, display name, employee ID and mobile phone. Edit those on the account."]}, {"h": "The three ways to set a field"}, {"bullets": ["\"Set for everyone\": every selected account gets the value, replacing what it had.", "\"Set only where empty\": only accounts that have nothing in that field get the value. \"Use the company-wide values, only where empty\" sets all your company-wide values this way in one click.", "\"Clear\": the value is removed. The usage location cannot be cleared once it is set; the preview says so for the accounts concerned and leaves that field alone."]}, {"h": "What the preview leaves out"}, {"bullets": ["Accounts that already have every value: nothing to change.", "Accounts copied from an on-premises directory: change them there.", "The person you chose as manager is not made their own manager; their other fields still change.", "An account that could not be read just now, or whose current manager could not be read when the manager is part of the change: the preview says \"N could not be read\" and is marked \"not complete\". A run is only applied on a complete preview: press \"Preview again\", or take those accounts out."]}, {"warn": "There is no undo button. To reverse a bulk edit, run another one with the old value. The Audit Log shows what each account had before."}, {"p": "If Microsoft refuses the first kind of change on an account (for example the app lost its permission), the run stops and the accounts after it are not attempted. If only that one account is protected, take it out of the selection and run again."}, {"h": "When a run does not change everything"}, {"p": "\"Not known\" means no clear answer came back for that account (a network cut, the host's time limit, or Microsoft answering late): the change may or may not have been made. \"Failed\" means Microsoft refused a part, or a part could not be sent in time; what was saved and what was not is named. In both cases the page offers \"Read the accounts again\": the preview runs again, the result of the run stays on screen above it, and the accounts that still show a change are the ones to apply to, with a new confirmation. Nothing is repeated by itself."}, {"bullets": ["While a run is in flight the page cannot be closed. If you leave it another way (the menu, closing the browser), the run stops: accounts not yet started are not changed, and what was changed is in the Audit Log.", "When the current manager of an account cannot be read during a run, that account is not changed at all (not even its other fields).", "Accounts the server did not get to within its time are sent again by the page; you only see the progress count."]}, {"h": "Dynamic groups"}, {"p": "Changing a department, a company name, an office, a country or a custom attribute for many people at once can move all of them in or out of dynamic groups whose rule reads that value, with the licenses and access those groups give. Look at the rules of your dynamic groups (People \u2192 Groups, marked \"Dynamic\") before a large run."}, {"p": "Logging: every part of every account is written to the Audit Log as soon as Microsoft answers it (m365_user_update, or m365_user_update_refused for a part that was refused, not known or not sent), with old and new values, named with the sign-in name and \"(bulk edit <run>)\". Each portion of the run adds a summary entry (m365_users_bulk_update) with the instruction, the accounts and the result; when a run was stopped, the entry says so. Search \"bulk edit\" and the run code shown on the result to see the whole run. The same entries appear in each account's change history."}, {"qa": [{"q": "How many accounts can I change at once?", "a": "As many as you tick. They are sent a few at a time, and the page shows the progress."}, {"q": "I see no boxes to tick, or no \"Edit selected\u2026\".", "a": "Your role needs \"Microsoft 365 \u00b7 Accounts\" with Edit."}, {"q": "The count in the confirmation is lower than what I selected.", "a": "The confirmation counts the accounts that will really change. Accounts with nothing to change, or that cannot be changed, are left out; the preview lists them with the reason."}, {"q": "\"This preview is not complete.\"", "a": "Some accounts could not be read, so the preview does not show everything the run would do. Press \"Preview again\". If the same accounts fail again, take them out of the selection (\u2715 on the account at the top) and edit them one by one later."}, {"q": "\"Type CHANGE and the number of accounts to confirm\" although I typed a number.", "a": "The number must be exactly the number of accounts the run will change, as the page shows it."}]}]}, {"title": "Custom fields and company-wide values", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft gives every account 15 spare text values, called custom attributes 1 to 15. They have numbers, not names. Administration \u2192 Onboarding Templates \u2192 \"Custom fields\" (next to \"New template\") is where you give the ones you use a name, such as Pronouns, Cost center or Desk extension. A named field then appears on every account: on the panel, and on \"Edit Microsoft 365 info\" in the section you chose. It is also on the Onboard screen (under \"+ More details\") and on every onboarding template (under \"Custom fields\"), so a new account can start with it."}, {"h": "Add a field"}, {"steps": ["Open Administration \u2192 Onboarding Templates and click \"Custom fields\" (top right, next to \"New template\"). Since 0621-BT71 it is only there, no longer on Microsoft 365 \u2192 People.", "Click \"+ Add a field\". \"Stored in\" proposes the first custom attribute nobody uses; the list shows for each attribute how many accounts already have a value (\"used by 12\" or \"empty\").", "Type the Name people will see, choose \"Shown under\" (Contact information or Organization) and the \"Kind of value\": Free text, or A list of choices (write one choice per line).", "Optional: a Help text, shown next to the field on the edit page.", "Click Save."]}, {"warn": "If you pick an attribute that already holds values, an amber note shows how many accounts and a few examples. Something else may be using it, for example an email signature or an older script. Naming it shows those values under your name; it does not change them. When in doubt, pick an empty attribute."}, {"bullets": ["A custom field cannot take the name of a built-in field (Department, Company, Manager\u2026), so the Audit Log never mixes two fields up. A list can have up to 60 choices.", "A saved field keeps its attribute, because the values of the accounts live there. To move it, remove the field and add a new one.", "\"Shown on the edit page\" unticked hides the field without removing it.", "\"Remove this field\" removes the name in ITOps. The values on the accounts stay as they are in Microsoft 365.", "The table \"How the 15 custom attributes are used today\" counts the accounts with a value in each attribute and shows examples. \"Count again\" reads the directory again.", "While a field is new you can still move it to another attribute; a company-wide value you typed for it moves with it.", "\"Count again\" (above the usage table) reads the accounts again and refreshes that table only. What you are typing on the page stays.", "The example values in the usage table are shown to the people who manage this page; others see the counts."]}, {"h": "Company-wide values"}, {"p": "Values that are the same for everybody: Company, Office, Office phone, Fax number, the address, Usage location, Preferred language, and any of your custom fields. They are used by one button on the edit page, \"Fill N empty fields from company-wide values\". They never replace a value an account already has, and saving this page writes nothing to any account."}, {"h": "Using a custom field in an email signature"}, {"p": "The values are stored on the account in Microsoft 365, not in ITOps, so other tools can read them. In CodeTwo, choose the same custom attribute number in the signature editor (it lists them as custom attributes 1 to 15). CodeTwo reads the accounts again about every 20 minutes. Values typed into CodeTwo's own attribute manager are different: they stay in CodeTwo and never reach Microsoft 365."}, {"warn": "Dynamic groups: a group in Microsoft 365 can have a rule that reads a custom attribute. Once a field is named here and people fill it in, such a group takes them in or puts them out, and licenses or access given through it follow. Before you reuse an attribute, check the rules of your dynamic groups (People \u2192 Groups, marked \"Dynamic\")."}, {"p": "Every save of this page is written to the Audit Log (action m365_custom_fields_save) with the fields (name, attribute, section, choices, help text, on or off) and the company-wide values before and after."}, {"qa": [{"q": "Who can change this page?", "a": "Roles with \"Onboarding\" and Edit. Everyone who can open Accounts can read it."}, {"q": "Why at most 15 fields?", "a": "That is the number of custom attributes Microsoft gives each account."}, {"q": "A custom field is refused when I save an account.", "a": "Custom attributes can be written for accounts that live only in the cloud. For an account copied from an on-premises directory, change the value there."}]}]}, {"title": "Licensing: Licenses, Reclaim, Reconcile and Coverage", "for": "admin", "mod": "m365", "body": [{"bullets": ["\"Licenses\": one card per subscription, most used first \u2014 used / total, free seats (amber when 10% or less is left, red when full). Click a card to open the list of holders; with \"Microsoft 365 \u00b7 Licenses\" you can tick people and \"Remove \u2026 from selected\".", "\"Reclaim\": licensed accounts that are disabled, never signed in, or idle for 30 / 60 / 90 / 180 days. Click a row of the per-license summary to filter. Remove licenses per row (\"Remove licenses\" \u2192 \"Remove N\") or tick several and \"Reclaim selected\" (all licenses, or one license). \"Export CSV\" downloads the whole list.", "\"Reconcile\": a read-only cross-check of Microsoft 365, vTiger and ITOps sign-ins, matched by email \u2014 status mismatches, Microsoft 365 only, vTiger only, reclaimable licenses, and access never used. Open a section to see who; \"Export CSV\" downloads everything.", "\"Coverage\" (ITOps): active people without a license, and Business Premium holders whose device isn't enrolled in Intune."]}, {"tip": "Idle detection needs Entra ID P1. Without it, Reclaim lists only disabled accounts that still hold licenses."}, {"tip": "Removing licenses from several people at once (Licenses, Reclaim, Reconcile) asks you to type REMOVE first."}]}, {"title": "Microsoft Entra screens: sign-in, groups, guests, devices, apps and the audit log", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft Entra ID is the identity service behind every Microsoft 365 account: who signs in, how they prove who they are, from which device, and which applications hold credentials. Its screens are where they are used: MFA, Groups and Guests under People; App secrets, Recommendations, Enterprise apps and Access & sign-in under Security; Device inventory under Devices; the audit log under Collaboration & activity."}, {"bullets": ["\"MFA\": who is registered for multi-factor sign-in. Starts on \"Not registered\"; \"Admins without MFA\" is the list to fix first.", "\"Groups\": every group in the directory with its type, owners and member count. Click a group for its members; add or remove people and devices where Microsoft allows it \u2014 see its own topic.", "\"Guests\": people from outside the organization who were invited in \u2014 who they are, whether they accepted and when they last signed in. Block or remove the ones nobody needs. See its own topic.", "\"App secrets\": every app registration and when its secrets and certificates expire (expired, expiring in 30 days, no credentials). Starts on \"Needs attention\".", "\"Recommendations\": Microsoft Entra's own advice for the tenant, with priority and status. Starts on the active ones; click a priority to filter."]}, {"p": "MFA, App secrets and Recommendations are read-only. The ITOps tabs after the line:"}, {"bullets": ["\"Device inventory\": every device that signs in with a work account, company or personal, with the actions on registered devices \u2014 see its own topics.", "\"Enterprise apps\": which applications hold access to the tenant, what they may do and who agreed to it. Read-only \u2014 see its own topic.", "\"Audit log\": who changed what in the directory, as Microsoft recorded it. Read-only \u2014 see its own topic.", "\"Access & sign-in\": MFA registration, who holds admin roles, app secrets, the sign-in methods people can use, and Conditional Access \u2014 click a rule to read in plain words who it applies to and what it requires. Changes there need \"Microsoft 365 \u00b7 Tenant configuration\" (edit)."]}, {"h": "\"About this screen\""}, {"p": "Groups, Guests, Device inventory, Enterprise apps and Audit log \u2014 and the screens opened from them (Clean up stale devices, Pending invitations, New group) \u2014 have an \"About this screen\" button (\u24d8) in the top bar, next to the page title. Click it: a box opens over the page, in three columns:"}, {"bullets": ["\"What it does\": what the screen is for, in two or three lines.", "\"What it needs\": the permission your role needs and the Microsoft permission the Azure app needs. A green tick means it is in place, a red cross that it is missing, an amber circle that it is optional and not in place. The Microsoft side is read from the token, so you know before you click.", "\"What to expect\": what each action really does, what can be undone and what cannot, and what the screen never touches."]}, {"p": "It is information only and never pushes the screen down (until build BT48 it was a box at the top of the page). A click elsewhere or Esc closes it. When something in \"What it needs\" is missing, the button shows \"1 missing\" in red without being opened."}, {"qa": [{"q": "Why are Accounts and Licensing not on this page? They are Entra too.", "a": "They are, but each is a job of its own that also touches Exchange and vTiger (onboarding, offboarding, reclaiming seats), so they keep their pages. Entra ID holds the Entra screens that are about sign-in, devices and applications."}, {"q": "A card on Overview used to open Security and now opens Entra ID.", "a": "That is expected: the screen moved, the card follows it."}, {"q": "Where are the Defender alerts that were at the top of Access & sign-in?", "a": "On Security \u2192 \"Alerts & actions\", with the same \"Working on it\" and \"Resolve\" buttons and the Secure Score next actions. Access & sign-in now holds only the Entra sections."}]}]}, {"title": "Security and devices: alerts and incidents, Secure Score, Compliance and Device policies", "for": "admin", "mod": "m365", "body": [{"p": "Each fact has one home. Where it shows elsewhere, it is a link (a small rounded button with \u2192) that opens its home with the right filter."}, {"bullets": ["Security \u2192 \"Alerts & actions\": the one list of Microsoft Defender alerts and incidents. The counts at the top are filters: \"Open alerts\", \"Active incidents\" (who has each incident, when it last changed, how many open alerts it holds), and High, Medium and Low for the list you are looking at. \"Open in Defender \u2197\" opens the item in the Microsoft portal. On an alert, \"part of an incident\" shows the incidents. \"Working on it\" and \"Resolve\" need \"Microsoft 365 \u00b7 Tenant configuration\" (edit).", "Security \u2192 \"Secure Score\": the score (as of date, % of the maximum) and Microsoft's next recommended actions, lowest score first. The \"Secure Score\" count on Alerts & actions opens it.", "Security \u2192 \"Access & sign-in\": admin roles, sign-in methods and Conditional Access. Multifactor registration and app secrets are links here: \"5 of 7 registered\" and \"1 admin without MFA\" open People \u2192 MFA, \"1 expired\" opens Security \u2192 App secrets.", "Devices \u2192 \"Compliance\": the one list of devices Intune manages. Counts filter it (compliant, non-compliant, \"Not synced in 7 days\"). \"Sync\" asks a device to check in; \"Lock\" locks a company device (type LOCK). Personal devices are marked and never locked. Both need \"Microsoft 365 \u00b7 Tenant configuration\" (edit).", "Devices \u2192 \"Device policies\": compliance and security policies, backup, invite to enrol. The devices are a line of links to Compliance (managed, non-compliant, not synced)."]}, {"tip": "Other counts that open their list: Storage (\"Near full\"), Reconcile (\"M365 members\" opens People, \"vTiger users\" opens vTiger users), Rollout readiness (each count filters the people below), the Posture score (opens its history) and the IT Budget's Microsoft 365 tiles (seats open Licenses, reclaimable opens Reclaim)."}]}, {"title": "Email: mailboxes, delegates, calendar access, distribution lists and message trace", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 Email covers day-to-day mailbox requests without opening the Exchange admin center."}, {"bullets": ["\"Mailboxes\": every mailbox in one list (people, shared, room and equipment), with its other addresses, size, % of quota and last activity. The counts at the top are filters: each kind, \"With send-on-behalf delegates\", \"Near quota\" (90% or more) and \"People inactive 30d\". Search finds a mailbox by any of its addresses. \"Export CSV\" saves what you see.", "Click a mailbox to see who may send on its behalf and who can see or change its calendar (\"Default\" is everyone in the organization). With \"Microsoft 365 \u00b7 Mailboxes\" (edit) you can add or remove a delegate and give, change or take away calendar access. Taking something away asks you to confirm first; every change is written to the Audit Log, with what changed.", "\"Distribution lists\": mail lists and mail-enabled security groups; click one for its members. Microsoft does not yet let apps change a list's members, so the link opens the Exchange admin center for that. Microsoft 365 groups and teams are on People \u2192 Groups.", "\"Message trace\": search the last 90 days, up to 10 days at a time, by sender, recipient or words in the subject. The result shows each message's status (Delivered, Failed, Quarantined, Filtered as spam\u2026); click a status to show only those. Every search is written to the Audit Log. From a mailbox, \"Message trace for this address\" opens it with the address filled in.", "Who sees what: anyone with Microsoft 365 (view) sees the mailbox list and distribution lists. Delegates, calendar access and Message trace need \"Microsoft 365 \u00b7 Mailboxes\" (view); changing them needs it with edit. Roles with \"Microsoft 365 \u00b7 Tenant configuration\" received the same level of Mailboxes when this version was installed. Any attempt without the permission is refused and written to the Audit Log."]}, {"p": "One-time setup in Microsoft (an administrator of the tenant):"}, {"bullets": ["Mailboxes, delegates and calendar access use Microsoft's Exchange Admin API, which is in preview. In Entra \u2192 App registrations \u2192 your app \u2192 API permissions \u2192 Add \u2192 \"APIs my organization uses\" \u2192 Office 365 Exchange Online \u2192 Application \u2192 Exchange.ManageAsAppV2 \u2192 Grant admin consent. Then in the Exchange admin center \u2192 Roles \u2192 Admin roles \u2192 Recipient Management \u2192 Assigned, add the app.", "Message trace needs the Microsoft Graph application permission ExchangeMessageTrace.Read.All with admin consent.", "Until this is done the screens say what is missing instead of failing, and \"Mailboxes\" falls back to the usage report (size and activity). Home \u2192 Diagnose tests both."]}, {"tip": "The app can only run the Exchange commands it needs (read mailboxes, change send-on-behalf delegates, read and change calendar permissions, read list members). It cannot delete or create mailboxes."}]}, {"title": "Devices: restart, scan, retire and wipe with a second person's approval, apps, configuration and update rings", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 Devices handles the day-to-day Intune work without opening the Intune admin center."}, {"bullets": ["Compliance \u2192 \"More\" on a device. \"Now\": Restart (type RESTART), Defender quick scan and Defender full scan (Windows). These are sent at once and need \"Microsoft 365 \u00b7 Tenant configuration\" (edit).", "\"With a second person's approval\": Retire (removes the organization's apps, data, email profiles and settings and takes the device out of Intune; the person's own files stay), Wipe (factory reset; you can keep the enrollment and, on Windows, the person's files) and Fresh start (reinstalls Windows; you can keep the person's files). Say why and type the device name; the request then waits.", "Devices \u2192 \"Wipe & retire\": the requests. Someone else with \"Microsoft 365 \u00b7 Retire and wipe devices\" approves (typing the device name) or denies (saying why). Nobody approves their own request. Only an approved request is sent to Intune. A request nobody answers lapses after 24 hours. The person who asked can withdraw it while it waits. The people who can approve get a bell; the person who asked gets one when it is approved, denied or could not be sent.", "Before sending, the device is read again: if Intune no longer has it, or it now has another name, nothing is sent and the request says why. \"check in Intune\" on a sent request shows what the device reported (pending, done, failed).", "Personal devices: only Retire is possible. Restart, scans, lock, wipe and fresh start are never sent to a device the organization does not own. A device whose owner Intune does not know is treated the same way until it is set to Corporate in Intune.", "\"Apps\": the apps Intune installs (required) or offers in Company Portal (available), and who gets each (groups, all users, all devices; an exclusion is struck through). Counts filter: required, available only, not assigned, and per platform. Switch to \"Software found on devices\" for what is actually installed, most widespread first; click a program for its versions and which devices have each.", "\"Configuration\": the configuration profiles (including settings-catalog profiles), who gets each, and on how many devices it worked, failed or conflicts. Counts filter: with errors, with conflicts, not assigned.", "\"Update rings\": how long each Windows ring waits for quality (monthly) and feature updates, the install deadline, and whether it is paused. \"Pause\" stops a ring taking those updates for up to 35 days, when an update causes trouble; \"Resume\" starts them again. This needs \"Microsoft 365 \u00b7 Tenant configuration\" (edit) and is written to the Audit Log.", "Changing apps, profiles and rings themselves stays in the Intune admin center (\"Open in Intune \u2197\")."]}, {"p": "One-time setup in Microsoft (Graph application permissions with admin consent):"}, {"bullets": ["DeviceManagementManagedDevices.PrivilegedOperations.All: restart, scans, retire, wipe, fresh start.", "DeviceManagementApps.Read.All: Apps. DeviceManagementManagedDevices.Read.All: software found. DeviceManagementConfiguration.Read.All: Configuration and Update rings; DeviceManagementConfiguration.ReadWrite.All to pause and resume a ring.", "Home \u2192 Diagnose tests the reads. Until a permission is granted, the screen names it instead of failing."]}, {"tip": "Give \"Microsoft 365 \u00b7 Retire and wipe devices\" (Settings \u2192 Roles) to at least two people. It is not given to any role automatically. An organization with one administrator: a Super Admin can switch the second person off per action in Settings \u2192 Approvals; the action is then sent as soon as the one person confirms (reason and typed name still asked), and the list shows it as \"sent, no second person\". Every request, approval, denial, withdrawal, lapse, refusal and change of the setting is in the Audit Log."}]}, {"title": "Groups: owners, members, new groups and what can be changed", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 People \u2192 \"Groups\" lists every group in the directory. Use it to see who is in a group before you rely on it for access, licenses or policies, to add or remove members and owners without opening a person's account, and to create a new security group."}, {"h": "Reading the list"}, {"bullets": ["Type: \"Microsoft 365\" (a mailbox, files and often a team \u2014 marked \"Team\"), \"Security\" (used for access, licenses and policies), \"Distribution list\" and \"Mail-enabled security\".", "Under the type: \"Dynamic membership\" (a rule decides who is in), \"Synced from on-premises\", \"Can hold admin roles\".", "Members and Owners: how many. \"\u2014\" means Microsoft did not return the number this time.", "Flags: \"No owner\" on a Microsoft 365 group or team that nobody owns, and \"Empty\" on a group without members.", "Tiles filter the list (Microsoft 365, Security, No owner, Empty); the chips filter mail lists, dynamic and synced groups. \"Export CSV\" downloads the rows you see."]}, {"h": "Members"}, {"steps": ["Click a group. Owners are on the left, members on the right \u2014 people, devices and groups inside the group under their own headings. \"disabled\" marks an account that is blocked from signing in but still in the group; \"guest\" marks an external person.", "\"+ Add person\": search by name or email and click the person.", "\"+ Add device\": search the Device inventory and click the device. This is how a computer is put in the company-PC group that the device policies are assigned to.", "\"remove\" next to a member takes them out, after a confirmation that says what they lose."]}, {"h": "Owners"}, {"steps": ["Click a group. Its owners are on the left.", "\"+ Add owner\": search by name or email and click the person. Owners must be people from the organization who can sign in; guests and blocked accounts are refused.", "For a Microsoft 365 group or team, \"Also add as a member\" is ticked: an owner who is not a member cannot work in the team. Untick it if you only want them to manage it.", "\"remove\" next to an owner takes the ownership away, after a confirmation. They stay a member if they were one."]}, {"bullets": ["The last owner of a Microsoft 365 group or team cannot be removed: Microsoft does not allow it. Add the new owner first, then remove the old one.", "Owners can be changed for cloud security groups and Microsoft 365 groups, dynamic ones included (the rule decides the members, not the owners).", "In Microsoft Teams a change of owner can take up to 2 hours to appear.", "When the buttons are missing, the line under the owners says why: the kind of group, your role, or the Microsoft permission Group.ReadWrite.All."]}, {"h": "Creating a group"}, {"steps": ["Click \"+ New group\" at the top right. A full page opens.", "Type a name (3 to 120 characters) and, if you like, a description of what the group is for.", "Under \"Owners\", search for a person and click them. At least one owner, up to five.", "Click \"Create group\". The page closes and the new group is open in the list, ready for \"+ Add person\" or \"+ Add device\"."]}, {"bullets": ["What you get is a security group in the cloud with members you choose yourself: the kind used to assign licenses, Intune policies and access to apps or SharePoint sites.", "It has no mailbox, no team and no shared files. For those, create a team in Microsoft Teams.", "The group gives nothing to anyone by itself. It starts to matter when you assign something to it.", "A name that another group already uses is refused, so two groups are never mixed up."]}, {"h": "What cannot be changed here, and where to do it"}, {"bullets": ["Members of dynamic groups: change the rule in the Entra admin center. The rule is shown when you open the group.", "Groups synced from on-premises: change members and owners in Active Directory.", "Distribution lists and mail-enabled security groups: the Exchange admin center. Microsoft does not let an application change them.", "Groups that can hold admin roles: the Entra admin center.", "Deleting a group: the Entra admin center. ITOps never deletes groups, because deleting a Microsoft 365 group also removes its team, mailbox and files."]}, {"h": "What it needs"}, {"bullets": ["Your role: \"Microsoft 365 \u00b7 View\" to see groups; \"Microsoft 365 \u00b7 Groups\" to change members and owners and to create groups (the same permission as on a person's account).", "Azure app, members: GroupMember.ReadWrite.All \u2014 the permission that adding people to groups on Microsoft 365 \u2192 People already uses. With only Group.Read.All the list works, read-only.", "Azure app, owners and new groups: Group.ReadWrite.All (Application, admin consent). It is optional: without it \"+ Add owner\", \"remove\" on owners and \"+ New group\" are hidden, the screen names the permission, and everything else works. After granting it, click \"Refresh token & re-test\" on Home \u2192 Diagnose.", "The list is kept for 10 minutes (\"\u00b7 cached\"); any change made here refreshes it. Every change is in the Audit Log."]}, {"qa": [{"q": "A group I know has members shows \"\u2014\".", "a": "Microsoft did not answer the count. Open the group to see its members, or click Refresh."}, {"q": "Applications that are members are not listed.", "a": "Microsoft does not return applications (service principals) as group members in this version of its interface."}, {"q": "What should I do about \"No owner\"?", "a": "Open the group and click \"+ Add owner\". Without an owner, nobody can approve members, renew the group or clean it up. If the button is missing, the Azure app lacks Group.ReadWrite.All: grant it, or add the owner in the Teams or Entra admin center."}, {"q": "I created a group but it is not in the list.", "a": "Microsoft can take a few seconds to show a new group. Click \"Refresh\". The green line above the list keeps the name you gave it."}, {"q": "Can I create a Microsoft 365 group or a team here?", "a": "No. ITOps creates security groups only. A Microsoft 365 group comes with a mailbox, a site and usually a team, and is best created from Microsoft Teams by the person who will own it."}]}]}, {"title": "Guests: external accounts, pending invitations and clean-up", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 People \u2192 \"Guests\" lists every guest account: people from outside the organization who were invited into a team, a SharePoint site or an app. Guests are easy to forget \u2014 nobody offboards them \u2014 so this is the place to check them every few months."}, {"h": "Reading the list"}, {"bullets": ["\"From\": the company when Entra knows it, and the domain of the person's address. The chips above the list filter by the most common domains.", "\"Invitation\": \"Accepted\", or \"Pending\" when the person never clicked the invitation \u2014 a pending guest cannot use anything yet.", "\"Last sign-in\": the last time the guest signed in, or \"never\". \"\u2014\" means Microsoft does not provide the dates (see \"What it needs\").", "Flags: \"Invitation pending\", \"Pending 30+ days\" (invited over a month ago and never accepted), \"Not used 90 days\" (accepted but no sign-in for 90 days, or never), \"Sign-in blocked\".", "The four tiles filter the list. \"Export CSV\" downloads the rows you see."]}, {"h": "Blocking, re-inviting and removing"}, {"steps": ["Click a guest. The details show the address, the invitation, the account name in Entra and what each flag means.", "\"Block sign-in\" stops the guest from signing in but keeps the account and its memberships; \"Restore sign-in\" undoes it. Use it when you are not sure the guest is finished.", "\"Resend invitation\" appears on a guest who has not accepted yet. Microsoft emails a new invitation to the guest's address; nothing else about the account changes. The button is off while the guest's sign-in is blocked: restore sign-in first.", "\"Remove guest\u2026\": type the guest's email address and click \"Remove guest\". The guest loses access to every team, site and app at once."]}, {"bullets": ["A removed guest stays under \"Deleted users\" in the Entra admin center for 30 days and can be restored there. After that the person has to be invited again.", "Files and messages the guest left in teams and sites stay where they are.", "Only guests can be removed here. A staff account is never deleted from this screen: staff are offboarded from Accounts \u2192 Offboard.", "To see or change a guest's groups, open People \u2192 Groups and the group."]}, {"h": "Pending invitations: several at once"}, {"steps": ["Click \"Pending invitations\u2026\" at the top right (the number is how many are waiting).", "The list shows every guest who has not accepted, oldest first, with the days waited. Guests waiting more than 30 days are ticked; change the ticks as you like.", "\"Resend invitation to N guests\" sends the invitation again to the ticked guests, after a confirmation.", "To remove instead: type REMOVE and the number of ticked guests (for example REMOVE 3) and click \"Remove N guests\".", "The result lists every guest with what happened. \"\u2190 Back to all guests\" returns to the full list."]}, {"bullets": ["Only guests whose invitation is still pending are handled. A guest who accepted in the meantime is skipped; a staff account can never be removed this way.", "A ticked guest whose sign-in is blocked is not re-invited; the screen says how many.", "A resent invitation keeps the guest \"pending\" until the person accepts. Refresh later to see who did."]}, {"h": "What it needs"}, {"bullets": ["Your role: \"Microsoft 365 \u00b7 View\" to see guests; \"Microsoft 365 \u00b7 Accounts\" to block, re-invite and remove them.", "Azure app: nothing new. The list uses User.Read.All; blocking, removing and resending invitations use User.ReadWrite.All \u2014 both already there if onboarding and offboarding work. (User.Invite.All alone is enough for resending.)", "Resending also needs guest invitations to be allowed in your tenant: Entra admin center \u2192 External Identities \u2192 External collaboration settings. If Microsoft refuses, the message says so.", "Last sign-in dates need AuditLog.Read.All and Entra ID P1 (part of Business Premium). Without them the guests are still listed, the dates show \"\u2014\", and nobody is flagged \"Not used 90 days\".", "The list is kept for 10 minutes (\"\u00b7 cached\"); blocking or removing a guest refreshes it. Every change is in the Audit Log."]}, {"qa": [{"q": "How do I invite a new guest?", "a": "Not from ITOps. People invite guests from Teams or SharePoint, or an administrator from the Entra admin center. ITOps resends invitations that were never accepted and removes guests nobody needs."}, {"q": "After \"Resend invitation\" the message says Microsoft created a new guest account.", "a": "Rarely, Microsoft does not match the address to the existing guest and makes a second account. Refresh the list: you will see two guests with that address. Remove the older one that stays pending."}, {"q": "A guest is \"Not used 90 days\" but I know they work with us.", "a": "They may only receive email from the team, which is not a sign-in. Ask the team's owner before removing; blocking first is the safe step."}, {"q": "Why does a guest show a strange account name with #EXT#?", "a": "That is how Entra names guest accounts: the person's own address with \"_\" instead of \"@\", followed by #EXT# and your tenant. The \"Email\" field is the address they sign in with."}]}]}, {"title": "Device inventory: every computer that signs in", "for": "admin", "body": [{"p": "Microsoft 365 \u2192 Devices \u2192 \"Device inventory\" lists every device that signs in with a work account \u2014 company computers and personal ones \u2014 without installing anything on them. It is built from two things Microsoft already records \u2014 the Entra device list and the Entra sign-in log \u2014 plus what ITOps itself sees when a person opens it (in Teams or in a browser). Reading it changes nothing; a registered device can also be disabled, removed or looked up for its recovery key from its row \u2014 see \"Device actions and recovery keys\"."}, {"h": "What each row tells you"}, {"bullets": ["Device and person: the device name and model when Entra knows them, and the person who uses it. \"+2 more\" means other people have signed in on the same device.", "OS: the operating system, with its exact version when the device is registered in Entra.", "Type: \"Company\" (joined to the organization, or marked company-owned in Intune), \"Personal\" (a personal device the person registered with their work account), \"Unregistered\" (seen only in the sign-in log) or \"Unknown\" (Entra does not say).", "Intune: \"Managed\" and whether it is compliant, or \"Not managed\".", "Last seen: the latest sign-in or activity, with the city it came from. Click a row for the details: everyone seen on it, the app and browser of the last sign-in, the IP address, when it was first recorded and what each flag means."]}, {"h": "Flags"}, {"bullets": ["\"Not managed\": Intune does not manage this computer, so its disk encryption, firewall and updates are not known. Normal for personal computers.", "\"OS out of support\": the operating system no longer gets security updates (Windows 10 or older, macOS 13 or older).", "\"Not seen 90 days\": probably retired, lost or replaced.", "\"Owner disabled\": the person's Microsoft 365 account is disabled but the device is still listed. Check it after an offboarding.", "\"Removed from Entra\" and \"Device disabled\": the device was deleted or disabled in Entra."]}, {"h": "Using the screen"}, {"steps": ["Open the tab. The first time, ITOps reads Entra and up to 30 days of sign-ins; this can take a minute.", "Click a tile (Company, Personal, Unregistered, Unknown) or a flag to filter. \"Computers\", \"Phones & tablets\" and \"All\" choose the kind of device; the screen starts on Computers.", "Switch to \"By person\" to see what each person uses \u2014 for example who works from a personal or unregistered computer.", "Search by device, person, operating system or city. \"Export CSV\" downloads the rows you are looking at.", "\"Sync now\" reads Microsoft again (at most once a minute). The scheduled job also syncs once a day.", "\"Clean up stale devices\u2026\" at the top opens the bulk clean-up: disable devices nobody uses, then remove them later. See its own topic."]}, {"h": "Good to know"}, {"bullets": ["An \"Unregistered\" row comes from the sign-in log. It groups one person's sign-ins from one operating system, so it can stand for more than one physical computer.", "For an \"Unregistered\" row, \"Last seen\" is the last time the person had to sign in on it (password or MFA). Apps that stay signed in do not add new entries, so the date can be weeks old on a computer that is used every day. Opening ITOps on the device (in Teams or a browser) also counts as \"seen\", and the row then shows \"in Teams\" or \"in ITOps\" under the date. The details show \"Person last active\", and the row is only flagged \"Not seen 90 days\" \u2014 or removed after 180 days \u2014 when the person has not been active either.", "The sign-in log does not tell Windows 10 from Windows 11. For a device that is not registered, the exact version (and \"OS out of support\") is known once its owner has opened ITOps on it, in Teams or in a browser.", "Microsoft keeps sign-ins for 30 days. ITOps keeps what it has read, so the history builds up from the day you install this build. Unregistered and removed devices leave the list after 180 days without activity.", "Disk encryption, firewall and update status are only known for computers Intune manages \u2014 see Devices \u2192 \"Compliance\".", "Microsoft 365 \u2192 Home has a \"Personal computers\" card, and \"Needs attention\" lists devices whose owner is disabled, computers out of support and devices not seen for 90 days.", "Access ends with the account: when a person is offboarded their devices stop signing in, and the row is flagged \"Owner disabled\".", "What ITOps records itself comes from the browser: operating system, version when the browser gives it (Chromium browsers), and the browser or Teams client. It is an indication, not proof, and it can be switched off under Integrations \u2192 Microsoft Teams \u2192 \"Device inventory\". If a person has exactly one registered device with that operating system, the report is attached to it; otherwise to their \"Unregistered\" row."]}, {"h": "What it needs"}, {"bullets": ["Your role: \"Microsoft 365 \u00b7 View\".", "Azure app: Device.Read.All for the Entra device list, and AuditLog.Read.All for the sign-in log (the sign-in log also needs Entra ID P1, which is part of Microsoft 365 Business Premium). With only one of the two, the screen shows what it can and names what is missing.", "To act on devices: \"Microsoft 365 \u00b7 Entra devices\" and, for recovery keys, \"Microsoft 365 \u00b7 Recovery keys\" \u2014 see the next topic."]}, {"qa": [{"q": "A person uses a personal PC but I only see an \"Unregistered\" row.", "a": "They sign in through the browser or chose \"sign in to this app only\", so the PC never registered in Entra. The row still shows the operating system, the last sign-in and where it came from."}, {"q": "The same person has an Unregistered row and a registered device with the same operating system.", "a": "Some of their sign-ins did not carry the device identity (for example a private browser window). It can be the same computer."}, {"q": "Can I lock or wipe a device from here?", "a": "Not lock or wipe: those are Intune actions, on Devices \u2192 \"Compliance\", for company devices only. From the inventory you can disable or remove the device's registration in Entra and look up its BitLocker recovery key \u2014 see \"Device actions and recovery keys\". Nothing here ever erases a computer."}, {"q": "The location looks wrong.", "a": "It is Microsoft's estimate from the IP address. VPNs and mobile networks often show another city."}]}]}, {"title": "Device actions and recovery keys (BitLocker, LAPS)", "for": "admin", "mod": "m365", "body": [{"p": "In Devices \u2192 \"Device inventory\", click a device that is registered in Entra. Under its details, \"Actions in Entra\" shows what can be done with it \u2014 and, in words, why something cannot. ITOps reads the device from Entra again at that moment, so the buttons match its real state, not yesterday's sync."}, {"h": "Disable and enable"}, {"bullets": ["\"Disable\" stops the device from using its identity with Microsoft 365: single sign-on ends and sign-in rules that ask for a known device block it. Nothing on the computer is erased, and \"Enable\" brings it back.", "Offered for Windows devices only. Microsoft does not let an application disable a Mac, a phone or a Linux computer; for those the screen says so and you use the Entra admin center.", "Not offered for computers synced from an on-premises Active Directory (\"Hybrid joined\"): disable them on-premises, or the next sync undoes it."]}, {"h": "Remove from Entra"}, {"steps": ["Disable the device first and wait until you are sure nobody misses it. This is Microsoft's own advice for cleaning up stale devices, and ITOps enforces it for Windows: \"Remove from Entra\u2026\" appears only once the device is disabled.", "Click \"Remove from Entra\u2026\". Read the three points: the registration cannot be restored, the BitLocker recovery keys and local administrator password Entra holds for it are deleted with it, and nothing on the computer itself is erased.", "Type the device name and click \"Remove from Entra\". The row is flagged \"Removed from Entra\" at once and leaves the list later."]}, {"bullets": ["A Mac, phone or Linux device cannot be disabled by an application, so it can be removed directly \u2014 but only when it has not been seen for 90 days or its owner's account is disabled.", "Never offered while Intune manages the device (retire or delete it in Intune first, on Devices \u2192 \"Compliance\"), while Windows Autopilot holds it, or for hybrid computers.", "Rows that come from the sign-in log (\"Unregistered\") have nothing to disable or remove: the device was never registered."]}, {"h": "Recovery key and local administrator password"}, {"steps": ["Click \"Recovery key & admin password\". ITOps lists the BitLocker recovery keys Entra holds for the computer \u2014 the drive and the date, not the key.", "Type why you need it (a ticket number or a few words).", "Click \"Show key\" on the right drive, or \"Show password\" for the local administrator password that Windows LAPS backed up. Compare the \"Key ID\" with the one on the person's BitLocker screen (the first 8 characters are enough).", "Read it to the person or click \"Copy\". \"Hide\" removes it from the page; it also hides itself after two minutes."]}, {"bullets": ["Every view is recorded: ITOps's Audit Log keeps who asked, for which device, which key and the reason \u2014 never the key or the password. Microsoft records the read in the Entra audit log as well.", "ITOps does not store keys or passwords, and the browser is told not to keep the answer.", "BitLocker keys exist only for Windows computers whose key was saved to Entra. Local administrator passwords exist only for computers joined to the organization with Windows LAPS set up; a personal (registered) PC has none.", "After a recovery key has been used, Windows can make a new one by itself when Intune's BitLocker policy has recovery-password rotation switched on. Until then the key you read stays valid, so treat it as a secret."]}, {"h": "What it needs"}, {"bullets": ["Your role: \"Microsoft 365 \u00b7 View\", plus \"Microsoft 365 \u00b7 Entra devices\" to disable, enable and remove, and \"Microsoft 365 \u00b7 Recovery keys\" to see keys and passwords. Neither is given to any role automatically \u2014 not even to roles with \"Tenant configuration\". Super Admins have both.", "Azure app (Application permissions with admin consent): Device.ReadWrite.All to disable, enable and remove; BitlockerKey.Read.All for recovery keys; DeviceLocalCredential.Read.All for local administrator passwords. Add only the ones you will use.", "If \"Disable\" is refused although Device.ReadWrite.All is granted: in the Entra admin center \u2192 Roles and administrators \u2192 \"Cloud Device Administrator\", add the ITOps enterprise application as a member. Microsoft requires that role for enabling and disabling devices."]}, {"qa": [{"q": "Why is \"Remove\" missing for a computer I want to delete?", "a": "The line under the buttons says why: it is still enabled (disable it first), Intune still manages it, Autopilot holds it, or it is synced from on-premises."}, {"q": "I removed a device by mistake.", "a": "An Entra device cannot be restored. Register or join the computer again (Settings \u2192 Accounts \u2192 Access work or school). Its old recovery keys are gone, which is why ITOps asks you to look them up first if they may still be needed."}, {"q": "It says \"Entra holds no recovery key for this computer\".", "a": "The drive is not encrypted, or the key was saved to a personal Microsoft account or printed instead. Intune's BitLocker policy (Devices \u2192 Device policies \u2192 \"Seed device security\") makes Windows save it to Entra."}, {"q": "\"No local administrator password is stored for this computer.\"", "a": "Windows LAPS is not set up for it, or it has not backed up a password yet. It needs a LAPS policy in Intune and \"Enable Microsoft Entra Local Administrator Password Solution\" in Entra \u2192 Devices \u2192 Device settings."}, {"q": "Who looked at a recovery key last month?", "a": "Logs & Integrations \u2192 Audit Log, search \"bitlocker\" or \"laps\". Each entry has the person, the device, the key ID and the reason they typed."}]}]}, {"title": "Cleaning up stale devices: disable, wait, remove", "for": "admin", "mod": "m365", "body": [{"p": "Over time the Entra device list fills with computers and phones nobody uses any more: replaced laptops, a phone someone traded in, the PC of a person who left. Devices \u2192 \"Device inventory\" \u2192 \"Clean up stale devices\u2026\" retires them several at a time, in the two steps Microsoft advises: disable first, remove later."}, {"h": "Step 1 \u2014 Disable"}, {"steps": ["Open the Device inventory and click \"Sync now\" if the last sync is old. The clean-up works from that list.", "Click \"Clean up stale devices\u2026\".", "Step 1 lists Windows devices that are registered, still enabled, not managed by Intune and not seen for 90 days. All are ticked; untick any you want to leave alone.", "Click \"Disable N devices\" and confirm."]}, {"bullets": ["A disabled device can no longer sign in with its device identity. Nothing is deleted and nothing on the computer changes.", "It is reversible: open the device's row in the inventory and click \"Enable\".", "If someone still uses one of them, they will tell you \u2014 that is the reason for waiting before step 2."]}, {"h": "Step 2 \u2014 Remove"}, {"steps": ["Come back after about 30 days.", "Step 2 lists Windows devices that are disabled and not seen for 90 days, and phones, tablets and Macs not seen for 90 days or whose owner's account is disabled.", "Read \"Why it is listed\". A Windows device is ticked only once it has been disabled from ITOps for 30 days; the line says who disabled it and when. Devices disabled somewhere else show \"date not known\" and are left unticked.", "Tick or untick as needed, type REMOVE and the number of ticked devices (for example REMOVE 4), and click \"Remove N devices\"."]}, {"warn": "Removing cannot be undone from ITOps. For a computer joined to the organization \u2014 marked \"Recovery keys go with it\" \u2014 the BitLocker recovery keys and the local administrator password Entra holds are deleted with it. If the disk may still be needed, look the key up first (the device's row \u2192 \"Recovery key & admin password\")."}, {"h": "What ITOps checks before it changes anything"}, {"bullets": ["Each device is read from Microsoft again just before it is changed. One that was used since the last sync is skipped.", "Never touched: computers managed by Intune (retire them on Devices \u2192 Compliance), registered with Windows Autopilot, or joined to an on-premises domain. The line under step 2 says how many stale devices were left out and where to handle them.", "Phones, tablets and Macs go straight to step 2 because Microsoft does not let an application disable them.", "Rows that only come from the sign-in log (\"Unregistered\") are not in Entra, so there is nothing to remove; they leave the inventory by themselves.", "After each step the result lists every device: Disabled or Removed, Skipped with the reason, or Failed with Microsoft's answer. If Microsoft refuses the first device for lack of permission, the rest is not attempted."]}, {"h": "What it needs"}, {"bullets": ["Your role: \"Microsoft 365 \u00b7 Entra devices\" to disable and remove. With \"Microsoft 365 \u00b7 View\" only, both lists are shown read-only.", "Azure app: Device.ReadWrite.All (Application, admin consent). The \"About this screen\" button (\u24d8 in the top bar) shows whether the token carries it.", "If Microsoft refuses to disable although the permission is there, give the app's enterprise application the Entra role \"Cloud Device Administrator\" (Entra admin center \u2192 Roles and administrators).", "Every device changed is written to the Audit Log, one entry per device, marked as part of a bulk action."]}, {"qa": [{"q": "Why is a device I disabled yesterday not ticked in step 2?", "a": "The waiting time is not over. It is listed with \"Waiting time not over: 30 days are advised\". You can tick it yourself if you are sure nobody needs it."}, {"q": "A device was skipped with \"seen in the last 90 days\".", "a": "Someone used it after the last sync, so it is no longer stale. Sync the inventory and it will leave the list."}, {"q": "Can I change the 90 and 30 days?", "a": "Not in this version. 90 days is the same limit as the \"Not seen 90 days\" flag in the inventory. A single device can always be disabled or removed from its own row, whatever its dates."}, {"q": "I removed a device that was still in use.", "a": "An Entra device cannot be restored. The person registers or joins the computer again (Settings \u2192 Accounts \u2192 Access work or school). This is why step 1 exists: disable first and wait."}]}]}, {"title": "Enterprise apps: which applications hold access", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 Security \u2192 \"Enterprise apps\" answers a question that is otherwise hard to see in one place: which applications can reach your tenant's data, what exactly each one may do, and who agreed to it. It is read-only."}, {"h": "Two kinds of access"}, {"bullets": ["\"Without a person\" (application permissions): the app works by itself, at any time, for the whole tenant \u2014 for example a backup tool that reads every mailbox. Only an administrator can grant these.", "\"On behalf of people\" (delegated permissions): the app acts as the person who is signed in, limited to what that person can reach. Either an administrator agreed for everyone (\"admin consent\"), or people agreed one by one for themselves.", "Click an app to see every permission, the Microsoft service it belongs to, and for delegated ones whether it is for everyone or how many people consented."]}, {"h": "Flags \u2014 what to look at first"}, {"bullets": ["\"High privilege\": the app may read or change mail, files, accounts or the directory without anyone signing in. Expected for tools you chose (ITOps itself is one); question any you do not recognise.", "\"User consent \u00b7 sensitive\": one or more people \u2014 not an administrator \u2014 let the app read their mail, files or contacts. This is how consent phishing works: a fake \"sign in to view the document\" page asks for these permissions. Check the app with the people who consented.", "\"User consent\": people agreed by themselves, but only to basics such as signing in and their own profile.", "\"Unverified publisher\": a third-party app whose publisher Microsoft has not verified.", "\"Sign-in disabled\": nobody can sign in to it, yet its permissions are still granted."]}, {"h": "What is listed"}, {"bullets": ["Every application that was granted a permission in your tenant, plus third-party applications and your own that were added to it.", "Microsoft's own background services that hold no grant are left out: every tenant has hundreds of them.", "\"From\" says whose application it is: your organization, Microsoft, or a third party.", "Application permissions are read for Microsoft Graph, Exchange Online and SharePoint \u2014 the services that hold mail, files and the directory.", "Permissions marked \"sensitive\" are the ones on ITOps's own watch list (mail, files, accounts, directory, roles, device secrets). It is a guide for where to look, not a verdict."]}, {"h": "Taking access away"}, {"p": "ITOps does not change applications. Use \"Open in the Entra admin center \u2197\" on the app: \"Permissions\" to review and revoke what was granted, \"Properties\" \u2192 \"Enabled for users to sign in\" = No to stop it at once, or delete the application. To stop people from consenting by themselves: Entra admin center \u2192 Enterprise applications \u2192 Consent and permissions \u2192 User consent settings."}, {"p": "Why ITOps does not do it for you: stopping an application or revoking its access needs Microsoft permissions (Application.ReadWrite.All, AppRoleAssignment.ReadWrite.All) that would let ITOps grant itself any access in the tenant. A web application should not hold those, so these few clicks stay in Microsoft's own admin center."}, {"h": "What it needs"}, {"bullets": ["Your role: \"Microsoft 365 \u00b7 View\".", "Azure app: Application.Read.All (already used by \"App secrets\") for the applications and their application permissions; Directory.Read.All for the delegated permissions. Without Directory.Read.All the screen still works and says that the delegated part is missing.", "The list is kept for 10 minutes; \"Refresh\" reads Microsoft again."]}, {"qa": [{"q": "ITOps itself is flagged \"High privilege\".", "a": "Correct: it holds the permissions you granted so it can onboard and offboard people, read reports and so on. The list in the details is exactly what its Azure app may do \u2014 the place to check when you remove a permission you no longer use."}, {"q": "An app I removed is still listed.", "a": "The list is cached for 10 minutes. Click Refresh."}, {"q": "Who are the people who consented?", "a": "ITOps shows how many, not who. The Entra admin center lists them under the app \u2192 Permissions \u2192 \"User consent\"."}]}]}, {"title": "Entra audit log: who changed what in the directory", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 Collaboration & activity \u2192 \"Audit log\" shows Microsoft's own record of changes in the directory: accounts created, blocked or deleted, password resets, group members added or removed, devices, applications and their permissions, admin roles and policies. It is read-only. Do not confuse it with ITOps's own Audit Log (Logs & Integrations), which records what people did inside ITOps."}, {"h": "Using it"}, {"steps": ["Choose the period: 24 hours (the screen opens there), 7 days or 30 days.", "Click a category chip (for example UserManagement, GroupManagement, ApplicationManagement, Policy) to ask Microsoft for that category only. The chip with \u2715 removes the filter.", "\"Failed only\" keeps the entries that did not succeed. Search matches the activity, the person, the target and the IP address.", "Click an entry to see what changed \u2014 the value before and after \u2014 plus the reason, the service that recorded it and the IP address.", "\"Export CSV\" downloads the entries you see."]}, {"h": "Good to know"}, {"bullets": ["\"By\" is the person who made the change, or the application when a program did it (marked \"app\"). Changes made from ITOps appear under the name of its application; ITOps's own Audit Log has the name of the person who clicked.", "Microsoft keeps this log for 7 days on Entra ID Free and 30 days with Entra ID P1 (part of Business Premium).", "At most the newest 1,000 entries of 24 hours, or 2,000 of a longer period, are read. When that limit is reached the screen says so: choose a category or a shorter period.", "Sign-ins are not here: see a person's recent sign-ins on Accounts, and devices on Device inventory.", "Answers are kept for 5 minutes; \"Refresh\" reads Microsoft again."]}, {"h": "What it needs"}, {"bullets": ["Your role: \"Microsoft 365 \u00b7 View\".", "Azure app: AuditLog.Read.All \u2014 the same permission the MFA report and the Device inventory use."]}, {"qa": [{"q": "Who disabled this account, and when?", "a": "Choose 7 or 30 days, click UserManagement, search the person's name. \"Update user\" with AccountEnabled true \u2192 false is the entry."}, {"q": "Did someone add an app or grant it permissions?", "a": "Category ApplicationManagement: look for \"Add service principal\", \"Consent to application\" and \"Add app role assignment to service principal\". Then check the app on Enterprise apps."}]}]}, {"title": "Service health, mailboxes, Teams, storage and Copilot", "for": "admin", "mod": "m365", "body": [{"bullets": ["\"Service health\": services that are not operational, open issues (tick \"show resolved\" for the rest) and Message center posts (tick \"action / major only\" for the ones with a deadline or a major change).", "\"Mailboxes\": size, % of quota (amber at 75%, red at 90%), items and last activity. Tiles filter to \"Near quota\" or \"Inactive 30d\".", "\"Teams\": messages, calls and meetings per person over 30 days; tiles filter active / inactive.", "\"Storage\": OneDrive accounts and SharePoint sites, biggest first, with \"near full only\".", "\"Copilot\": licensed vs active vs idle, the daily active-user trend, which Copilot apps are used, and per-person last activity. The period is the one Microsoft answers for: Microsoft's newer Copilot reports cover 28 days, so the page then says \"over the last 28 days\" and \"Active 28d\"."]}, {"p": "All five read Microsoft's usage reports (Reports.Read.All; Service health needs ServiceHealth.Read.All and ServiceMessage.Read.All). Microsoft's reports lag by one to two days."}, {"qa": [{"q": "Copilot showed \"The period value 'RL30' is not supported \u2026 Use 'RL28' instead\" or \"Invalid period value specified: RL28\".", "a": "That was Microsoft changing its Copilot reports: it now reports 28 days. From build BT56 the app reads Microsoft's message, asks for the period it accepts (D28) and remembers it, so the page loads and says \"over the last 28 days\". Press \"Refresh\" on the page if it still shows the old message."}]}]}, {"title": "Microsoft 365 permissions: who can do what", "for": "admin", "mod": ["roles", "users"], "body": [{"p": "The Microsoft 365 area is split by kind of change, so a role can read everything but change only what it should. Set them under Administration \u2192 Roles & Permissions \u2192 \"Microsoft 365\"."}, {"bullets": ["Microsoft 365 \u00b7 View \u2014 every Microsoft 365 screen, read-only, including Guests, Enterprise apps and the Entra audit log (m365.view).", "Microsoft 365 \u00b7 Accounts \u2014 edit contact information, manager and custom fields of one account or of several at once; Onboard, Offboard, block and restore sign-in; also block, re-invite and remove guests on People \u2192 Guests, one at a time or under \"Pending invitations\" (m365.users).", "Microsoft 365 \u00b7 Credentials \u2014 reset password, reset MFA, revoke sessions, sign-in methods, Temporary access pass (m365.credentials).", "Microsoft 365 \u00b7 Licenses \u2014 assign, remove and reclaim licenses (m365.licenses).", "Microsoft 365 \u00b7 Groups \u2014 add people and devices to groups and remove them: on a person, on People \u2192 Groups, and the template groups at onboarding. Also change group owners and create security groups on People \u2192 Groups (m365.groups).", "Microsoft 365 \u00b7 Directory roles \u2014 assign and remove Entra admin roles (m365.roles). Not given to any role automatically.", "Microsoft 365 \u00b7 Entra devices \u2014 disable, enable and remove devices in Entra from the Device inventory, one at a time or with \"Clean up stale devices\". Not given to any role automatically.", "Microsoft 365 \u00b7 Recovery keys \u2014 see BitLocker recovery keys and local administrator (LAPS) passwords; each view asks for a reason and is recorded. Not given to any role automatically.", "Provisioning \u00b7 Onboard to vTiger / Offboard from vTiger \u2014 create the vTiger user; reassign records, deactivate and verify (provision.onboard / provision.offboard). These are needed for the vTiger steps of any onboarding or offboarding, also in History and in a template; a vTiger admin is handled by a Super Admin only.", "Onboarding templates & history \u2014 view the History tab and the templates; edit = create and change onboarding templates, work the steps of a process and the vTiger provisioning connection. Without \"All records\" a person sees the processes they started and those of their own department.", "Microsoft 365 \u00b7 Tenant configuration \u2014 the ITOps extras: Rollout ticks and emails, device and app-protection policies, Conditional Access, email security.", "Onboarding \u00b7 Edit \u2014 also names the custom fields and keeps the company-wide values (Onboarding Templates \u2192 \"Custom fields\"). Everyone with Microsoft 365 \u00b7 View can read them.", "Company systems (under Administration in the grid, with the Settings permissions) \u2014 View: each person's accounts in the other systems, shown on their account under Microsoft 365 \u2192 People (the block \"Systems\" and the count in the list), and \"Needs attention\" under Microsoft 365 \u2192 People. A role that has only this permission gets \"Settings\" in its menu with that one tab. Edit: record, correct and close accounts. Not given to any role automatically. The steps inside an onboarding or offboarding are answered by whoever runs it; which systems are in use is set by a Super Admin or a role with Integrations \u00b7 Edit."]}, {"p": "Upgrading keeps everyone's access: roles that had \"M365 Admin\" (edit) get Accounts, Credentials, Licenses and Groups; roles that could edit onboarding get the two Provisioning permissions. Nobody gets Directory roles, Entra devices or Recovery keys automatically: tick them for the people who need them. Super Admins always have them."}, {"p": "Whatever the role: actions on admin accounts and the high-risk directory roles are Super Admin only (see \"Accounts: managing one person\")."}]}, {"title": "Company systems: the list, what needs attention and recording accounts", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "Administration \u2192 Settings \u2192 \"Company systems\" is the list of systems where a person has an account, a seat or a number, with a tab for each connected system. A person's accounts are shown on the person: Microsoft 365 \u2192 People, in the block \"Systems\". Microsoft 365 \u2192 People \u2192 \"Needs attention\" names the people to look at."}, {"h": "Systems"}, {"bullets": ["Microsoft 365 and vTiger are shown as \"Connected\", with how many accounts each has: they have their own steps and are not set up here.", "HubSpot, JustCall, eFax (Documo), Jotform, the phone system (PBX) and Paylocity are known by name. Each starts as \"Not used\". For Paylocity the account is the employee ID, and its steps are HR's: enter the hire, enter the termination.", "\"+ Add a system\" adds one of your own: accounting, a door badge, anything a leaver must lose. Up to 20."]}, {"steps": ["Click \"Switch on\u2026\" (or \"Set up\u2026\"). The system opens as a full page. Its box \"How to connect \u2026\" says where the API key is made at the vendor; \"How the process works\" says what you will see and what happens at onboarding, offboarding and verification.", "\"Use\": \"Tracked by hand\" or \"Not used\". JustCall also offers \"Connected\": see \"JustCall connected: reading its users instead of typing them\".", "\"Link to its admin page\": shown on every step, opens in a new tab. It must be a full web address.", "Tick \"Offer it at onboarding\" and \"Add a step at offboarding\". Leave \"At every offboarding, also when no account is recorded for the person\" on until your records are complete.", "\"An account there is\": the hint shown in the box where an account is typed, for example \"the extension number\".", "Write \"What to do at onboarding\" and \"What to do at offboarding\" in your own words. They are shown on the step.", "Click \"Save\"."]}, {"p": "Setting a system to \"Not used\" takes its step out of new onboardings and offboardings. What was recorded is kept, and an account that is still open shows on the person under \"Systems no longer in use\". A system of your own can be removed from the list only while no account was ever recorded for it."}, {"h": "Company tools: hosting provider, WHM / cPanel, CodeTwo"}, {"p": "Under the systems, \"Company tools\" lists what the company uses with no account per person. A tool never adds a step to onboarding or offboarding, takes no recorded accounts and is not offered in onboarding templates. Its set-up page has only \"Use\" (\"In use by the company\" or \"Not used\"), a link, and its guide."}, {"bullets": ["Hosting provider: where to request an API key in the provider's customer portal and what to keep in mind. A read-only connection (servers, the provider's tickets, invoices) is planned; there is no box for the key yet.", "WHM / cPanel: how to make a WHM API token (WHM \u2192 Development \u2192 Manage API Tokens \u2192 Generate Token; limit it to the server's address; untick \"Everything\", \"Change Password\" and \"Create User Session and Manage API Tokens\"; copy it at once). The token goes under Server Guardian \u2192 Configure server checks (Super Admin), with the WHM host, port 2087 and user. The list says whether Server Guardian already has a WHM host and token saved; it never shows them.", "CodeTwo Email Signatures: nothing to connect. CodeTwo reads every account from Microsoft Entra ID about every 20 minutes, so a change on Microsoft 365 \u2192 People reaches the signatures by itself. To see it sooner: login.codetwo.com \u2192 Tenants \u2192 your tenant \u2192 User Entra ID attributes \u2192 \"Update cache manually now\"."]}, {"tip": "Paylocity approves API access per company and charges for it. Start the request early: the steps are on Paylocity's set-up page under \"How to connect Paylocity\"."}, {"h": "Needs attention"}, {"bullets": ["On Microsoft 365 \u2192 People, tab \"Needs attention\" (until BT160 it was under the list of systems). It is not a list of everybody: the people are on Microsoft 365 \u2192 People, each with every system. Here are only the ones to look at, also when no other system is switched on.", "\"Left \u00b7 accounts still open\" (red): the Microsoft 365 account is blocked and the vTiger user is still active, or an account elsewhere is still recorded as open.", "\"Not in Microsoft 365\" (amber): an account is recorded under an email that no Microsoft 365 account has. The person left and was removed, or the email was typed differently.", "\"In vTiger only\": an active vTiger user that no Microsoft 365 account matches. It is listed for information and not counted in the number.", "One column per system in use shows the accounts. \"Refresh\" reads Microsoft 365, vTiger and the connected systems again. With nobody to list it says \"Nothing needs attention.\"", "Click a row: the person opens as a full page with a section per system. This is the way to someone who has no Microsoft 365 account any more."]}, {"h": "A person"}, {"steps": ["Open Microsoft 365 \u2192 People and click the person. Their systems are in the block \"Systems\", one row each.", "On the row of a system tracked by hand click \"+ Record an account\". Type its name (or leave it empty when you only know that there is one), an optional note, and click \"Record an account\".", "\"Edit\" corrects the name or the note. \"Close\" records that the account was removed in the other system; ITOps does not remove it there.", "\"+ Show closed accounts\" lists what was closed, with who and when, and offers \"Open again\"."]}, {"p": "The row of a connected system (JustCall) shows what that system listed at its last reading, with \"Read from JustCall: change it there.\" Its accounts are not typed, corrected or closed in ITOps."}, {"h": "Recording many accounts at once"}, {"steps": ["On \"Systems\" click \"Record accounts from a list\u2026\" (shown when at least one system is tracked by hand).", "Choose the system and paste one line per account: the work email, then the account name, then an optional note, separated by a comma, a semicolon or a tab. A user export from that system usually fits.", "Click \"Preview\". Each line is marked New, Already recorded, Closed before or Not a work email. Nothing is recorded yet.", "Type the confirmation shown (for example RECORD 42) and click \"Record\". At most 500 lines at a time."]}, {"p": "People are matched by their exact work email or sign-in name, never by name. Every system that is switched on or changed, and every account recorded, corrected, closed, opened again or handed over, is written to the Audit Log with who did it, when, the person, the system and the old and new values (filter the Audit Log by type \"access\")."}, {"qa": [{"q": "I do not see \"Company systems\".", "a": "It is a tab of Administration \u2192 Settings (until build BT47 it was a page under IT Operations). Your role needs \"Company systems\" (View); it is not given to any role automatically."}, {"q": "I see the list but no \"Set up\u2026\" button.", "a": "Changing the list is for a Super Admin, or a role with Integrations \u00b7 Edit."}, {"q": "I see a person's systems but cannot record anything.", "a": "Recording, correcting and closing need \"Company systems\" with Edit."}, {"q": "Where did the \"Access overview\" tab go?", "a": "It was a second list of the same people as Microsoft 365 \u2192 People. Each person's systems are now on their account, and \"Needs attention\" keeps the ones to look at. The list of everybody and its CSV export went with the tab."}, {"q": "\"Needs attention\" says Microsoft 365 could not be read.", "a": "Nobody can then be flagged as having left. Check the Microsoft 365 connection under Microsoft 365 \u2192 Home \u2192 Diagnose."}, {"q": "A person who left is not flagged.", "a": "The flag needs two things: the Microsoft 365 account is blocked, and an account in another system is recorded as open. If nothing was ever recorded for the person, there is nothing to flag: bring the accounts in with \"Record accounts from a list\u2026\"."}, {"q": "The run page says \"Run db-update.php\".", "a": "An update added a table or columns. Open db-update.php once (Settings \u2192 Maintenance) after uploading the new version."}, {"q": "Someone I know has a Microsoft 365 account is listed as \"In vTiger only\", with \"no account\".", "a": "Up to build BT48 the page took who has an account from one Microsoft listing, the one that also carries sign-in dates. When that listing left an account out, the person looked like they had none; that is the likely cause. Since BT49 the accounts are read from the plain listing, and before the page says \"no account\" Microsoft 365 is asked for that exact address: as sign-in name, mail address or alias. The line above the table says how many accounts were read, how many addresses were asked for and what Microsoft 365 answered (left out of the list, under an alias, a guest). An address that could not be asked about shows \"not read\", never \"no account\"; \"Refresh\" asks again. The Event Log (Microsoft 365) records each time this found accounts, with counts and no names. If a person is still listed with \"no account\", the address in vTiger is not one of theirs in Microsoft 365: correct it in vTiger, or add it as an alias in Microsoft 365."}]}]}, {"title": "Connecting vTiger provisioning", "for": "admin", "mod": ["onboarding:edit", "integrations"], "body": [{"p": "vTiger cannot create users through its Web Services API, so ITOps uses a small bridge file on the vTiger server. It creates and deactivates users, lists roles and users, and moves record ownership for onboarding and offboarding."}, {"h": "First-time setup (Super Admin)"}, {"steps": ["Upload vtiger-bridge/itops-bridge.php from the install package to the vTiger web root, next to config.inc.php.", "In ITOps, open Settings \u2192 Company systems \u2192 vTiger \u2192 Set up\u2026.", "Under \"Provisioner bridge\", enter the \"Bridge URL\" and click \"Generate\" next to \"Shared secret\". Copy the value.", "Click \"Save bridge\".", "On the vTiger server (cPanel File Manager is fine), create a file named itops-bridge.secret next to the bridge, containing only that value. Set its permissions to 600 and deny web access to it in .htaccess.", "Click \"Test bridge\". It should say \"Bridge reachable\" with the vTiger version, admin and PHP version."]}, {"bullets": ["Under \"Default role for new vTiger users\" (shown once the bridge is saved), pick a role from the list and click \"Save default role\". The roles are read from vTiger through the bridge \u2014 nothing to type. The default is used when a template has no role, and is preselected on the Onboard screen.", "\"Provisioning account \u00b7 Web Services\" (endpoint, username, access key) is optional when the bridge is set up. \"Test & save\" logs in before saving.", "\"Read-only DB\" is optional too. Roles, the user list and duplicate-email checks all come through the bridge; the DB is only a fallback if the bridge can't answer."]}, {"h": "Changing the secret safely"}, {"steps": ["Click \"Rotate secret\u2026\" and confirm. A new secret is shown once; the current one keeps working. Copy it.", "Put the new value in itops-bridge.secret on the vTiger server.", "Click \"Activate new secret\". ITOps tests the bridge with it and switches only if it is accepted. \"Cancel rotation\" discards it."]}, {"warn": "The bridge settings are Super Admin only. Never put the secret in a file the web can read. The secret is never shown again after you leave the page."}, {"h": "Updating the bridge file"}, {"p": "The bridge file carries a build number (now o8). When ITOps needs a newer one it says \"The vTiger bridge on the server is an older build (\u2026)\" on the Offboard steps, and \"vTiger users are not shown.\" on Microsoft 365 \u2192 People; \"Test bridge\" says when the server still runs a build older than o8. Upload vtiger-bridge/itops-bridge.php from the install package over the old file in the vTiger web root. The secret file (itops-bridge.secret) stays as it is. \"Test bridge\" then reports the new build."}, {"h": "Build o8 (with ITOps 0621-BT89)"}, {"bullets": ["Update ITOps first, then upload the bridge: build o8 refuses requests from an older ITOps (\"Missing one-time number\").", "Every request carries a one-time number; the bridge refuses one it has already seen, so a copied request cannot be sent again. It keeps them in a private folder under the server's temporary folder, which PHP must be able to write.", "New users and password changes are refused over plain http: use the https:// address of the bridge. \"Test bridge\" warns when the address is not https://.", "The bridge never creates a vTiger admin and refuses vTiger's own tables (users, roles, profiles, settings\u2026) and its standard modules as the employee record.", "Error answers no longer show file names; the details are in the vTiger server's error log, with the reference shown in ITOps."]}]}, {"title": "The vTiger user of an account: profile, employee record and password", "for": "admin", "mod": ["vtiger_users", "vtiger_credentials"], "body": [{"p": "In Microsoft 365 \u2192 People, the account panel's \"Edit vTiger user\" lets you change that person's vTiger user without signing in to vTiger: their profile, their row in your employees table, and their password. Everything is saved through vTiger's own code, so vTiger behaves exactly as if the change had been made there. You need \"vTiger \u00b7 Users\" View to look and Edit to change; setting passwords needs \"vTiger \u00b7 Passwords\"."}, {"warn": "This page needs the vTiger bridge build o7. If it says the bridge is older, upload vtiger-bridge/itops-bridge.php from the install package to the vTiger web root (see \"Connecting vTiger provisioning\")."}, {"h": "Open it"}, {"steps": ["Open Microsoft 365 \u2192 People and click the person's account.", "At the top right of the panel, click \"Edit vTiger user\". It shows when the person has a vTiger user (the \"vTiger:\" badge under their name).", "The vTiger user opens inside the panel with three tabs: Profile, Employee record and Password. \"\u2190 Back to the account\" returns to the account."]}, {"h": "Profile"}, {"bullets": ["The sections and fields are read live from vTiger, in vTiger's order (User Login & Role, Currency, More Information, Address and your site's own fields, such as Lock User, Include in Timesheet? or Default Landing Page). Picklists show vTiger's own choices.", "Change what you need and click \"Save\". The page says \"Saved through vTiger\". A role change takes effect at once: vTiger rebuilds the user's privileges.", "If someone changed the same user in vTiger while you had the page open, ITOps does not overwrite it: it tells you and shows the new values. Make your change again on top of them.", "Making someone a vTiger admin, and the Admin box itself, are Super Admin only. The vTiger admin the bridge runs as cannot be deactivated or demoted from here."]}, {"h": "Employee record"}, {"p": "Your vTiger database has an employees table with columns of its own. A cron runs during the day: it adds a row for each new vTiger user, then keeps that row updated from the user. ITOps never adds rows: a user created a moment ago shows \"No row in employees for this user yet \u2014 the cron adds it on its next run\"; come back after the cron has run. Each column is one of:"}, {"bullets": ["Edited here: change it and click \"Save\".", "Copied from vTiger by the cron: read-only here, with its state: in sync, or waiting for the cron (the vTiger value changed and the cron has not copied it yet). Change it on the Profile tab; the cron brings it over.", "Hidden: not shown."]}, {"p": "ITOps only ever changes one row: if no row or more than one row matches the user, it says so and changes nothing. The key column and the column that links the row to the user are never changed."}, {"h": "Setting up the employee record (Super Admin)"}, {"p": "When nothing is saved yet and the vTiger database has no \"employees\" table, the Employee record tab already uses the vTiger module called \"Employees\" (for example VTE Employees, vtiger_vteemployee) and says \"Found the vTiger module \u2026\". Check the suggestions and save them once in \"Employees table\u2026\" (on the Employee record tab) before editing."}, {"steps": ["On a user's Employee record tab, click \"Employees table\u2026\".", "Enter where the employee records are and click \"Read this table\": a table in the vTiger database, or one of the tables of a vTiger module such as VTE Employees (vtiger_vteemployee). If the name does not exist, the page lists what it found (tables and modules named like \"employee\"); click one to read it.", "For a module, the page says \"This table belongs to the vTiger module \u2026\" and lists the module's fields with their vTiger labels \u2014 custom fields too. Fields read-only in vTiger are marked and cannot be edited here.", "Choose how a record links to its vTiger user: the field and whether it holds the vTiger user id, user name or email. For VTE Employees this is usually its own user field (for example \"vTiger User\").", "For each field choose Edited here, Copied from vTiger by the cron (and which vTiger field it comes from) or Hidden. ITOps suggests these from matching names and labels; check them.", "Click \"Save\"."]}, {"bullets": ["With a module, a change is saved through vTiger's own record save: both tables are updated and vTiger records the change in the record's history and runs its workflows, as if the change had been made in vTiger.", "Deleted records are ignored. If two live records match one user, nothing can be changed until there is one."]}, {"h": "Password"}, {"steps": ["Open the Password tab (needs \"vTiger \u00b7 Passwords\").", "Click \"Generate a strong password\" (16 characters), or type one: 10 to 64 characters, no spaces, at least three of lower case, upper case, digits and symbols.", "Click \"Set this password\". The new password is shown once with a \"Copy\" button. Give it to the person safely."]}, {"bullets": ["The password is changed by vTiger's own password change. If your vTiger has a \"Last Password Date\" field, it is set to today.", "ITOps never stores, logs or emails the password. The Audit Log records who set it for whom, and when, not the password.", "Passwords are only sent when the bridge address is https. Otherwise the tab explains why it is off.", "The password of the vTiger admin the bridge runs as is changed in vTiger itself."]}, {"tip": "Every change, failure and refusal is in the Audit Log with the old and new values (vtiger_user_updated, vtiger_employee_updated, vtiger_password_set)."}]}, {"title": "API keys and webhooks", "for": "admin", "mod": "integrations", "body": [{"p": "Logs & Integrations \u2192 Integrations connects other systems to ITOps: API keys let them send data in, and webhooks tell them when something changes."}, {"h": "Create an API key"}, {"steps": ["Go to Logs & Integrations \u2192 Integrations \u2192 \"API keys\" \u2192 \"+ New key\".", "Give it a name for the system (e.g. HR system) and an optional expiry date.", "For each module the system needs, choose \"Read only\", \"Read + write\" or \"Read + write + delete\". Leave the rest at \"No access\".", "Click \"Create key\" and copy the key. It is shown only once."]}, {"bullets": ["A key can never have more access than you do, and it can never manage integrations.", "\"Revoke\" stops a key immediately."]}, {"h": "Add a webhook"}, {"steps": ["Go to \"Webhooks\" \u2192 \"+ New webhook\".", "Enter a name and the receiver's URL (https only).", "Pick the events (or \"All events\") and click \"Create webhook\".", "Copy the signing secret from the table and give it to the developer. Click \"Test\" to send a ping."]}, {"bullets": ["Each delivery is signed. The receiver must check X-ITOps-Signature before trusting it.", "Receivers must reply 2xx within 5 seconds. Failures retry up to 5 times (about 1, 3, 9 and 27 minutes apart). See them in \"Delivery log\"; \"Retry failed now\" retries at once.", "\"Pause\" / \"Resume\" stops and restarts a webhook without deleting it.", "A webhook goes only to a public internet address: an address inside your network (or a name that leads there) is refused, and \"Test\" shows only the HTTP status the receiver answered, never what it wrote back."]}, {"tip": "\"How to connect\" has copy-ready examples and a button to open the full integration guide for developers."}, {"p": "Permissions: Integrations (view) to see this page, Integrations (edit) to create or change keys and webhooks."}]}, {"title": "Announcement banner and queued webhooks", "for": "admin", "mod": "integrations", "body": [{"p": "Two system switches on Logs & Integrations \u2192 Integrations \u2192 \"System\" let a Super Admin post a notice to everyone and change how webhooks are sent."}, {"tip": "The banner is one line for everyone, with no record of who saw it. For a full message to chosen people, by email and Teams as well, with \"I have read this\", use Announcements in the menu."}, {"h": "Post an announcement banner"}, {"steps": ["Go to Logs & Integrations \u2192 Integrations \u2192 \"System\".", "Under \"Announcement banner\", type the message (up to 240 characters), for example \"Scheduled maintenance Saturday 8\u201310pm ET\".", "Pick the level: \"Info (blue)\", \"Warning (amber)\" or \"Critical (red)\".", "Click \"Save\". The banner shows across the top of ITOps for everyone; refresh to see it."]}, {"p": "To remove the banner, clear the text and click \"Save\"."}, {"h": "Queue webhook deliveries"}, {"p": "Tick \"Queue webhook deliveries\" and click \"Save\". Actions then finish at once, and the scheduled job sends webhooks in the background with automatic retry. Use it when you have several webhooks or a slow receiver."}, {"warn": "Queued webhooks are only sent when the scheduled job (cron-sla.php) runs. Without it, or without someone having ITOps open, deliveries wait."}, {"tip": "The \"System\" tab is Super Admin only. Other admins see \"Super-admin only.\""}]}, {"title": "Implementing Business Premium: the ITOps playbook", "for": "admin", "mod": ["m365", "m365_admin"], "body": [{"p": "Microsoft 365 Business Premium includes sign-in protection (Entra ID P1: MFA and Conditional Access), device management (Intune), Defender for Business, Defender for Office 365 Plan 1 and the Windows Pro \u2192 Business upgrade. This topic is the short version. The full plan \u2014 timeline, who does what, every email, checklists and an FAQ \u2014 is the organization's own Business Premium implementation guide; Microsoft 365 \u2192 Home \u2192 Rollout turns it into a checklist you tick off in ITOps."}, {"h": "The rule that keeps it gentle: device tiers"}, {"bullets": ["A \u2014 Company PC with Windows Pro/Business: joined to Entra and enrolled in Intune (Defender, BitLocker, updates, compliance, remote lock). IT does it with the person, about 15 minutes.", "B \u2014 Company PC with Windows HOME: Business Premium does NOT include a Home \u2192 Pro upgrade and Defender for Business doesn't support Home. Buy the Pro upgrade (about US$99) and treat it as A, or treat it as C until you do.", "C \u2014 Personal computer (any edition, or a Mac) \u2014 VOLUNTARY: never enrolled. We recommend working in the browser; a browser-only rule (downloads blocked) is optional and would be announced first.", "D \u2014 Personal phone \u2014 VOLUNTARY: never enrolled. Three equal choices: don't use it for work, the phone's browser, or the Outlook/Teams apps (app protection switches on inside them only).", "E \u2014 Company phone: enrolled with the Company Portal app (only when the organization provides phones)."]}, {"tip": "So no \u2014 not everyone needs Windows Pro. Only company PCs you want fully managed do. And MFA doesn't need a personal phone either: people choose the Authenticator app, a company security key, or a text message. Nobody's personal device is ever enrolled, and IT can't see personal files, photos, messages or location."}, {"h": "The phases (about 10 weeks)"}, {"steps": ["Step 1 \u00b7 Prepare (week 0) \u2014 IT and leadership only: two break-glass admin accounts; stop personal computers from enrolling in Intune (Windows \"personally owned\" = Block, MDM user scope limited to the company-PC group \u2014 Devices \u2192 Device policies checks both); computer inventory by tier; allow the sign-in methods; security keys; the personal-device statement; pilot groups (people and their company PCs); staff guides; manager briefing and announcement.", "Step 2 \u00b7 Sign-in approval / MFA (weeks 1\u20132) \u2014 everyone, the one required step: Authenticator app, security key or text message; the three sign-in rules start REPORT-ONLY and are switched On after about a week of clean results; weekly reminders until everyone has a method.", "Step 3 \u00b7 Email protection (weeks 2\u20133) \u2014 nobody notices: SPF, DKIM, DMARC at p=none, Standard preset, block auto-forwarding and SMTP AUTH, mailbox audit; later DMARC \u2192 quarantine.", "Step 4 \u00b7 Company computers (weeks 3\u20139) \u2014 company PCs only, in four parts: A get ready (back up policies, connect Defender for Business to Intune, turn on Windows LAPS); B pilot (compliance baseline in report-only + \"Seed device security\" for the pilot PC group, then a one-week review); C everyone in waves (seed device security again for the all-company-PCs group); D turn the rules on (attack-surface rules to Block, compliance to \"Block after 7 days\", optional Defender risk requirement).", "Step 5 \u00b7 Keep it healthy (every month) \u2014 30 minutes: Secure Score, non-compliant company PCs, Defender alerts and attack-surface detections, readiness, key stock, unused licences."]}, {"h": "Lost or stolen device"}, {"steps": ["Devices \u2192 \"Lock\" (type LOCK).", "Microsoft 365 \u2192 People \u2192 the person \u2192 \"Revoke sessions\" + \"Reset password\".", "Company device that won't be recovered: wipe it from the Intune admin center (ITOps deliberately doesn't offer wipe). On a personal phone, only the work data inside the protected apps is removed."]}, {"warn": "Never create or switch On a sign-in rule without the break-glass accounts excluded. ITOps refuses to create a rule without them \u2014 that exclusion is what saves you if a rule locks everyone out."}, {"qa": [{"q": "Do all users need Windows Pro?", "a": "No. Only company-owned PCs you want enrolled need Pro/Business. Personal computers of any edition work in the browser; company Home PCs are upgraded or treated as personal until they are."}, {"q": "Will anyone be locked out on day one?", "a": "No. Sign-in rules start report-only, the device baseline can start as \"Report only (never block)\", and the enforce phase gives a 7-day grace period \u2014 announced ahead with the rollout emails."}, {"q": "Do staff have to use their personal phone?", "a": "No. When the organization provides no phones, phone use is voluntary. For sign-in, a company security key replaces the phone. People who want work on their phone choose the browser or the protected Outlook/Teams apps; the phone itself is never managed."}]}]}, {"title": "The Rollout tab: 5 steps, staff emails and readiness", "for": "admin", "mod": ["m365", "m365_admin"], "body": [{"p": "Microsoft 365 \u2192 Home \u2192 Rollout turns the Business Premium plan into 5 steps: 1 Prepare \u00b7 2 Sign-in approval (MFA) \u00b7 3 Email protection \u00b7 4 Company computers \u00b7 5 Keep it healthy. Only step 2 is required of everyone. Step 4 touches company PCs only \u2014 using a personal phone or computer stays voluntary, and nothing in the plan installs anything on one."}, {"h": "What's on the page"}, {"bullets": ["The five step cards across the top show where you are (\"You are here\") and how far each step is. Click a card to jump to it.", "\"Next up\" always shows the single next task, with its buttons (Open, \u2709 Email, Check). Tick it and the next one appears.", "Each step opens to its tasks; step 4 is split into A get ready \u00b7 B pilot \u00b7 C everyone \u00b7 D turn the rules on. Only the current step is open at first.", "Tasks are tagged REQUIRED, RECOMMENDED or OPTIONAL. Tick one when it is done, or press \"Skip\u2026\" and write why \u2014 the reason is kept with who and when (\"undo\" reverses it). Required tasks can't be skipped.", "\"Optional tightening\" (collapsed at the bottom) holds the rules that would restrict personal devices. Each is a decision, not a deadline.", "\"Check readiness\": every licensed person, their sign-in method (security key, app, or text/call only), their company computer, and phone apps (information only).", "\"Add the user guides to the Knowledge Base\": 20 draft articles in English and Spanish. Running it again refreshes drafts only; published guides are never touched.", "Progress recorded before BT15 is kept \u2014 every task has the same id as before."]}, {"h": "Sending a communication"}, {"steps": ["Press \u2709 Send communication (or \u2709 Email on a step).", "Pick the email: announcement, manager briefing, set up sign-in approval, your security key is ready, sign-in approval date, personal computer (safe way), company computer join, phone choices (optional), reminder, company-computer rules date, or rollout complete.", "Pick who gets it: everyone with a licence, all managers (Entra \"manager\" field), a group such as the pilot, people with no sign-in method yet, or specific emails.", "Fill in only the fields that email uses (dates, what's still to do, who signs it, where to collect a key).", "Press Preview recipients \u2014 it shows the count and a sample. Then Send. At most 500 per send."]}, {"tip": "Each person gets English and Spanish in one email. The wording is editable under Settings \u2192 Email templates \u2192 Security rollout."}, {"qa": [{"q": "Who can use it?", "a": "Anyone with Microsoft 365 view can see the checklist and readiness. Ticking or skipping steps and sending email need \"Microsoft 365 \u00b7 Tenant configuration\" (edit)."}, {"q": "Readiness shows \u2014 instead of values", "a": "A permission is missing; the yellow note names it (AuditLog.Read.All for MFA, DeviceManagementManagedDevices.Read.All for computers, DeviceManagementApps.Read.All for phone apps)."}]}]}, {"title": "Sign-in methods, security keys and Temporary Access Pass", "for": "admin", "mod": ["m365", "m365_admin"], "body": [{"p": "MFA doesn't need a personal phone. Microsoft 365 \u2192 Security \u2192 Access & sign-in \u2192 \"Sign-in methods people can use\" controls which methods staff may choose, and ITOps marks our advice for each."}, {"bullets": ["Microsoft Authenticator app \u2014 recommended: allow.", "Security keys / passkeys (FIDO2) \u2014 recommended: allow. USB keys the company provides; no phone needed; the strongest option.", "Temporary Access Pass \u2014 recommended: allow. How IT hands out keys and helps people who lost a phone or key.", "Text message and phone call \u2014 your choice. Weakest, but works on any phone; fine as a start or backup.", "Email one-time code and certificates \u2014 not needed for staff MFA."]}, {"p": "\"Allow\" switches a method on for all users. \"Turn off\" asks you to type OFF, because anyone using that method must pick another at their next sign-in."}, {"h": "Handing out a security key"}, {"steps": ["Record the key in Assets & Vendors \u2192 Equipment and loan it to the person.", "Microsoft 365 \u2192 People \u2192 the person \u2192 \"+ Temporary access pass\". Give them the pass in person.", "Sit with them: aka.ms/mysecurityinfo \u2192 sign in with the pass \u2192 Add sign-in method \u2192 Security key \u2192 USB \u2192 set a key PIN \u2192 touch the key.", "Rollout \u2192 Check readiness now shows \"security key\" for them."]}, {"h": "Lost key or new phone"}, {"steps": ["Microsoft 365 \u2192 People \u2192 the person \u2192 \"+ Manage methods\" \u2192 \u2715 on the lost key or the old phone.", "Issue a Temporary pass so they can sign in and register the replacement.", "If you suspect misuse, also Reset password and Sign out everywhere."]}, {"warn": "Never send a Temporary Access Pass by email or chat \u2014 it is as good as a password for its lifetime. ITOps shows it once and does not store it."}, {"qa": [{"q": "\"Could not issue the pass\"", "a": "Temporary Access Pass isn't allowed yet (Microsoft 365 \u2192 Security \u2192 Access & sign-in \u2192 Sign-in methods \u2192 Allow), or ITOps lacks UserAuthenticationMethod.ReadWrite.All."}, {"q": "The Sign-in methods card asks for a permission", "a": "Policy.Read.All to read it; Policy.ReadWrite.AuthenticationMethod to change it."}]}]}, {"title": "Intune policies: inventory, backup, restore and clone", "for": "admin", "mod": ["m365", "m365_admin"], "body": [{"p": "Devices \u2192 \"All policies\" reads every Intune policy type \u2014 compliance, configuration profiles (including Windows Update rings), settings catalog and endpoint security (Defender antivirus, firewall, BitLocker, attack-surface reduction) and app protection \u2014 including ones created in the Intune portal. It shows the platform, who it applies to and how many devices succeeded, failed, conflict or are pending."}, {"h": "Back up before you change anything"}, {"steps": ["Press \"Load all policies\", then \"Back up all\" (or Back up on one row).", "ITOps stores the complete policy exactly as Microsoft returned it, with who took it and when.", "Backups are listed underneath, newest first."]}, {"h": "Restore and clone"}, {"bullets": ["Restore as new: re-creates a backed-up policy \u2014 useful if someone deletes or breaks one in the portal.", "Clone: copies a live policy, e.g. to test a change on the pilot group before touching the real one.", "Both ALWAYS create a NEW policy; nothing is overwritten. You're asked whether to copy the original's assignments \u2014 say no (safest), check it, then assign it."]}, {"h": "Editing"}, {"bullets": ["Compliance policies: Edit on the compliance table (PIN, encryption, Defender, OS minimum, what happens when a device breaks the rules, and who it applies to \u2014 all devices, all users or a group).", "App protection (phones): Edit on the app-protection table (app PIN and length, backup, Save-as, printing, copy/paste, wipe after days offline, assignment).", "Settings catalog / endpoint security: back up, clone and restore here; change individual settings in the Intune admin center."]}, {"h": "Seeding the baseline"}, {"p": "\"Seed recommended baseline\" now asks for a mode \u2014 Report only (marks non-compliant, never blocks; start here) or Enforce (block after a 7-day grace) \u2014 and whether to assign it to a pilot group or everyone. Existing policies with the same name are skipped."}, {"warn": "Backups need the BT12 database update: open db-update.php once while signed in as a Super Admin. Until then, the backups section says so."}]}, {"title": "Device security for company PCs (antivirus, firewall, BitLocker\u2026)", "for": "admin", "body": [{"p": "The compliance baseline only CHECKS a computer (is BitLocker on? is Defender on?). Device security CONFIGURES it. Microsoft 365 \u2192 Devices \u2192 Device policies \u2192 \"Seed device security\" creates six Intune profiles and assigns them to a device group of company PCs that you choose. Personal computers are never included."}, {"h": "What it creates"}, {"bullets": ["Antivirus \u2014 real-time, behaviour and cloud protection (High), blocks potentially unwanted apps, daily quick scan, signatures every 4 hours.", "Firewall \u2014 on for domain, private and public networks; unsolicited inbound connections blocked.", "Attack surface reduction \u2014 12 rules that stop common malware tricks (Office macros, downloaded scripts, password theft from memory, unsigned USB programs, ransomware). They start in AUDIT: nothing is blocked, detections are only reported.", "BitLocker \u2014 silent disk encryption (TPM only, nothing extra to type); the recovery key is saved to Entra before encryption starts.", "Windows Update ring \u2014 quality updates after 3 days, feature updates after 60, installs outside 7:00\u201319:00, restart deadline 7 days plus 2 days grace.", "Local admin passwords (Windows LAPS) \u2014 every PC gets its own 20-character local administrator password, rotated every 30 days and stored in Entra."]}, {"h": "How to use it"}, {"steps": ["In Entra, create a device group with the pilot company PCs (and later one with all company PCs \u2014 a dynamic group on \"device ownership = Company\" works well).", "Microsoft 365 \u2192 Devices \u2192 Device policies \u2192 Seed device security \u2192 tick the items \u2192 choose the pilot device group \u2192 Create & assign.", "Wait a week. The Device security card shows, per item, how many PCs applied it (ok / error / conflict / pending).", "Run it again with the all-company-PCs group. Nothing is duplicated: existing ITOps profiles just get the new group added.", "After two clean weeks, check security.microsoft.com \u2192 Reports \u2192 Attack surface reduction rules, add any exclusions, then press \"Switch to Block\u2026\" on the card and type BLOCK. \"Back to Audit\" reverses it."]}, {"h": "Things ITOps does not do for you"}, {"bullets": ["Defender for Business onboarding: in security.microsoft.com \u2192 Settings \u2192 Endpoints \u2192 Onboarding choose Intune, and in Intune \u2192 Endpoint security \u2192 Microsoft Defender for Endpoint switch the connector On. The card shows CONNECTED once it is done.", "Windows LAPS also needs Entra \u2192 Devices \u2192 Device settings \u2192 \"Enable Microsoft Entra LAPS\" = Yes.", "Removing or changing a profile: unassign or edit it in Intune (or with the policy inventory). PCs revert at their next check-in; BitLocker stays encrypted."]}, {"tip": "The full manual procedure, with every value, is INTUNE-DEFENDER-SETUP.md in the support files pack (Reference folder)."}], "mod": "m365_admin"}, {"title": "Personal computers in Intune (enrolment guard-rail)", "for": "admin", "body": [{"p": "Personal devices are voluntary, so a personal PC must never be enrolled. It happens anyway when someone adds their work account in Windows while automatic enrolment is open to all users. Microsoft 365 \u2192 Devices \u2192 Device policies warns you when that is possible and lists any personal Windows PCs already enrolled."}, {"h": "Close the gap (both settings)"}, {"steps": ["Intune admin center \u2192 Devices \u2192 Enrollment \u2192 Device platform restriction \u2192 Windows \u2192 Personally owned = Block.", "Entra admin center \u2192 Devices \u2192 Device settings (older portals: Mobility (MDM and MAM) \u2192 Microsoft Intune) \u2192 MDM user scope = Some \u2192 the group of company-PC users. Leave MAM user scope = All so phone app protection keeps working."]}, {"h": "A personal PC is already enrolled"}, {"bullets": ["It is marked PERSONAL in the device list. ITOps has no Lock button for it \u2014 IT never acts on a device the company does not own.", "If it should not be there (for example a former employee's own laptop): first copy its BitLocker recovery key from Entra \u2192 Devices \u2192 the device \u2192 BitLocker keys (so the owner is never locked out), then delete the device record in Intune and in Entra. Deleting the record does not wipe or change the computer.", "The owner can also remove the leftover work connection: Settings \u2192 Accounts \u2192 Access work or school \u2192 Disconnect."]}, {"tip": "To see which personal computers people actually use \u2014 without enrolling them \u2014 open Devices \u2192 \"Device inventory\" and click the \"Personal\" or \"Unregistered\" tile."}], "mod": "m365_admin"}, {"title": "Sign-in rules (Conditional Access) from templates", "for": "admin", "mod": ["m365", "m365_admin"], "body": [{"p": "Microsoft 365 \u2192 Security \u2192 Access & sign-in \u2192 Sign-in protection lists every Conditional Access rule and whether MFA-for-all and legacy blocking are in force. With \"Microsoft 365 \u00b7 Tenant configuration\" (edit) you can create rules from six tested templates and change their state."}, {"h": "Reading what a rule does"}, {"p": "Click any rule in the list \u2014 one made from a template or one somebody created in the Entra admin center. ITOps reads the rule from Microsoft and describes it in plain words:"}, {"bullets": ["\"Applies to\" and \"Except\": everyone, guests, or the people, groups and admin roles it names \u2014 by name, not by id.", "\"When they use\": all apps, Office 365, the admin portals or named apps; or an action such as setting up MFA.", "\"Only when\": the kind of app (browser, mobile and desktop apps, legacy clients), device platforms, locations, a device filter, sign-in or user risk.", "\"Then\": block, require MFA, a compliant device, an app protection policy\u2026 and whether all of them or one of them is needed.", "\"During the session\": sign-in frequency, whether the browser may stay signed in, browser-only access."]}, {"p": "Warnings appear above the description: the rule is report-only or off; no account is excluded from a rule that applies to everyone (keep an emergency account out); the rule blocks everyone from everything; or it refers to a person, group or app that no longer exists. Reading a rule needs only \"Microsoft 365 \u00b7 View\" and Policy.Read.All; the On / Report-only / Off buttons still need \"Tenant configuration\"."}, {"h": "The templates"}, {"bullets": ["Require MFA for admin roles \u2014 do this first.", "Require MFA for all users \u2014 replaces Security Defaults.", "Block legacy sign-in \u2014 old protocols can't do MFA.", "Phones must use protected apps \u2014 Outlook/Teams/OneDrive on phones only through app-protected apps.", "Desktop apps need a compliant company device \u2014 personal computers still reach mail and files in the browser.", "Personal computers: browser-only, no downloads \u2014 pair it with SharePoint admin center \u2192 Access control \u2192 Unmanaged devices \u2192 \"Allow limited, web-only access\"."]}, {"h": "Safe by design"}, {"steps": ["Every rule is created REPORT-ONLY: it logs what would happen and blocks nobody.", "You must name at least one emergency (break-glass) account; it's excluded from the rule and remembered for next time.", "Watch Entra \u2192 Sign-in logs \u2192 Report-only for about a week.", "Press On (type ON). Report-only and Off are one click."]}, {"h": "Security Defaults"}, {"p": "Security Defaults can't run alongside Conditional Access. When it's on, a \"Turn Security Defaults off\" button appears (type OFF). ITOps only allows it once a \"Require MFA for all users\" rule exists \u2014 switch that rule On the same day."}, {"warn": "Needs Policy.ReadWrite.ConditionalAccess and Policy.Read.All (turning Security Defaults off also needs Policy.ReadWrite.SecurityDefaults). The browser-only experience in Outlook on the web also needs the OWA command in Email \u2192 Email security \u2192 hardening checklist."}, {"tip": "Switching a rule On asks you to type ON; switching it Off asks you to type OFF."}]}, {"title": "Email security: SPF, DKIM, DMARC and the mailbox audit", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 Email \u2192 Email security covers three layers of email protection: who may send as your domain (DNS, checked live), the Exchange Online settings (assessed with PowerShell, recorded as evidence), and whether any mailbox is already compromised (the audit)."}, {"h": "The three DNS records"}, {"bullets": ["SPF \u2014 lists the servers allowed to send as your domain. Must include spf.protection.outlook.com and end in -all.", "DKIM \u2014 Microsoft signs your outgoing mail once the two selector CNAMEs are published and signing is enabled.", "DMARC \u2014 tells the world what to do with mail that fails: p=none (monitor) \u2192 p=quarantine \u2192 p=reject. The page grades each domain and shows the exact record to publish."]}, {"h": "The mailbox audit"}, {"steps": ["Click \"Scan mailboxes\" (up to 300 licensed mailboxes per run; needs the MailboxSettings.Read Application permission \u2014 ReadWrite to disable rules).", "Red rows forward mail OUTSIDE your domains \u2014 the classic sign of a compromised or leaking mailbox. Amber rows silently delete mail.", "For any rule you can't explain: \"Disable\", then Microsoft 365 \u2192 People \u2192 the person \u2192 \"Reset password\", \"Revoke sessions\", \"Reset MFA\"."]}, {"p": "Vendor routing domains (for example CodeTwo's *.smtp.codetwo.online) are listed but never get DKIM or DNS advice \u2014 their DNS belongs to the vendor."}, {"h": "Exchange Online controls \u2014 assess, change, verify, evidence"}, {"p": "Exchange Online settings aren't available through Microsoft Graph, so ITOps can't read or change them; you manage them in Exchange Online PowerShell (and preset protection in the Defender portal). ITOps never runs these commands."}, {"steps": ["Copy \"Step 1 \u2014 Read-only assessment\" and run it. It changes nothing.", "For each control (DKIM, forwarding, SMTP AUTH, Outlook on the web for personal computers, preset protection), compare the output with \"Good looks like\".", "Only where needed, run the \"Change\" commands. DKIM is created disabled, the CNAMEs Microsoft prints are published exactly, then signing is enabled. Forwarding changes only the Default policy. SMTP AUTH is turned off only after listing the scanners, printers and apps that use it.", "Run \"Verify\".", "Press \"Record result\": Verified OK, Needs change, Exception accepted or Not applicable, with the key output lines. ITOps saves who and when; every change is also in the Audit Log."]}, {"warn": "Outlook on the web for personal computers is optional and needs TWO things: the Exchange OWA setting AND a Conditional Access rule with app-enforced restrictions (\"Personal computers: browser-only\" on Security \u2192 Access & sign-in). ITOps shows whether that rule exists. Choose ReadOnly (view attachments in the browser, no download) unless attachments must not be viewed at all (ReadOnlyPlusAttachmentsBlocked)."}, {"tip": "Server Guardian re-checks SPF/DKIM/DMARC on every scan and raises an alert if a record breaks \u2014 you'll know before customers start landing in spam."}]}, {"title": "JustCall connected: reading its users instead of typing them", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "JustCall can be connected. ITOps then reads from JustCall who has a user there, with which role and which numbers, so nobody types that in, and a step of an onboarding or offboarding is done when JustCall itself shows it."}, {"p": "ITOps only reads JustCall. It never changes anything there. JustCall's API has no call to add or remove a user, so that is still done by hand in JustCall; ITOps checks afterwards."}, {"h": "Connecting"}, {"steps": ["Open Administration \u2192 Settings \u2192 Company systems \u2192 \"Systems\" and click \"Set up\u2026\" (or \"Switch on\u2026\") on JustCall.", "In the box \"Connection\", paste the API key and the API secret. You find them in JustCall under your profile \u2192 \"APIs and Webhooks\". The key another app already uses works here too. Only a Super Admin sees these two boxes.", "Click \"Save the key and test\". The box says \"The test passed\" and which fields a user carries, or \"The test FAILED\" with the reason.", "Under \"Use\" choose \"Connected: the users are read from JustCall\" and click \"Save\". JustCall is read for the first time.", "A tab \"JustCall\" appears next to \"Systems\"."]}, {"bullets": ["The key is stored encrypted on the server. It is never shown again, never sent back to a browser and never written to the Audit Log or the Event Log. A saved box reads \"saved \u00b7 leave empty to keep it\".", "\"Connected\" is only accepted after a test that passed.", "Accounts that were typed by hand for JustCall are closed at the first reading and replaced by what JustCall lists. Each one is in the Audit Log.", "\"Test the connection\" checks the saved key again (a role with Integrations \u00b7 Edit can use it). \"Delete the key\u2026\" removes the key from ITOps and puts JustCall back to \"Tracked by hand\"; the accounts read so far stay in the records. The key stays valid in JustCall until you revoke it there."]}, {"h": "The JustCall tab"}, {"bullets": ["One row per user in JustCall: name, email, role, group, the numbers they own, extension, shared numbers, last sign-in, and the person the user is matched to.", "A user is matched to a person by the exact email. \"Left \u00b7 still a user here\" (red): that person's Microsoft 365 account is blocked. \"Matched to nobody\" (amber): no Microsoft 365 account has that email. \"No email in the system\" (amber): JustCall gave no email.", "\"Assign\u2026\" says whose account it is when the email does not tell: a shared line, a personal address. Type the person's work email and click \"Assign\". An assignment stays until you undo it (\"Back to \u2026\"); a reading does not change it.", "\"Read now\" reads JustCall at once and says what changed. \"Need attention\" filters to the flagged users. \"Export CSV\" saves what is shown."]}, {"h": "When JustCall is read"}, {"bullets": ["When you click \"Read now\", or \"Refresh\" under \"Needs attention\".", "When a JustCall step of an onboarding or offboarding is opened (if the last reading is older than ten minutes), and every time one is answered.", "At \"Verify offboarding\" and the monthly re-check.", "Every four hours by the scheduled job."]}, {"h": "When a reading is not used"}, {"bullets": ["JustCall does not answer, refuses the key or answers with an error: nothing is changed. The tab shows \"The last reading of JustCall failed\" with the reason and keeps the reading before it.", "The list is not complete (a later page failed, or JustCall says it has more users than were read): refused, nothing is changed.", "The list lacks more than half of the users known so far, or is empty: it is held back. Nobody is closed. The tab names the missing users. Look in JustCall; if they are really gone, a person with \"Company systems\" \u00b7 Edit clicks \"Accept the list\u2026\". Until then, steps and verification for JustCall do not pass."]}, {"h": "In offboarding and onboarding"}, {"steps": ["Offboarding: the JustCall box shows what JustCall lists for the person, with the numbers, and when it was read. Reassign the numbers and remove the user in JustCall, then click \"I removed the user: check JustCall again\".", "The step is done only when JustCall no longer lists the person. Otherwise it says who is still there. If JustCall cannot be read, the step stays open and says so.", "If JustCall lists no user for the person, the button reads \"Confirm: no user in JustCall\". The box warns when JustCall has users matched to nobody: one of them may be this person under another email. Assign it on the JustCall tab first.", "Onboarding: add the person in JustCall with their work email, then click \"Check JustCall for the user\". Or \"Not needed for this person\"."]}, {"p": "\"Verify offboarding\" has the line \"Account removed (read from JustCall)\". It asks JustCall at that moment: \u2717 when the user is still listed or JustCall cannot be read, \u2713 with the time of the reading."}, {"p": "While JustCall is connected, its accounts cannot be typed in, pasted from a list, renamed, closed or opened again in ITOps: change them in JustCall. The note on an account can still be edited."}, {"p": "The Audit Log (type \"access\") has: the key saved, replaced or deleted, with who and when and never the key; JustCall set to Connected; every reading that changed something, with a line per user that appeared, disappeared, came back or changed email, and whether a person or the scheduled job read; a held-back list and who accepted it; and every assignment with the person before and after."}, {"qa": [{"q": "I do not see the key boxes.", "a": "Only a Super Admin can save, replace or delete the key. A role with Integrations \u00b7 Edit sees the state of the connection and can test it."}, {"q": "\"Connected\" is refused: \"Save the JustCall key and get a successful test first\".", "a": "Paste the key and the secret in the Connection box and click \"Save the key and test\". Choose \"Connected\" after the test passed."}, {"q": "The test fails with \"JustCall refused the key (HTTP 401)\".", "a": "The key or the secret is wrong, was revoked, or the JustCall plan does not include the API. Copy both again from JustCall \u2192 profile \u2192 \"APIs and Webhooks\"."}, {"q": "The test fails with HTTP 429.", "a": "Too many requests were made with this key in a short time. The key is shared with any other app that uses it. Wait a few minutes."}, {"q": "A person has a JustCall user but the step says there is none.", "a": "The user in JustCall has another email than the person's work email. On the JustCall tab, find the user (it is flagged \"Matched to nobody\"), click \"Assign\u2026\" and type the person's work email."}, {"q": "I removed the user in JustCall and the step still refuses.", "a": "The step reads JustCall each time you press the button. If it still names the user, the user is still there: in JustCall a user is removed under Teams \u2192 Team Members after the numbers were reassigned."}, {"q": "The tab says accounts are \"held back\".", "a": "JustCall's list lacked most of the users it had before. That is usually a fault, so nothing was closed. Look in JustCall. If the users are really gone, click \"Accept the list\u2026\"."}, {"q": "It says \"Run db-update.php\".", "a": "This update adds columns to one table. Open db-update.php once (Settings \u2192 Maintenance). Until then everything tracked by hand keeps working and \"Connected\" is refused."}, {"q": "Does ITOps read calls, texts or recordings?", "a": "No. It reads the list of users and their numbers, nothing else."}, {"q": "What about HubSpot, eFax, Jotform and the phone system?", "a": "They are tracked by hand in this build. A direct connection is planned for each."}]}]}, {"title": "CallTrackingMetrics: users, tracking numbers, calls and missed calls as tickets", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "CallTrackingMetrics can be connected under Company systems. ITOps then reads its users (for onboarding and offboarding, like JustCall), its tracking numbers and its calls, and can open a ticket for every call nobody answered. ITOps never changes anything in CallTrackingMetrics."}, {"h": "Connecting"}, {"steps": ["In CallTrackingMetrics, open Settings \u2192 Account Settings \u2192 API Integration (an account administrator). Turn API access on if it is off, and copy the Access Key and the Secret Key.", "In ITOps open Administration \u2192 Settings \u2192 Company systems \u2192 \"Systems\" and click \"Set up\u2026\" on CallTrackingMetrics.", "In the box \"Connection\", paste the two keys. Leave \"Account ID\" empty when the key belongs to one account; for an agency key that reaches several accounts, type the ID of the company's account. Only a Super Admin sees these boxes.", "Click \"Save the key and test\". The box names the account it reached and the fields a user carries, or says why the test failed.", "Under \"Use\" choose \"Connected\" and click \"Save\". A tab \"CallTrackingMetrics\" appears next to \"Systems\"."]}, {"h": "The four parts of its tab"}, {"bullets": ["Users: every user, matched to the person by email, with role and groups. A user whose Microsoft 365 account is blocked is flagged. Read every four hours and at each onboarding or offboarding step.", "Tracking numbers: each number with its label, the marketing source and the numbers it rings. Export to CSV.", "Calls: for a period of up to 92 days, the calls, how many were answered and missed, and the average talk time, by line, source, agent and day. Export to CSV.", "Missed calls \u2192 tickets: the settings and the list of missed calls looked at, each with what was done."]}, {"h": "Missed calls \u2192 tickets"}, {"steps": ["Open the tab \"Missed calls \u2192 tickets\" (a Super Admin, or a role with Integrations \u00b7 Edit, changes it).", "Tick \"Open a ticket for each missed call\", choose the ticket category (its routing decides who gets the tickets) and the priority.", "Choose the lines: usually only the help line. With none chosen, every line counts.", "Choose what counts as missed: no answer, busy, canceled and hang-up are ticked to start; a call that ended in a menu or failed to connect can be added.", "Set the window: the same caller again within these minutes, while their ticket is open, adds a note instead of a new ticket. Click \"Save\"."]}, {"bullets": ["Every five minutes the scheduled job reads the new calls. \"Check now\" runs it at once.", "Calls from before you switched it on never make tickets, so switching on does not flood the desk. Each call is looked at once.", "The ticket says who called, which line, when, what happened and the number to call back. It is opened in the name of the person who switched this on; the caller is kept as the ticket's contact.", "A call answered by a voicemail box counts as answered in CallTrackingMetrics, so it makes no ticket.", "Every ticket made, and every change of these settings, is written to the Audit Log."]}]}, {"title": "Jotform: forms, who owns them, and forms that open tickets", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "With Jotform connected (Company systems), its tab has three parts: Team members, Forms and Forms \u2192 tickets. ITOps only reads Jotform: the key with \"Read Access\" is enough, and nothing is set up or changed in Jotform."}, {"h": "Forms"}, {"bullets": ["Every form of the account, with its owner (the Jotform user, matched to the person), its status, the number of submissions and the last one.", "Filter the forms that make tickets, the forms whose owner is nobody here, and the disabled ones. Export to CSV.", "When someone leaves, the Jotform step of the offboarding lists the forms they own, so you move them to a colleague before removing the member."]}, {"h": "Forms \u2192 tickets"}, {"steps": ["On the Forms list, click \"Make tickets\u2026\" on the form (a Super Admin, or a role with Integrations \u00b7 Edit).", "Tick \"Each new submission opens a ticket\", choose the ticket category (its routing decides who gets the tickets) and the priority, and click \"Save\".", "Submissions sent from then on open tickets. \"Check now\" on Forms \u2192 tickets runs the check at once; otherwise it runs every ten minutes."]}, {"bullets": ["The ticket carries the answers as the form shows them and a link to the submission in Jotform. Headings and buttons are left out; files and signatures are named and stay in Jotform.", "When the form has an email answer that belongs to a person of ITOps, that person is the requester. Otherwise the ticket is opened in the name of the person who switched the form on, and the sender is kept as the ticket's contact.", "Submissions sent before a form was switched on never make tickets, and each submission makes one ticket, once.", "Each check uses one Jotform call per form switched on. Jotform counts calls per day by plan; ten-minute checks stay far inside the smallest plan.", "Every ticket made, and every change, is written to the Audit Log."]}]}, {"title": "JustCall: calls and activity, missed calls and voicemails as tickets", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "With JustCall connected, its tab has three parts: Users, Calls and activity, and Missed calls \u2192 tickets. ITOps only reads JustCall."}, {"bullets": ["Users: a user who has not signed in for 90 days is flagged \"No sign-in for 90 days\": a seat that may no longer be needed.", "Calls and activity: choose a period (up to 92 days; JustCall keeps the last three months) to see the calls by line, by person and by day, with how many were answered and missed and the average talk time. Export to CSV."]}, {"h": "Missed calls \u2192 tickets"}, {"steps": ["Open \"Missed calls \u2192 tickets\" (a Super Admin, or a role with Integrations \u00b7 Edit, changes it).", "Tick \"Open a ticket for each missed call\", choose the category and priority, and the JustCall numbers that count (usually the support line).", "Choose what counts: missed, voicemail and abandoned are ticked to start; busy and failed can be added. Set the window for the same caller, and click \"Save\"."]}, {"bullets": ["Every five minutes ITOps asks JustCall for the calls since the last check. A voicemail ticket includes JustCall's transcription when there is one.", "Calls from before you switched it on never make tickets (JustCall's call numbers decide, not the clock), and each call is looked at once.", "The same caller again while their ticket is open adds a note instead of a new ticket. Every ticket and change is in the Audit Log."]}]}, {"title": "The office phone system (Grandstream UCM): extensions in onboarding and offboarding", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "A Grandstream UCM63xx (for example the UCM6302) can be connected under Company systems \u2192 Phone system (PBX). ITOps then reads its extensions as accounts, takes a leaver's extension out of service from the offboarding step, and shows the PBX's model, firmware and uptime. It never deletes an extension."}, {"h": "Connecting"}, {"steps": ["On the PBX's web page: Integrations \u2192 API Configuration \u2192 HTTPS API Settings (New). Tick Enable, keep port 8089, and set an API user and password of its own.", "Add this server's address to the PBX's login whitelist, so a wrong password can never ban it.", "In ITOps, open Company systems \u2192 Systems \u2192 Phone system (PBX) \u2192 Set up\u2026. Enter the address: try the PBX's RemoteConnect address first (https://xxxx.a.gdms.cloud); if the API does not answer there, ask for one port-forward to port 8089 allowed only from this server and enter https://<office address>:8089. Enter the API user and password and click \"Save the key and test\".", "The test names the model, the firmware and the number of extensions, and remembers the PBX's certificate. Set Use to \"Connected\".", "On the PBX tab, give each extension without an email to its person with \"Assign\u2026\"."]}, {"h": "Offboarding and the extensions"}, {"bullets": ["The offboarding step for the phone system has \"Take the extension out of service now\". The extension can no longer make or take calls and its call forwarding is cleared; its voicemail and settings stay. The step is done when the PBX shows it.", "\"All extensions and status\" lists every extension, out of service ones too, with \"Take out of service\u2026\" and \"Put back in service\u2026\". You type the extension number to confirm.", "The PBX bans an address after a few failed sign-ins. A refused sign-in therefore stops every reading until the connection is tested again; nothing retries by itself.", "Every change, and every refusal, is written to the Audit Log."]}]}, {"title": "The office phone system: call reports, missed calls as tickets, and how it connects", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "With the phone system (Grandstream UCM) connected, its tab also has Calls and reports, and Missed calls \u2192 tickets. The call records are read every five minutes over the same connection as the extensions: the PBX sends nothing to ITOps, so nothing has to be opened towards ITOps."}, {"h": "How ITOps reaches the office PBX"}, {"bullets": ["No VPN is needed. ITOps only asks the PBX's HTTPS API (port 8089); the PBX never calls ITOps.", "First choice: the PBX's RemoteConnect address (Grandstream's cloud relay, https://xxxx.a.gdms.cloud), when its API answers there. Nothing changes on the office firewall.", "Otherwise: one port-forward on the office firewall to the PBX's port 8089, allowed only from ITOps's server address. On the set-up page, \"Find this server's public address\" shows that address; put it in the firewall rule and in the PBX's allowlists (Maintenance \u2192 Login Settings, and System Settings \u2192 Security Settings \u2192 Fail2Ban).", "A site-to-site VPN only when your policy requires it; it needs ITOps on a server you control (a VPS), not shared hosting."]}, {"h": "Calls and reports"}, {"bullets": ["Choose a period (up to 92 days) to see calls, answered, missed and the average talk time, by trunk, by extension with its person, by day and by hour; inbound, outbound and internal; outbound calls by destination; and the outside numbers seen most. Export to CSV.", "The first reading goes back 90 days and finishes over the next runs. \"Read now\" reads the newest records at once.", "The records are kept 400 days by default (at least 30): change it in the box above the report. Recordings stay on the PBX; a call that has one is counted."]}, {"h": "Missed calls \u2192 tickets"}, {"steps": ["Open \"Missed calls \u2192 tickets\" on the phone system tab (a Super Admin, or a role with Integrations \u00b7 Edit).", "Tick \"Open a ticket for each missed call\", choose the category, the priority and the numbers that count (the main number, usually).", "No answer, busy and voicemail count as missed to start; failed can be added. Click \"Save\"."]}, {"bullets": ["The ticket names the caller, the trunk and the number called, the extension that rang and the number to call back. The same caller again while it is open adds a note.", "Calls from before you switched it on are never looked at. Every ticket and change is in the Audit Log."]}, {"h": "Older firmware"}, {"p": "If the test passes but the call records stay empty with \"did not give its call records\", the firmware gives them only through its older CDR API: on the PBX enable it (port 8443, its own user, this server in \"Permitted IP(s)\"), then enter that CDR user and password on the connection."}]}, {"title": "The office phone system: creating, changing and deleting extensions", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "With the phone system connected, ITOps can manage its extensions, not only read them. Everything is done on the PBX through its API, and every change is written to the Audit Log."}, {"h": "A new person"}, {"steps": ["Tick the phone system on the onboarding (a template can tick it).", "On its step, the next free extension is suggested. Change it if you want, choose what it may call, and click \"Create the extension now\".", "The extension is made with the person's name and work email; the step is done when the PBX lists it.", "On Company systems \u2192 Phone system \u2192 All extensions, use \"Wave QR\u2026\" to sign the person in to Grandstream Wave and \"Voicemail PIN\u2026\" to give them a PIN (shown once)."]}, {"bullets": ["The SIP password, voicemail PIN and user portal password are made by ITOps, given to the PBX and never kept. Nobody needs to know them: desk phones are provisioned by the PBX, Wave signs in with the QR code.", "\"Add an extension\u2026\" on All extensions does the same for anyone (a shared phone, a meeting room).", "\"Edit\u2026\" changes the name and email. ITOps reads the extension back: if the firmware did not take a field, it says so."]}, {"h": "Someone who leaves"}, {"bullets": ["The offboarding step takes the extension out of service (call forwarding cleared). Nothing is deleted then.", "After the waiting period (30 days by default, set on PBX set-up), \"Delete\u2026\" on the extension's row removes it with its voicemail and settings, with its number typed. Only a Super Admin, or a role with Integrations \u00b7 Edit, can delete.", "The period counts from when ITOps first saw the extension out of service; the row shows from which date it can be deleted."]}, {"h": "PBX set-up"}, {"p": "A read-only page: model, firmware and uptime, the trunks and their state, the departments and their extensions. It warns when the PBX restarted in the last day or a trunk is out of service or not registered. Routes, trunks and departments are still set up on the PBX itself."}]}, {"title": "Getting the API key for each company system (HubSpot, JustCall, eFax, Jotform, phone system)", "for": "admin", "mod": ["access", "integrations"], "body": [{"p": "Each company system's set-up page (Administration \u2192 Settings \u2192 Company systems \u2192 \"Systems\" \u2192 \"Switch on\u2026\" or \"Set up\u2026\") has a box \"How to connect \u2026\". It says who can get the key at the vendor, where to click there, what the key must be allowed to do, and what to keep in mind. This topic is the same reference in one place."}, {"p": "In this build only JustCall has a place to paste a key. For the other systems the connection is planned; they are tracked by hand until then. The steps are here so the key can be prepared, and so it is known where each one comes from. The steps were taken from each vendor's own help on October 7, 2026; vendors move their menus, and the box on the set-up page links to the vendor's page."}, {"h": "JustCall (available now, read only)"}, {"steps": ["Sign in to JustCall in a web browser as the Account Owner or an Admin. Team Members and custom roles do not see the credentials.", "Click the user icon at the top right and choose \"APIs and Webhooks\".", "In \"API Credentials\", click the copy icon next to \"API Key\".", "Click the eye icon to show the \"API Secret\", then its copy icon.", "In ITOps, paste both in the \"Connection\" box on JustCall's set-up page and click \"Save the key and test\"."]}, {"bullets": ["JustCall has one key and one secret per account. Every app that uses it counts against the same limit.", "Do not click \"Reset Credentials\" unless you mean it: the old pair stops working at once in every app that uses it.", "JustCall's API cannot add or remove a user. Those stay by hand in JustCall; ITOps checks afterwards by reading."]}, {"h": "HubSpot (planned)"}, {"steps": ["As a HubSpot Super Admin (or with \"Developer tools access\"), open \"Development\" \u2192 \"Keys\" \u2192 \"Service keys\". HubSpot also names the path Settings \u2192 Integrations \u2192 Service Keys.", "Click \"Create service key\" and name it for its use, for example \"ITOps user access\".", "Click \"Add new scope\", tick the scopes below, click \"Update\".", "Click \"Create\" and confirm.", "Open the key, click \"Show\", then \"Copy\". It starts with \"pat-\". Keep it in the Vault until the connection asks for it."]}, {"bullets": ["Scopes for the first, read-only step: settings.users.read (users, roles, teams) and crm.objects.owners.read (who owns records).", "Scopes for the later step that creates and removes users: settings.users.write, crm.objects.users.read, crm.objects.users.write; settings.billing.write only if seats are assigned from ITOps.", "Use a service key, not a \"private app\": HubSpot stops the creation of new private apps on October 26, 2026 for existing accounts. Private apps that already exist keep working.", "Do not reuse a token another app uses: with a key of its own, either app can be cut off without touching the other.", "To replace a key: \"Rotate\" \u2192 \"Rotate and expire later\" keeps the old key working for seven days.", "In HubSpot, removing a user cannot be undone and does not move their records. Reassign the records first."]}, {"h": "eFax (Documo) (planned)"}, {"steps": ["Sign in to Documo and open the \"Toolbox\" menu.", "Click \"API Keys\", then \"Create\".", "Copy the key at once, or have it emailed to you: Documo shows it only this one time."]}, {"bullets": ["API keys need Documo's Business plan or higher and the API Add-On (bought under billing).", "The key belongs to the user who creates it. Create it under a user that will not leave: Documo does not let a user with an active API key be deactivated, and deleting that user deletes the key.", "If another app already sends faxes with a Documo key, find out which Documo user owns it before that person is ever offboarded.", "Not confirmed yet: whether Documo's API lists users. If it does not, eFax stays tracked by hand."]}, {"h": "Jotform (planned)"}, {"steps": ["Sign in to Jotform with the account that owns the company's forms, open the account settings and go to \"API\".", "On the right, click \"Create New Key\".", "Click the new key and type a label, for example \"ITOps\".", "Under \"Permissions\", choose \"Read Access\"."]}, {"bullets": ["Jotform counts API calls per day by plan: Starter 1,000; Bronze 10,000; Silver 50,000; Gold 100,000; Enterprise unlimited.", "An account on Jotform's healthcare-compliance or EU servers is reached at a different address: say which one is used when the connection is built.", "If people sign in to Jotform with their Microsoft account, blocking the Microsoft 365 account already ends their access; the step is then about moving their forms."]}, {"h": "Phone system, Grandstream UCM63xx (planned)"}, {"steps": ["Sign in to the web page of the UCM as administrator.", "Open \"Integrations\" \u2192 \"API Configuration\" \u2192 \"HTTPS API Settings (New)\".", "Tick \"Enable\".", "Set a user name and a password for the API. Do not reuse the administrator's.", "Leave the port at 8089 unless your network needs another one."]}, {"bullets": ["The phone system sits in the office, so the ITOps server cannot reach it by itself. How it is reached (one firewall rule for this server only, or a small relay in the office) is decided before the connection is built.", "Several wrong passwords in a row make the phone system refuse that address. Add the server's address to the whitelist on the same page."]}, {"h": "Microsoft 365 and vTiger"}, {"p": "These two are already connected and have no key on the Company systems page. Microsoft 365 is set up under Logs & Integrations \u2192 Integrations \u2192 \"System\": see the topic \"Connecting Microsoft 365\". vTiger is set up under Administration \u2192 Onboarding Templates \u2192 \"vTiger provisioning\": see \"Connecting vTiger provisioning\"."}, {"qa": [{"q": "Where do I paste the HubSpot, Documo or Jotform key?", "a": "Nowhere yet. This build can connect JustCall only. Keep the key in the Vault; the set-up page of that system will get a \"Connection\" box when its connection is built."}, {"q": "Should I create the other keys now?", "a": "It is not needed. The one thing with a date is HubSpot: after October 26, 2026 a new HubSpot credential is a service key, which is what these steps describe."}, {"q": "Is a key ever shown again in ITOps?", "a": "No. A saved key is stored encrypted, is never sent back to a browser and never written to a log. To change it, paste a new one."}]}]}, {"title": "Company systems: the whole process, from switching a system on to verifying an offboarding", "for": "admin", "mod": ["access", "m365_users:edit", "onboarding"], "body": [{"p": "ITOps knows three kinds of system. Microsoft 365 and vTiger are connected and ITOps acts in them by itself. A system set to \"Connected\" (JustCall can be) is read: ITOps sees who has an account there. A system \"Tracked by hand\" is one where a person does the work and answers in ITOps. Every set-up page has a box \"How the process works\" with these steps in the words that fit that system."}, {"h": "What you see, and where"}, {"bullets": ["Administration \u2192 Settings \u2192 Company systems \u2192 \"Systems\": Microsoft 365 and vTiger with how many accounts each has, then every other system with its use (Not used, Tracked by hand, Connected), the steps it adds, and its open accounts.", "\"Needs attention\" (Microsoft 365 \u2192 People): only the people to look at, not everybody. An active vTiger user that no Microsoft 365 account matches is listed as \"In vTiger only\".", "Red flag \"Left \u00b7 accounts still open\": the Microsoft 365 account is blocked and the vTiger user is still active, or an account in another system is still open. Amber flag \"Not in Microsoft 365\": an account under an email nobody has.", "A tab per connected system (JustCall): the users that system lists, read from it.", "Microsoft 365 \u2192 People, a person: the block \"Systems\" with Microsoft 365, vTiger and a row for every system in use, with their accounts, open and closed. An account is recorded, corrected and closed there.", "Microsoft 365 \u2192 People, the list: next to a person, how many accounts they have in the other systems; in red when sign-in is blocked and one is still open.", "Onboard, Offboard and History: one step per system.", "Audit Log, type \"access\": every change with who, when, the person, the system, old and new values."]}, {"h": "1. Set up"}, {"p": "On \"Systems\" click \"Switch on\u2026\". Choose the use, check the link to the system's admin page, tick whether it takes part in onboarding and offboarding, and write what to do there in your own words. For JustCall you can also save its key, test it and choose \"Connected\"."}, {"h": "2. The accounts become known"}, {"bullets": ["Tracked by hand: bring in what exists today once with \"Record accounts from a list\u2026\" (a user export from the system usually fits), or record accounts per person on Microsoft 365 \u2192 People. From then on onboarding and offboarding keep the records up to date.", "Connected: ITOps reads the users from the system: on \"Read now\", when a step is opened or answered, at verification, and every four hours."]}, {"h": "3. Onboarding"}, {"steps": ["On Microsoft 365 \u2192 People \u2192 \"Onboard\", tick the systems the new person needs. An onboarding template can tick them.", "ITOps creates the Microsoft 365 account and the vTiger user by itself.", "Each ticked system then shows a box with your instructions and the link. Tracked by hand: set the account up there, type its name, click \"The account is set up\". Connected: add the person there with their work email, click \"Check \u2026 for the user\".", "The onboarding stays open in History until every box is answered."]}, {"h": "4. Offboarding"}, {"steps": ["On \"Offboard\", pick the person. Each system is listed with the accounts known for them.", "Run it. ITOps blocks the Microsoft 365 account, removes licenses and groups, reassigns the vTiger records and deactivates the vTiger user.", "Each system then shows a box. Tracked by hand: do the work there and answer \"Removed there\", \"Handed over to a colleague\u2026\" or \"Checked: no account there\". Connected: remove the user there and click \"I removed the user: check \u2026 again\"; the step is done only when the system no longer lists them.", "The offboarding stays \"in progress\" until every box is answered. The boxes are also in History."]}, {"h": "5. Verification"}, {"p": "\"Verify offboarding\" (and the monthly re-check of past leavers) has a line per system. Microsoft 365 and vTiger are read live. A connected system is asked at that moment: \"Account removed (read from \u2026)\". A system tracked by hand reports what was answered: \"Account removed (recorded by hand)\". Any line that fails keeps the offboarding from being clean."}, {"h": "6. The record"}, {"p": "Every step, answer, reading and correction is on the person's onboarding or offboarding record and in the Audit Log. That is the evidence that a leaver lost every access, system by system."}, {"qa": [{"q": "The block \"Systems\" on an account shows only Microsoft 365 and vTiger.", "a": "No other system is switched on yet, or your role does not have \"Company systems\" (View). Systems are switched on under Administration \u2192 Settings \u2192 Company systems \u2192 \"Systems\"."}, {"q": "vTiger shows nothing for anybody.", "a": "vTiger is not connected, or could not be read just now; an amber line at the top of the list of accounts says which. It is set up under Administration \u2192 Onboarding Templates \u2192 \"vTiger provisioning\"."}, {"q": "Somebody is listed as \"In vTiger only\".", "a": "An active vTiger user whose email no Microsoft 365 account has: a service account, or a person under another address. Microsoft 365 \u2192 Licenses \u2192 \"Reconcile\" compares the two lists in detail."}, {"q": "Where are the steps to get each system's API key?", "a": "On each system's set-up page, in the box \"How to connect \u2026\", and in the topic \"Getting the API key for each company system\"."}]}]}, {"title": "IT Budget: plan next year's IT costs, office by office", "for": "admin", "mod": "budget", "body": [{"p": "IT Operations \u2192 Planning \u2192 \"IT Budget\" plans the IT costs of a fiscal year and follows the spend. It opens on next year; the year picker at the top changes it, and \"Export CSV\u2026\" shows the lines of that year first and downloads them from the preview."}, {"h": "Where to start"}, {"steps": ["\"Microsoft 365\": the licenses of the tenant \u2014 seats bought, seats in use, unused seats, the price per user per month and the renewal date. The price is Microsoft's published one (nonprofit or commercial, from July 1, 2026, \"Microsoft list \u00b7 confirm\") until you click \"change\" and save the price on your invoice. Then \"Add to the budget\u2026\": one line per paid license.", "\"Offices\": the organization's offices (a new installation starts with \"Main office\" and \"Remote and field staff\"; add your own with \"+ Add an office\"), with their people (Microsoft 365 accounts with a license, matched by office or city) and equipment (Equipment, matched by location). \"Standard lines\u2026\" proposes the office's communications (internet, backup internet, phone seats, mobile plans, fax) and equipment (firewall, network refresh, printer, computer refresh, new-hire computers, accessories). Untick what the office does not have.", "\"Budget lines\": \"Add from Contracts\u2026\" (active contracts with a payment amount), \"+ Add a line\" for anything else (IT staff, managed services, training), and \"Copy a year forward\u2026\" once a year exists.", "Open each line marked \"needs a price\" and type the price from the invoice or the quote. Until then it does not count in the totals."]}, {"h": "Each line"}, {"bullets": ["Category: the TBM cost pools \u2014 Internal labor, External labor, Outside services, Hardware, Software & SaaS, Cloud & hosting, Telecom & internet, Facilities & power, Other.", "Supports: the IT tower (end user, business applications, network, voice & fax, servers & hosting, security, IT management).", "Run, Grow or Transform; OpEx (operating) or CapEx (capital).", "Billed monthly, quarterly, twice a year, yearly or one time, with the months in the year for something that starts or ends inside it. The planned amount = price \u00d7 quantity \u00d7 times billed, and is always computed by the server.", "Status: Planned, Approved, or Cut (kept and shown greyed, not counted). A line with spend recorded cannot be removed: set it to Cut."]}, {"h": "Vendor and contract on every line"}, {"p": "Each line names who is paid (\"Vendor\") and under which agreement (\"Contract or agreement\"). Choose them from the lists, or use \"+ New vendor\" and \"+ New contract or agreement\" on the line: they are added to Vendors and Contracts, where documents, credentials and renewals are kept, and selected on the line. The contract list shows the chosen vendor's contracts; choosing a contract fills in its vendor."}, {"bullets": ["Settings \u2192 \"Every line names its vendor\" (On to start) and \"Contract or agreement required\" (on recurring lines to start; or every line, or never). IT staff (Internal labor) and Cut lines are exempt.", "A line that misses either shows what it lacks, is counted on the Overview and listed by the filter \"Needs vendor or contract\". It cannot be saved, changed or approved until it is completed. Lines proposed in bulk (Microsoft 365, standard office lines, a copied year) are added and flagged.", "The contract's dates, renewal and payment show on the line, with a warning when it ends inside the year without renewing by itself, ended before the year, was terminated or archived, or when its payment differs from the line. \"Use the contract's payment and end date on this line\" copies them. A renewed contract stays linked to its current term.", "Microsoft 365 tab: choose Microsoft's vendor and agreement once; the license lines take them.", "Vendors and Contracts \u2192 \"IT budget\" tab: the lines that name that vendor or contract, by year, planned and spent."]}, {"tip": "Adding a vendor or a contract from a line needs Vendors \u00b7 Create or Contracts \u00b7 Create; without it, ask someone who has it, or choose an existing one."}, {"h": "Equipment: what must be replaced"}, {"p": "The \"Equipment\" tab reads IT Operations \u2192 Equipment: every item in use, on loan or in repair whose purchase date plus the refresh cycle of its category falls before the end of the fiscal year \u2014 with its tag, office, who has it, when it was bought and when it is due. Items already past their cycle are marked; items with no purchase date are listed apart (add the date in Equipment to plan them)."}, {"bullets": ["Price per kind: the replacement price saved in Settings, else the average paid for that kind in Equipment over the last three years, else \"needs a price\".", "\"Add to the budget\u2026\" (or Budget lines \u2192 \"Add from Equipment\u2026\") adds one line per kind and office \u2014 one-time, capital, Hardware \u2014 with the asset tags in the reason. Adding again updates the quantity and price.", "Settings \u2192 \"Equipment replacement\": the refresh cycle of every Equipment category (0 = not replaced on a cycle) and an optional replacement price."]}, {"h": "The budget document for management"}, {"steps": ["Click \"Budget document\u2026\" at the top.", "Choose the status (Draft for review \u2014 printed with a DRAFT watermark \u2014 Proposed for approval, Approved, Final), the version, who it is for and who prepared it.", "Write an introduction, or leave it empty: it is then written from the figures.", "Choose the sections: executive summary, budget by category (with the year before), Run/Grow/Transform and operating/capital, offices, Microsoft 365 licenses, equipment replacement plan, contracts and renewals, vendors, benchmarks with their sources, spend to date, assumptions and notes, approval (signature lines), and the line detail (grouped by category or office).", "Click \"Preview\". The document opens on screen, page by page. If something needs changing, close the preview, change it and preview again. Then click \"Download PDF\" (ready to send) or \"Download Word\" (to change before sending) in the preview."]}, {"p": "Every figure comes from the budget lines. The logo, organization name, footer and colour come from Settings \u2192 Branding \u2192 Documents. Your choices are kept for the year; every download is in the Audit Log."}, {"h": "Offices"}, {"p": "A new installation starts with two sites: \"Main office\" and \"Remote and field staff\". Open \"Edit\" to add the address, set \"Matches\" (the office or city as written on Microsoft 365 \u2192 People and in Equipment) and switch off an office that is closed. People whose office matches no office are listed under the table with the value to match."}, {"h": "Spend, overview and benchmarks"}, {"bullets": ["\"Spend\": record what was paid each month, against a line (it takes the line's category and office) or a category.", "\"Overview\": planned, contingency (Settings, 5% to start), total request, spent so far (against a straight-line expectation), the change from last year, by category with spend, by office, Run/Grow/Transform, OpEx/CapEx, renewals inside the year.", "Benchmarks, each with its source: nonprofits' IT share of the operating budget (median about 1.1%) and IT spend per employee (median about $1,281), both from IRS Form 990 data that leaves out IT staff pay and telecom \u2014 so the comparison leaves them out too; the yearly change of IT budgets (+3.0% median) and security's share (about 5.4%) from Avasant's 2025/2026 benchmarks. Enter the number of employees and the operating budget in Settings to see your figures next to them."]}, {"h": "Settings"}, {"bullets": ["The month the fiscal year starts (change it at any time), the currency, nonprofit or commercial Microsoft 365 prices, the contingency, the yearly increase used when a year is copied, the employees and the operating budget, the Equipment replacement cycles and prices (above), and the rules for vendors and contracts."]}, {"tip": "Microsoft does not tell an app what a license costs, and an older agreement or a reseller can differ from the list. Save the invoice price once per license; the budget uses it from then on."}, {"p": "Permission: IT Budget (View, Create, Edit, Delete), not given to any role automatically; the Microsoft 365 tab also needs Microsoft 365 \u00b7 View. Every change is in the Audit Log (type \"budget\") with the values before and after, and so is every refused change. Nothing is changed in Microsoft 365 or Equipment from here; a vendor or contract added from a line is added to Vendors or Contracts and logged there."}, {"tip": "A line is approved by someone other than the person who added it (a Super Admin excepted). Add it as Planned; the other person sets it to Approved. A refused approval is in the Audit Log."}]}, {"title": "Security assessment: the rule library, baselines and the tenant's security settings", "for": "admin", "mod": "security_assessment", "body": [{"p": "Microsoft 365 \u2192 Posture checks the tenant against ITOps's library of security rules and tells you, for each one, what it found, who or what it affects, why it matters, how to fix it, whether the tenant already owns the license it needs, and what to do first. It only reads: nothing here changes the tenant."}, {"h": "The library and the baselines"}, {"bullets": ["57 rules in eight areas: identity and sign-in, admin accounts, tenant settings, applications, email, devices and Windows, sharing and collaboration, and Secure Score.", "Three baselines choose which rules count: Essentials (22 rules, any tenant), Business standard (50, for Business Premium tenants; the default) and Strict (all 57, some needing Entra ID P2). Change it with the menu next to \"Run now\"; the score changes at once, without a new scan.", "\"Rules of the baseline\" lists only those; \"Every rule in the library\" shows the others too, marked with their level."]}, {"h": "The tenant profile"}, {"bullets": ["\"Tenant profile\" (next to the baseline) is answered once: staff, where people work, personal phones for company email, countries people sign in from, likely targets, outside requirements (customers, cyber insurance, a regulated field).", "Emergency access accounts: the two cloud-only Global Administrator accounts kept out of every Conditional Access policy. Name them here by their sign-in address; the rule \"Two emergency access accounts are ready\" checks them, and later Conditional Access changes will always leave them out.", "Rules use the profile to decide what applies (for example, app protection for phones applies when people read company email on personal phones)."]}, {"h": "Running it"}, {"steps": ["Click \"Run now\" (it takes up to a minute), or let it run on its own: weekly by default; the menu changes it to daily or by hand only.", "Look at the score and the counts. Click a count (Failed, Warnings, Not licensed\u2026) to see only those rules, or use the filters and the search (it also finds accounts and domains).", "Click a rule to open it: what was found, the affected accounts, apps, domains or devices, why it matters, the steps to fix it, the effort and effect on people, what to do first (click one to open it), and the license and Microsoft permission it needs.", "After fixing something, run it again. A rule that changed since the run before says \"Better\" or \"Worse since last run\"."]}, {"h": "Reading the results"}, {"bullets": ["Passed, Warning, Failed: the result. Severity (High, Medium, Low) says how much it matters.", "\"You already pay for this\": the rule failed, and the tenant's subscriptions already include what it needs. The line under the score lists what the tenant owns (Entra ID P1 and P2, Intune, Defender, Exchange Online, SharePoint Online).", "\"Needs \u2026\" (Not licensed): the tenant does not have the license the rule needs. It is shown and left out of the score.", "Could not be read: Microsoft refused the read: a permission is missing (Microsoft 365 \u2192 Home \u2192 Diagnose shows which). Left out of the score; never counted as passed.", "Does not apply: nothing to check here (for example, no Windows computers are enrolled).", "The score counts the rules of the chosen baseline that could be read and are licensed; high severity weighs 3, medium 2, low 1, and a warning counts half.", "History keeps every run (the last 60): open one to see the tenant as it was. Export CSV gives one run as a spreadsheet, with the baseline, license fit, effort, effect and what to do first per rule."]}, {"h": "The plan"}, {"p": "Posture \u2192 Plan turns the latest scan into a plan. It takes the rules of the chosen baseline that failed or warned (and that the tenant is licensed for), puts them in four stages (Prepare, Report-only, Enforce, Tighten), and orders each stage so that what other items wait on comes first (the emergency accounts before everything that needs them), then by severity and effort. It is built by rules: the same scan always gives the same plan."}, {"bullets": ["Decide each item: \"Do it\" (an owner and a wanted-by date), \"Make it a task\" (creates a ticket in the service desk with the rule, what was found and the steps; assigned to the owner), \"Accept the risk\" (a reason, someone who reviews it, and an expiry at most a year away), \"Not for us\" (a reason) or \"Later\".", "Sign-off: once every item is decided, the client contact who agreed to the plan is named and the version is signed off. A signed version is kept as it is.", "\"Rebuild from the latest scan\" refreshes the draft; \"Start a new version\" begins the next one from a signed plan. Decisions carry over; an accepted risk whose expiry has passed comes back undecided, saying so.", "\"Fixed since\": items whose rule passes in the latest scan. The counts at the top filter the list. Export CSV gives the version as a spreadsheet.", "Every build, decision, task, sign-off and refusal is in the Audit Log."]}, {"h": "Microsoft's recommended actions"}, {"p": "The tab of that name lists Microsoft's own recommended actions for the tenant (the actions behind Secure Score), with their points, effect on people and effort, To do or Done. Where one of ITOps's rules checks the same thing, the action links to it. It is a second opinion next to the library, so Microsoft's newest advice still shows."}, {"h": "Microsoft permissions"}, {"p": "Application permissions with admin consent: User.Read.All, AuditLog.Read.All, RoleManagement.Read.Directory, Policy.Read.All, Application.Read.All, Domain.Read.All, Organization.Read.All, DeviceManagementManagedDevices.Read.All, DeviceManagementConfiguration.Read.All, DeviceManagementApps.Read.All, DeviceLocalCredential.ReadBasic.All, BitlockerKey.ReadBasic.All, RoleEligibilitySchedule.Read.Directory, SharePointTenantSettings.Read.All and SecurityEvents.Read.All; the Exchange rules use the Exchange connection (Exchange.ManageAsAppV2). A missing permission only leaves its rules unread."}, {"tip": "Coming next: fixes made from ITOps (report-only first, with an impact preview) and an AI planning assistant that tailors and explains the plan."}]}, {"title": "The planning assistant: suggested decisions, explanations, staff notices and KB articles for the security plan", "for": "admin", "mod": "security_assessment", "body": [{"p": "Microsoft 365 \u2192 Posture \u2192 Plan has a planning assistant once the AI integration is set up (Settings \u2192 Sign-in & AI)."}, {"bullets": ["Suggest decisions: for each undecided item of the draft plan, the assistant proposes Do it, Make it a task, Accept the risk, Not for us or Later, with one sentence why. It uses the baseline, the tenant profile (Posture \u2192 Tenant profile) and the findings.", "A suggestion is only shown (\"Suggested: \u2026\" on the item). Open the item and press \"Use it\" to fill the decision and the note; nothing is decided until you save. Suggestions about rules that are not undecided items of the plan are left out, and the count says so.", "On each item: Explain in plain words (for a manager who is not technical), Draft a staff notice, Draft a KB article. Edit the text, fill in [date] and [IT contact], then copy it or save it as a KB article draft or an announcement draft. Nothing is published or sent from here.", "What the assistant is given: the rules, their area, severity, stage, effort, effect on people, license, what was found as counts, the decisions and the tenant profile. Never people's names, addresses or device names.", "Every request is in the Audit Log with what was asked and how many answers were kept (not the text). Asking for suggestions and drafts needs Security assessment (edit); an explanation needs view. Saving needs Knowledge Base (create) or Announcements (create)."]}]}, {"title": "Proof: drift, the executive report, the house baseline and the Scorecard", "for": "admin", "mod": "security_assessment", "body": [{"p": "Microsoft 365 \u2192 Posture has three tabs that show the work holds: Drift, Executive report and House baseline."}, {"bullets": ["Drift: after every scan, a rule of the baseline in use that passed in the scan before and now fails or warns is recorded. The people with Security assessment (edit) and Super Admins get a bell, and the Audit Log has it (\"sa_drift\").", "Each drift lists what changed between the two scans: Conditional Access and admin role changes made in the app (with who made them), and, when Microsoft 365 is connected, the Entra audit log and the Intune audit log. Exchange changes are not in those logs: check the Exchange admin center audit. Reading the audit logs needs AuditLog.Read.All and DeviceManagementApps.Read.All.", "Someone with edit acknowledges each drift with a short note (who changed it and why, or what was done). \"Passes again now\" shows when the latest scan has it fixed.", "Executive report: \"Build the report\" makes one page for the client \u2014 the score and its trend over six months, the plan and its sign-off, the top ten open risks, the risks accepted and when they expire, drift in the last 90 days and what improved. Print it or save it as PDF, or download it.", "House baseline: \"Make it from the baseline in use\" starts your own rule set. Tick rules in or out, and write a note on why. Export gives a file; at the next client, Import reads it (rules this version does not know are left out and listed) and can put it in use. The house baseline then appears in the baseline list at the top.", "Scorecard: add a measurable with the source \"Security assessment \u2014 score\", \"\u2014 failed rules\" or \"\u2014 drift\". Score and failed rules use the last scan before the end of each period; drift counts what was found in the period."]}, {"p": "Everything here \u2014 scans, drift, acknowledgements, reports, house baseline changes, imports and exports \u2014 is written to the Audit Log. Nothing here changes the tenant."}]}, {"title": "Microsoft invoices from Microsoft's billing", "for": "admin", "mod": "invoices", "body": [{"p": "Assets & Vendors \u2192 Invoices \u2192 Microsoft billing imports the invoices of a Microsoft Customer Agreement, so you do not type them in."}, {"bullets": ["Once: create the vendor \"Microsoft\" (Microsoft 365 \u2192 Licenses \u2192 Subscriptions & contracts). In Microsoft's billing, give the app (its service principal) the role \"Billing profile reader\" or \"Invoice manager\" on the billing profile. No API permission to add.", "\"Find it\" asks Microsoft which billing account the app can see and fills it in; Save. \"Pull new invoices every day\" lets the daily job import the last two months once a day.", "\"Import now\" brings in the invoices dated in the period you choose (up to about a year at a time). Each one is imported once: a line per charge, tied to the Microsoft contract with the same name; a line for any difference to Microsoft's subtotal (credits, rounding); the tax; the PDF attached.", "Imported invoices arrive as Received. Approve and pay them as for any vendor; paying records the spend in IT Budget. Microsoft's own status (Due, Paid, amount due) is shown on the invoice and refreshed on each import, apart from your notes.", "Credit notes are skipped and listed. Older direct accounts (no Microsoft Customer Agreement) do not have this: upload the PDF as for any vendor.", "Every import, every new invoice and every refusal (no permission here, or Microsoft saying no) is in the Audit Log."]}]}, {"title": "Conditional Access: policies from templates in report-only, what they would do, turning them on and putting a change back", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 Security \u2192 Conditional Access changes Conditional Access in the tenant without opening the Entra admin center, with guard rails."}, {"bullets": ["First mark the emergency access accounts (Posture \u2192 Security assessment \u2192 Tenant profile). Nothing is created or turned on here until they are, and they are left out of every policy made here. A policy that does not leave them all out cannot be turned on from here.", "Templates: block legacy sign-in, multifactor for everyone, multifactor for admins, phishing-resistant sign-in for admins, block device code sign-in, compliant device for admins, compliant device or protected app for everyone, challenge risky sign-ins and fix high-risk users (Entra ID P2), block sign-in from other countries (you name the allowed countries). Each is created in report-only: nothing changes for anyone, Microsoft only records what it would have done.", "\"What it would do\" on a policy reads the sign-in log (last day, 7 or 30 days) and lists who would have been blocked or asked for more. Give a new report-only policy a few days before turning it on.", "On, Report-only and Off on each policy. Delete is offered only for policies made here; others are turned off instead.", "Security defaults: when on, policies cannot be turned on. \"Switch to Conditional Access\" (type SWITCH) turns security defaults off and turns on four policies that do the same; if Microsoft refuses one, security defaults are turned back on and nothing else changes.", "Changes made here: every change keeps the policy as it was, and \"Put back\" undoes it (a deleted policy is created again, a state goes back, security defaults come back on).", "Second person: Settings \u2192 Approvals \u2192 \"Change Conditional Access\" (off by default). When on, a change waits for someone else with \"Microsoft 365 \u00b7 Conditional Access\"; it lapses after 24 hours.", "Every sign-in of an emergency access account raises a bell for Super Admins and Conditional Access holders and goes in the Audit Log (checked by the scheduled job).", "A failed rule or plan item that a template fixes has a \"Fix in \u2026\" button that opens this tab on that template.", "Permissions: \"Microsoft 365 \u00b7 Conditional Access\" (edit), not given to any role automatically. Graph: Policy.Read.All, Policy.ReadWrite.ConditionalAccess and Application.Read.All to change, AuditLog.Read.All for \"What it would do\" and the emergency watch, User.Read.All for the emergency accounts."]}]}, {"title": "Defender incidents and admin roles: handling an incident, removing a role or making it eligible", "for": "admin", "mod": "m365", "body": [{"p": "Microsoft 365 \u2192 Security handles two more things without opening Microsoft's portals."}, {"bullets": ["Alerts & actions \u2192 Open incidents \u2192 \"Handle\" on an incident: its alerts (with the people and devices they touch) and comments. Assign it (to you or someone with \"Microsoft 365 \u00b7 Security incidents\"), mark it \"Working on it\", add a comment, make a ticket of it (once per incident; the ticket gets the alerts and the Defender link), and resolve it.", "Resolving asks what it was, as Microsoft does: a true positive (malware, phishing, compromised account\u2026), expected activity (a security test, a line-of-business app\u2026) or a false positive, plus what was found and done. That text is kept with the incident in Defender.", "Security \u2192 Admin roles: everyone who holds a directory role, permanent or eligible, and what makes each admin account risky: synchronized from on-premises, licensed (used every day), no multifactor sign-in, not signed in for 90 days, disabled, guest. Each count filters the list.", "Remove a role (type the account's address to confirm), or \"Make eligible\" (Entra ID P2): the person keeps the role but switches it on in Entra when needed. At least two people always stay Global Administrator permanently, and an emergency access account keeps its role. Roles held by a group are changed in Entra.", "Changes made here: every change is kept and \"Put back\" undoes it.", "Second person: Settings \u2192 Approvals \u2192 \"Change an admin role\" (off by default). When on, someone else with \"Microsoft 365 \u00b7 Directory roles\" approves; requests lapse after 24 hours.", "A failed admin rule in Posture (Global Administrator count, separate admin accounts, cloud-only admins, roles when needed, admin multifactor) has a \"Fix in \u2026\" button that opens Admin roles on the right filter.", "Permissions: \"Microsoft 365 \u00b7 Security incidents\" (new, not given to any role automatically) and \"Microsoft 365 \u00b7 Directory roles\". Graph: SecurityIncident.ReadWrite.All; RoleManagement.ReadWrite.Directory; RoleEligibilitySchedule.ReadWrite.Directory for eligible roles; AuditLog.Read.All for last sign-in and multifactor registration."]}]}, {"title": "Risky people: who is at risk and the automatic follow-up", "for": "admin", "mod": "security_assessment", "body": [{"p": "Microsoft 365 \u2192 People \u2192 At risk lists every account the security assessment finds at risk, one row per person, with a score from 0 to 100, a level (High 50+, Medium 25+, Low) and the reasons. It refreshes with every assessment run."}, {"bullets": ["Reasons and their points: Microsoft marks the account compromised (60), high sign-in risk (50), admin without multifactor sign-in (40), medium sign-in risk (30), no multifactor sign-in (25), unencrypted computer (20), admin role on the everyday account (15), not used for 90 days (15), device that breaks the security rules (15), never signed in (10), text message or call as the only second step (10), low sign-in risk (10).", "Microsoft's own sign-in risk needs Entra ID P2 and the permission IdentityRiskyUser.Read.All; without them the other reasons still count, and the page says what could not be read.", "Microsoft's list (the tab beside People at risk) is Microsoft's own risky-users list. Microsoft gives it to apps only when the tenant has Microsoft Entra ID P2; Microsoft 365 Business Premium includes Entra ID P1, where the Entra admin center shows the people with limited data (risk level \"None\", no reason). The tab says which is missing \u2014 the permission (with the steps in the Entra admin center) or the license \u2014 and \"Check again\" asks Microsoft afresh once it is added. One P2 license is enough to try it; Microsoft's licensing expects one for each person the feature protects. Until then, People at risk and the fixes on the person's account work with P1: reset the password (an admin-set password counts as remediating Microsoft's risk), revoke sessions, require multifactor registration again, block sign-in.", "Click a person to see each reason, its points and what they are asked to do. A \u25b2 or \u25bc shows how the score moved since the run before."]}, {"h": "The automatic follow-up"}, {"steps": ["Switch it on under Follow-up, choose the levels to follow (High, Medium, Low), the days to fix it, when to remind, and what happens at the deadline. While it is on, the assessment runs every day.", "Someone newly at a followed level gets an email with their own reasons, the steps and the deadline.", "If it is still open after the reminder days, they get one reminder.", "At the deadline: their manager (from Microsoft 365) gets an email, IT gets a ticket, and the changes ITOps can make are proposed under Approvals.", "When a later assessment no longer finds them at a followed level, the follow-up closes as Fixed, the ticket is resolved with a note, and open proposals are withdrawn."]}, {"h": "Approvals: nothing changes without one"}, {"bullets": ["Proposed changes: add to the MFA-required group (set the group under Follow-up), sign out everywhere, block sign-in.", "Approve carries it out at once in Microsoft 365; Dismiss asks why. Approving also needs the matching Microsoft 365 permission (Groups, Accounts or Tenant configuration), admin accounts need a Super Admin, and nobody can approve a change on their own account.", "Dismiss under Follow-up stops following someone for 30 days (for example a shared account you accept), resolves their ticket and withdraws their proposals."]}, {"p": "The three emails are in Settings \u2192 Email templates \u2192 \"Risky people follow-up\" (English and Spanish). Every message, ticket, proposal, approval and refusal is in the Audit Log."}]}]}], "quickstarts": {"user": {"title": "End-user Quick Start", "intro": "How to sign in, ask IT and Operations for help, and follow your request. Keep this page handy.", "body": [{"h": "1. Sign in"}, {"steps": ["Open the ITOps link, type your email and password, and choose \"Sign In\". Or choose \"Sign in with Microsoft 365\" if you see it.", "If asked for a code, type the 6-digit code from your authenticator app and choose \"Verify\" (or \"Use a backup code instead\").", "8 wrong passwords in 15 minutes locks sign-in for about 15 minutes. Forgot your password? Ask your ITOps administrator; there is no reset link."]}, {"h": "2. Set up your account (once)"}, {"steps": ["Click your name at the top right to open \"Account\".", "\"Email language\": choose \"English\", \"Espa\u00f1ol\" or \"Organisation default\".", "\"Set up 2FA\": scan the QR code, type the code, choose \"Verify & turn on\".", "Choose \"Copy codes\" and store your 10 backup codes somewhere safe, then \"Done\"."]}, {"h": "3. Ask for help"}, {"bullets": ["No account needed: use the \"Submit a Help Request\" page or a request form your team shared, or email the help desk. Save the TK- number you get.", "If a suggested article fixes it, choose \"This solved it \u2014 no ticket needed\"."]}, {"steps": ["In the app: Service Desk \u2192 Tickets \u2192 \"+ New Ticket\".", "Choose a \"Subject\" group, then a \"Category\". Leave \"Priority\" at \"Medium\" unless it's urgent.", "Put all the detail in \"Description\": what's wrong, error messages, when it started, what you tried.", "Choose \"Create Ticket\". Leave \"Assignee\" and the due boxes empty."], "mod": "tickets:create"}, {"h": "4. Add files", "mod": "tickets"}, {"bullets": ["Open your ticket \u2192 \"Upload\" \u2192 drag a file in or \"Browse\". One file at a time, up to 50 MB: pictures, audio/video, PDF, Word, Excel, PowerPoint, CSV, TXT, XML or JSON.", "Or use the camera icon in the top bar: \"Photo\", \"Video\" or \"Screenshot\" \u2192 \"\ud83d\udcce Attach to ticket\".", "Files attached to emails are NOT saved to the ticket. Upload them in the app."], "mod": "tickets"}, {"h": "5. Follow and reply", "mod": "tickets"}, {"bullets": ["Find your tickets under Dashboard \u2192 \"My Tickets\" or Service Desk \u2192 Tickets. Use \"Opened by me\" / \"Assigned to me\", \"Still open\", and the search box to narrow the list. The \"Open TK-\u2026 in ITOps\" button in ticket emails takes you straight there.", "Reply in \"Add a comment\u2026\" \u2192 \"Post\". The person working on it gets a bell and an email, so you can go back and forth until it's solved.", "Or reply to a ticket email keeping the TK- number in the subject (text only).", "Status: open \u2192 in progress \u2192 pending (waiting, often on you) \u2192 resolved \u2192 closed. Not fixed after \"resolved\"? Comment on the same ticket."], "mod": "tickets"}, {"h": "6. Watch the bell"}, {"bullets": ["The bell shows \"New comment\", reminders and requests, with a red unread count.", "Click an item to open the page; \"Mark all read\" clears the count."]}, {"h": "7. Find answers yourself", "mod": "kb"}, {"bullets": ["Knowledge \u2192 Knowledge Base has your team's how-to articles. Search them from the top search box."], "mod": "kb"}, {"bullets": ["Knowledge \u2192 Ask IT: type your question in plain words and choose \"Send\"."], "mod": "kb_assist"}, {"h": "8. Procedures you must acknowledge", "mod": "sops"}, {"steps": ["Open Knowledge \u2192 SOPs (the bell tells you when one is waiting).", "Read the procedure and choose \"Acknowledge this version\"."], "mod": "sops"}, {"tip": "Click the question mark in the top bar at any time to open the Help Center. ITOps signs you out after about 30 minutes of inactivity, so save your work."}]}, "agent": {"title": "Support Agent Quick Start", "intro": "A daily checklist for working the ticket queue in Service Desk \u2192 Tickets.", "mod": "tickets:all", "body": [{"h": "1. Start of day"}, {"steps": ["Check the bell for \"Ticket assigned to you\", \"New comment\" and \"\u2026 SLA due soon\" / \"\u2026 SLA breached\".", "Service Desk \u2192 Tickets \u2192 first filter \"Unassigned\" (+ \"Still open\"): triage these first.", "Then switch to \"Assigned to me\" and work the red and amber SLA badges first.", "Use the refresh button to reload. The list holds the 1,000 newest tickets; use the top search for older ones."]}, {"h": "2. Triage a new ticket"}, {"steps": ["Open it \u2192 \"Edit\".", "Set \"Category\" and \"Priority\" (Critical, High, Medium, Low, Planning).", "Due times are filled in automatically from the category and priority; adjust \"Response due\" / \"Resolution due\" only if you agreed something else.", "Pick an \"Assignee\" \u2192 \"Save Changes\". They get a bell notification and an email."]}, {"h": "3. Work it"}, {"bullets": ["A normal comment is PUBLIC: the requester sees it and may get it by email. Tick \"Internal note\" first for team-only notes (yellow, INTERNAL).", "Use \"\ud83d\udd14 Notify\" to message a colleague privately (bell, optional email).", "\"Upload\" adds files (up to 50 MB; pictures, audio/video, PDF, Office, CSV, TXT, XML, JSON). \"Transcribe\" turns audio or video (up to 25 MB) into text.", "AI: in \"Edit\" \u2192 \"Summarize & suggest\" \u2192 check \u2192 \"Apply to form\" \u2192 \"Save Changes\"; \"Copy\" the draft reply into a comment and edit it before you \"Post\"."]}, {"h": "4. Keep the status honest"}, {"bullets": ["open \u2192 in progress when you start. Saving off open records the first response.", "pending when waiting on the requester. The badge says \"Paused\": no SLA alerts, and the due times move on by the time spent in Pending.", "resolved when fixed, closed when finished, cancelled for duplicates or withdrawn requests.", "Changing the priority or category recalculates the due times (unless you type your own in the same edit)."]}, {"h": "5. SLA badges"}, {"bullets": ["Blue \"Due \u2026\" on track. Amber due soon (response under 1h, resolution under 4h). Red \"Overdue \u2026\". Green \"Met\". Purple \"Paused\" (pending).", "The list shows the resolution badge; the ticket shows \"Response\" and \"Resolution\"."]}, {"h": "6. Watch for"}, {"bullets": ["\"EXT\" requesters have no ITOps login. Email is their only channel. Their email replies ring your bell and send you a \"Requester replied\" email.", "Comments starting \"(email from UNRECOGNISED sender \u2026)\" are internal notes. Verify the sender before acting.", "Email attachments aren't saved. Ask for uploads or upload them yourself."]}, {"h": "7. Close out"}, {"steps": ["Post a final comment explaining the fix.", "Set \"Status\" to resolved (or closed) \u2192 \"Save Changes\". The requester is emailed if status emails are on."]}, {"steps": ["If the fix will come up again, write it up in Knowledge \u2192 Knowledge Base \u2192 \"New Article\"."], "mod": "kb:create"}, {"tip": "Always read AI output and transcripts before posting them. You are responsible for what the requester receives."}]}, "admin": {"title": "Administrator Quick Start", "intro": "A setup checklist for a new ITOps install, then the routine that keeps it healthy. Most settings live under Administration \u2192 Settings, and several steps need a Super Admin.", "mod": ["settings:edit", "users:edit"], "body": [{"h": "Part 1: New install checklist"}, {"h": "1. Check the install"}, {"steps": ["Sign in with the Super Admin account the installer created.", "Delete the install/ folder on the server, or deny web access to it.", "Browse to https://YOUR-SITE/config.php and https://YOUR-SITE/sql/. Both must return 403.", "Settings \u2192 \"General\": \"Backend connection\" should say \"API reachable and database connected\". Under \"About\", note the Version.", "Settings \u2192 \"Maintenance\": \"Database Updates\" should say \"Your database is up to date.\" If not, click \"Apply updates now\"."]}, {"h": "2. Make it yours"}, {"steps": ["Settings \u2192 \"Branding\": \"Application name\", then upload a PNG \"Logo\" and a \"Favicon\" (SVG files are refused).", "Optional: set the \"Public form redirect URL\" and the \"Navigation icons\"."]}, {"h": "3. Email"}, {"steps": ["Settings \u2192 \"Email\": tick \"Enabled\" for outbound email, set \"From name\", \"From address\" and \"Send via\", then click \"Save settings\". Saving once also creates the cron token.", "Click \"Send test email to myself\" and check the Result in the outbound email log.", "Choose the ticket email tick boxes (acknowledgements, replies and status changes are off by default).", "Optional: turn on \"Email-to-Ticket Intake\" for your help-desk mailbox, then \"Test connection\" and \"Run now\".", "Settings \u2192 \"Email templates\" \u2192 \"Header, footer & language\": pick the default language and check the footer. Review the ticket emails."]}, {"h": "4. Categories and the SLA clock"}, {"steps": ["Administration \u2192 Ticket Categories: add groups and categories, with \"Response SLA (hours)\" and \"Resolution SLA (hours)\" only where a category needs its own; blank uses the priority targets. Give each an owner and backup who can edit tickets.", "Settings \u2192 \"SLA & Hours\" \u2192 \"Priority targets\": check the hours for each priority, then \"Save priority targets\".", "Settings \u2192 \"SLA & Hours\": set business hours (check the time zone spelling) and holidays, then \"Save business hours\".", "In the same tab, check the alert warning times and the weekly digest box, then \"Save SLA settings\".", "Back on Ticket Categories, read the \"Routing & SLA check\" box and fix anything red or amber."]}, {"h": "5. Scheduled jobs"}, {"steps": ["In cPanel \u2192 Cron Jobs, add cron-mail.php and cron-sla.php every 5 minutes, and \"cron-sla.php digest\" weekly. The exact lines are in the Help Center topic on scheduled jobs.", "Without cron, leave \"Run automatically while ITOps is open\" ticked. The weekly digest and exact-time offboarding still need cron.", "Check Logs & Integrations \u2192 Event Log, channel cron, for \"SLA scan complete\" entries."]}, {"h": "6. Microsoft 365 and sign-in"}, {"steps": ["Settings \u2192 \"Sign-in & AI\" \u2192 \"Microsoft 365 / Azure\": enter the tenant ID, client ID, secret and redirect URI, tick \"Enable SSO\", \"Save\", then \"Test Graph connection\".", "The same tenant, client ID and secret also power the Microsoft 365 pages, Server Guardian and onboarding (they are shown in Logs & Integrations \u2192 Integrations \u2192 \"System\" \u2192 \"Microsoft 365 connection\"). Add the application permissions in Azure with admin consent, then check Microsoft 365 \u2192 Home \u2192 \"Diagnose\".", "Remember: first-time Microsoft sign-ins get the Viewer role automatically."]}, {"h": "7. Roles, people and security"}, {"steps": ["Administration \u2192 Roles & Permissions: build your roles from the presets. See \"Recommended role setups\". Only agents should get Tickets \"All records\".", "Administration \u2192 Users (or Bulk Import): add people and give them roles. Keep Super Admin to one or two people.", "Settings \u2192 \"General\" \u2192 \"Session security\": choose who must use 2FA and set the idle timeout. Then set up 2FA on your own account."]}, {"h": "8. Optional extras"}, {"steps": ["Settings \u2192 \"Sign-in & AI\" \u2192 \"AI assist\": provider, model and key.", "Knowledge \u2192 KB Content Gaps \u2192 \"Seed starter articles\", then review and publish the drafts.", "Administration \u2192 Forms: build request forms.", "vTiger: deploy vtiger-bridge/itops-bridge.php, save the bridge secret, click \"Test bridge\". Then build onboarding templates in Administration \u2192 Onboarding Templates."]}, {"h": "Part 2: Ongoing routine"}, {"h": "Every week"}, {"steps": ["Read the weekly SLA digest. Look into falling compliance or a growing overdue count.", "Logs & Integrations \u2192 Event Log: filter to Error and fix anything new.", "Settings \u2192 \"Email\": scan the outbound email log for failed sends.", "Knowledge \u2192 KB Content Gaps: turn the most-asked questions into articles, then click \"Mark covered\"."]}, {"h": "Every month"}, {"steps": ["Administration \u2192 Users: set leavers to Inactive and check new Microsoft sign-ins that got the Viewer role.", "Check who holds Super Admin and which roles include SENSITIVE modules.", "Logs & Integrations \u2192 Audit Log: look for login_lockout, mfa_failed, settings_updated and role changes you don't recognise. Export a CSV if you keep records.", "Read the monthly access re-check result (the \"Access re-check found a problem\" email, or the Event Log, channel onboarding).", "Look at contracts and credentials marked Expiring, Due soon or Overdue.", "Logs & Integrations \u2192 Integrations: revoke API keys and pause webhooks nobody uses."]}, {"h": "When a new build arrives"}, {"steps": ["Follow \"Updating ITOps to a new build\": extract the full zip over the folder, run the database update if the CHANGELOG says \"DB UPDATE REQUIRED\", upload a new vTiger bridge only if asked, hard-refresh, and check the build stamp under Settings \u2192 General \u2192 About."]}, {"h": "Once a year"}, {"steps": ["Add next year's holidays under Settings \u2192 \"SLA & Hours\".", "Rotate the vTiger bridge secret with \"Rotate secret\u2026\", and renew the Azure client secret before it expires.", "Review the 2FA policy, the idle timeout and your role setups."]}, {"tip": "The database update is safe to run at any time. It only applies what's missing."}]}}};
const $=id=>document.getElementById(id);
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function bodyHtml(body){
  let h='';
  (body||[]).forEach(it=>{
    if(it.mod&&!allowed(it.mod)) return;   // block meant for another role (e.g. an agent-only paragraph)
    if(it.p) h+='<p>'+esc(it.p)+'</p>';
    else if(it.h) h+='<h4>'+esc(it.h)+'</h4>';
    else if(it.bullets){ h+='<ul>'+it.bullets.map(b=>'<li>'+esc(b)+'</li>').join('')+'</ul>'; }
    else if(it.steps){ h+='<ol>'+it.steps.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol>'; }
    else if(it.tip){ h+='<div class="tip"><b>Tip:</b> '+esc(it.tip)+'</div>'; }
    else if(it.warn){ h+='<div class="warn"><b>Important:</b> '+esc(it.warn)+'</div>'; }
    else if(it.qa){ h+='<div class="qa"><div class="qah">Common questions</div>'+it.qa.map(x=>'<div class="qai"><div class="q">'+esc(x.q)+'</div><div class="a">'+esc(x.a)+'</div></div>').join('')+'</div>'; }
  });
  return h;
}
function searchText(t){ let s=t.title+' '; (t.body||[]).forEach(it=>{ if(it.mod&&!allowed(it.mod))return; s+=(it.p||'')+' '+(it.tip||'')+' '+(it.warn||'')+' '+(it.h||'')+' '+((it.qa||[]).map(x=>x.q+' '+x.a).join(' '))+' '+((it.bullets||[]).join(' '))+' '+((it.steps||[]).join(' '))+' '; }); return s.toLowerCase(); }

const list=$('list'), results=$('results');

/* ---------- Role-aware Help Center ----------
   Topics carry "mod" = the permission module they are about ("tickets", "tickets:edit", or a list = any of).
   The signed-in user's role decides which topics show (same rules as the app's menu — keep in sync with
   itopsCanFrom in index.html / itops_can in api/index.php). Not signed in = general topics only. */
const PERM_INHERIT={security_assessment:['m365_admin','edit'],m365_mail:['m365_admin','edit'],license:['settings','edit'],calendar:['tickets','view'],kb_assist:['kb','view'],kb_gaps:['kb','edit'],event_log:['audit','view'],integrations:['settings','edit'],branding:['settings','edit'],email_cfg:['settings','edit'],sla_cfg:['settings','edit'],m365_users:['m365_admin','edit'],m365_credentials:['m365_admin','edit'],m365_licenses:['m365_admin','edit'],m365_groups:['m365_admin','edit'],provision_onboard:['onboarding','edit'],provision_offboard:['onboarding','edit']};
function itopsWild(w){ return !!w&&w!=='0'&&!(Array.isArray(w)&&!w.length)&&!(typeof w==='object'&&!Array.isArray(w)&&!Object.keys(w).length); }
function canFrom(role,p,mod,act){
  act=act||'view'; if(role==='super_admin')return true; p=p||{};
  if(itopsWild(p['*']))return true;
  if(mod==='dashboard')return true;
  const v=p[mod];
  if(v==null){
    if(mod==='my_signatures'||mod==='my_equipment')return act==='view';
    if(Object.keys(p).some(k=>Array.isArray(p[k])))return false;
    if(mod==='changelog')return act==='view';
    const inh=PERM_INHERIT[mod]; if(inh)return canFrom(role,p,inh[0],act==='view'?'view':inh[1]);
    return false; }
  if(Array.isArray(v))return act==='view'?v.length>0:v.includes(act);
  if(v==='none'||v===false)return false;
  if(act==='view')return true;
  if(act==='create'||act==='edit')return ['crud','create_edit','dept_manage','own','full',true].includes(v);
  if(act==='delete')return ['crud','dept_manage','full',true].includes(v);
  if(act==='all')return ['crud','dept_manage','full','read_all','all',true].includes(v);
  return true;
}
let ME=null;          // {role, role_permissions, display_name} when signed in
let SHOW_ALL=false;   // admins can switch to "all topics"
// BT101: topics of modules that are not part of this installation are left out for everyone ("all topics" included)
let PERMS_OFF={};
const CAT_MOD={'Tickets & support':'tickets','Forms & intake':'forms'};
function modOff(mod){ const l=(Array.isArray(mod)?mod:[mod]).filter(Boolean); return l.length>0&&l.every(x=>PERMS_OFF[String(x).split(':')[0]]); }
function allowed(mod){
  if(modOff(mod)) return false;
  if(!mod) return true;
  if(SHOW_ALL) return true;
  if(!ME) return false;
  return (Array.isArray(mod)?mod:[mod]).some(x=>{ const [m,a]=String(x).split(':'); return canFrom(ME.role,ME.role_permissions,m,a||'view'); });
}
function visibleCats(){ return CONTENT.categories.map(c=>({cat:c.cat,topics:c.topics.filter(t=>!modOff(t.mod||CAT_MOD[c.cat])&&allowed(t.mod))})).filter(c=>c.topics.length); }

let flat=[];
function render(){
  list.innerHTML='';
  const cats=visibleCats();
  cats.forEach((c)=>{
    const row=document.createElement('button'); row.className='catrow'; row.type='button';
    row.innerHTML='<span class="catname">'+esc(c.cat)+'</span><span class="cnt">'+c.topics.length+'</span><span class="chev">›</span>';
    const wrap=document.createElement('div'); wrap.className='topics'; wrap.hidden=true;
    c.topics.forEach(t=>{
      const tr=document.createElement('button'); tr.className='toprow'; tr.type='button';
      tr.innerHTML='<span>'+esc(t.title)+(t.for==='admin'?' <span class="tag">Admin</span>':'')+'</span>';
      const tb=document.createElement('div'); tb.className='topbody'; tb.hidden=true; tb.innerHTML=bodyHtml(t.body);
      tr.addEventListener('click',()=>{ const op=!tb.hidden; tb.hidden=op; tr.classList.toggle('open',!op); });
      wrap.appendChild(tr); wrap.appendChild(tb);
    });
    row.addEventListener('click',()=>{ const op=!wrap.hidden; wrap.hidden=op; row.classList.toggle('open',!op); });
    list.appendChild(row); list.appendChild(wrap);
  });
  flat=[]; cats.forEach(c=>c.topics.forEach(t=>flat.push({c:c.cat,t:t,s:searchText(t)+' '+c.cat.toLowerCase()})));
  const total=CONTENT.categories.reduce((n,c)=>n+c.topics.length,0), shown=flat.length;
  const note=$('rolenote');
  if(note){
    if(!ME) note.innerHTML='Showing general topics. <b>Sign in</b> to '+esc(APP_NAME)+' to see the guides for the features your role uses.';
    else if(ME.role==='super_admin'||shown===total) note.innerHTML='';
    else note.innerHTML='Showing the '+shown+' topics for your role'+(ME.role_name?' (<b>'+esc(ME.role_name)+'</b>)':'')+'.'+(ME.canAll?' <a href="#" id="allt">'+(SHOW_ALL?'Show only my topics':'Show all '+total+' topics')+'</a>':'');
    const at=$('allt'); if(at) at.onclick=(e)=>{ e.preventDefault(); SHOW_ALL=!SHOW_ALL; render(); };
  }
  const q=$('q'); if(q&&q.value) q.dispatchEvent(new Event('input'));
}
$('q').addEventListener('input',function(){
  const q=this.value.trim().toLowerCase();
  if(!q){ list.style.display=''; results.style.display='none'; results.innerHTML=''; return; }
  list.style.display='none'; results.style.display='';
  const hits=flat.filter(x=>x.s.indexOf(q)>=0);
  results.innerHTML = hits.length ? hits.map(x=>'<div class="rcard"><div class="rcat">'+esc(x.c)+'</div><div class="rtitle">'+esc(x.t.title)+(x.t.for==='admin'?' <span class="tag">Admin</span>':'')+'</div>'+bodyHtml(x.t.body)+'</div>').join('') : '<div class="rnone">No matching topics.</div>';
});
render();   // general topics right away; refined as soon as we know who is signed in
(function loadMe(){
  const API0=location.pathname.replace(/\/[^/]*$/,'')+'/api';
  const hdr={}; try{ const tk=localStorage.getItem('itops_token'); if(tk) hdr['X-ITOps-Token']=tk; }catch(_){}
  fetch(API0+'/auth/me',{headers:hdr,credentials:'include'}).then(r=>r.ok?r.json():null).then(d=>{
    const u=d&&d.user; if(!u) return;
    ME={role:u.role,role_permissions:u.role_permissions||{},role_name:u.role_name||'',display_name:u.display_name||''};
    // people who manage roles may look at every topic (e.g. to help a colleague)
    ME.canAll=u.role==='super_admin'||canFrom(u.role,ME.role_permissions,'roles','view')||canFrom(u.role,ME.role_permissions,'settings','edit');
    render();
    loadVisuals(API0,hdr);
    fetch(API0+'/modules',{headers:hdr,credentials:'include'}).then(r=>r.ok?r.json():null).then(m=>{
      if(!m||!Array.isArray(m.perms_off)||!m.perms_off.length) return;
      PERMS_OFF={}; m.perms_off.forEach(p=>{PERMS_OFF[p]=true;}); render();
    }).catch(()=>{});
  }).catch(()=>{});
})();

/* ---------- BT50: visual guides ----------
   Only the pages given to this person's role or to them are listed (a Super Admin sees all and can change who sees
   them). A page is fetched with the person's sign-in and shown in a sandboxed frame: it can draw, it cannot reach
   the person's session. */
let VIS_API=null, VIS_HDR={}, VIS_IDS=[];
function visFromHash(){ const h=(location.hash||'').match(/^#v=([a-z0-9-]+)$/); if(h&&VIS_IDS.indexOf(h[1])>=0&&$('vview').hidden) openVisual(h[1]); }
window.addEventListener('hashchange',visFromHash);
function loadVisuals(api,hdr){
  VIS_API=api; VIS_HDR=hdr||{};
  fetch(api+'/help/visuals',{headers:VIS_HDR,credentials:'include'}).then(r=>r.ok?r.json():null).then(d=>{
    const box=$('vis'), l=$('visl'); if(!d||!box)return;
    const vs=d.visuals||[];
    if(!vs.length){ box.hidden=true; return; }
    l.innerHTML=vs.map(v=>'<button type="button" class="visc" data-vis="'+esc(v.id)+'"><b>'+esc(v.title)+'</b><span>'+esc(v.description||'')+'</span><i>Open ›</i></button>').join('');
    l.querySelectorAll('[data-vis]').forEach(b=>b.addEventListener('click',()=>openVisual(b.getAttribute('data-vis'))));
    const m=$('vismanage'); if(m){ m.hidden=!d.can_manage; wireManage(m); }
    box.hidden=false;
    VIS_IDS=vs.map(v=>v.id); visFromHash();
  }).catch(()=>{});
}
/* BT71: "Who sees them…" opens Settings → Help visuals in the app itself. Inside the app's Help panel this page is a frame:
   it asks the app to go there (and close the panel) instead of loading a second copy of the app inside the panel. */
function wireManage(a){ a.href=appUrl+'#help_visuals'; a.target='_top';
  a.onclick=function(e){ let framed=false; try{ framed=window.parent&&window.parent!==window&&window.parent.location.origin===location.origin; }catch(_){ framed=false; }
    if(!framed) return true;   // a page of its own: follow the link
    e.preventDefault(); try{ window.parent.postMessage({type:'itops-help-goto',page:'help_visuals'},location.origin); }catch(_){} return false; }; }
/* BT51: the pages can be read light or dark. The first time it follows the theme chosen in the app (or the computer's);
   a choice made here is remembered on this browser. The page gets it from here only: the frame keeps no storage. */
function visTheme(){ let t=null; try{ t=localStorage.getItem('itops_vis_theme')||localStorage.getItem('itops_theme'); }catch(_){}
  if(t!=='light'&&t!=='dark') t=(window.matchMedia&&matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light'; return t; }
function visThemeShow(t){ document.querySelectorAll('[data-vtheme]').forEach(b=>b.setAttribute('aria-pressed',String(b.getAttribute('data-vtheme')===t)));
  const f=document.querySelector('#vbody iframe'); if(f){ f.classList.toggle('dark',t==='dark'); try{ f.contentWindow.postMessage({type:'itops-theme',theme:t},'*'); }catch(_){} } }
document.querySelectorAll('[data-vtheme]').forEach(b=>b.addEventListener('click',()=>{ const t=b.getAttribute('data-vtheme'); try{ localStorage.setItem('itops_vis_theme',t); }catch(_){} visThemeShow(t); }));
function closeVisual(){ const v=$('vview'); v.hidden=true; $('vbody').innerHTML=''; document.body.style.overflow=''; if(/^#v=/.test(location.hash)) history.replaceState(null,'',location.pathname+location.search); }
function openVisual(id){
  const v=$('vview'), body=$('vbody'); $('vtitle').textContent='Loading…'; body.innerHTML='<div class="vmsg">Loading…</div>'; v.hidden=false; document.body.style.overflow='hidden';
  fetch(VIS_API+'/help/visuals/'+encodeURIComponent(id),{headers:VIS_HDR,credentials:'include'}).then(r=>r.json().then(j=>({ok:r.ok,j}))).then(({ok,j})=>{
    if(!ok||!j||!j.html){ $('vtitle').textContent='Visual guide'; body.innerHTML='<div class="vmsg">'+esc((j&&j.error&&j.error.message)||'This page could not be opened.')+'</div>'; return; }
    $('vtitle').textContent=j.title||'Visual guide';
    const th=visTheme();
    const f=document.createElement('iframe'); f.className='vframe'+(th==='dark'?' dark':''); f.title=j.title||'Visual guide'; f.setAttribute('sandbox','allow-scripts'); f.setAttribute('data-vis-frame',id);
    f.srcdoc=String(j.html).replace('<html lang="en" data-theme="light">','<html lang="en" data-theme="'+th+'">'); visThemeShow(th);
    body.innerHTML=''; body.appendChild(f);
    try{ history.replaceState(null,'','#v='+id); }catch(_){}
  }).catch(()=>{ body.innerHTML='<div class="vmsg">This page could not be opened. Check the connection and try again.</div>'; });
}
$('vclose').addEventListener('click',closeVisual);
$('vfull').addEventListener('click',()=>{ const f=document.querySelector('#vbody iframe'); const el=f||$('vview'); if(el.requestFullscreen) el.requestFullscreen().catch(()=>{}); });
document.addEventListener('keydown',e=>{ if(e.key==='Escape'&&!$('vview').hidden&&!document.fullscreenElement) closeVisual(); });
/* ---------- Branding + logo for exports ---------- */
/* BT20: the guide is written with the product name "ITOps"; when the client renamed the app (Settings → Branding →
   App name) every topic, quick start and export shows THEIR name instead. Header names such as X-ITOps-Signature
   are technical and stay as they are. */
function brandContent(n){
  if(!n||n==='ITOps') return;
  const re=/(?<![-\w])ITOps(?![-\w\u2060])/g;   // "ITOps\u2060" = the product name on purpose
  const walk=o=>{ if(typeof o==='string') return o.replace(re,n); if(Array.isArray(o)){ for(let i=0;i<o.length;i++) o[i]=walk(o[i]); return o; }
    if(o&&typeof o==='object'){ for(const k in o) o[k]=walk(o[k]); return o; } return o; };
  walk(CONTENT);
}
// APP_NAME is declared at the top (used by the first render)
const API=location.pathname.replace(/\/[^/]*$/,'')+'/api';
fetch(API+'/branding').then(r=>r.json()).then(b=>{
  if(!b)return;
  if(b.app_name){ APP_NAME=b.app_name; brandContent(APP_NAME); render(); } document.title='IT Help Center';
  if(b.logo){ const lg=$('logo'); lg.src=b.logo; lg.style.display='block'; }
}).catch(()=>{});
const appUrl=location.pathname.replace(/\/[^/]*$/,'')+'/';
$('foot').textContent='Powered by ITOps · © 2026 Indisse-BTS. All rights reserved. Licensed, not sold.';   // BT96: the product and its owner (fixed)

